-- ---------- TABLE: ACTIVITY ----------
CREATE TABLE "FCS_FRN"."ACTIVITY" 
   (	"ACTIVITY_ID" NUMBER(38,0) NOT NULL ENABLE, 
	"ACTIVITY_TYPE" VARCHAR2(2), 
	"ACTIVITY_DATE" DATE, 
	"ACTIVITY_START_TIME" VARCHAR2(10), 
	"ACTIVITY_END_TIME" VARCHAR2(10), 
	"TIME_DIVIDE" VARCHAR2(2), 
