	"SUBJECT" VARCHAR2(1000), 
	"PLACE" VARCHAR2(1000), 
	"CREATE_DATE" DATE, 
	"CREATE_USER" VARCHAR2(200), 
	"UPDATE_DATE" DATE, 
	"UPDATE_USER" VARCHAR2(200), 
	"AMOUNT" NUMBER(38,0), 
	"RESPONSIBLE_USER" NUMBER(38,0), 
	"UPDATE_FUNC" VARCHAR2(1), 
	"ACTIVITY_END_DATE" DATE, 
	"BUILDING" VARCHAR2(100 CHAR), 
	"FLOOR" VARCHAR2(50 CHAR), 
	"ROOM" VARCHAR2(50 CHAR), 
	"REGISTER_TIME" VARCHAR2(20 CHAR), 
	 PRIMARY KEY ("ACTIVITY_ID")
  USING INDEX  ENABLE
   )   NO INMEMORY ;

