-- ---------- VIEW: V_ACTIVITY_TRAINEE ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_ACTIVITY_TRAINEE" ("FRANCHISEE_ID", "SUBJECT", "TRAIN_DATE", "PLACE", "ACTIVITY_TYPE", "TRAIN_RESULT", "REMARK", "FZ_FIRST_NAME", "FZ_LAST_NAME", "BRANCH_ID", "BRANCH_NAME", "FIRST_NAME", "LAST_NAME", "TRAIN_RESULT_VALUE", "TRAIN_RESULT_NAME") AS 
  SELECT ATN.FRANCHISEE_ID,
    AC.SUBJECT,
    TO_CHAR(ATN.TRAIN_DATE,'DD/MM/YYYY') TRAIN_DATE,
    AC.PLACE,
    AC.ACTIVITY_TYPE,
    DECODE(AC.ACTIVITY_TYPE,9, DECODE(ATN.TRAIN_RESULT,'P','เข้าร่วม','N','ไม่เข้าร่วม',NULL),10, DECODE(ATN.TRAIN_RESULT,'P','ผ่านการอบรม','N','ไม่ผ่านการอบรม',NULL),NULL) TRAIN_RESULT,
    ATN.REMARK,
    FS.FIRST_NAME FZ_FIRST_NAME,
    FS.LAST_NAME FZ_LAST_NAME,
    FS.BRANCH_ID,
    FS.BRANCH_NAME,
    ATN.FIRST_NAME,
    ATN.LAST_NAME,
    ATN.TRAIN_RESULT TRAIN_RESULT_VALUE,
    DECODE(ATN.TRAIN_RESULT,'P','ผ่าน','N','ไม่ผ่าน',NULL) TRAIN_RESULT_NAME
  FROM ACTIVITY AC
  INNER JOIN ACTIVITY_TRAINEE ATN
  ON AC.ACTIVITY_ID = ATN.ACTIVITY_ID
  INNER JOIN
    (SELECT f.*,
      ff.BRANCH_ID,
      ff.BRANCH_NAME
    FROM franchisee f
    INNER JOIN
      (SELECT fz.franchisee_id,
        LISTAGG(fs.store_id, ', ') WITHIN GROUP (
      ORDER BY fs.store_id) BRANCH_ID ,
        LISTAGG(fs.store_name, ', ') WITHIN GROUP (
      ORDER BY fs.store_name) BRANCH_NAME
      FROM franchisee fz
      INNER JOIN fr_store fs
      ON NVL(fz.status, '-')  != 'D'
      AND NVL(fs.status, '-') != 'D'
      AND fs.owner_id1         = fz.franchisee_id
      AND ( ( fs.cancel_date  IS NULL
      AND fs.cancel_type       = '00')
      OR fs.cancel_date       >= sysdate )
      GROUP BY fz.franchisee_id
      ) ff ON ff.franchisee_id = f.franchisee_id
    ) FS ON FS.FRANCHISEE_ID   = ATN.FRANCHISEE_ID
  WHERE atn.active_flag        = 'Y';

-- ---------- VIEW: V_EXP_CC_EMAIL_WF1 ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_EXP_CC_EMAIL_WF1" ("รหัสขั้นตอน", "ชื่อขั้นตอน", "Email") AS 
  SELECT ed.wf_email_detail_id ,
            ed.wf_email_detail_name ,
            ed.cc_email 
       FROM    wf_email_detail ed
            INNER JOIN
               wf_route r
            ON r.then_email_with_id = ed.wf_email_detail_id
      WHERE r.wf_version_id = 1
   GROUP BY ed.wf_email_detail_id, ed.wf_email_detail_name, ed.cc_email
   ORDER BY ed.wf_email_detail_id;

-- ---------- VIEW: V_EXP_CC_EMAIL_WF2 ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_EXP_CC_EMAIL_WF2" ("รหัสขั้นตอน", "ชื่อขั้นตอน", "EMAIL") AS 
  select ed.wf_email_detail_id, ed.wf_email_detail_name, ed.cc_email
from wf_email_detail ed 
