-- ---------- VIEW: V_EXP_CC_EMAIL_WF4 ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_EXP_CC_EMAIL_WF4" ("รหัสขั้นตอน", "ชื่อขั้นตอน", "EMAIL") AS 
