-- ---------- VIEW: V_FCS_AUTHORIZE ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_FCS_AUTHORIZE" ("USER_ID", "GROUP_ID", "AUTH_ID", "AUTH_GROUP_ID", "SYSTEM_CODE", "TRANSACTION_PK", "TABLE_TRANSACTION_PK", "START_DATE", "END_DATE", "AUTH_BRANCH_TYPE", "AUTH_REGION", "AUTH_BRANCH_ID", "AUTH_FC_EMP_ID", "AUTH_MN_EMP_ID", "AUTH_DV_EMP_ID", "BRANCH_ID", "BRANCH_NAME", "BRANCH_TYPE", "STATUS_TYPE", "REGION", "DATA_TYPE", "FC_EMP_ID", "FC_FULL_NAME", "MN_EMP_ID", "MN_FULLNAME", "DV_EMP_ID", "DV_FULLNAME") AS 
  SELECT bu.user_id,
          bu.GROUP_ID,
          auth."AUTH_ID",
          auth."AUTH_GROUP_ID",
          auth."SYSTEM_CODE",
          auth."TRANSACTION_PK",
          auth."TABLE_TRANSACTION_PK",
          auth."START_DATE",
          auth."END_DATE",
          auth."AUTH_BRANCH_TYPE",
          auth."AUTH_REGION",
          auth."AUTH_BRANCH_ID",
          auth."AUTH_FC_EMP_ID",
          auth."AUTH_MN_EMP_ID",
          auth."AUTH_DV_EMP_ID",
          ms."BRANCH_ID",
          ms."BRANCH_NAME",
          ms."BRANCH_TYPE",
          ms."STATUS_TYPE",
          ms."REGION",
          ms."DATA_TYPE",
          ms."FC_EMP_ID",
          ms."FC_FULL_NAME",
          ms."MN_EMP_ID",
          ms."MN_FULLNAME",
          ms."DV_EMP_ID",
          ms."DV_FULLNAME"
     FROM (SELECT au.auth_id,
                  agt.GROUP_ID AS auth_group_id,
                  au.system_code,
                  au.transaction_pk,
                  au.table_transaction_pk,
                  au.start_date,
                  au.end_date,
                  au1.auth_value AS auth_branch_type,
                  au2.auth_value AS auth_region,
                  au3.auth_value AS auth_branch_id,
                  au4.auth_value AS auth_fc_emp_id,
                  au5.auth_value AS auth_mn_emp_id,
                  au6.auth_value AS auth_dv_emp_id
             FROM fcs_authorize au
                  INNER JOIN fcs_authorize_group ag
                     ON ag.auth_group_id = au.auth_group_id
                        AND ag.system_code = 'FML'
                  INNER JOIN fcs_authorize_group_trans agt
                     ON agt.auth_group_id = ag.auth_group_id
                  LEFT JOIN (SELECT aut1.*
                               FROM fcs_authorize_trans aut1
                              WHERE aut1.auth_type = 1) au1
                     ON au1.auth_id = au.auth_id
                  LEFT JOIN (SELECT aut1.*
                               FROM fcs_authorize_trans aut1
                              WHERE aut1.auth_type = 2) au2
                     ON au2.auth_id = au.auth_id
                  LEFT JOIN (SELECT aut1.*
                               FROM fcs_authorize_trans aut1
                              WHERE aut1.auth_type = 3) au3
                     ON au3.auth_id = au.auth_id
                  LEFT JOIN (SELECT aut1.*
                               FROM fcs_authorize_trans aut1
                              WHERE aut1.auth_type = 4) au4
                     ON au4.auth_id = au.auth_id
                  LEFT JOIN (SELECT aut1.*
                               FROM fcs_authorize_trans aut1
                              WHERE aut1.auth_type = 5) au5
                     ON au5.auth_id = au.auth_id
                  LEFT JOIN (SELECT aut1.*
                               FROM fcs_authorize_trans aut1
                              WHERE aut1.auth_type = 6) au6
                     ON au6.auth_id = au.auth_id
            WHERE au.system_code = 'FML'
                  AND TRUNC (SYSDATE) BETWEEN NVL (au.start_date,
                                                   TRUNC (SYSDATE))
                                          AND NVL (au.end_date,
                                                   TRUNC (SYSDATE))) auth
          INNER JOIN (SELECT s.branch_id,
                             s.branch_name,
                             s.branch_type,
                             s.status_type,
                             s.region,
                             s.data_type,
                             fc.emp_id AS fc_emp_id,
                             fc.fullname AS fc_full_name,
                             mn.emp_id AS mn_emp_id,
                             mn.fullname AS mn_fullname,
                             dv.emp_id AS dv_emp_id,
                             dv.fullname AS dv_fullname
                        FROM mas_store s
                             LEFT JOIN mas_store_organize fc
                                ON     fc.branch_id = s.branch_id
                                   AND s.active_flag = 'Y'
                                   AND fc.active_flag = 'Y'
                                   AND fc.GROUP_ID = 2000
                             LEFT JOIN mas_store_organize mn
                                ON     mn.branch_id = s.branch_id
                                   AND s.active_flag = 'Y'
                                   AND mn.active_flag = 'Y'
                                   AND mn.GROUP_ID = 70
                             LEFT JOIN mas_store_organize dv
                                ON     dv.branch_id = s.branch_id
                                   AND s.active_flag = 'Y'
                                   AND dv.active_flag = 'Y'
                                   AND dv.GROUP_ID = 15) ms
             ON ms.status_type = NVL (auth.auth_branch_type, ms.status_type)
                AND ms.region = NVL (auth.auth_region, ms.region)
                AND ms.branch_id = NVL (auth.auth_branch_id, ms.branch_id)
                AND ms.fc_emp_id = NVL (auth.auth_fc_emp_id, ms.fc_emp_id)
                AND ms.mn_emp_id = NVL (auth.auth_mn_emp_id, ms.mn_emp_id)
                AND ms.dv_emp_id = NVL (auth.auth_dv_emp_id, ms.dv_emp_id)
          INNER JOIN business_user bu
             ON bu.GROUP_ID = NVL (auth.auth_group_id, bu.GROUP_ID)
          LEFT JOIN franchisee fz
             ON fz.franchisee_id = bu.franchisee_id
          LEFT JOIN fr_store fs
             ON     fs.owner_id1 = fz.franchisee_id
                AND fs.cancel_date IS NULL
                AND NVL (fs.status, '-') != 'D';

-- ---------- VIEW: V_FCS_COORDINATE_REGION ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_FCS_COORDINATE_REGION" ("พื้นที่", "รหัสพนักงาน", "ชื่อ (TH)", "นามสกุล (TH)") AS 
  select 
		column1 region,
		column2 emp_id,
		column3 first_name,
		column4 last_name
	from mas_tmp_import_data
	where data_type = 'COORDINATE_REGION'
	order by column1, column2, column3, column4;

-- ---------- VIEW: V_FCS_STORE_ORGANIZE ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_FCS_STORE_ORGANIZE" ("USER_ID", "USER_NAME", "FIRST_NAME", "LAST_NAME", "GROUP_ID", "EMAIL", "BRANCH_ID", "REGION") AS 
  select bu.user_id, p.param_value || bu.user_name as user_name, bu.first_name, bu.last_name, ms.group_id, bu.email, ms.branch_id,
    ms.region
from business_user bu
    inner JOIN (
        select ms.region, u.user_id, u.group_id, ms.branch_id
        from mas_store ms
            inner join mas_store_organize mso on mso.branch_id = ms.branch_id
                  and ms.data_type = '1'
                  and ms.active_flag = 'Y'
                  and mso.data_type = '1'
                  and mso.active_flag = 'Y'
            inner join (
                select bu.user_id, bu.emp_id, bu.first_name, bu.last_name, nvl (bug.group_id, bu.group_id) as group_id
                from business_user bu
                    left join (
                        select distinct user_id, group_id
                        from business_user_group
                        where group_id in (2000, 70, 15, 38, 28)                              --2000=FC, 70=MN, 15=DV, 38=GM, 28=VP
                    ) bug on bug.user_id = bu.user_id
                 where bu.active_flag = 'Y' 
                    and (
                        bu.group_id in (2000, 70, 15, 38, 28)
                        or bug.group_id in (2000, 70, 15, 38, 28)
                    )                                 
            ) u on u.group_id = mso.group_id
                and (
                    u.emp_id = mso.emp_id
                    or (
                        instr (mso.fullname, u.first_name) > 0
                        and instr (mso.fullname, u.last_name) > 0
                    )
                )
    ) ms on ms.user_id = bu.user_id
        and bu.active_flag = 'Y'    
    inner join mas_param p on p.param_name = 'K2_PREFIX_USERNAME' ;

-- ---------- VIEW: V_FES_EVALUATE_SUMMARY ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_FES_EVALUATE_SUMMARY" ("FRANCHISEE_ID", "OWNER_ID2", "OWNER_ID3", "OWNER_ID4", "EVALUATE_ID", "EVA_ORDER_ID", "STORE_ID", "STORE_NAME", "START_DATE", "FR_TYPE_NAME", "EVAL_TYPE", "EVAL_YEAR", "EVAL_MONTH", "EVAL_NO", "EVA_PERIOD", "TOTAL_POINT", "FULL_POINT", "PERCENT_POINT", "GRADE", "PERIOD", "CONFIRM_GRADE_STATUS", "CONFIRM_GRADE_DATE") AS 
  SELECT 
    s.owner_id1 AS franchisee_id,
    s.owner_id2,
    s.owner_id3,
    s.owner_id4,
    eva.evaluate_id,
    eva.eva_order_id,
    s.store_id,
    ms.branch_name                                                                                                                              AS store_name,
    TO_CHAR (s.start_date, 'DD/MM/YYYY', 'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')                                                 AS start_date,
    DECODE (ms.status_type, 'FPT1', 'Type ปตท.', 'FAM', 'Type A', 'FB1', 'Type B', 'FB2', 'Type พนักงาน', 'FC1', 'Type C', 'FBGC', 'BGC', 'FVB', 'Type VB', 'FVC', 'Type VC', NULL) AS fr_type_name,
    eva.eval_type,
    eva.eval_year,
    eva.eval_month,
    NULL eval_no,
    TO_CHAR ( ADD_MONTHS ( TO_DATE (LPAD (eva.eval_month, 2, '0')
    || eva.eval_year, 'MMYYYY'), -3), 'FMMON YY', 'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
    || ' - '
    || TO_CHAR ( ADD_MONTHS ( TO_DATE (LPAD (eva.eval_month, 2, '0')
    || eva.eval_year, 'MMYYYY'), -1), 'FMMON YY', 'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI') AS eva_period,
    eva.total_point,
    frm.total_point                                       AS full_point,
    ROUND ( (eva.total_point / frm.total_point) * 100, 2) AS percent_point,
    eva.grade,
    eva.eval_year
    || LPAD (eva.eval_month, 2, '0') AS period,
    eva.confirm_grade_status,
    eva.confirm_grade_date
  FROM
    (SELECT *
    FROM
      (SELECT eva.evaluate_id,
        eva.eval_month,
        eva.eval_year,
        eva.total_point,
        eva.grade,
        eva.eval_type,
        eva.order_id AS eva_order_id,
        s.order_id,
        eva.confirm_grade_status,
        eva.confirm_grade_date,
        DENSE_RANK () OVER ( PARTITION BY s.order_id ORDER BY eva.del_status NULLS FIRST, eva.eval_year DESC, eva.eval_month DESC) AS row_rank
      FROM fes_evaluate eva
      INNER JOIN
        (SELECT *
        FROM
          (SELECT order_id,
            REGEXP_SUBSTR ( SUBSTR (root_path, 2), ',?([^,]*)', 1, LEVEL, 'i', 1) AS ref_order_id
          FROM
            (SELECT s.order_id,
              s.store_id,
              s.start_date,
              s.parent_order_id,
              SYS_CONNECT_BY_PATH ( s.order_id, ',') AS root_path
            FROM fr_store s
            WHERE store_id                 != '00000'
            AND (s.status                  IS NULL
            OR s.status                    != 'D')
            AND s.cancel_date              IS NULL
              START WITH s.parent_order_id IS NULL
              CONNECT BY PRIOR s.order_id   = s.parent_order_id
            )
            CONNECT BY (REGEXP_COUNT (root_path, ',') + 1 >= LEVEL
          AND PRIOR order_id                               = order_id
          AND PRIOR DBMS_RANDOM.VALUE                     IS NOT NULL)
          )
        WHERE ref_order_id IS NOT NULL
        ) s
      ON s.ref_order_id = eva.fr_store_order_id
      AND eva.eval_type = 'THREE'
      AND eva.status    = 'DO'
      AND eva.eval_year
        || LPAD (eva.eval_month, 2, '0') >= TO_NUMBER ( TO_CHAR (ADD_MONTHS (SYSDATE, -12), 'YYYYMM'))
        /*display within 1 year*/
      AND eva.eval_year >= 2010
        /*minimum year for display is 2010*/
      )
    WHERE row_rank = 1
    ) eva
  INNER JOIN fes_evaluatedform frm
  ON TO_NUMBER (eva.eval_year
    || LPAD (eva.eval_month, 2, 0)) BETWEEN TO_NUMBER ( (start_year)
    || LPAD ( start_month, 2, 0))
  AND TO_NUMBER ( (end_year)
    || LPAD ( end_month, 2, 0))
  OR (TO_NUMBER (eva.eval_year
    || LPAD (eva.eval_month, 2, 0)) >= TO_NUMBER ( ( (start_year)
    || LPAD (start_month, 2, 0)))
  AND frm.end_month IS NULL
  AND frm.end_year  IS NULL)
  INNER JOIN fr_store s
  ON s.order_id = eva.order_id
  LEFT JOIN mas_store ms
  ON ms.branch_id = s.store_id
  UNION ALL
  --MIDYEAR
  SELECT s.owner_id1 AS franchisee_id,
    s.owner_id2,
    s.owner_id3,
    s.owner_id4,
    eva.evaluate_id,
    eva.order_id AS eva_order_id,
    s.store_id,
    ms.branch_name                                                                                                                                   AS store_name,
    TO_CHAR (s.start_date, 'DD/MM/YYYY', 'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')                                                      AS start_date,
    DECODE (ms.status_type, 'FPT1', 'Type ปตท.', 'FAM', 'Type A', 'FB1', 'Type B', 'FB2', 'Type พนักงาน', 'FC1', 'Type C', 'FBGC', 'BGC', 'FVB', 'Type VB', 'FVC', 'Type VC', NULL) AS fr_type_name,
    eva.eval_type,
    eva.eval_year,
    eva.eval_month,
    CASE
      WHEN FLOOR (eva.eval_month / 7) = 0
      THEN 1
      ELSE 2
    END AS eval_no,
    TO_CHAR ( ADD_MONTHS ( TO_DATE (LPAD (eva.eval_month, 2, '0')
    || eva.eval_year, 'MMYYYY'),
    CASE
      WHEN (ADD_MONTHS (s.start_date,                 +6)                   > TRUNC (ADD_MONTHS (s.start_date, +6), 'MM'))
      AND (TO_CHAR ( TRUNC (ADD_MONTHS (s.start_date, +6), 'MM'), 'YYYYMM') = eva.eval_year
        || LPAD (eva.eval_month, 2, '0'))
      THEN -5
      ELSE -6
    END), 'FMMON YY', 'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
    || ' - '
    || TO_CHAR ( ADD_MONTHS ( TO_DATE (LPAD (eva.eval_month, 2, '0')
    || eva.eval_year, 'MMYYYY'), -1), 'FMMON YY', 'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI') eva_period,
    eva.total_point,
    frm.total_point                                       AS full_point,
    ROUND ( (eva.total_point / frm.total_point) * 100, 2) AS percent_point,
    eva.grade,
    eva.eval_year
    || LPAD (eva.eval_month, 2, '0') AS period,
    eva.confirm_grade_status,
    eva.confirm_grade_date
  FROM
    (SELECT *
    FROM
      (SELECT eva.evaluate_id,
        eva.eval_month,
        eva.eval_year,
        eva.total_point,
        eva.grade,
        eva.eval_type,
        eva.order_id AS eva_order_id,
        s.order_id,
        eva.confirm_grade_status,
        eva.confirm_grade_date,
        DENSE_RANK () OVER ( PARTITION BY s.order_id, eva.eval_year, eva.eval_month ORDER BY eva.del_status NULLS FIRST, eva.eval_year DESC, eva.eval_month DESC) AS row_rank
      FROM fes_evaluate eva
      INNER JOIN
        (SELECT *
        FROM
          (SELECT order_id,
            start_date,
            REGEXP_SUBSTR ( SUBSTR (root_path, 2), ',?([^,]*)', 1, LEVEL, 'i', 1) AS ref_order_id
          FROM
            (SELECT s.order_id,
              s.store_id,
              s.start_date,
              s.parent_order_id,
              SYS_CONNECT_BY_PATH ( s.order_id, ',') AS root_path
            FROM fr_store s
            WHERE store_id                 != '00000'
            AND (s.status                  IS NULL
            OR s.status                    != 'D')
            AND s.cancel_date              IS NULL
              START WITH s.parent_order_id IS NULL
              CONNECT BY PRIOR s.order_id   = s.parent_order_id
            )
            CONNECT BY (REGEXP_COUNT (root_path, ',') + 1 >= LEVEL
          AND PRIOR order_id                               = order_id
          AND PRIOR DBMS_RANDOM.VALUE                     IS NOT NULL)
          )
        WHERE ref_order_id IS NOT NULL
        ) s
      ON s.ref_order_id  = eva.fr_store_order_id
      AND eva.eval_type  = 'MIDYEAR'
      AND eva.status     = 'DO'
      AND eva.eval_year >= (TO_NUMBER (TO_CHAR (SYSDATE, 'YYYY')) - 6)
        /*display data backward 6 years*/
      AND eva.eval_year >= 2010
        /*minimum year for display is 2010*/
      AND (eva.eval_month = TO_CHAR (ADD_MONTHS (s.start_date, 6), 'MM')
      OR eva.eval_month   = TO_CHAR (s.start_date, 'MM'))
      AND TO_NUMBER ( eva.eval_year
        || LPAD (eva.eval_month, 2, '0')) >= TO_NUMBER ( TO_CHAR (ADD_MONTHS (s.start_date, 6), 'YYYYMM'))
      )
    WHERE row_rank = 1
    ) eva
  INNER JOIN fes_evaluatedform frm
  ON TO_NUMBER (eva.eval_year
    || LPAD (eva.eval_month, 2, 0)) BETWEEN TO_NUMBER ( (start_year)
    || LPAD ( start_month, 2, 0))
  AND TO_NUMBER ( (end_year)
    || LPAD ( end_month, 2, 0))
  OR (TO_NUMBER (eva.eval_year
    || LPAD (eva.eval_month, 2, 0)) >= TO_NUMBER ( (start_year)
    || LPAD (start_month, 2, 0))
  AND frm.end_month IS NULL
  AND frm.end_year  IS NULL)
  INNER JOIN fr_store s
  ON s.order_id = eva.order_id
  LEFT JOIN mas_store ms
  ON ms.branch_id = s.store_id;

-- ---------- VIEW: V_FES_EVALUATE_SUMMARY_BAK ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_FES_EVALUATE_SUMMARY_BAK" ("FRANCHISEE_ID", "EVALUATE_ID", "EVA_ORDER_ID", "STORE_ID", "STORE_NAME", "START_DATE", "FR_TYPE_NAME", "EVAL_TYPE", "EVAL_YEAR", "EVAL_MONTH", "EVAL_NO", "EVA_PERIOD", "TOTAL_POINT", "FULL_POINT", "PERCENT_POINT", "GRADE", "PERIOD") AS 
  SELECT s.owner_id1 AS franchisee_id,
          eva.evaluate_id,
          eva.eva_order_id,
          s.store_id,
          ms.branch_name AS store_name,
          TO_CHAR (s.start_date,
                   'DD/MM/YYYY',
                   'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
             AS start_date,
          DECODE (ms.status_type,
                  'FPT1', 'Type ปตท.',
                  'FAM', 'Type A',
                  'FB1', 'Type B',
                  'FB2', 'Type พนักงาน',
                  'FC1', 'Type C',
                  'FBGC', 'BGC',
                  NULL)
             AS fr_type_name,
          eva.eval_type,
          eva.eval_year,
          eva.eval_month,
          NULL eval_no,
          TO_CHAR (
             ADD_MONTHS (
                TO_DATE (LPAD (eva.eval_month, 2, '0') || eva.eval_year,
                         'MMYYYY'),
                -3),
             'FMMON YY',
             'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
          || ' - '
          || TO_CHAR (
                ADD_MONTHS (
                   TO_DATE (LPAD (eva.eval_month, 2, '0') || eva.eval_year,
                            'MMYYYY'),
                   -1),
                'FMMON YY',
                'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
             AS eva_period,
          eva.total_point,
          frm.total_point AS full_point,
          ROUND ( (eva.total_point / frm.total_point) * 100, 2)
             AS percent_point,
          eva.grade,
          eva.eval_year || LPAD (eva.eval_month, 2, '0') AS period
     FROM (SELECT *
             FROM (SELECT eva.evaluate_id,
                          eva.eval_month,
                          eva.eval_year,
                          eva.total_point,
                          eva.grade,
                          eva.eval_type,
                          eva.order_id AS eva_order_id,
                          s.order_id,
                          DENSE_RANK ()
                          OVER (
                             PARTITION BY s.order_id
                             ORDER BY
                                eva.del_status NULLS FIRST,
                                eva.eval_year DESC,
                                eva.eval_month DESC)
                             AS row_rank
                     FROM    fes_evaluate eva
                          INNER JOIN
                             (SELECT *
                                FROM (    SELECT order_id,
                                                 REGEXP_SUBSTR (
                                                    SUBSTR (root_path, 2),
                                                    ',?([^,]*)',
                                                    1,
                                                    LEVEL,
                                                    'i',
                                                    1)
                                                    AS ref_order_id
                                            FROM (    SELECT s.order_id,
                                                             s.store_id,
                                                             s.start_date,
                                                             s.parent_order_id,
                                                             SYS_CONNECT_BY_PATH (
                                                                s.order_id,
                                                                ',')
                                                                AS root_path
                                                        FROM fr_store s
                                                       WHERE store_id != '00000'
                                                             AND (s.status IS NULL
                                                                  OR s.status != 'D')
                                                             AND s.cancel_date
                                                                    IS NULL
                                                  START WITH s.parent_order_id
                                                                IS NULL
                                                  CONNECT BY PRIOR s.order_id =
                                                                s.parent_order_id)
                                      CONNECT BY (REGEXP_COUNT (root_path,
                                                                ',')
                                                  + 1 >= LEVEL
                                                  AND PRIOR order_id =
                                                         order_id
                                                  AND PRIOR DBMS_RANDOM.VALUE
                                                         IS NOT NULL))
                               WHERE ref_order_id IS NOT NULL) s
                          ON     s.ref_order_id = eva.fr_store_order_id
                             AND eva.eval_type = 'THREE'
                             AND eva.status = 'DO'
                             AND eva.eval_year
                                 || LPAD (eva.eval_month, 2, '0') >=
                                    TO_NUMBER (
                                       TO_CHAR (ADD_MONTHS (SYSDATE, -12),
                                                'YYYYMM')) /*display within 1 year*/
                             AND eva.eval_year >= 2010 /*minimum year for display is 2010*/
                                                      )
            WHERE row_rank = 1) eva
          INNER JOIN fes_evaluatedform frm
             ON TO_NUMBER (eva.eval_year || LPAD (eva.eval_month, 2, 0)) BETWEEN TO_NUMBER (
                                                                                    (start_year)
                                                                                    || LPAD (
                                                                                          start_month,
                                                                                          2,
                                                                                          0))
                                                                             AND TO_NUMBER (
                                                                                    (end_year)
                                                                                    || LPAD (
                                                                                          end_month,
                                                                                          2,
                                                                                          0))
                OR (TO_NUMBER (eva.eval_year || LPAD (eva.eval_month, 2, 0)) >=
                       TO_NUMBER ( (start_year) || LPAD (start_month, 2, 0))
                    AND frm.end_month IS NULL
                    AND frm.end_year IS NULL)
          INNER JOIN fr_store s
             ON s.order_id = eva.order_id
          LEFT JOIN mas_store ms
             ON ms.branch_id = s.store_id
   UNION ALL
   --MIDYEAR
   SELECT s.owner_id1 AS franchisee_id,
          eva.evaluate_id,
          eva.order_id AS eva_order_id,
          s.store_id,
          ms.branch_name AS store_name,
          TO_CHAR (s.start_date,
                   'DD/MM/YYYY',
                   'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
             AS start_date,
          DECODE (ms.status_type,
                  'FPT1', 'Type ปตท.',
                  'FAM', 'Type A',
                  'FB1', 'Type B',
                  'FB2', 'Type พนักงาน',
                  'FC1', 'Type C',
                  'FBGC', 'Type BGC',
                  NULL)
             AS fr_type_name,
          eva.eval_type,
          eva.eval_year,
          eva.eval_month,
          CASE WHEN FLOOR (eva.eval_month / 7) = 0 THEN 1 ELSE 2 END
             AS eval_no,
          TO_CHAR (
             ADD_MONTHS (
                TO_DATE (LPAD (eva.eval_month, 2, '0') || eva.eval_year,
                         'MMYYYY'),
                CASE
                   WHEN (ADD_MONTHS (s.start_date, +6) >
                            TRUNC (ADD_MONTHS (s.start_date, +6), 'MM'))
                        AND (TO_CHAR (
                                TRUNC (ADD_MONTHS (s.start_date, +6), 'MM'),
                                'YYYYMM') =
                                eva.eval_year
                                || LPAD (eva.eval_month, 2, '0'))
                   THEN
                      -5
                   ELSE
                      -6
                END),
             'FMMON YY',
             'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
          || ' - '
          || TO_CHAR (
                ADD_MONTHS (
                   TO_DATE (LPAD (eva.eval_month, 2, '0') || eva.eval_year,
                            'MMYYYY'),
                   -1),
                'FMMON YY',
                'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
             eva_period,
          eva.total_point,
          frm.total_point AS full_point,
          ROUND ( (eva.total_point / frm.total_point) * 100, 2)
             AS percent_point,
          eva.grade,
          eva.eval_year || LPAD (eva.eval_month, 2, '0') AS period
     FROM (SELECT *
             FROM (SELECT eva.evaluate_id,
                          eva.eval_month,
                          eva.eval_year,
                          eva.total_point,
                          eva.grade,
                          eva.eval_type,
                          eva.order_id AS eva_order_id,
                          s.order_id,
                          DENSE_RANK ()
                          OVER (
                             PARTITION BY s.order_id,
                                          eva.eval_year,
                                          eva.eval_month
                             ORDER BY
                                eva.del_status NULLS FIRST,
                                eva.eval_year DESC,
                                eva.eval_month DESC)
                             AS row_rank
                     FROM    fes_evaluate eva
                          INNER JOIN
                             (SELECT *
                                FROM (    SELECT order_id,
                                                 start_date,
                                                 REGEXP_SUBSTR (
                                                    SUBSTR (root_path, 2),
                                                    ',?([^,]*)',
                                                    1,
                                                    LEVEL,
                                                    'i',
                                                    1)
                                                    AS ref_order_id
                                            FROM (    SELECT s.order_id,
                                                             s.store_id,
                                                             s.start_date,
                                                             s.parent_order_id,
                                                             SYS_CONNECT_BY_PATH (
                                                                s.order_id,
                                                                ',')
                                                                AS root_path
                                                        FROM fr_store s
                                                       WHERE store_id != '00000'
                                                             AND (s.status IS NULL
                                                                  OR s.status != 'D')
                                                             AND s.cancel_date
                                                                    IS NULL
                                                  START WITH s.parent_order_id
                                                                IS NULL
                                                  CONNECT BY PRIOR s.order_id =
                                                                s.parent_order_id)
                                      CONNECT BY (REGEXP_COUNT (root_path,
                                                                ',')
                                                  + 1 >= LEVEL
                                                  AND PRIOR order_id =
                                                         order_id
                                                  AND PRIOR DBMS_RANDOM.VALUE
                                                         IS NOT NULL))
                               WHERE ref_order_id IS NOT NULL) s
                          ON     s.ref_order_id = eva.fr_store_order_id
                             AND eva.eval_type = 'MIDYEAR'
                             AND eva.status = 'DO'
                             AND eva.eval_year >=
                                    (TO_NUMBER (TO_CHAR (SYSDATE, 'YYYY'))
                                     - 6)    /*display data backward 6 years*/
                             AND eva.eval_year >= 2010 /*minimum year for display is 2010*/
                             AND (eva.eval_month =
                                     TO_CHAR (ADD_MONTHS (s.start_date, 6),
                                              'MM')
                                  OR eva.eval_month =
                                        TO_CHAR (s.start_date, 'MM'))
                             AND TO_NUMBER (
                                    eva.eval_year
                                    || LPAD (eva.eval_month, 2, '0')) >=
                                    TO_NUMBER (
                                       TO_CHAR (ADD_MONTHS (s.start_date, 6),
                                                'YYYYMM')))
            WHERE row_rank = 1) eva
          INNER JOIN fes_evaluatedform frm
             ON TO_NUMBER (eva.eval_year || LPAD (eva.eval_month, 2, 0)) BETWEEN TO_NUMBER (
                                                                                    (start_year)
                                                                                    || LPAD (
                                                                                          start_month,
                                                                                          2,
                                                                                          0))
                                                                             AND TO_NUMBER (
                                                                                    (end_year)
                                                                                    || LPAD (
                                                                                          end_month,
                                                                                          2,
                                                                                          0))
                OR (TO_NUMBER (eva.eval_year || LPAD (eva.eval_month, 2, 0)) >=
                       TO_NUMBER ( (start_year) || LPAD (start_month, 2, 0))
                    AND frm.end_month IS NULL
                    AND frm.end_year IS NULL)
          INNER JOIN fr_store s
             ON s.order_id = eva.order_id
          LEFT JOIN mas_store ms
             ON ms.branch_id = s.store_id;

-- ---------- VIEW: V_FES_EVALUATE_SUMMARY_WAIT ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_FES_EVALUATE_SUMMARY_WAIT" ("STORE_ID", "STORE_NAME", "FR_TYPE_NAME", "FRANCHISEE_ID", "OWNER_ID2", "OWNER_ID3", "OWNER_ID4", "START_DATE", "EVALUATE_ID", "CUR_EVAL_TYPE", "CUR_EVAL_MONTH", "CUR_EVAL_YEAR", "STATUS", "FR_STORE_ORDER_ID", "CUR_IMPORTDATA_MM", "CUR_IMPORTDATA_YY", "EVAL_TYPE", "PERIOD", "EVA_PERIOD") AS 
  SELECT ms.branch_id                                                                                                                                AS store_id,
    ms.branch_name                                                                                                                                   AS store_name,
    DECODE (ms.status_type, 'FPT1', 'Type ปตท.', 'FAM', 'Type A', 'FB1', 'Type B', 'FB2', 'Type พนักงาน', 'FC1', 'Type C', 'FBGC', 'Type BGC', 'FVB', 'Type VB', 'FVC', 'Type VC', NULL) AS fr_type_name,
    s.owner_id1                                                                                                                                      AS franchisee_id,
    s.owner_id2,
    s.owner_id3,
    s.owner_id4,
    TO_CHAR (s.start_date, 'DD/MM/YYYY')                                                                                                             AS start_date,
    eva1.evaluate_id,
    eva1.eval_type  AS cur_eval_type,
    eva1.eval_month AS cur_eval_month,
    eva1.eval_year  AS cur_eval_year,
    eva1.status,
    eva1.fr_store_order_id,
    eva1.mm AS cur_importdata_mm,
    eva1.yy AS cur_importdata_yy,
    CASE
      WHEN (eva1.status = 'DO')
      THEN
        CASE
          WHEN (eva1.eval_type = 'TWO')
          THEN 'THREE'
          ELSE 'MIDYEAR'
        END
      WHEN (eva1.status IS NULL)
      THEN 'MIDYEAR'
      ELSE TO_CHAR (eva1.eval_type)
    END AS eval_type,
    CASE
      WHEN (eva1.status = 'DO')
      THEN
        CASE
          WHEN (eva1.eval_type = 'TWO')
          THEN TO_CHAR (ADD_MONTHS (s.start_date, 4), 'YYYYMM')
          WHEN (eva1.eval_type = 'THREE')
          THEN TO_CHAR ( ADD_MONTHS ( TO_DATE ( eva1.eval_month
            || '/'
            || eva1.eval_year, 'MM/YYYY'), 2), 'YYYYMM')
          ELSE TO_CHAR ( ADD_MONTHS ( TO_DATE ( eva1.eval_month
            || '/'
            || eva1.eval_year, 'MM/YYYY'), 6), 'YYYYMM')
        END
      WHEN (eva1.status IS NULL)
      THEN FUNC_FES_EVALUATE_PERIOD (s.start_date, s.open_date, eva1.mm, eva1.yy, '1')
      ELSE eva1.eval_year
        || LPAD (eva1.eval_month, 2, '0')
    END AS period,
    CASE
      WHEN (eva1.status = 'DO')
      THEN
        CASE
          WHEN (eva1.eval_type = 'TWO')
            /*and (imp2.yy | imp2.mm between to_char(add_months(s.start_date,1),'YYMM') and to_char(add_months(s.start_date,4),'YYMM') )*/
          THEN TO_CHAR ( ADD_MONTHS (s.start_date, 1), 'FMMON YY', 'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
            || ' - '
            || TO_CHAR ( ADD_MONTHS (s.start_date, 3), 'FMMON YY', 'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
          WHEN (eva1.eval_type = 'THREE')
          AND (eva1.yy
            || eva1.mm BETWEEN TO_CHAR ( TO_DATE ( eva1.eval_month
            || '/'
            || eva1.eval_year, 'MM/YYYY'), 'YYMM')
          AND TO_CHAR ( ADD_MONTHS ( TO_DATE ( eva1.eval_month
            || '/'
            || eva1.eval_year, 'MM/YYYY'), 5), 'YYMM'))
          THEN TO_CHAR ( ADD_MONTHS ( s.start_date,
            CASE
              WHEN (ADD_MONTHS (s.start_date, 6) > TRUNC (ADD_MONTHS (s.start_date, 6), 'MM'))
              THEN 1
              ELSE 0
            END), 'FMMON YY', 'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
            || ' - '
            || TO_CHAR ( ADD_MONTHS (s.start_date, 5), 'FMMON YY', 'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
          WHEN (eva1.eval_type = 'MIDYEAR')
          AND (eva1.yy
            || eva1.mm BETWEEN TO_CHAR ( TO_DATE ( LPAD ( eva1.eval_month, 2, '0')
            || '/'
            || eva1.eval_year, 'MM/YYYY'), 'YYMM')
          AND TO_CHAR ( ADD_MONTHS ( TO_DATE ( LPAD ( eva1.eval_month, 2, '0')
            || '/'
            || eva1.eval_year, 'MM/YYYY'), 5), 'YYMM'))
          THEN TO_CHAR ( TO_DATE ( LPAD (eva1.eval_month, 2, '0')
            || '/'
            || eva1.eval_year, 'MM/YYYY'), 'FMMON YY', 'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
            || ' - '
            || TO_CHAR ( ADD_MONTHS ( TO_DATE ( LPAD (eva1.eval_month, 2, '0')
            || '/'
            || eva1.eval_year, 'MM/YYYY'), 5), 'FMMON YY', 'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
        END
      WHEN (eva1.status IS NULL)
      THEN FUNC_FES_EVALUATE_PERIOD (s.start_date, s.open_date, eva1.mm, eva1.yy, '2')
      ELSE
        CASE
          WHEN (eva1.eval_type = 'THREE')
          THEN TO_CHAR ( ADD_MONTHS ( TO_DATE ( LPAD (eva1.eval_month, 2, '0')
            || '/'
            || eva1.eval_year, 'MM/YYYY'), -3), 'FMMON YY', 'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
            || ' - '
            || TO_CHAR ( ADD_MONTHS ( TO_DATE ( LPAD (eva1.eval_month, 2, '0')
            || '/'
            || eva1.eval_year, 'MM/YYYY'), -1), 'FMMON YY', 'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
          WHEN (eva1.eval_type = 'MIDYEAR')
          THEN TO_CHAR ( ADD_MONTHS ( TO_DATE ( LPAD (eva1.eval_month, 2, '0')
            || '/'
            || eva1.eval_year, 'MM/YYYY'),
            CASE
              WHEN (ADD_MONTHS (s.start_date,                  +6)                   > TRUNC (ADD_MONTHS (s.start_date, +6), 'MM'))
              AND (TO_CHAR ( TRUNC ( ADD_MONTHS (s.start_date, +6), 'MM'), 'YYYYMM') = eva1.eval_year
                || LPAD (eva1.eval_month, 2, '0'))
              THEN -5
              ELSE -6
            END), 'FMMON YY', 'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
            || ' - '
            || TO_CHAR ( ADD_MONTHS ( TO_DATE ( LPAD (eva1.eval_month, 2, '0')
            || '/'
            || eva1.eval_year, 'MM/YYYY'), -1), 'FMMON YY', 'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
        END
    END AS eva_period
  FROM
    (SELECT s1.order_id,
      s1.parent_order_id,
      s1.store_id,
      s1.fr_type,
      s1.start_date,
      s1.open_date,
      s1.owner_id1,
      s1.owner_id2,
      s1.owner_id3,
      s1.owner_id4,
      s2.store_id AS parent_store_id
    FROM fr_store s1
    LEFT JOIN fr_store s2
    ON s2.order_id              = s1.parent_order_id
    WHERE NVL (s1.status, '-') != 'D'
    AND s1.cancel_date         IS NULL --order by s1.store_id
    ) s
  LEFT JOIN mas_store ms
  ON ms.branch_id = s.store_id
  LEFT JOIN common_code cc
  ON cc.code_type   = '00019'
  AND cc.code_value = s.fr_type
  INNER JOIN
    (SELECT eva1.*,
      imp1.yy,
      imp1.mm
    FROM fes_evaluate eva1
    INNER JOIN
      (SELECT fr_store_order_id,
        MAX ( TO_NUMBER ( eva.eval_year
        || LPAD ( eva.eval_month, 2, '0'))) AS max_eval_year_month
      FROM fes_evaluate eva
      WHERE TO_CHAR (eva.eval_type) IN ('TWO', 'THREE', 'MIDYEAR', 'YEAR') --exclude 'IMPROVE'
      AND NVL (eva.del_status, '-') != 'D'
      GROUP BY eva.fr_store_order_id
      ) eva2
    ON eva2.fr_store_order_id = eva1.fr_store_order_id
    AND eva1.eval_year
      || LPAD (eva1.eval_month, 2, '0') = eva2.max_eval_year_month
    LEFT JOIN
      (SELECT imp.fr_store_order_id,
        SUBSTR ( MAX ( TO_NUMBER ( imp.yy
        || imp.mm)), 1, 2) AS yy,
        SUBSTR ( MAX ( TO_NUMBER ( imp.yy
        || imp.mm)), 3) AS mm
      FROM fes_importdata imp
      WHERE TO_CHAR (imp.yy) BETWEEN TO_CHAR ( TRUNC ( TRUNC ( SYSDATE, 'Year') - 1, 'Year'), 'YY') AND TO_CHAR ( ADD_MONTHS ( TRUNC ( SYSDATE, 'Year'), 12), 'YY')
      GROUP BY imp.fr_store_order_id
      ) imp1
    ON imp1.fr_store_order_id        = eva1.fr_store_order_id
    ) eva1 ON eva1.fr_store_order_id = s.order_id;

-- ---------- VIEW: V_FES_EVALUATE_SUMMARY_WAIT_1 ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_FES_EVALUATE_SUMMARY_WAIT_1" ("STORE_ID", "STORE_NAME", "FR_TYPE_NAME", "FRANCHISEE_ID", "START_DATE", "EVALUATE_ID", "CUR_EVAL_TYPE", "CUR_EVAL_MONTH", "CUR_EVAL_YEAR", "STATUS", "FR_STORE_ORDER_ID", "CUR_IMPORTDATA_MM", "CUR_IMPORTDATA_YY", "EVAL_TYPE", "PERIOD", "EVA_PERIOD") AS 
  SELECT ms.branch_id AS store_id,
          ms.branch_name AS store_name,
          DECODE (ms.status_type,
                  'FPT1', 'Type ปตท.',
                  'FAM', 'Type A',
                  'FB1', 'Type B',
                  'FB2', 'Type พนักงาน',
                  'FC1', 'Type C',
                  'FBGC', 'Type BGC',
                  NULL)
             AS fr_type_name,
          s.owner_id1 AS franchisee_id,
          TO_CHAR (s.start_date, 'DD/MM/YYYY') AS start_date,
          eva1.evaluate_id,
          eva1.eval_type AS cur_eval_type,
          eva1.eval_month AS cur_eval_month,
          eva1.eval_year AS cur_eval_year,
          eva1.status,
          eva1.fr_store_order_id,
          eva1.mm AS cur_importdata_mm,
          eva1.yy AS cur_importdata_yy,
          CASE
             WHEN (eva1.status = 'DO')
             THEN
                CASE
                   WHEN (eva1.eval_type = 'TWO') THEN 'THREE'
                   ELSE 'MIDYEAR'
                END
             WHEN (eva1.status IS NULL)
             THEN
                'MIDYEAR'
             ELSE
                TO_CHAR (eva1.eval_type)
          END
             AS eval_type,
          CASE
             WHEN (eva1.status = 'DO')
             THEN
                CASE
                   WHEN (eva1.eval_type = 'TWO')
                   THEN
                      TO_CHAR (ADD_MONTHS (s.start_date, 4), 'YYYYMM')
                   WHEN (eva1.eval_type = 'THREE')
                   THEN
                      TO_CHAR (
                         ADD_MONTHS (
                            TO_DATE (
                               eva1.eval_month || '/' || eva1.eval_year,
                               'MM/YYYY'),
                            2),
                         'YYYYMM')
                   ELSE
                      TO_CHAR (
                         ADD_MONTHS (
                            TO_DATE (
                               eva1.eval_month || '/' || eva1.eval_year,
                               'MM/YYYY'),
                            6),
                         'YYYYMM')
                END
             WHEN (eva1.status IS NULL)
             THEN
                FUNC_FES_EVALUATE_PERIOD (s.start_date,
                                          s.open_date,
                                          eva1.mm,
                                          eva1.yy,
                                          '1')
             ELSE
                eva1.eval_year || LPAD (eva1.eval_month, 2, '0')
          END
             AS period,
          CASE
             WHEN (eva1.status = 'DO')
             THEN
                CASE
                   WHEN (eva1.eval_type = 'TWO') /*and (imp2.yy | imp2.mm between to_char(add_months(s.start_date,1),'YYMM') and to_char(add_months(s.start_date,4),'YYMM') )*/
                   THEN
                      TO_CHAR (
                         ADD_MONTHS (s.start_date, 1),
                         'FMMON YY',
                         'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                      || ' - '
                      || TO_CHAR (
                            ADD_MONTHS (s.start_date, 3),
                            'FMMON YY',
                            'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                   WHEN (eva1.eval_type = 'THREE')
                        AND (eva1.yy || eva1.mm BETWEEN TO_CHAR (
                                                           TO_DATE (
                                                              eva1.eval_month
                                                              || '/'
                                                              || eva1.eval_year,
                                                              'MM/YYYY'),
                                                           'YYMM')
                                                    AND TO_CHAR (
                                                           ADD_MONTHS (
                                                              TO_DATE (
                                                                 eva1.eval_month
                                                                 || '/'
                                                                 || eva1.eval_year,
                                                                 'MM/YYYY'),
                                                              5),
                                                           'YYMM'))
                   THEN
                      TO_CHAR (
                         ADD_MONTHS (
                            s.start_date,
                            CASE
                               WHEN (ADD_MONTHS (s.start_date, 6) >
                                        TRUNC (ADD_MONTHS (s.start_date, 6),
                                               'MM'))
                               THEN
                                  1
                               ELSE
                                  0
                            END),
                         'FMMON YY',
                         'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                      || ' - '
                      || TO_CHAR (
                            ADD_MONTHS (s.start_date, 5),
                            'FMMON YY',
                            'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                   WHEN (eva1.eval_type = 'MIDYEAR')
                        AND (eva1.yy || eva1.mm BETWEEN TO_CHAR (
                                                           TO_DATE (
                                                              LPAD (
                                                                 eva1.eval_month,
                                                                 2,
                                                                 '0')
                                                              || '/'
                                                              || eva1.eval_year,
                                                              'MM/YYYY'),
                                                           'YYMM')
                                                    AND TO_CHAR (
                                                           ADD_MONTHS (
                                                              TO_DATE (
                                                                 LPAD (
                                                                    eva1.eval_month,
                                                                    2,
                                                                    '0')
                                                                 || '/'
                                                                 || eva1.eval_year,
                                                                 'MM/YYYY'),
                                                              5),
                                                           'YYMM'))
                   THEN
                      TO_CHAR (
                         TO_DATE (
                               LPAD (eva1.eval_month, 2, '0')
                            || '/'
                            || eva1.eval_year,
                            'MM/YYYY'),
                         'FMMON YY',
                         'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                      || ' - '
                      || TO_CHAR (
                            ADD_MONTHS (
                               TO_DATE (
                                     LPAD (eva1.eval_month, 2, '0')
                                  || '/'
                                  || eva1.eval_year,
                                  'MM/YYYY'),
                               5),
                            'FMMON YY',
                            'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                END
             WHEN (eva1.status IS NULL)
             THEN
                FUNC_FES_EVALUATE_PERIOD (s.start_date,
                                          s.open_date,
                                          eva1.mm,
                                          eva1.yy,
                                          '2')
             ELSE
                CASE
                   WHEN (eva1.eval_type = 'THREE')
                   THEN
                      TO_CHAR (
                         ADD_MONTHS (
                            TO_DATE (
                                  LPAD (eva1.eval_month, 2, '0')
                               || '/'
                               || eva1.eval_year,
                               'MM/YYYY'),
                            -3),
                         'FMMON YY',
                         'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                      || ' - '
                      || TO_CHAR (
                            ADD_MONTHS (
                               TO_DATE (
                                     LPAD (eva1.eval_month, 2, '0')
                                  || '/'
                                  || eva1.eval_year,
                                  'MM/YYYY'),
                               -1),
                            'FMMON YY',
                            'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                   WHEN (eva1.eval_type = 'MIDYEAR')
                   THEN
                      TO_CHAR (
                         ADD_MONTHS (
                            TO_DATE (
                                  LPAD (eva1.eval_month, 2, '0')
                               || '/'
                               || eva1.eval_year,
                               'MM/YYYY'),
                            CASE
                               WHEN (ADD_MONTHS (s.start_date, +6) >
                                        TRUNC (ADD_MONTHS (s.start_date, +6),
                                               'MM'))
                                    AND (TO_CHAR (
                                            TRUNC (
                                               ADD_MONTHS (s.start_date, +6),
                                               'MM'),
                                            'YYYYMM') =
                                            eva1.eval_year
                                            || LPAD (eva1.eval_month, 2, '0'))
                               THEN
                                  -5
                               ELSE
                                  -6
                            END),
                         'FMMON YY',
                         'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                      || ' - '
                      || TO_CHAR (
                            ADD_MONTHS (
                               TO_DATE (
                                     LPAD (eva1.eval_month, 2, '0')
                                  || '/'
                                  || eva1.eval_year,
                                  'MM/YYYY'),
                               -1),
                            'FMMON YY',
                            'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                END
          END
             AS eva_period
     FROM (SELECT s1.order_id,
                  s1.parent_order_id,
                  s1.store_id,
                  s1.fr_type,
                  s1.start_date,
                  s1.open_date,
                  s1.owner_id1,
                  s2.store_id AS parent_store_id
             FROM    fr_store s1
                  LEFT JOIN
                     fr_store s2
                  ON s2.order_id = s1.parent_order_id
            WHERE NVL (s1.status, '-') != 'D' AND s1.cancel_date IS NULL --order by s1.store_id
                                                                        ) s
          LEFT JOIN mas_store ms
             ON ms.branch_id = s.store_id
          LEFT JOIN common_code cc
             ON cc.code_type = '00019' AND cc.code_value = s.fr_type
          INNER JOIN (SELECT eva1.*, imp1.yy, imp1.mm
                        FROM fes_evaluate eva1
                             INNER JOIN (  SELECT fr_store_order_id,
                                                  MAX (
                                                     TO_NUMBER (
                                                        eva.eval_year
                                                        || LPAD (
                                                              eva.eval_month,
                                                              2,
                                                              '0')))
                                                     AS max_eval_year_month
                                             FROM fes_evaluate eva
                                            WHERE TO_CHAR (eva.eval_type) IN
                                                     ('TWO',
                                                      'THREE',
                                                      'MIDYEAR',
                                                      'YEAR') --exclude 'IMPROVE'
                                                  AND NVL (eva.del_status, '-') !=
                                                         'D'
                                         GROUP BY eva.fr_store_order_id) eva2
                                ON eva2.fr_store_order_id =
                                      eva1.fr_store_order_id
                                   AND eva1.eval_year
                                       || LPAD (eva1.eval_month, 2, '0') =
                                          eva2.max_eval_year_month
                             LEFT JOIN (  SELECT imp.fr_store_order_id,
                                                 SUBSTR (
                                                    MAX (
                                                       TO_NUMBER (
                                                          imp.yy || imp.mm)),
                                                    1,
                                                    2)
                                                    AS yy,
                                                 SUBSTR (
                                                    MAX (
                                                       TO_NUMBER (
                                                          imp.yy || imp.mm)),
                                                    3)
                                                    AS mm
                                            FROM fes_importdata imp
                                           WHERE TO_CHAR (imp.yy) BETWEEN TO_CHAR (
                                                                             TRUNC (
                                                                                TRUNC (
                                                                                   SYSDATE,
                                                                                   'Year')
                                                                                - 1,
                                                                                'Year'),
                                                                             'YY')
                                                                      AND TO_CHAR (
                                                                             ADD_MONTHS (
                                                                                TRUNC (
                                                                                   SYSDATE,
                                                                                   'Year'),
                                                                                12),
                                                                             'YY')
                                        GROUP BY imp.fr_store_order_id) imp1
                                ON imp1.fr_store_order_id =
                                      eva1.fr_store_order_id) eva1
             ON eva1.fr_store_order_id = s.order_id;

-- ---------- VIEW: V_FES_IMPORTDATA ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_FES_IMPORTDATA" ("ORDER_ID", "STORE_ID", "ROOT_ORDER_ID", "STORE_NAME", "STORE_TYPE", "START_DATE", "FR_START_DATE", "OPEN_DATE", "FR_STORE_ORDER_ID", "IMPORTDATA_STORE_ID", "IMPORT_ID", "FIRST_IMPORT_ID", "TITLE_ID", "GOAL_GET", "MM", "YY", "TOP_VALUE", "BOTTOM_VALUE", "TITLE", "POINT") AS 
  SELECT s1.order_id,
          s1.store_id,
          imp.root_order_id,
          ms.branch_name AS store_name,
          DECODE (ms.status_type,
                  'FPT1', 'Type ปตท.',
                  'FAM', 'Type A',
                  'FB1', 'Type B',
                  'FB2', 'Type พนักงาน',
                  'FC1', 'Type C',
                  NULL)
             AS store_type,
          TO_CHAR (s1.start_date,
                   'FMMON YY',
                   'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
             AS start_date,
          s1.start_date AS fr_start_date,
          s1.open_date,
          imp.fr_store_order_id,
          imp.importdata_store_id,
          imp.import_id,
          imp.first_import_id,
          imp.title_id,
          imp.goal_get,
          imp.mm,
          imp.yy,
          imp.top_value,
          imp.bottom_value,
          lv3.levelthree_name AS title,
          lv3.point
     FROM fr_store s1
          LEFT JOIN mas_store ms
             ON ms.branch_id = s1.store_id
          INNER JOIN (SELECT s2.*,
                             imp.import_id,
                             title_id,
                             imp.goal_get,
                             imp.mm,
                             imp.yy,
                             imp.branch_id AS importdata_store_id,
                             imp.top_value,
                             imp.bottom_value,
                             imp.status,
                             imp.fr_store_order_id,
                             FIRST_VALUE (
                                imp.import_id)
                             OVER (
                                PARTITION BY s2.store_id,
                                             imp.title_id,
                                             imp.goal_get,
                                             imp.yy,
                                             imp.mm
                                ORDER BY import_id DESC)
                                first_import_id
                        FROM fr_store s1
                             INNER JOIN (           SELECT s.store_id,
                                                           s.order_id,
                                                           NVL (s.parent_order_id,
                                                                s.order_id)
                                                              AS parent_order_id,
                                                           CONNECT_BY_ROOT s.order_id
                                                              AS root_order_id,
                                                           LEVEL AS root_level,
                                                           SYS_CONNECT_BY_PATH (
                                                              s.order_id,
                                                              '/')
                                                           || '/'
                                                              AS root_path
                                                      FROM fr_store s
                                                START WITH s.parent_order_id IS NULL
                                                CONNECT BY PRIOR s.order_id =
                                                              s.parent_order_id
                                         ORDER SIBLINGS BY s.parent_order_id) s2
                                ON     s2.order_id = s1.order_id
                                   AND NVL (s1.status, '-') != 'D'
                                   AND s1.cancel_date IS NULL
                             --and s1.store_id = '09088'
                             INNER JOIN (SELECT s.order_id, imp.*
                                           FROM    fes_importdata imp
                                                INNER JOIN
                                                   fr_store s
                                                ON s.store_id = imp.branch_id
                                                   AND imp.status = 'Y' --and imp.yy || imp.mm between '1301' and '1306'
                                                                       ) imp
                                ON INSTR (s2.root_path,
                                          '/' || imp.order_id || '/') > 0) imp
             ON     imp.order_id = s1.order_id
                AND NVL (s1.status, '-') != 'D'
                AND s1.cancel_date IS NULL
                AND imp.import_id = imp.first_import_id
          INNER JOIN fes_title t
             ON t.title_id = imp.title_id AND t.title_id > 0
          INNER JOIN fes_evallevelthree lv3
             ON lv3.levelthree_name = t.title AND lv3.evalleveltwo_id = 31;

-- ---------- VIEW: V_FES_RENEWAL ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_FES_RENEWAL" ("FRANCHISEE_ID", "OWNER_ID2", "OWNER_ID3", "OWNER_ID4", "STORE_ID", "STORE_NAME", "FR_TYPE", "FR_TYPE_NAME", "START_DATE", "CONTRACT_START_DATE", "CONTRACT_END_DATE", "CED_CHECK", "EXTEND_ROUND", "EVA_END_MONTH", "EVA_END_YEAR", "EVAL_PERIOD", "PERCENT_RENEWAL_POINT", "GRADE", "CONTRACT_AGE", "FEE", "CONTRACT_END_MONTH", "CONTRACT_END_YEAR", "START_MONTH", "MONTH_EVA", "FRANCHISE_AGE") AS 
  SELECT fe.franchisee_id,
    fe.owner_id2,
    fe.owner_id3,
    fe.owner_id4,
    fe.store_id,
    fe.store_name,
    fe.fr_type,
    fe.fr_type_name,
    fe.start_date,
    fe.contract_start_date,
    TO_CHAR (fe.contract_end_date, 'DD/MM/YYYY', 'NLS_CALENDAR=''Thai Buddha'' NLS_DATE_LANGUAGE=THAI') AS contract_end_date,
    fe.contract_end_date                                                                                AS ced_check,
    ' (ครั้งที่ '
    || FUNC_RENEWAL_ROUND (fe.start_date, fe.contract_end_date, scp.period_all)
    || ')' EXTEND_ROUND,
    fe.eval_month AS eva_end_month,
    fe.eva_end_year,
    TO_CHAR (TO_DATE (fe.eva_start_year, 'YYYY'), 'YYYY', 'NLS_CALENDAR=''Thai Buddha'' NLS_DATE_LANGUAGE=THAI')
    || ' (ครั้งที่ '
    || DECODE (FLOOR (fe.eval_month / 7), 0, 1, 2)
    || ') - '
    || TO_CHAR (TO_DATE (fe.eva_end_year, 'YYYY'), 'YYYY', 'NLS_CALENDAR=''Thai Buddha'' NLS_DATE_LANGUAGE=THAI')
    || ' (ครั้งที่ '
    || fe.eva_end_round
    || ')' AS eval_period,
    --            fe.point,
    --            fe.total_point,
    ROUND (fe.percent_renewal_point, 2) AS percent_renewal_point,
    --            TO_CHAR (ROUND ( (fe.point / fe.total_point) * 100, 2), '9999.99')
    --               AS percent_renewal_point,
    CASE
      WHEN ROUND (fe.percent_renewal_point, 2) BETWEEN 90 AND 100
      THEN 'E'
      WHEN ROUND (fe.percent_renewal_point, 2) BETWEEN 80 AND 89.99
      THEN 'G'
      WHEN ROUND (fe.percent_renewal_point, 2) BETWEEN 70 AND 79.99
      THEN 'P'
      WHEN ROUND (fe.percent_renewal_point, 2) BETWEEN 60 AND 69.99
      THEN 'I'
      ELSE 'F'
    END        AS grade,
    scp.period AS contract_age,
    --            CASE
    --               WHEN (fe.fr_type = 'B' OR fe.fr_type = 'EMP')
    --                    AND scp.contract_no = 2
    --               THEN
    --                  '150,000.00'
    --               WHEN fe.fr_type = 'PTT'
    --               THEN
    --                  'ค่าธรรมเนียมเป็นไปตามเงื่อนไขที่บริษัทกำหนด'
    --               ELSE
    --                  CASE
    --                     WHEN ROUND (fe.percent_renewal_point, 2) BETWEEN 90
    --                                                                            AND 100
    --                     THEN
    --                        'ไม่มีค่าธรรมเนียม'
    --                     WHEN ROUND (fe.percent_renewal_point, 2) BETWEEN 80
    --                                                                            AND 89.99
    --                     THEN
    --                        '100,000.00'
    --                     WHEN ROUND (fe.percent_renewal_point, 2) BETWEEN 70
    --                                                                            AND 79.99
    --                     THEN
    --                        '200,000.00'
    --                     WHEN ROUND (fe.percent_renewal_point, 2) BETWEEN 60
    --                                                                            AND 69.99
    --                     THEN
    --                        '250,000.00'
    --                     ELSE
    --                        '250,000.00'
    --                  END
    --            END
    --               AS fee,
    scf.fee,
    TO_CHAR (fe.contract_end_date, 'MM')   AS contract_end_month,
    TO_CHAR (fe.contract_end_date, 'YYYY') AS contract_end_year,
    TO_CHAR (fe.start_date, 'MM')          AS start_month,
    fe.month_eva,
    TRUNC ( TRUNC (MONTHS_BETWEEN (fe.contract_end_date, fe.start_date)) / 12) AS franchise_age
  FROM
    (SELECT a.*,
      MAX (a.eva_end_round_tmp) OVER (PARTITION BY a.order_id) AS eva_end_round,
      MAX (a.eva_start_year) OVER (PARTITION BY a.order_id)    AS eva_end_year,
      --                       SUM (
      --                          a.eva_point)
      --                       OVER (PARTITION BY a.order_id
      --                             ORDER BY a.eva_start_year DESC, a.eval_month DESC
      --                             ROWS BETWEEN UNBOUNDED PRECEDING AND 0 PRECEDING)
      --                          AS point,
      --                       SUM (
      --                          a.eva_total_point)
      --                       OVER (PARTITION BY a.order_id
      --                             ORDER BY a.eva_start_year DESC, a.eval_month DESC
      --                             ROWS BETWEEN UNBOUNDED PRECEDING AND 0 PRECEDING)
      --                          AS total_point,
      AVG ( ( (a.eva_point * 100) / a.eva_total_point)) OVER (PARTITION BY a.order_id ORDER BY a.eva_start_year DESC, a.eval_month DESC ROWS BETWEEN UNBOUNDED PRECEDING AND 0 PRECEDING) AS percent_renewal_point
    FROM
      (SELECT eva.evaluate_id,
        eva.order_id,
        eva.eval_year AS eva_start_year,
        eva.eval_month,
        eva.total_point AS eva_point,
        CASE
          WHEN FLOOR ( (SUBSTR ( MAX ( TO_NUMBER (eva.eval_year)
            || TO_NUMBER (eva.eval_month)) OVER ( PARTITION BY eva.order_id ORDER BY eva.order_id, eva.eval_year DESC, eva.eval_month DESC), 5, 2)) / 7) = 0
          THEN 1
          ELSE 2
        END eva_end_round_tmp,
        s1.store_id,
        ms.branch_name                                                                                                AS store_name,
        DECODE (ms.status_type, 'FPT1', 'PTT', 'FAM', 'A', 'FB1', 'B', 'FB2', 'EMP', 'FC1', 'C', 'FBGC', 'BGC', NULL) AS fr_type,
        s1.contract_start_date,
        s1.contract_end_date,
        s1.owner_id1 AS franchisee_id,
        s1.owner_id2,
        s1.owner_id3,
        s1.owner_id4,
        s1.start_date,
        CEIL ( (SYSDATE - s1.transfer_date) / 365) + 1 AS fz_age,
        SUM (
        CASE
          WHEN eva.eval_type = 'MIDYEAR'
          THEN 6
          WHEN eva.eval_type = 'YEAR'
          THEN 12
          ELSE 0
        END) OVER ( PARTITION BY eva.order_id ORDER BY eva.order_id, eva.eval_year DESC, eva.eval_month DESC)                                            AS month_eva,
        frm.total_point                                                                                                                                  AS eva_total_point,
        DECODE (ms.status_type, 'FPT1', 'Type ปตท.', 'FAM', 'Type A', 'FB1', 'Type B', 'FB2', 'Type พนักงาน', 'FC1', 'Type C', 'FBGC', 'Type BGC', NULL) AS fr_type_name
      FROM
        (SELECT a.evaluate_id,
          a.eval_type,
          a.eval_month,
          a.eval_year,
          DECODE (b.grade, NULL, a.grade, b.grade)                   AS grade,
          DECODE (b.total_point, NULL, a.total_point, b.total_point) AS total_point,
          a.status,
          a.order_id
        FROM
          (SELECT *
          FROM
            (SELECT eva.fr_store_order_id,
              eva.evaluate_id,
              eva.eval_type,
              eva.eval_month,
              eva.eval_year,
              eva.grade,
              eva.total_point,
              eva.status,
              s.order_id,
              eva.order_id                                                                                                                               AS store_id,
              DENSE_RANK () OVER ( PARTITION BY eva.eval_type, eva.eval_month, eva.eval_year, s.order_id ORDER BY eva.evaluate_id DESC, s.order_id DESC) AS row_rank
            FROM fes_evaluate eva
            INNER JOIN
              (
              /*=====merge related evaluate=====*/
              SELECT *
              FROM
                (SELECT order_id,
                  contract_end_date,
                  REGEXP_SUBSTR ( SUBSTR ( root_path, 2), ',?([^,]*)', 1, LEVEL, 'i', 1) AS ref_order_id
                FROM
                  (SELECT s.order_id,
                    s.contract_end_date, --s.store_id, s.start_date, s.parent_order_id, s.contract_end_date, s.transfer_date,
                    SYS_CONNECT_BY_PATH ( s.order_id, ',') AS root_path
                  FROM fr_store s
                  WHERE store_id                 != '00000'
                  AND (s.status                  IS NULL
                  OR s.status                    != 'D')
                  AND s.cancel_date              IS NULL
                    START WITH s.parent_order_id IS NULL
                    CONNECT BY PRIOR s.order_id   = s.parent_order_id
                  )
                  CONNECT BY (REGEXP_COUNT ( root_path, ',') + 1 >= LEVEL
                AND PRIOR order_id                                = order_id
                AND PRIOR DBMS_RANDOM.VALUE                      IS NOT NULL)
                )
              WHERE ref_order_id IS NOT NULL
              ) s
            ON s.ref_order_id = eva.fr_store_order_id
              --                                                      and NVL (eva.del_status, '-') != 'D'
            AND eva.status = 'DO'
              /*confirm status must 'DO' only*/
            AND (eva.eval_type = 'MIDYEAR'
            OR eva.eval_type   = 'YEAR')
            AND eva.eval_year >= TO_NUMBER ( TO_CHAR ( ADD_MONTHS ( SYSDATE, -72), 'YYYY'))
              /*display data backward 6 years*/
            AND eva.eval_year >= 2010
              /*minimum year for display is 2010*/
            AND ADD_MONTHS ( TO_DATE ( eva.eval_year
              || eva.eval_month, 'YYYYMM'), -1) <= ADD_MONTHS ( s.contract_end_date, -12)
            )
          WHERE row_rank = 1
        --       and store_id = 07871
         ) a
        LEFT JOIN fes_adjust_grade b
        ON a.eval_type   = 'MIDYEAR'
        AND a.store_id   = b.store_id
        AND b.eval_year  = a.eval_year
        AND b.eval_month = a.eval_month
        ) eva
      INNER JOIN fes_evaluatedform frm
      ON TO_NUMBER ( eva.eval_year
        || LPAD (eva.eval_month, 2, 0)) BETWEEN TO_NUMBER ( (frm.start_year)
        || LPAD ( frm.start_month, 2, 0))
      AND TO_NUMBER ( (frm.end_year)
        || LPAD ( frm.end_month, 2, 0))
      OR (TO_NUMBER ( eva.eval_year
        || LPAD (eva.eval_month, 2, 0)) >= TO_NUMBER ( (start_year)
        || LPAD (start_month, 2, 0))
      AND frm.end_month IS NULL
      AND frm.end_year  IS NULL)
      INNER JOIN fr_store s1
      ON s1.order_id = eva.order_id
      LEFT JOIN mas_store ms
      ON ms.branch_id      = s1.store_id
      WHERE eva.eval_month = TO_CHAR (s1.start_date, 'MM')
      OR eva.eval_month    = TO_CHAR (ADD_MONTHS (s1.start_date, 6), 'MM')
      ) a
    ) fe
  INNER JOIN setup_contract_period scp
  ON scp.fr_type = fe.fr_type
  AND fe.fz_age BETWEEN scp.fr_age_start AND scp.fr_age_end
  INNER JOIN setup_contract_fee scf
  ON scf.fr_type = scp.fr_type
  AND fe.percent_renewal_point BETWEEN scf.start_point AND scf.end_point
  AND FUNC_RENEWAL_ROUND (fe.start_date, fe.contract_end_date, scp.period_all) BETWEEN scf.contract_no_start AND scf.contract_no_end
  WHERE fe.month_eva = 36
  ORDER BY fe.ORDER_ID,
    fe.EVA_START_YEAR DESC,
    fe.EVAL_MONTH DESC;

-- ---------- VIEW: V_FES_RENEWAL_20170202 ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_FES_RENEWAL_20170202" ("FRANCHISEE_ID", "STORE_ID", "STORE_NAME", "FR_TYPE", "FR_TYPE_NAME", "START_DATE", "CONTRACT_START_DATE", "CONTRACT_END_DATE", "CED_CHECK", "EXTEND_ROUND", "EVA_END_MONTH", "EVA_END_YEAR", "EVAL_PERIOD", "PERCENT_RENEWAL_POINT", "GRADE", "CONTRACT_AGE", "FEE", "CONTRACT_END_MONTH", "CONTRACT_END_YEAR", "START_MONTH", "MONTH_EVA", "FRANCHISE_AGE") AS 
  SELECT fe.franchisee_id,
            fe.store_id,
            fe.store_name,
            fe.fr_type,
            fe.fr_type_name,
            fe.start_date,
            fe.contract_start_date,
            TO_CHAR (fe.contract_end_date,
                     'DD/MM/YYYY',
                     'NLS_CALENDAR=''Thai Buddha'' NLS_DATE_LANGUAGE=THAI')
               AS contract_end_date,
            fe.contract_end_date AS ced_check,
            ' (ครั้งที่ '
            || FUNC_RENEWAL_ROUND (fe.start_date,
                                   fe.contract_end_date,
                                   scp.period_all)
            || ')'
               EXTEND_ROUND,
            fe.eval_month AS eva_end_month,
            fe.eva_end_year,
            TO_CHAR (TO_DATE (fe.eva_start_year, 'YYYY'),
                     'YYYY',
                     'NLS_CALENDAR=''Thai Buddha'' NLS_DATE_LANGUAGE=THAI')
            || ' (ครั้งที่ '
            || DECODE (FLOOR (fe.eval_month / 7), 0, 1, 2)
            || ') - '
            || TO_CHAR (TO_DATE (fe.eva_end_year, 'YYYY'),
                        'YYYY',
                        'NLS_CALENDAR=''Thai Buddha'' NLS_DATE_LANGUAGE=THAI')
            || ' (ครั้งที่ '
            || fe.eva_end_round
            || ')'
               AS eval_period,
            --            fe.point,
            --            fe.total_point,

            ROUND (fe.percent_renewal_point, 2) AS percent_renewal_point,
            --            TO_CHAR (ROUND ( (fe.point / fe.total_point) * 100, 2), '9999.99')
            --               AS percent_renewal_point,
            CASE
               WHEN ROUND (fe.percent_renewal_point, 2) BETWEEN 90 AND 100
               THEN
                  'E'
               WHEN ROUND (fe.percent_renewal_point, 2) BETWEEN 80 AND 89.99
               THEN
                  'G'
               WHEN ROUND (fe.percent_renewal_point, 2) BETWEEN 70 AND 79.99
               THEN
                  'P'
               WHEN ROUND (fe.percent_renewal_point, 2) BETWEEN 60 AND 69.99
               THEN
                  'I'
               ELSE
                  'F'
            END
               AS grade,
            scp.period AS contract_age,
            --            CASE
            --               WHEN (fe.fr_type = 'B' OR fe.fr_type = 'EMP')
            --                    AND scp.contract_no = 2
            --               THEN
            --                  '150,000.00'
            --               WHEN fe.fr_type = 'PTT'
            --               THEN
            --                  'ค่าธรรมเนียมเป็นไปตามเงื่อนไขที่บริษัทกำหนด'
            --               ELSE
            --                  CASE
            --                     WHEN ROUND (fe.percent_renewal_point, 2) BETWEEN 90
            --                                                                            AND 100
            --                     THEN
            --                        'ไม่มีค่าธรรมเนียม'
            --                     WHEN ROUND (fe.percent_renewal_point, 2) BETWEEN 80
            --                                                                            AND 89.99
            --                     THEN
            --                        '100,000.00'
            --                     WHEN ROUND (fe.percent_renewal_point, 2) BETWEEN 70
            --                                                                            AND 79.99
            --                     THEN
            --                        '200,000.00'
            --                     WHEN ROUND (fe.percent_renewal_point, 2) BETWEEN 60
            --                                                                            AND 69.99
            --                     THEN
            --                        '250,000.00'
            --                     ELSE
            --                        '250,000.00'
            --                  END
            --            END
            --               AS fee,

            scf.fee,
            TO_CHAR (fe.contract_end_date, 'MM') AS contract_end_month,
            TO_CHAR (fe.contract_end_date, 'YYYY') AS contract_end_year,
            TO_CHAR (fe.start_date, 'MM') AS start_month,
            fe.month_eva,
            TRUNC (
               TRUNC (MONTHS_BETWEEN (fe.contract_end_date, fe.start_date))
               / 12)
               AS franchise_age
       FROM (SELECT a.*,
                    MAX (a.eva_end_round_tmp) OVER (PARTITION BY a.order_id)
                       AS eva_end_round,
                    MAX (a.eva_start_year) OVER (PARTITION BY a.order_id)
                       AS eva_end_year,
                    --                       SUM (
                    --                          a.eva_point)
                    --                       OVER (PARTITION BY a.order_id
                    --                             ORDER BY a.eva_start_year DESC, a.eval_month DESC
                    --                             ROWS BETWEEN UNBOUNDED PRECEDING AND 0 PRECEDING)
                    --                          AS point,
                    --                       SUM (
                    --                          a.eva_total_point)
                    --                       OVER (PARTITION BY a.order_id
                    --                             ORDER BY a.eva_start_year DESC, a.eval_month DESC
                    --                             ROWS BETWEEN UNBOUNDED PRECEDING AND 0 PRECEDING)
                    --                          AS total_point,


                    AVG (
                       ( (a.eva_point * 100) / a.eva_total_point))
                    OVER (PARTITION BY a.order_id
                          ORDER BY a.eva_start_year DESC, a.eval_month DESC
                          ROWS BETWEEN UNBOUNDED PRECEDING AND 0 PRECEDING)
                       AS percent_renewal_point
               FROM (SELECT eva.evaluate_id,
                            eva.order_id,
                            eva.eval_year AS eva_start_year,
                            eva.eval_month,
                            eva.total_point AS eva_point,
                            CASE
                               WHEN FLOOR (
                                       (SUBSTR (
                                           MAX (
                                              TO_NUMBER (eva.eval_year)
                                              || TO_NUMBER (eva.eval_month))
                                           OVER (
                                              PARTITION BY eva.order_id
                                              ORDER BY
                                                 eva.order_id,
                                                 eva.eval_year DESC,
                                                 eva.eval_month DESC),
                                           5,
                                           2))
                                       / 7) = 0
                               THEN
                                  1
                               ELSE
                                  2
                            END
                               eva_end_round_tmp,
                            s1.store_id,
                            ms.branch_name AS store_name,
                            DECODE (ms.status_type,
                                    'FPT1', 'PTT',
                                    'FAM', 'A',
                                    'FB1', 'B',
                                    'FB2', 'EMP',
                                    'FC1', 'C',
                                    'FBGC', 'BGC',
                                    NULL)
                               AS fr_type,
                            s1.contract_start_date,
                            s1.contract_end_date,
                            s1.owner_id1 AS franchisee_id,
                            s1.start_date,
                            CEIL ( (SYSDATE - s1.transfer_date) / 365) + 1
                               AS fz_age,
                            SUM (
                               CASE
                                  WHEN eva.eval_type = 'MIDYEAR' THEN 6
                                  WHEN eva.eval_type = 'YEAR' THEN 12
                                  ELSE 0
                               END)
                            OVER (
                               PARTITION BY eva.order_id
                               ORDER BY
                                  eva.order_id,
                                  eva.eval_year DESC,
                                  eva.eval_month DESC)
                               AS month_eva,
                            frm.total_point AS eva_total_point,
                            DECODE (ms.status_type,
                                    'FPT1', 'Type ปตท.',
                                    'FAM', 'Type A',
                                    'FB1', 'Type B',
                                    'FB2', 'Type พนักงาน',
                                    'FC1', 'Type C',
                                    'FBGC', 'Type BGC',
                                    NULL)
                               AS fr_type_name
                       FROM (SELECT a.evaluate_id,
                                    a.eval_type,
                                    a.eval_month,
                                    a.eval_year,
                                    DECODE (b.grade, NULL, a.grade, b.grade)
                                       AS grade,
                                    DECODE (b.total_point,
                                            NULL, a.total_point,
                                            b.total_point)
                                       AS total_point,
                                    a.status,
                                    a.order_id
                               FROM    (SELECT *
                                          FROM (SELECT eva.fr_store_order_id,
                                                       eva.evaluate_id,
                                                       eva.eval_type,
                                                       eva.eval_month,
                                                       eva.eval_year,
                                                       eva.grade,
                                                       eva.total_point,
                                                       eva.status,
                                                       s.order_id,
                                                       eva.order_id AS store_id,
                                                       DENSE_RANK ()
                                                       OVER (
                                                          PARTITION BY eva.eval_type,
                                                                       eva.eval_month,
                                                                       eva.eval_year,
                                                                       s.order_id
                                                          ORDER BY
                                                             eva.evaluate_id DESC,
                                                             s.order_id DESC)
                                                          AS row_rank
                                                  FROM    fes_evaluate eva
                                                       INNER JOIN
                                                          ( /*=====merge related evaluate=====*/
                                                           SELECT *
                                                             FROM (    SELECT order_id,
                                                                              contract_end_date,
                                                                              REGEXP_SUBSTR (
                                                                                 SUBSTR (
                                                                                    root_path,
                                                                                    2),
                                                                                 ',?([^,]*)',
                                                                                 1,
                                                                                 LEVEL,
                                                                                 'i',
                                                                                 1)
                                                                                 AS ref_order_id
                                                                         FROM (    SELECT s.order_id,
                                                                                          s.contract_end_date, --s.store_id, s.start_date, s.parent_order_id, s.contract_end_date, s.transfer_date,
                                                                                          SYS_CONNECT_BY_PATH (
                                                                                             s.order_id,
                                                                                             ',')
                                                                                             AS root_path
                                                                                     FROM fr_store s
                                                                                    WHERE store_id !=
                                                                                             '00000'
                                                                                          AND (s.status
                                                                                                  IS NULL
                                                                                               OR s.status !=
                                                                                                     'D')
                                                                                          AND s.cancel_date
                                                                                                 IS NULL
                                                                               START WITH s.parent_order_id
                                                                                             IS NULL
                                                                               CONNECT BY PRIOR s.order_id =
                                                                                             s.parent_order_id)
                                                                   CONNECT BY (REGEXP_COUNT (
                                                                                  root_path,
                                                                                  ',')
                                                                               + 1 >=
                                                                                  LEVEL
                                                                               AND PRIOR order_id =
                                                                                      order_id
                                                                               AND PRIOR DBMS_RANDOM.VALUE
                                                                                      IS NOT NULL))
                                                            WHERE ref_order_id
                                                                     IS NOT NULL) s
                                                       ON s.ref_order_id =
                                                             eva.fr_store_order_id
                                                          --                                                      and NVL (eva.del_status, '-') != 'D'
                                                          AND eva.status = 'DO' /*confirm status must 'DO' only*/
                                                          AND (eva.eval_type =
                                                                  'MIDYEAR'
                                                               OR eva.eval_type =
                                                                     'YEAR')
                                                          AND eva.eval_year >=
                                                                 TO_NUMBER (
                                                                    TO_CHAR (
                                                                       ADD_MONTHS (
                                                                          SYSDATE,
                                                                          -72),
                                                                       'YYYY')) /*display data backward 6 years*/
                                                          AND eva.eval_year >=
                                                                 2010 /*minimum year for display is 2010*/
                                                          AND ADD_MONTHS (
                                                                 TO_DATE (
                                                                    eva.eval_year
                                                                    || eva.eval_month,
                                                                    'YYYYMM'),
                                                                 -1) <=
                                                                 ADD_MONTHS (
                                                                    s.contract_end_date,
                                                                    -12))
                                         WHERE row_rank = 1) a
                                    LEFT JOIN
                                       fes_adjust_grade b
                                    ON     a.eval_type = 'MIDYEAR'
                                       AND a.store_id = b.store_id
                                       AND b.eval_year = a.eval_year
                                       AND b.eval_month = a.eval_month) eva
                            INNER JOIN fes_evaluatedform frm
                               ON TO_NUMBER (
                                     eva.eval_year
                                     || LPAD (eva.eval_month, 2, 0)) BETWEEN TO_NUMBER (
                                                                                (frm.start_year)
                                                                                || LPAD (
                                                                                      frm.start_month,
                                                                                      2,
                                                                                      0))
                                                                         AND TO_NUMBER (
                                                                                (frm.end_year)
                                                                                || LPAD (
                                                                                      frm.end_month,
                                                                                      2,
                                                                                      0))
                                  OR (TO_NUMBER (
                                         eva.eval_year
                                         || LPAD (eva.eval_month, 2, 0)) >=
                                         TO_NUMBER (
                                            (start_year)
                                            || LPAD (start_month, 2, 0))
                                      AND frm.end_month IS NULL
                                      AND frm.end_year IS NULL)
                            INNER JOIN fr_store s1
                               ON s1.order_id = eva.order_id
                            LEFT JOIN mas_store ms
                               ON ms.branch_id = s1.store_id
                      WHERE eva.eval_month = TO_CHAR (s1.start_date, 'MM')
                            OR eva.eval_month =
                                  TO_CHAR (ADD_MONTHS (s1.start_date, 6), 'MM')) a) fe
            INNER JOIN setup_contract_period scp
               ON scp.fr_type = fe.fr_type
                  AND fe.fz_age BETWEEN scp.fr_age_start AND scp.fr_age_end
            INNER JOIN setup_contract_fee scf
               ON scf.fr_type = scp.fr_type
                  AND fe.percent_renewal_point BETWEEN scf.start_point
                                                   AND scf.end_point
                  AND FUNC_RENEWAL_ROUND (fe.start_date,
                                          fe.contract_end_date,
                                          scp.period_all) BETWEEN scf.contract_no_start
                                                              AND scf.contract_no_end
      WHERE fe.month_eva = 36
   ORDER BY fe.ORDER_ID, fe.EVA_START_YEAR DESC, fe.EVAL_MONTH DESC;

-- ---------- VIEW: V_FGI_SBP_APPROVER ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_FGI_SBP_APPROVER" ("STORE_AREA", "STORE_TYPE", "SBP_DV_EMP_ID1", "SBP_DV_FNAME_TH1", "SBP_DV_LNAME_TH1", "SBP_DV_FNAME_EN1", "SBP_DV_LNAME_EN1", "SBP_DV_EMAIL1", "SBP_GM_EMP_ID1", "SBP_GM_FNAME_TH1", "SBP_GM_LNAME_TH1", "SBP_GM_FNAME_EN1", "SBP_GM_LNAME_EN1", "SBP_GM_EMAIL1", "SBP_VP_EMP_ID1", "SBP_VP_FNAME_TH1", "SBP_VP_LNAME_TH1", "SBP_VP_FNAME_EN1", "SBP_VP_LNAME_EN1", "SBP_VP_EMAIL1") AS 
  WITH sbp_approver AS
  (SELECT *
  FROM
    (SELECT bug1.user_id,
      bug1.group_id,
      bu1.emp_id,
      bu1.first_name,
      bu1.last_name,
      bu1.first_name_en,
      bu1.last_name_en,
      bu1.email,
      bu1.position_level,
      CC.CODE_MAPPING AS store_type,
      bug1.store_area,
      dense_rank() over(partition BY bug1.group_id, SUBSTR(bu1.position_level,1,1) , bug1.store_type, bug1.store_area order by SUBSTR(bu1.position_level,2,1) DESC ,NLSSORT(bu1.first_name
      ||' '
      ||bu1.last_name, 'NLS_SORT = THAI_DICTIONARY')) AS row_rank,
      dense_rank() over(partition BY bug1.group_id, SUBSTR(bu1.position_level,1,1) , bug1.store_type, bug1.store_area order by SUBSTR(bu1.position_level,2,1) DESC ,NLSSORT(bu1.first_name
      ||' '
      ||bu1.last_name, 'NLS_SORT = THAI_DICTIONARY') DESC) AS row_rank2
    FROM business_user bu1
    INNER JOIN business_user_group bug1
    ON bug1.group_id    = 21
    AND bug1.user_id    = bu1.user_id
    AND bu1.active_flag = 'Y'
    LEFT JOIN common_code cc
    ON cc.code_type    = '00019'
    AND cc.code_value  = bug1.store_type
    AND cc.active_flag = 'Y'
    ) bu
  ) ,
  sbp_acting_approver AS
  (SELECT *
  FROM
    (SELECT bug1.user_id,
      bug1.group_id,
      bu1.emp_id,
      bu1.first_name,
      bu1.last_name,
      bu1.first_name_en,
      bu1.last_name_en,
      bu1.email,
      bu1.CPALL_ACTING_SUPERVISOR_LVL,
      CC.CODE_MAPPING AS store_type,
      bug1.store_area,
      dense_rank() over(partition BY bug1.group_id, SUBSTR(bu1.CPALL_ACTING_SUPERVISOR_LVL,1,1) , bug1.store_type, bug1.store_area order by SUBSTR(bu1.position_level,2,1) DESC ,NLSSORT(bu1.first_name
      ||' '
      ||bu1.last_name, 'NLS_SORT = THAI_DICTIONARY')) AS row_rank,
      dense_rank() over(partition BY bug1.group_id, SUBSTR(CPALL_ACTING_SUPERVISOR_LVL,1,1) , bug1.store_type, bug1.store_area order by SUBSTR(bu1.position_level,2,1) DESC ,NLSSORT(bu1.first_name
      ||' '
      ||bu1.last_name, 'NLS_SORT = THAI_DICTIONARY') DESC) AS row_rank2
    FROM business_user bu1
    INNER JOIN business_user_group bug1
    ON bug1.group_id    = 21
    AND bug1.user_id    = bu1.user_id
    AND bu1.active_flag = 'Y'
    LEFT JOIN common_code cc
    ON cc.code_type    = '00019'
    AND cc.code_value  = bug1.store_type
    AND cc.active_flag = 'Y'
    where bu1.CPALL_ACTING_SUPERVISOR_LVL is not null
    ) bu
  ) ,
  sbp_dv_approver AS
  (SELECT MAX(row_rank) m,
    MAX(row_rank2) m2,
    store_type,
    store_area
  FROM sbp_approver
  WHERE position_level LIKE '3%'
  GROUP BY store_type,
    store_area
  ) ,
  sbp_dv_acting_approver AS
  (SELECT MAX(row_rank) m,
    MAX(row_rank2) m2,
    store_type,
    store_area
  FROM sbp_acting_approver
  WHERE CPALL_ACTING_SUPERVISOR_LVL LIKE '3%'
  GROUP BY store_type,
    store_area
  ) ,
  sbp_gm_approver AS
  (SELECT MAX(row_rank) m,
    MAX(row_rank2) m2,
    store_type,
    store_area
  FROM sbp_approver
  WHERE position_level LIKE '2%'
  GROUP BY store_type,
    store_area
  ) ,
  sbp_gm_acting_approver AS
  (SELECT MAX(row_rank) m,
    MAX(row_rank2) m2,
    store_type,
    store_area
  FROM sbp_acting_approver
  WHERE CPALL_ACTING_SUPERVISOR_LVL LIKE '2%'
  GROUP BY store_type,
    store_area
  ) ,
  sbp_vp_approver AS
  (SELECT MAX(row_rank) m,
    MAX(row_rank2) m2,
    store_type,
    store_area
  FROM sbp_approver
  WHERE position_level LIKE '1%'
  GROUP BY store_type,
    store_area
  ) ,
  sbp_vp_acting_approver AS
  (SELECT MAX(row_rank) m,
    MAX(row_rank2) m2,
    store_type,
    store_area
  FROM sbp_acting_approver
  WHERE CPALL_ACTING_SUPERVISOR_LVL LIKE '1%'
  GROUP BY store_type,
    store_area
  ) ,
  mas AS
  (SELECT c1.code_value store_area,
    c2.code_mapping store_type
  FROM common_code c1
  INNER JOIN common_code c2
  ON c1.code_type    = '00025'
  AND c2.code_type   = '00019'
  AND c1.active_flag = 'Y'
  AND c2.active_flag = 'Y'
  ),
  approver AS
  (SELECT mas.store_area,
    mas.store_type ,
    NVL(NVL(NVL(dv.user_id,adv.user_id), gm.user_id), vp.user_id) dv_user_id ,
    NVL(
        NVL(DECODE(NVL(dv.user_id,adv.user_id),
            NULL,mgm.user_id,
            DECODE(mgm.user_id,
                gm.user_id,gm.user_id,
                DECODE(mgm.position_level,
                    gm.position_level,gm.user_id,
                    DECODE(mgm.position_level,
                        mgmBn.position_level,mgmBn.user_id,
                        mgm.user_id)
                    )
                )
            ) ,agm.user_id), vp.user_id) gm_user_id ,
    nvl(DECODE(gm.user_id,NULL,
    CASE
      WHEN vp.user_id = mvp.user_id
      AND mvp.user_id = mvpBn.user_id
      THEN vp.user_id
      WHEN vp.user_id != mvp.user_id
      AND vp.user_id   = mvpBn.user_id
      THEN mvp.user_id
      ELSE mvpBn.user_id
    END, mvpBn.user_id ), avp.user_id) vp_user_id
  FROM mas
  LEFT JOIN
    (SELECT sa.*
    FROM sbp_approver sa
    INNER JOIN sbp_dv_approver sgm
    ON sgm.store_area  = sa.store_area
    AND sgm.store_type = sa.store_type
    AND sgm.m2         = sa.row_rank2
    AND sa.position_level LIKE '3%'
    ) dv ON dv.store_area = mas.store_area
  AND dv.store_type       = mas.store_type
  LEFT JOIN
    (SELECT sa.*
    FROM sbp_acting_approver sa
    INNER JOIN sbp_dv_acting_approver sgm
    ON sgm.store_area  = sa.store_area
    AND sgm.store_type = sa.store_type
    AND sgm.m2         = sa.row_rank2
    AND sa.CPALL_ACTING_SUPERVISOR_LVL LIKE '3%'
    ) adv ON adv.store_area = mas.store_area
  AND adv.store_type       = mas.store_type
  LEFT JOIN sbp_approver gm
  ON gm.store_area  = mas.store_area
  AND gm.store_type = mas.store_type
  AND gm.row_rank   = 1
  AND gm.position_level LIKE '2%'
  LEFT JOIN sbp_acting_approver agm
  ON agm.store_area  = mas.store_area
  AND agm.store_type = mas.store_type
  AND agm.row_rank   = 1
  AND agm.CPALL_ACTING_SUPERVISOR_LVL LIKE '2%'
  LEFT JOIN sbp_approver vp
  ON vp.store_area  = mas.store_area
  AND vp.store_type = mas.store_type
  AND vp.row_rank   = 1
  AND vp.position_level LIKE '1%'
  LEFT JOIN sbp_acting_approver avp
  ON avp.store_area  = mas.store_area
  AND avp.store_type = mas.store_type
  AND avp.row_rank   = 1
  AND avp.CPALL_ACTING_SUPERVISOR_LVL LIKE '1%'
  LEFT JOIN
    (SELECT sa.*
    FROM sbp_approver sa
    INNER JOIN sbp_gm_approver sgm
    ON sgm.store_area  = sa.store_area
    AND sgm.store_type = sa.store_type
    AND sgm.m          = sa.row_rank
    AND sa.position_level LIKE '2%'
    ) mgm ON mgm.store_area = mas.store_area
  AND mgm.store_type        = mas.store_type
  LEFT JOIN
    (SELECT sa.*
    FROM sbp_approver sa
    INNER JOIN sbp_gm_approver sgm
    ON sgm.store_area  = sa.store_area
    AND sgm.store_type = sa.store_type
    AND sgm.m2         = sa.row_rank2
    AND sa.position_level LIKE '2%'
    ) mgmBn ON mgmBn.store_area = mas.store_area
  AND mgmBn.store_type          = mas.store_type
  LEFT JOIN
    (SELECT sa.*
    FROM sbp_approver sa
    INNER JOIN sbp_vp_approver sgm
    ON sgm.store_area  = sa.store_area
    AND sgm.store_type = sa.store_type
    AND sgm.m          = sa.row_rank
    AND sa.position_level LIKE '1%'
    ) mvp ON mvp.store_area = mas.store_area
  AND mvp.store_type        = mas.store_type
  LEFT JOIN
    (SELECT sa.*
    FROM sbp_approver sa
    INNER JOIN sbp_vp_approver sgm
    ON sgm.store_area  = sa.store_area
    AND sgm.store_type = sa.store_type
    AND sgm.m2         = sa.row_rank2
    AND sa.position_level LIKE '1%'
    ) mvpBn ON mvpBn.store_area = mas.store_area
  AND mvpBn.store_type          = mas.store_type
)
SELECT a.store_area,
  a.store_type,
  sbp_dv.emp_id        AS sbp_dv_emp_id1,
  sbp_dv.first_name    AS sbp_dv_fname_th1,
  sbp_dv.last_name     AS sbp_dv_lname_th1,
  sbp_dv.first_name_en AS sbp_dv_fname_en1,
  sbp_dv.last_name_en  AS sbp_dv_lname_en1,
  sbp_dv.email         AS sbp_dv_email1,
  sbp_gm.emp_id        AS sbp_gm_emp_id1,
  sbp_gm.first_name    AS sbp_gm_fname_th1,
  sbp_gm.last_name     AS sbp_gm_lname_th1,
  sbp_gm.first_name_en AS sbp_gm_fname_en1,
  sbp_gm.last_name_en  AS sbp_gm_lname_en1,
  sbp_gm.email         AS sbp_gm_email1,
  sbp_vp.emp_id        AS sbp_vp_emp_id1,
  sbp_vp.first_name    AS sbp_vp_fname_th1,
  sbp_vp.last_name     AS sbp_vp_lname_th1,
  sbp_vp.first_name_en AS sbp_vp_fname_en1,
  sbp_vp.last_name_en  AS sbp_vp_lname_en1,
  sbp_vp.email         AS sbp_vp_email1
FROM approver a
LEFT JOIN business_user sbp_dv
ON sbp_dv.user_id = a.dv_user_id
LEFT JOIN business_user sbp_gm
ON sbp_gm.user_id = a.gm_user_id
LEFT JOIN business_user sbp_vp
ON sbp_vp.user_id = a.vp_user_id
ORDER BY a.store_area,
  a.store_type;

-- ---------- VIEW: V_FML_CHILD ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_FML_CHILD" ("FZ_FIRST_NAME", "FZ_LAST_NAME", "STORE_ID", "STORE_NAME", "REGION", "STORE_TYPE", "CHILD_TITLE_NAME", "CHILD_FIRST_NAME", "CHILD_LAST_NAME", "CHILD_NICK_NAME", "CHILD_NATIONALITY", "CHILD_BIRTHDAY", "CHILD_AGE", "CHILD_SEX", "CHILD_RERATION", "RELATION") AS 
  select 

       fz.first_name fz_first_name,
       fz.last_name fz_last_name,
       fs.store_id,
       fs.store_name,
       ms.region,
       st.code_value store_type,
       tt.code_name child_title_name,
       ch.first_name child_first_name,
       ch.last_name child_last_name,
       ch.nick_name child_nick_name,
       na.code_name child_nationality,
       to_char(ch.birthday,'dd/MM/yyyy', 'NLS_CALENDAR=''THAI BUDDHA''') child_birthday,
       trunc(months_between(sysdate, ch.birthday)/12) child_age,
       sex.code_name child_sex,
       c.code_name child_reration,
       ch.relation

from franchisee fz
    inner join fr_store fs on nvl(fz.status, '-') != 'D'
        and nvl(fs.status, '-') != 'D'
        and fs.start_date is not null
        and fs.cancel_type = '00'
        and (
            fs.cancel_date is null
            or fs.cancel_date >= sysdate
        )
        and fs.owner_id1 = fz.franchisee_id

    inner join mas_store ms on ms.branch_id = fs.store_id
    left join franchisee_child ch on fz.franchisee_id = ch.franchisee_id
    left join common_code tt on ch.title_code = tt.code_value and tt.code_type = '00001' and tt.active_flag = 'Y'
    left join common_code na on ch.nationality = na.code_value and na.code_type = '00014' and na.active_flag = 'Y'
    left join common_code sex on ch.sex = sex.code_value and sex.code_type = '00005' and sex.active_flag = 'Y'
    left join common_code c on ch.relation = c.code_value and c.code_type = '00009' and c.active_flag = 'Y'
    left join common_code st on ms.status_type = st.code_mapping and st.code_type = '00019' and st.active_flag = 'Y'

order by nlssort(fz.first_name, 'NLS_SORT = THAI_DICTIONARY')
, nlssort(fz.last_name, 'NLS_SORT = THAI_DICTIONARY')
, fs.store_id
, nlssort(ch.first_name, 'NLS_SORT = THAI_DICTIONARY')
, nlssort(ch.last_name, 'NLS_SORT = THAI_DICTIONARY');

-- ---------- VIEW: V_FML_CONFIRM_RELATION ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_FML_CONFIRM_RELATION" ("FRANCHISEE_ID", "FZ_ID_CARD", "FZ_FNAME", "FZ_LNAME", "FZ_BIRTHDAY", "FZ_SEX", "FZ_MOBILE", "FZ_EMAIL", "REGION", "SBP_START_DATE", "SBP_CANCEL_DATE", "FZ_MARITAL_STATUS", "EMP_ID", "HQ_FNAME", "HQ_LNAME", "HQ_EMAIL", "HQ_POSITION", "OPT_REGION", "CONFIRM_DATE", "RELATION_CATE", "RELATION_CATE_DESC", "ROUND_NO", "IS_RELATED", "RELATED_DESC", "SEQ_NO", "STORE_ID", "RELATE_EMP_ID", "RELATE_FNAME", "RELATE_LNAME", "RELATE_POSITION", "RELATE_MOBILE", "RELATE_EMAIL", "RELATION_TYPE", "RELATION_TYPE_DESC", "RELATION", "RELATION_DESC", "RELATION_OTHER", "IS_LAST_TRANS", "RELATE_DEPT", "RELATE_DEPARTMENT", "RELATE_DIVISION", "RELATE_JOBFIELD", "RELATE_MANAGERID", "RELATE_MANAGER_FNAME", "RELATE_MANAGER_LNAME", "RELATE_MANAGER_POSITION", "RELATE_MANAGER_DEPT", "RELATE_MANAGER_DEPARTMENT", "RELATE_MANAGER_DIVISION", "RELATE_MANAGER_JOBFIELD", "RELATE_MANAGER_EMAIL", "ACTIVE_FLAG") AS 
  select 

    fcr.franchisee_id, fz.id_card as fz_id_card, fz.first_name as fz_fname, fz.last_name as fz_lname, fz.birthday as fz_birthday, 
    fz.sex as fz_sex, fz.mobile as fz_mobile, fz.email as fz_email, 
    s.region, s.start_date as sbp_start_date, s.cancel_date as sbp_cancel_date,
    cc04.code_name as fz_marital_status,

    fcr.emp_id, bu.first_name as hq_fname, bu.last_name as hq_lname, bu.email as hq_email,
    bg.group_name as hq_position, op.opt_region,

    fcr.confirm_date, fcr.relation_cate, cc16.code_name as relation_cate_desc, fcr.round_no, 
    fcr.is_related,
    decode(fcr.is_related, 'Y', 'มี', 'N', 'ไม่มี', 'S', 'ไม่ประสงค์ให้ข้อมูล', null) as related_desc,
    fcr.seq_no, fcr.store_id,
    fcr.relate_emp_id, fcr.relate_fname, fcr.relate_lname, fcr.relate_position, 
    fcr.relate_mobile, fcr.relate_email, 
    fcr.relation_type, 
    decode(fcr.relation_type, '1', 'มี', '2', 'ไม่มี', null) as relation_type_desc,
    fcr.relation,
    cc14.code_name as relation_desc,   
    fcr.relation_other as relation_other, fcr.is_last_trans,
    frr.relate_dept, frr.relate_department, frr.relate_division,
    frr.relate_jobfield, frr.relate_managerid, frr.relate_manager_fname, 
    frr.relate_manager_lname, frr.relate_manager_position,
    frr.relate_manager_dept, frr.relate_manager_department, frr.relate_manager_division,
    frr.relate_manager_jobfield, frr.relate_manager_email, bu.active_flag

from fml_confirm_relation fcr

    left join franchisee fz on fz.franchisee_id = fcr.franchisee_id
    left join (
            select owner_id1, start_date, cancel_date,
                listagg(region,',') within group (order by region) as region
            from (
                    select distinct 
                        fs.owner_id1, 
                        min(fs.start_date) over(partition by fs.owner_id1) as start_date,
                        max(fs2.cancel_date) over(partition by fs.owner_id1) as cancel_date,
                        ms.region,
                        decode(fs2.owner_id1, null, 'Y', 'N') as fz_active_flag
                    from fr_store fs
                        inner join mas_store ms on ms.branch_id = fs.store_id
                        left join fr_store fs2 on fs2.owner_id1 = fs.owner_id1
                            and nvl(fs2.status, '-') != 'D'
                            and nvl(fs2.store_id, '00000') != '00000'
                            and fs2.cancel_type != '00'
                            and fs2.owner_id1 not in (
                                    select fs3.owner_id1
                                    from fr_store fs3
                                    where nvl(fs3.status, '-') != 'D'
                                        and fs3.cancel_type = '00'
                                )
                    where fs.owner_id1 is not null
                        and nvl(fs.status, '-') != 'D'
                ) 
            group by owner_id1, start_date, cancel_date     
        ) s on s.owner_id1 = fcr.franchisee_id

    left join business_user bu on bu.emp_id = fcr.emp_id
    left join business_group bg on bg.group_id = bu.group_id
    left join (
            select emp_id, 
                listagg(region,',') within group (order by region) as opt_region
            from (
                    select distinct opt.emp_id, ms.region 
                    from mas_store ms
                        inner join mas_store_organize mso on mso.branch_id = ms.branch_id
                            and ms.data_type = '1'
                            and ms.active_flag = 'Y'
                            and mso.active_flag = 'Y'        
                        inner join business_user opt on opt.group_id = mso.group_id
                            and (
                                opt.emp_id = mso.emp_id
                                or (
                                    mso.emp_id is null
                                    and instr(mso.fullname, opt.first_name) > 0
                                    and instr(mso.fullname, opt.last_name) > 0
                                )    
                            ) 
                )
            group by emp_id        
        ) op on op.emp_id = bu.emp_id

    left join common_code cc04 on cc04.code_type = '00004'
        and cc04.active_flag = 'Y'
        and cc04.code_value = fz.status_code      
    left join common_code cc14 on cc14.code_type = 'FML00014_' || fcr.relation_type
        and cc14.active_flag = 'Y'
        and cc14.code_value = fcr.relation 
    left join common_code cc16 on cc16.code_type = 'FML00016'
        and cc16.active_flag = 'Y'
        and cc16.code_value = fcr.relation_cate
    left join fml_reply_confirm_relation frr on fcr.trans_id = frr.trans_id 
    
order by fcr.franchisee_id, op.opt_region, bu.first_name, bu.last_name, fcr.confirm_date, fcr.round_no, fcr.seq_no;

-- ---------- VIEW: V_FML_CONTRACT ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_FML_CONTRACT" ("REGION", "STORE_ID", "DEPARTMENT", "NAME", "TEL") AS 
  select 
    fc.region,
    fc.store_id ,
    fc.department,
    fc.name,
    fc.tel
    
  from fml_contract fc;

-- ---------- VIEW: V_FML_COOPERATION_TOPIC ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_FML_COOPERATION_TOPIC" ("ID", "ข้อ", "ข้อย่อย", "หัวข้อ", "เกณฑ์ (มีการตรวจสอบข้อเท็จจริงทุกกรณี)", "หลักฐานขอความร่วมมือด้วยวาจา", "ใช้งาน") AS 
  SELECT ID, 
SEQ_NO,
SUB_SEQ_NO,
TOPIC,
DESCRIPTION,
COUNT_WARNING_SPEECH,
ACTIVE_FLAG
  FROM FML_COOPERATION_TOPIC
  ORDER BY ID;

-- ---------- VIEW: V_FML_COOP_APPROVER_BY_STEP ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_FML_COOP_APPROVER_BY_STEP" ("TRANSACTION_PK", "APPROVE_BY0", "APPROVE_DATE0", "APPROVE_BY1", "APPROVE_DATE1", "APPROVE_BY2", "APPROVE_DATE2", "APPROVE_BY3", "APPROVE_DATE3", "APPROVE_BY4", "APPROVE_DATE4", "APPROVE_BY5", "APPROVE_DATE5", "APPROVE_BY6", "APPROVE_DATE6") AS 
  select wt.transaction_pk,
(SELECT concat(concat(bu01.first_name ,' ') ,bu01.last_name)
  FROM wf_approver apr01
  join wf_approve wfap01 on apr01.wf_approve_id = wfap01.wf_approve_id
  join business_user bu01 on apr01.user_id = bu01.user_id
  where WT.TRANSACTION_PK =  apr01.transaction_pk and apr01.wf_step_id = 600001 and apr01.wf_version_id = 6) approve_by0, /*send*/
  (SELECT wfap02.approve_date
  FROM wf_approver apr02
  join wf_approve wfap02 on apr02.wf_approve_id = wfap02.wf_approve_id
  where WT.TRANSACTION_PK =  apr02.transaction_pk and apr02.wf_step_id = 600001 and apr02.wf_version_id = 6) approve_date0, /*send*/
  (SELECT concat(concat(bu11.first_name ,' ') ,bu11.last_name)
  FROM wf_approver apr11
  join wf_approve wfap11 on apr11.wf_approve_id = wfap11.wf_approve_id
  join business_user bu11 on apr11.user_id = bu11.user_id
  where WT.TRANSACTION_PK =  apr11.transaction_pk and apr11.wf_step_id in( 601001,601002, 602001, 602002) and apr11.group_id in(70, 4)  and apr11.wf_version_id = 6) approve_by1, /*MN*/
  (SELECT wfap12.approve_date
  FROM wf_approver apr12
  join wf_approve wfap12 on apr12.wf_approve_id = wfap12.wf_approve_id
  where WT.TRANSACTION_PK =  apr12.transaction_pk and apr12.wf_step_id in( 601001,601002, 602001, 602002) and apr12.group_id in(70, 4) and apr12.wf_version_id = 6) approve_date1, /*MN*/
   (SELECT concat(concat(bu21.first_name ,' ') ,bu21.last_name)
  FROM wf_approver apr21
  join wf_approve wfap21 on apr21.wf_approve_id = wfap21.wf_approve_id
  join business_user bu21 on apr21.user_id = bu21.user_id
  where WT.TRANSACTION_PK =  apr21.transaction_pk and apr21.wf_step_id in( 601001,601002, 602001, 602002) and apr21.group_id in(15, 3) and apr21.wf_version_id = 6) approve_by2, /*DV*/
  (SELECT wfap22.approve_date
  FROM wf_approver apr22
  join wf_approve wfap22 on apr22.wf_approve_id = wfap22.wf_approve_id
  where WT.TRANSACTION_PK =  apr22.transaction_pk and apr22.wf_step_id in( 601001,601002, 602001, 602002) and apr22.group_id in(15, 3) and apr22.wf_version_id = 6) approve_date2, /*DV*/
   (SELECT concat(concat(bu31.first_name ,' ') ,bu31.last_name)
  FROM wf_approver apr31
  join wf_approve wfap31 on apr31.wf_approve_id = wfap31.wf_approve_id
  join business_user bu31 on apr31.user_id = bu31.user_id
  where WT.TRANSACTION_PK =  apr31.transaction_pk and apr31.wf_step_id in( 601001,601002, 602001, 602002) and apr31.group_id in(38, 2) and apr31.wf_version_id = 6) approve_by3, /*GM*/
  (SELECT wfap32.approve_date
  FROM wf_approver apr32
  join wf_approve wfap32 on apr32.wf_approve_id = wfap32.wf_approve_id
  where WT.TRANSACTION_PK =  apr32.transaction_pk and apr32.wf_step_id in( 601001,601002, 602001, 602002) and apr32.group_id in(38, 2) and apr32.wf_version_id = 6) approve_date3, /*GM*/
  (SELECT distinct concat(concat(bu41.first_name ,' ') ,bu41.last_name)
  FROM wf_approver apr41
  join wf_approve wfap41 on apr41.wf_approve_id = wfap41.wf_approve_id
  join business_user bu41 on apr41.user_id = bu41.user_id
  where WT.TRANSACTION_PK =  apr41.transaction_pk and apr41.wf_step_id in (603001,603002) and apr41.wf_version_id = 6) approve_by4,
  (SELECT distinct  wfap42.approve_date
  FROM wf_approver apr42
  join wf_approve wfap42 on apr42.wf_approve_id = wfap42.wf_approve_id
  where WT.TRANSACTION_PK =  apr42.transaction_pk and apr42.wf_step_id in (603001,603002) and apr42.wf_version_id = 6) approve_date4,

  (SELECT concat(concat(bu51.first_name ,' ') ,bu51.last_name)
  FROM wf_approver apr51
  join wf_approve wfap51 on apr51.wf_approve_id = wfap51.wf_approve_id
  join business_user bu51 on apr51.user_id = bu51.user_id
  where WT.TRANSACTION_PK =  apr51.transaction_pk  and apr51.wf_step_id = 604001 and apr51.wf_version_id = 6) approve_by5,
  (SELECT wfap52.approve_date
  FROM wf_approver apr52
  join wf_approve wfap52 on apr52.wf_approve_id = wfap52.wf_approve_id
  where WT.TRANSACTION_PK =  apr52.transaction_pk and apr52.wf_step_id = 604001 and apr52.wf_version_id = 6) approve_date5,

  (SELECT concat(concat(bu61.first_name ,' ') ,bu61.last_name)
  FROM wf_approver apr61
  join wf_approve wfap61 on apr61.wf_approve_id = wfap61.wf_approve_id
  join business_user bu61 on apr61.user_id = bu61.user_id
  where WT.TRANSACTION_PK =  apr61.transaction_pk  and apr61.wf_step_id = 605001 and apr61.wf_version_id = 6) approve_by6,
  (SELECT wfap62.approve_date
  FROM wf_approver apr62
  join wf_approve wfap62 on apr62.wf_approve_id = wfap62.wf_approve_id
  where WT.TRANSACTION_PK =  apr62.transaction_pk and apr62.wf_step_id = 605001 and apr62.wf_version_id = 6) approve_date6

  from wf_transaction wt
  where wt.wf_version_id = 6

  order by to_number(transaction_pk);

-- ---------- VIEW: V_FML_FES_EVALUATE_MIDYEAR ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_FML_FES_EVALUATE_MIDYEAR" ("STORE_ID", "STORE_NAME", "REGION", "START_DATE", "PARENT_STORE_ID", "FR_TYPE", "FR_TYPE_NAME", "EVAL_MONTH_ROUND1", "EVAL_YEAR_ROUND1", "EVAL_PERIOD_ROUND1", "POINT_YEAR_ROUND1", "POINT_PCT_YEAR_ROUND1", "GRADE_YEAR_ROUND1", "POINT_ADJUST_YEAR_ROUND1", "POINT_PCT_ADJUST_YEAR_ROUND1", "GRADE_ADJUST_YEAR_ROUND1", "CONCLUDE_DATE_YEAR_ROUND1", "M_CONCLUDE_DATE_YEAR_ROUND1", "CONFIRM_GRADE_YEAR_ROUND1", "CONFIRM_GRADE_D_YEAR_ROUND1", "EVAL_MONTH_ROUND2", "EVAL_YEAR_ROUND2", "EVAL_PERIOD_ROUND2", "POINT_YEAR_ROUND2", "POINT_PCT_YEAR_ROUND2", "GRADE_YEAR_ROUND2", "POINT_ADJUST_YEAR_ROUND2", "POINT_PCT_ADJUST_YEAR_ROUND2", "GRADE_ADJUST_YEAR_ROUND2", "CONCLUDE_DATE_YEAR_ROUND2", "M_CONCLUDE_DATE_YEAR_ROUND2", "CONFIRM_GRADE_YEAR_ROUND2", "CONFIRM_GRADE_D_YEAR_ROUND2", "EVAL_MONTH1_ROUND1", "EVAL_YEAR1_ROUND1", "EVAL_PERIOD1_ROUND1", "POINT_YEAR1_ROUND1", "POINT_PCT_YEAR1_ROUND1", "GRADE_YEAR1_ROUND1", "POINT_ADJUST_YEAR1_ROUND1", "POINT_PCT_ADJUST_YEAR1_ROUND1", "GRADE_ADJUST_YEAR1_ROUND1", "CONCLUDE_DATE_YEAR1_ROUND1", "M_CONCLUDE_DATE_YEAR1_ROUND1", "CONFIRM_GRADE_YEAR1_ROUND1", "CONFIRM_GRADE_D_YEAR1_ROUND1", "EVAL_MONTH1_ROUND2", "EVAL_YEAR1_ROUND2", "EVAL_PERIOD1_ROUND2", "POINT_YEAR1_ROUND2", "POINT_PCT_YEAR1_ROUND2", "GRADE_YEAR1_ROUND2", "POINT_ADJUST_YEAR1_ROUND2", "POINT_PCT_ADJUST_YEAR1_ROUND2", "GRADE_ADJUST_YEAR1_ROUND2", "CONCLUDE_DATE_YEAR1_ROUND2", "M_CONCLUDE_DATE_YEAR1_ROUND2", "CONFIRM_GRADE_YEAR1_ROUND2", "CONFIRM_GRADE_D_YEAR1_ROUND2", "EVAL_MONTH2_ROUND1", "EVAL_YEAR2_ROUND1", "EVAL_PERIOD2_ROUND1", "POINT_YEAR2_ROUND1", "POINT_PCT_YEAR2_ROUND1", "GRADE_YEAR2_ROUND1", "POINT_ADJUST_YEAR2_ROUND1", "POINT_PCT_ADJUST_YEAR2_ROUND1", "GRADE_ADJUST_YEAR2_ROUND1", "CONCLUDE_DATE_YEAR2_ROUND1", "M_CONCLUDE_DATE_YEAR2_ROUND1", "CONFIRM_GRADE_YEAR2_ROUND1", "CONFIRM_GRADE_D_YEAR2_ROUND1", "EVAL_MONTH2_ROUND2", "EVAL_YEAR2_ROUND2", "EVAL_PERIOD2_ROUND2", "POINT_YEAR2_ROUND2", "POINT_PCT_YEAR2_ROUND2", "GRADE_YEAR2_ROUND2", "POINT_ADJUST_YEAR2_ROUND2", "POINT_PCT_ADJUST_YEAR2_ROUND2", "GRADE_ADJUST_YEAR2_ROUND2", "CONCLUDE_DATE_YEAR2_ROUND2", "M_CONCLUDE_DATE_YEAR2_ROUND2", "CONFIRM_GRADE_YEAR2_ROUND2", "CONFIRM_GRADE_D_YEAR2_ROUND2") AS 
  SELECT s1.store_id,                                     -- as "รหัสสาขา",
            ms.branch_name AS store_name,                    -- as "ชื่อสาขา",
            ms.region,                                            -- as "ภาค",
            s1.start_date,                         -- as "วันที่เป็นแฟรนไชส์",
            s2.store_id AS parent_store_id,             -- as "ย้ายร้านมาจาก",
            DECODE (ms.status_type,
                    'FPT1', 'PTT',
                    'FAM', 'A',
                    'FB1', 'B',
                    'FB2', 'EMP',
                    'FC1', 'C',
                    'FBGC', 'BGC',
					'FVB', 'VB',
                    'FVC', 'VC',
                    NULL)
               AS fr_type,                                -- "ประเภทการลงทุน",
            DECODE (ms.status_type,
                    'FPT1', 'Type ปตท.',
                    'FAM', 'Type A',
                    'FB1', 'Type B',
                    'FB2', 'Type พนักงาน',
                    'FC1', 'Type C',
                    'FBGC', 'Type BGC',
					'FVB', 'Type VB',
                    'FVC', 'Type VC',
                    NULL)
               AS fr_type_name,
            --YYYY #1
            MAX (DECODE (eval_month1, eval_month1, eval_month1))
               AS eval_month_round1,
            MAX (DECODE (eval_year1, eval_year1, eval_year1))
               AS eval_year_round1,
            MAX (period_year_round1) AS EVAL_PERIOD_round1,
            MAX (point_year_round1) AS point_year_round1,
            MAX (point_pct_year_round1) AS point_pct_year_round1,
            MAX (grade_year_round1) AS grade_year_round1,
            MAX (point_adjust_year_round1) AS point_adjust_year_round1,
            MAX (point_pct_adjust_year_round1) AS point_pct_adjust_year_round1,
            MAX (grade_adjust_year_round1) AS grade_adjust_year_round1,
            MAX (
               TO_CHAR (CONCLUDE_DATE_YEAR_ROUND1,
                        'DD/MM/YYYY',
                        'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI'))
               AS CONCLUDE_DATE_YEAR_ROUND1,
            MAX (
               TO_CHAR (M_CONCLUDE_DATE_YEAR_ROUND1,
                        'DD/MM/YYYY',
                        'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI'))
               AS M_CONCLUDE_DATE_YEAR_ROUND1,
            MAX (CONFIRM_GRADE_YEAR_ROUND1) AS CONFIRM_GRADE_YEAR_ROUND1,
            MAX (
               TO_CHAR (CONFIRM_GRADE_D_YEAR_ROUND1,
                        'DD/MM/YYYY',
                        'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI'))
               AS CONFIRM_GRADE_D_YEAR_ROUND1,
            --YYYY #2
            MAX (DECODE (eval_month2, eval_month2, eval_month2))
               AS eval_month_round2,
            MAX (DECODE (eval_year2, eval_year2, eval_year2))
               AS eval_year_round2,
            MAX (period_year_round2) AS EVAL_PERIOD_round2,
            MAX (point_year_round2) AS point_year_round2,
            MAX (point_pct_year_round2) AS point_pct_year_round2,
            MAX (grade_year_round2) AS grade_year_round2,
            MAX (point_adjust_year_round2) AS point_adjust_year_round2,
            MAX (point_pct_adjust_year_round2) AS point_pct_adjust_year_round2,
            MAX (grade_adjust_year_round2) AS grade_adjust_year_round2,
            MAX (
               TO_CHAR (CONCLUDE_DATE_YEAR_ROUND2,
                        'DD/MM/YYYY',
                        'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI'))
               AS CONCLUDE_DATE_YEAR_ROUND2,
            MAX (
               TO_CHAR (M_CONCLUDE_DATE_YEAR_ROUND2,
                        'DD/MM/YYYY',
                        'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI'))
               AS M_CONCLUDE_DATE_YEAR_ROUND2,
            MAX (CONFIRM_GRADE_YEAR_ROUND2) AS CONFIRM_GRADE_YEAR_ROUND2,
            MAX (
               TO_CHAR (CONFIRM_GRADE_D_YEAR_ROUND2,
                        'DD/MM/YYYY',
                        'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI'))
               AS CONFIRM_GRADE_D_YEAR_ROUND2,
            --(YYYY-1) #1
            MAX (
               DECODE (eval_month1_round1,
                       eval_month1_round1, eval_month1_round1))
               AS eval_month1_round1,
            MAX (
               DECODE (eval_year1_round1, eval_year1_round1, eval_year1_round1))
               AS eval_year1_round1,
            MAX (period_year1_round1) AS EVAL_PERIOD1_round1,
            MAX (point_year1_round1) AS point_year1_round1,
            MAX (point_pct_year1_round1) AS point_pct_year1_round1,
            MAX (grade_year1_round1) AS grade_year1_round1,
            MAX (point_adjust_year1_round1) AS point_adjust_year1_round1,
            MAX (point_pct_adjust_year1_round1)
               AS point_pct_adjust_year1_round1,
            MAX (grade_adjust_year1_round1) AS grade_adjust_year1_round1,
            MAX (TO_CHAR (CONCLUDE_DATE_YEAR1_ROUND1, 'DD/MM/YYYY'))
               AS CONCLUDE_DATE_YEAR1_ROUND1,
            MAX (TO_CHAR (M_CONCLUDE_DATE_YEAR1_ROUND1, 'DD/MM/YYYY'))
               AS M_CONCLUDE_DATE_YEAR1_ROUND1,
            MAX (CONFIRM_GRADE_YEAR1_ROUND1) AS CONFIRM_GRADE_YEAR1_ROUND1,
            MAX (TO_CHAR (CONFIRM_GRADE_D_YEAR1_ROUND1, 'DD/MM/YYYY'))
               AS CONFIRM_GRADE_D_YEAR1_ROUND1,
            --(YYYY-1) #2
            MAX (
               DECODE (eval_month1_round2,
                       eval_month1_round2, eval_month1_round2))
               AS eval_month1_round2,
            MAX (
               DECODE (eval_year1_round2, eval_year1_round2, eval_year1_round2))
               AS eval_year1_round2,
            MAX (period_year1_round2) AS EVAL_PERIOD1_round2,
            MAX (point_year1_round2) AS point_year1_round2,
            MAX (point_pct_year1_round2) AS point_pct_year1_round2,
            MAX (grade_year1_round2) AS grade_year1_round2,
            MAX (point_adjust_year1_round2) AS point_adjust_year1_round2,
            MAX (point_pct_adjust_year1_round2)
               AS point_pct_adjust_year1_round2,
            MAX (grade_adjust_year1_round2) AS grade_adjust_year1_round2,
            MAX (TO_CHAR (CONCLUDE_DATE_YEAR1_ROUND2, 'DD/MM/YYYY'))
               AS CONCLUDE_DATE_YEAR1_ROUND2,
            MAX (TO_CHAR (M_CONCLUDE_DATE_YEAR1_ROUND2, 'DD/MM/YYYY'))
               AS M_CONCLUDE_DATE_YEAR1_ROUND2,
            MAX (CONFIRM_GRADE_YEAR1_ROUND2) AS CONFIRM_GRADE_YEAR1_ROUND2,
            MAX (TO_CHAR (CONFIRM_GRADE_D_YEAR1_ROUND2, 'DD/MM/YYYY'))
               AS CONFIRM_GRADE_D_YEAR1_ROUND2,
            --(YYYY-2) #1
            MAX (
               DECODE (eval_month2_round1,
                       eval_month2_round1, eval_month2_round1))
               AS eval_month2_round1,
            MAX (
               DECODE (eval_year2_round1, eval_year2_round1, eval_year2_round1))
               AS eval_year2_round1,
            MAX (period_year2_round1) AS EVAL_PERIOD2_round1,
            MAX (point_year2_round1) AS point_year2_round1,
            MAX (point_pct_year2_round1) AS point_pct_year2_round1,
            MAX (grade_year2_round1) AS grade_year2_round1,
            MAX (point_adjust_year2_round1) AS point_adjust_year2_round1,
            MAX (point_pct_adjust_year2_round1)
               AS point_pct_adjust_year2_round1,
            MAX (grade_adjust_year2_round1) AS grade_adjust_year2_round1,
            MAX (TO_CHAR (CONCLUDE_DATE_YEAR2_ROUND1, 'DD/MM/YYYY'))
               AS CONCLUDE_DATE_YEAR2_ROUND1,
            MAX (TO_CHAR (M_CONCLUDE_DATE_YEAR2_ROUND1, 'DD/MM/YYYY'))
               AS M_CONCLUDE_DATE_YEAR2_ROUND1,
            MAX (CONFIRM_GRADE_YEAR2_ROUND1) AS CONFIRM_GRADE_YEAR2_ROUND1,
            MAX (TO_CHAR (CONFIRM_GRADE_D_YEAR2_ROUND1, 'DD/MM/YYYY'))
               AS CONFIRM_GRADE_D_YEAR2_ROUND1,
            --(YYYY-2) #2
            MAX (
               DECODE (eval_month2_round2,
                       eval_month2_round2, eval_month2_round2))
               AS eval_month2_round2,
            MAX (
               DECODE (eval_year2_round2, eval_year2_round2, eval_year2_round2))
               AS eval_year2_round2,
            MAX (period_year2_round2) AS EVAL_PERIOD2_round2,
            MAX (point_year2_round2) AS point_year2_round2,
            MAX (point_pct_year2_round2) AS point_pct_year2_round2,
            MAX (grade_year2_round2) AS grade_year2_round2,
            MAX (point_adjust_year2_round2) AS point_adjust_year2_round2,
            MAX (point_pct_adjust_year2_round2)
               AS point_pct_adjust_year2_round2,
            MAX (grade_adjust_year2_round2) AS grade_adjust_year2_round2,
            MAX (TO_CHAR (CONCLUDE_DATE_YEAR2_ROUND2, 'DD/MM/YYYY'))
               AS CONCLUDE_DATE_YEAR2_ROUND2,
            MAX (TO_CHAR (M_CONCLUDE_DATE_YEAR2_ROUND2, 'DD/MM/YYYY'))
               AS M_CONCLUDE_DATE_YEAR2_ROUND2,
            MAX (CONFIRM_GRADE_YEAR2_ROUND2) AS CONFIRM_GRADE_YEAR2_ROUND2,
            MAX (TO_CHAR (CONFIRM_GRADE_D_YEAR2_ROUND2, 'DD/MM/YYYY'))
               AS CONFIRM_GRADE_D_YEAR2_ROUND2
       FROM (SELECT eva.*,
                    --YYYY #1
                    DECODE (FLOOR (eva.eval_month / 7) || eva.eval_year,
                            0 || TO_CHAR (SYSDATE, 'YYYY'), eva.eval_month)
                       AS eval_month1,
                    DECODE (FLOOR (eva.eval_month / 7) || eva.eval_year,
                            0 || TO_CHAR (SYSDATE, 'YYYY'), eva.eval_year)
                       AS eval_year1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || TO_CHAR (SYSDATE, 'YYYY'), CASE
                                                          WHEN eva.start_date <=
                                                                  ADD_MONTHS (
                                                                     TO_DATE (
                                                                        '01/'
                                                                        || eva.eval_month
                                                                        || '/'
                                                                        || eva.eval_year,
                                                                        'DD/MM/YYYY'),
                                                                     -6)
                                                          THEN
                                                             TO_CHAR (
                                                                ADD_MONTHS (
                                                                   TO_DATE (
                                                                      LPAD (
                                                                         eva.eval_month,
                                                                         2,
                                                                         '0')
                                                                      || '/'
                                                                      || eva.eval_year,
                                                                      'MM/YYYY'),
                                                                   -6),
                                                                'FMMON YY',
                                                                'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                             || ' - '
                                                             || TO_CHAR (
                                                                   ADD_MONTHS (
                                                                      TO_DATE (
                                                                         LPAD (
                                                                            eva.eval_month,
                                                                            2,
                                                                            '0')
                                                                         || '/'
                                                                         || eva.eval_year,
                                                                         'MM/YYYY'),
                                                                      -1),
                                                                   'FMMON YY',
                                                                   'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                          ELSE
                                                             TO_CHAR (
                                                                ADD_MONTHS (
                                                                   TO_DATE (
                                                                      LPAD (
                                                                         eva.eval_month,
                                                                         2,
                                                                         '0')
                                                                      || '/'
                                                                      || eva.eval_year,
                                                                      'MM/YYYY'),
                                                                   -5),
                                                                'FMMON YY',
                                                                'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                             || ' - '
                                                             || TO_CHAR (
                                                                   ADD_MONTHS (
                                                                      TO_DATE (
                                                                         LPAD (
                                                                            eva.eval_month,
                                                                            2,
                                                                            '0')
                                                                         || '/'
                                                                         || eva.eval_year,
                                                                         'MM/YYYY'),
                                                                      -1),
                                                                   'FMMON YY',
                                                                   'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                       END)
                       period_year_round1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || TO_CHAR (SYSDATE, 'YYYY'), TO_CHAR (
                                                          eva.total_point,
                                                          '9999.99'))
                       point_year_round1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || TO_CHAR (SYSDATE, 'YYYY'), TO_CHAR (
                                                          (eva.total_point
                                                           * 100)
                                                          / eva.total_point_ef,
                                                          '9999.99'))
                       point_pct_year_round1,
                    DECODE (FLOOR (eva.eval_month / 7) || eva.eval_year,
                            0 || TO_CHAR (SYSDATE, 'YYYY'), eva.grade)
                       grade_year_round1,
                    --ADJUST
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || TO_CHAR (SYSDATE, 'YYYY'), TO_CHAR (
                                                          eva.total_point_adjust,
                                                          '9999.99'))
                       point_adjust_year_round1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || TO_CHAR (SYSDATE, 'YYYY'), TO_CHAR (
                                                          (eva.total_point_adjust
                                                           * 100)
                                                          / eva.total_point_ef,
                                                          '9999.99'))
                       point_pct_adjust_year_round1,
                    DECODE (FLOOR (eva.eval_month / 7) || eva.eval_year,
                            0 || TO_CHAR (SYSDATE, 'YYYY'), eva.grade_adjust)
                       grade_adjust_year_round1,
                    --CONFIRM_GRADE
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY')), eva.CONCLUDE_DATE)
                       CONCLUDE_DATE_YEAR_ROUND1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY')), eva.MODIFY_CONCLUDE_DATE)
                       M_CONCLUDE_DATE_YEAR_ROUND1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY')), eva.CONFIRM_GRADE_STATUS)
                       CONFIRM_GRADE_YEAR_ROUND1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY')), eva.CONFIRM_GRADE_DATE)
                       CONFIRM_GRADE_D_YEAR_ROUND1,
                    --YYYY #2
                    DECODE (FLOOR (eva.eval_month / 7) || eva.eval_year,
                            1 || TO_CHAR (SYSDATE, 'YYYY'), eva.eval_month)
                       AS eval_month2,
                    DECODE (FLOOR (eva.eval_month / 7) || eva.eval_year,
                            1 || TO_CHAR (SYSDATE, 'YYYY'), eva.eval_year)
                       AS eval_year2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || TO_CHAR (SYSDATE, 'YYYY'), CASE
                                                          WHEN eva.start_date <=
                                                                  ADD_MONTHS (
                                                                     TO_DATE (
                                                                        '01/'
                                                                        || eva.eval_month
                                                                        || '/'
                                                                        || eva.eval_year,
                                                                        'DD/MM/YYYY'),
                                                                     -6)
                                                          THEN
                                                             TO_CHAR (
                                                                ADD_MONTHS (
                                                                   TO_DATE (
                                                                      LPAD (
                                                                         eva.eval_month,
                                                                         2,
                                                                         '0')
                                                                      || '/'
                                                                      || eva.eval_year,
                                                                      'MM/YYYY'),
                                                                   -6),
                                                                'FMMON YY',
                                                                'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                             || ' - '
                                                             || TO_CHAR (
                                                                   ADD_MONTHS (
                                                                      TO_DATE (
                                                                         LPAD (
                                                                            eva.eval_month,
                                                                            2,
                                                                            '0')
                                                                         || '/'
                                                                         || eva.eval_year,
                                                                         'MM/YYYY'),
                                                                      -1),
                                                                   'FMMON YY',
                                                                   'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                          ELSE
                                                             TO_CHAR (
                                                                ADD_MONTHS (
                                                                   TO_DATE (
                                                                      LPAD (
                                                                         eva.eval_month,
                                                                         2,
                                                                         '0')
                                                                      || '/'
                                                                      || eva.eval_year,
                                                                      'MM/YYYY'),
                                                                   -5),
                                                                'FMMON YY',
                                                                'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                             || ' - '
                                                             || TO_CHAR (
                                                                   ADD_MONTHS (
                                                                      TO_DATE (
                                                                         LPAD (
                                                                            eva.eval_month,
                                                                            2,
                                                                            '0')
                                                                         || '/'
                                                                         || eva.eval_year,
                                                                         'MM/YYYY'),
                                                                      -1),
                                                                   'FMMON YY',
                                                                   'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                       END)
                       AS period_year_round2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || TO_CHAR (SYSDATE, 'YYYY'), TO_CHAR (
                                                          eva.total_point,
                                                          '9999.99'))
                       AS point_year_round2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || TO_CHAR (SYSDATE, 'YYYY'), TO_CHAR (
                                                          (eva.total_point
                                                           * 100)
                                                          / eva.total_point_ef,
                                                          '9999.99'))
                       point_pct_year_round2,
                    DECODE (FLOOR (eva.eval_month / 7) || eva.eval_year,
                            1 || TO_CHAR (SYSDATE, 'YYYY'), eva.grade)
                       AS grade_year_round2,
                    --ADJUST
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || TO_CHAR (SYSDATE, 'YYYY'), TO_CHAR (
                                                          eva.total_point_adjust,
                                                          '9999.99'))
                       point_adjust_year_round2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || TO_CHAR (SYSDATE, 'YYYY'), TO_CHAR (
                                                          (eva.total_point_adjust
                                                           * 100)
                                                          / eva.total_point_ef,
                                                          '9999.99'))
                       point_pct_adjust_year_round2,
                    DECODE (FLOOR (eva.eval_month / 7) || eva.eval_year,
                            1 || TO_CHAR (SYSDATE, 'YYYY'), eva.grade_adjust)
                       grade_adjust_year_round2,
                    --CONFIRM_GRADE
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY')), eva.CONCLUDE_DATE)
                       CONCLUDE_DATE_YEAR_ROUND2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY')), eva.MODIFY_CONCLUDE_DATE)
                       M_CONCLUDE_DATE_YEAR_ROUND2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY')), eva.CONFIRM_GRADE_STATUS)
                       CONFIRM_GRADE_YEAR_ROUND2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY')), eva.CONFIRM_GRADE_DATE)
                       CONFIRM_GRADE_D_YEAR_ROUND2,
                    --(YYYY-1) #1
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 1), eva.eval_month)
                       AS eval_month1_round1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 1), eva.eval_year)
                       AS eval_year1_round1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 1), CASE
                                                                WHEN eva.start_date <=
                                                                        ADD_MONTHS (
                                                                           TO_DATE (
                                                                              '01/'
                                                                              || eva.eval_month
                                                                              || '/'
                                                                              || eva.eval_year,
                                                                              'DD/MM/YYYY'),
                                                                           -6)
                                                                THEN
                                                                   TO_CHAR (
                                                                      ADD_MONTHS (
                                                                         TO_DATE (
                                                                            LPAD (
                                                                               eva.eval_month,
                                                                               2,
                                                                               '0')
                                                                            || '/'
                                                                            || eva.eval_year,
                                                                            'MM/YYYY'),
                                                                         -6),
                                                                      'FMMON YY',
                                                                      'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                                   || ' - '
                                                                   || TO_CHAR (
                                                                         ADD_MONTHS (
                                                                            TO_DATE (
                                                                               LPAD (
                                                                                  eva.eval_month,
                                                                                  2,
                                                                                  '0')
                                                                               || '/'
                                                                               || eva.eval_year,
                                                                               'MM/YYYY'),
                                                                            -1),
                                                                         'FMMON YY',
                                                                         'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                                ELSE
                                                                   TO_CHAR (
                                                                      ADD_MONTHS (
                                                                         TO_DATE (
                                                                            LPAD (
                                                                               eva.eval_month,
                                                                               2,
                                                                               '0')
                                                                            || '/'
                                                                            || eva.eval_year,
                                                                            'MM/YYYY'),
                                                                         -5),
                                                                      'FMMON YY',
                                                                      'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                                   || ' - '
                                                                   || TO_CHAR (
                                                                         ADD_MONTHS (
                                                                            TO_DATE (
                                                                               LPAD (
                                                                                  eva.eval_month,
                                                                                  2,
                                                                                  '0')
                                                                               || '/'
                                                                               || eva.eval_year,
                                                                               'MM/YYYY'),
                                                                            -1),
                                                                         'FMMON YY',
                                                                         'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                             END)
                       period_year1_round1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 1), TO_CHAR (
                                                                eva.total_point,
                                                                '9999.99'))
                       point_year1_round1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 1), TO_CHAR (
                                                                (eva.total_point
                                                                 * 100)
                                                                / eva.total_point_ef,
                                                                '9999.99'))
                       point_pct_year1_round1,
                    DECODE (FLOOR (eva.eval_month / 7) || eva.eval_year,
                            0 || (TO_CHAR (SYSDATE, 'YYYY') - 1), eva.grade)
                       grade_year1_round1,
                    --ADJUST
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 1), TO_CHAR (
                                                                eva.total_point_adjust,
                                                                '9999.99'))
                       point_adjust_year1_round1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 1), TO_CHAR (
                                                                (eva.total_point_adjust
                                                                 * 100)
                                                                / eva.total_point_ef,
                                                                '9999.99'))
                       point_pct_adjust_year1_round1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 1), eva.grade_adjust)
                       grade_adjust_year1_round1,
                    --CONFIRM_GRADE
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 1), eva.CONCLUDE_DATE)
                       CONCLUDE_DATE_YEAR1_ROUND1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 1), eva.MODIFY_CONCLUDE_DATE)
                       M_CONCLUDE_DATE_YEAR1_ROUND1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 1), eva.CONFIRM_GRADE_STATUS)
                       CONFIRM_GRADE_YEAR1_ROUND1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 1), eva.CONFIRM_GRADE_DATE)
                       CONFIRM_GRADE_D_YEAR1_ROUND1,
                    --(YYYY-1) #2
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 1), eva.eval_month)
                       AS eval_month1_round2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 1), eva.eval_year)
                       AS eval_year1_round2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 1), CASE
                                                                WHEN eva.start_date <=
                                                                        ADD_MONTHS (
                                                                           TO_DATE (
                                                                              '01/'
                                                                              || eva.eval_month
                                                                              || '/'
                                                                              || eva.eval_year,
                                                                              'DD/MM/YYYY'),
                                                                           -6)
                                                                THEN
                                                                   TO_CHAR (
                                                                      ADD_MONTHS (
                                                                         TO_DATE (
                                                                            LPAD (
                                                                               eva.eval_month,
                                                                               2,
                                                                               '0')
                                                                            || '/'
                                                                            || eva.eval_year,
                                                                            'MM/YYYY'),
                                                                         -6),
                                                                      'FMMON YY',
                                                                      'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                                   || ' - '
                                                                   || TO_CHAR (
                                                                         ADD_MONTHS (
                                                                            TO_DATE (
                                                                               LPAD (
                                                                                  eva.eval_month,
                                                                                  2,
                                                                                  '0')
                                                                               || '/'
                                                                               || eva.eval_year,
                                                                               'MM/YYYY'),
                                                                            -1),
                                                                         'FMMON YY',
                                                                         'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                                ELSE
                                                                   TO_CHAR (
                                                                      ADD_MONTHS (
                                                                         TO_DATE (
                                                                            LPAD (
                                                                               eva.eval_month,
                                                                               2,
                                                                               '0')
                                                                            || '/'
                                                                            || eva.eval_year,
                                                                            'MM/YYYY'),
                                                                         -5),
                                                                      'FMMON YY',
                                                                      'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                                   || ' - '
                                                                   || TO_CHAR (
                                                                         ADD_MONTHS (
                                                                            TO_DATE (
                                                                               LPAD (
                                                                                  eva.eval_month,
                                                                                  2,
                                                                                  '0')
                                                                               || '/'
                                                                               || eva.eval_year,
                                                                               'MM/YYYY'),
                                                                            -1),
                                                                         'FMMON YY',
                                                                         'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                             END)
                       AS period_year1_round2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 1), TO_CHAR (
                                                                eva.total_point,
                                                                '9999.99'))
                       AS point_year1_round2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 1), TO_CHAR (
                                                                (eva.total_point
                                                                 * 100)
                                                                / eva.total_point_ef,
                                                                '9999.99'))
                       point_pct_year1_round2,
                    DECODE (FLOOR (eva.eval_month / 7) || eva.eval_year,
                            1 || (TO_CHAR (SYSDATE, 'YYYY') - 1), eva.grade)
                       AS grade_year1_round2,
                    --ADJUST
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 1), TO_CHAR (
                                                                eva.total_point_adjust,
                                                                '9999.99'))
                       point_adjust_year1_round2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 1), TO_CHAR (
                                                                (eva.total_point_adjust
                                                                 * 100)
                                                                / eva.total_point_ef,
                                                                '9999.99'))
                       point_pct_adjust_year1_round2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 1), eva.grade_adjust)
                       grade_adjust_year1_round2,
                    --CONFIRM_GRADE
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 1), eva.CONCLUDE_DATE)
                       CONCLUDE_DATE_YEAR1_ROUND2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 1), eva.MODIFY_CONCLUDE_DATE)
                       M_CONCLUDE_DATE_YEAR1_ROUND2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 1), eva.CONFIRM_GRADE_STATUS)
                       CONFIRM_GRADE_YEAR1_ROUND2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 1), eva.CONFIRM_GRADE_DATE)
                       CONFIRM_GRADE_D_YEAR1_ROUND2,
                    --(YYYY-2) #1
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 2), eva.eval_month)
                       AS eval_month2_round1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 2), eva.eval_year)
                       AS eval_year2_round1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 2), CASE
                                                                WHEN eva.start_date <=
                                                                        ADD_MONTHS (
                                                                           TO_DATE (
                                                                              '01/'
                                                                              || eva.eval_month
                                                                              || '/'
                                                                              || eva.eval_year,
                                                                              'DD/MM/YYYY'),
                                                                           -6)
                                                                THEN
                                                                   TO_CHAR (
                                                                      ADD_MONTHS (
                                                                         TO_DATE (
                                                                            LPAD (
                                                                               eva.eval_month,
                                                                               2,
                                                                               '0')
                                                                            || '/'
                                                                            || eva.eval_year,
                                                                            'MM/YYYY'),
                                                                         -6),
                                                                      'FMMON YY',
                                                                      'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                                   || ' - '
                                                                   || TO_CHAR (
                                                                         ADD_MONTHS (
                                                                            TO_DATE (
                                                                               LPAD (
                                                                                  eva.eval_month,
                                                                                  2,
                                                                                  '0')
                                                                               || '/'
                                                                               || eva.eval_year,
                                                                               'MM/YYYY'),
                                                                            -1),
                                                                         'FMMON YY',
                                                                         'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                                ELSE
                                                                   TO_CHAR (
                                                                      ADD_MONTHS (
                                                                         TO_DATE (
                                                                            LPAD (
                                                                               eva.eval_month,
                                                                               2,
                                                                               '0')
                                                                            || '/'
                                                                            || eva.eval_year,
                                                                            'MM/YYYY'),
                                                                         -5),
                                                                      'FMMON YY',
                                                                      'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                                   || ' - '
                                                                   || TO_CHAR (
                                                                         ADD_MONTHS (
                                                                            TO_DATE (
                                                                               LPAD (
                                                                                  eva.eval_month,
                                                                                  2,
                                                                                  '0')
                                                                               || '/'
                                                                               || eva.eval_year,
                                                                               'MM/YYYY'),
                                                                            -1),
                                                                         'FMMON YY',
                                                                         'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                             END)
                       AS period_year2_round1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 2), TO_CHAR (
                                                                eva.total_point,
                                                                '9999.99'))
                       point_year2_round1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 2), TO_CHAR (
                                                                (eva.total_point
                                                                 * 100)
                                                                / eva.total_point_ef,
                                                                '9999.99'))
                       point_pct_year2_round1,
                    DECODE (FLOOR (eva.eval_month / 7) || eva.eval_year,
                            0 || (TO_CHAR (SYSDATE, 'YYYY') - 2), eva.grade)
                       grade_year2_round1,
                    --ADJUST
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 2), TO_CHAR (
                                                                eva.total_point_adjust,
                                                                '9999.99'))
                       point_adjust_year2_round1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 2), TO_CHAR (
                                                                (eva.total_point_adjust
                                                                 * 100)
                                                                / eva.total_point_ef,
                                                                '9999.99'))
                       point_pct_adjust_year2_round1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 2), eva.grade_adjust)
                       grade_adjust_year2_round1,
                    --CONFIRM_GRADE
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 2), eva.CONCLUDE_DATE)
                       CONCLUDE_DATE_YEAR2_ROUND1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 2), eva.MODIFY_CONCLUDE_DATE)
                       M_CONCLUDE_DATE_YEAR2_ROUND1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 2), eva.CONFIRM_GRADE_STATUS)
                       CONFIRM_GRADE_YEAR2_ROUND1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 2), eva.CONFIRM_GRADE_DATE)
                       CONFIRM_GRADE_D_YEAR2_ROUND1,
                    --(YYYY-2) #2
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 2), eva.eval_month)
                       AS eval_month2_round2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 2), eva.eval_year)
                       AS eval_year2_round2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 2), CASE
                                                                WHEN eva.start_date <=
                                                                        ADD_MONTHS (
                                                                           TO_DATE (
                                                                              '01/'
                                                                              || eva.eval_month
                                                                              || '/'
                                                                              || eva.eval_year,
                                                                              'DD/MM/YYYY'),
                                                                           -6)
                                                                THEN
                                                                   TO_CHAR (
                                                                      ADD_MONTHS (
                                                                         TO_DATE (
                                                                            LPAD (
                                                                               eva.eval_month,
                                                                               2,
                                                                               '0')
                                                                            || '/'
                                                                            || eva.eval_year,
                                                                            'MM/YYYY'),
                                                                         -6),
                                                                      'FMMON YY',
                                                                      'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                                   || ' - '
                                                                   || TO_CHAR (
                                                                         ADD_MONTHS (
                                                                            TO_DATE (
                                                                               LPAD (
                                                                                  eva.eval_month,
                                                                                  2,
                                                                                  '0')
                                                                               || '/'
                                                                               || eva.eval_year,
                                                                               'MM/YYYY'),
                                                                            -1),
                                                                         'FMMON YY',
                                                                         'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                                ELSE
                                                                   TO_CHAR (
                                                                      ADD_MONTHS (
                                                                         TO_DATE (
                                                                            LPAD (
                                                                               eva.eval_month,
                                                                               2,
                                                                               '0')
                                                                            || '/'
                                                                            || eva.eval_year,
                                                                            'MM/YYYY'),
                                                                         -5),
                                                                      'FMMON YY',
                                                                      'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                                   || ' - '
                                                                   || TO_CHAR (
                                                                         ADD_MONTHS (
                                                                            TO_DATE (
                                                                               LPAD (
                                                                                  eva.eval_month,
                                                                                  2,
                                                                                  '0')
                                                                               || '/'
                                                                               || eva.eval_year,
                                                                               'MM/YYYY'),
                                                                            -1),
                                                                         'FMMON YY',
                                                                         'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                             END)
                       AS period_year2_round2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 2), TO_CHAR (
                                                                eva.total_point,
                                                                '9999.99'))
                       AS point_year2_round2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 2), TO_CHAR (
                                                                (eva.total_point
                                                                 * 100)
                                                                / eva.total_point_ef,
                                                                '9999.99'))
                       point_pct_year2_round2,
                    DECODE (FLOOR (eva.eval_month / 7) || eva.eval_year,
                            1 || (TO_CHAR (SYSDATE, 'YYYY') - 2), eva.grade)
                       AS grade_year2_round2,
                    --ADJUST
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 2), TO_CHAR (
                                                                eva.total_point_adjust,
                                                                '9999.99'))
                       point_adjust_year2_round2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 2), TO_CHAR (
                                                                (eva.total_point_adjust
                                                                 * 100)
                                                                / eva.total_point_ef,
                                                                '9999.99'))
                       point_pct_adjust_year2_round2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 2), eva.grade_adjust)
                       grade_adjust_year2_round2,
                    --CONFIRM_GRADE
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 2), eva.CONCLUDE_DATE)
                       CONCLUDE_DATE_YEAR2_ROUND2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 2), eva.MODIFY_CONCLUDE_DATE)
                       M_CONCLUDE_DATE_YEAR2_ROUND2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 2), eva.CONFIRM_GRADE_STATUS)
                       CONFIRM_GRADE_YEAR2_ROUND2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 2), eva.CONFIRM_GRADE_DATE)
                       CONFIRM_GRADE_D_YEAR2_ROUND2
               FROM (SELECT eva.evaluate_id,
                            eva.eval_month,
                            eva.eval_year,
                            eva.total_point,
                            eva.grade,
                            s.order_id,
                            s.start_date,
                            ag.total_point total_point_adjust,
                            ag.grade grade_adjust,
                            ag.eval_month eval_month_adjust,
                            ag.eval_year eval_year_adjust,
                            ef.TOTAL_POINT TOTAL_POINT_EF,
                            DENSE_RANK ()
                            OVER (
                               PARTITION BY s.order_id,
                                            eva.eval_year,
                                            eva.eval_month
                               ORDER BY
                                  eva.del_status NULLS FIRST,
                                  eva.evaluate_id DESC)
                               AS row_rank,
                            eva.CONCLUDE_DATE,
                            eva.MODIFY_CONCLUDE_DATE,
                            cgs.code_name AS CONFIRM_GRADE_STATUS,
                            eva.CONFIRM_GRADE_DATE
                       FROM fes_evaluate eva
                            INNER JOIN (SELECT *
                                          FROM (    SELECT order_id,
                                                           start_date,
                                                           REGEXP_SUBSTR (
                                                              SUBSTR (root_path, 2),
                                                              ',?([^,]*)',
                                                              1,
                                                              LEVEL,
                                                              'i',
                                                              1)
                                                              AS ref_order_id
                                                      FROM (    SELECT s.order_id,
                                                                       s.store_id,
                                                                       s.start_date,
                                                                       s.parent_order_id,
                                                                       SYS_CONNECT_BY_PATH (
                                                                          s.order_id,
                                                                          ',')
                                                                          AS root_path
                                                                  FROM fr_store s
                                                                 WHERE store_id !=
                                                                          '00000'
                                                                       AND (s.status
                                                                               IS NULL
                                                                            OR s.status !=
                                                                                  'D')
                                                                       AND s.cancel_date
                                                                              IS NULL
                                                            START WITH s.parent_order_id
                                                                          IS NULL
                                                            CONNECT BY PRIOR s.order_id =
                                                                          s.parent_order_id)
                                                CONNECT BY (REGEXP_COUNT (
                                                               root_path,
                                                               ',')
                                                            + 1 >= LEVEL
                                                            AND PRIOR order_id =
                                                                   order_id
                                                            AND PRIOR DBMS_RANDOM.VALUE
                                                                   IS NOT NULL))
                                         WHERE ref_order_id IS NOT NULL) s
                               ON s.ref_order_id = eva.fr_store_order_id
                                  AND eva.eval_type = 'MIDYEAR'
                                  --                    and eva.status = 'DO'  --if status older store not equal DO can't show this round  Supakit Madsathan
                                  AND eva.eval_year >=
                                         (TO_NUMBER (TO_CHAR (SYSDATE, 'YYYY'))
                                          - 6)
                                  AND eva.eval_year >= 2010
                                  /*minimum year for display is 2010*/
                                  AND (eva.eval_month =
                                          TO_CHAR (
                                             ADD_MONTHS (s.start_date, 6),
                                             'MM')
                                       OR eva.eval_month =
                                             TO_CHAR (s.start_date, 'MM'))
                                  AND TO_NUMBER (
                                         eva.eval_year
                                         || LPAD (eva.eval_month, 2, '0')) >=
                                         TO_NUMBER (
                                            TO_CHAR (
                                               ADD_MONTHS (s.start_date, 6),
                                               'YYYYMM'))
                            LEFT JOIN fes_adjust_grade ag
                               ON     ag.store_id = eva.order_id
                                  AND ag.eval_month = eva.eval_month
                                  AND ag.eval_year = eva.eval_year
                            LEFT JOIN FES_EVALUATEDFORM ef
                               ON ( (TO_DATE (eva.eval_year || eva.eval_month,
                                              'yyyymm') BETWEEN TO_DATE (
                                                                   ef.start_year
                                                                   || ef.start_month,
                                                                   'yyyymm')
                                                            AND TO_DATE (
                                                                   ef.end_year
                                                                   || ef.end_month,
                                                                   'yyyymm'))
                                   OR (TO_DATE (
                                          eva.eval_year || eva.eval_month,
                                          'yyyymm') >=
                                          TO_DATE (
                                             ef.start_year || ef.start_month,
                                             'yyyymm')
                                       AND ef.end_year IS NULL
                                       AND ef.end_month IS NULL))
                            LEFT JOIN COMMON_CODE cgs
                               ON     cgs.CODE_VALUE = eva.CONFIRM_GRADE_STATUS
                                  AND cgs.code_type = '00105'
                                  AND cgs.ACTIVE_FLAG = 'Y') eva
              WHERE eva.row_rank = 1) a
            INNER JOIN fr_store s1
               ON s1.order_id = a.order_id
            LEFT JOIN fr_store s2
               ON s2.order_id = s1.parent_order_id
            LEFT JOIN mas_store ms
               ON ms.branch_id = s1.store_id
   GROUP BY s1.store_id,
            ms.branch_name,
            ms.region,
            s1.start_date,
            s2.store_id,
            ms.status_type;

-- ---------- VIEW: V_FML_FES_EVALUATE_MIDYEAR_1 ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_FML_FES_EVALUATE_MIDYEAR_1" ("STORE_ID", "STORE_NAME", "REGION", "START_DATE", "PARENT_STORE_ID", "FR_TYPE", "FR_TYPE_NAME", "EVAL_MONTH_ROUND1", "EVAL_YEAR_ROUND1", "EVAL_PERIOD_ROUND1", "POINT_YEAR_ROUND1", "POINT_PCT_YEAR_ROUND1", "GRADE_YEAR_ROUND1", "POINT_ADJUST_YEAR_ROUND1", "POINT_PCT_ADJUST_YEAR_ROUND1", "GRADE_ADJUST_YEAR_ROUND1", "CONCLUDE_DATE_YEAR_ROUND1", "M_CONCLUDE_DATE_YEAR_ROUND1", "CONFIRM_GRADE_YEAR_ROUND1", "CONFIRM_GRADE_D_YEAR_ROUND1", "EVAL_MONTH_ROUND2", "EVAL_YEAR_ROUND2", "EVAL_PERIOD_ROUND2", "POINT_YEAR_ROUND2", "POINT_PCT_YEAR_ROUND2", "GRADE_YEAR_ROUND2", "POINT_ADJUST_YEAR_ROUND2", "POINT_PCT_ADJUST_YEAR_ROUND2", "GRADE_ADJUST_YEAR_ROUND2", "CONCLUDE_DATE_YEAR_ROUND2", "M_CONCLUDE_DATE_YEAR_ROUND2", "CONFIRM_GRADE_YEAR_ROUND2", "CONFIRM_GRADE_D_YEAR_ROUND2", "EVAL_MONTH1_ROUND1", "EVAL_YEAR1_ROUND1", "EVAL_PERIOD1_ROUND1", "POINT_YEAR1_ROUND1", "POINT_PCT_YEAR1_ROUND1", "GRADE_YEAR1_ROUND1", "POINT_ADJUST_YEAR1_ROUND1", "POINT_PCT_ADJUST_YEAR1_ROUND1", "GRADE_ADJUST_YEAR1_ROUND1", "CONCLUDE_DATE_YEAR1_ROUND1", "M_CONCLUDE_DATE_YEAR1_ROUND1", "CONFIRM_GRADE_YEAR1_ROUND1", "CONFIRM_GRADE_D_YEAR1_ROUND1", "EVAL_MONTH1_ROUND2", "EVAL_YEAR1_ROUND2", "EVAL_PERIOD1_ROUND2", "POINT_YEAR1_ROUND2", "POINT_PCT_YEAR1_ROUND2", "GRADE_YEAR1_ROUND2", "POINT_ADJUST_YEAR1_ROUND2", "POINT_PCT_ADJUST_YEAR1_ROUND2", "GRADE_ADJUST_YEAR1_ROUND2", "CONCLUDE_DATE_YEAR1_ROUND2", "M_CONCLUDE_DATE_YEAR1_ROUND2", "CONFIRM_GRADE_YEAR1_ROUND2", "CONFIRM_GRADE_D_YEAR1_ROUND2", "EVAL_MONTH2_ROUND1", "EVAL_YEAR2_ROUND1", "EVAL_PERIOD2_ROUND1", "POINT_YEAR2_ROUND1", "POINT_PCT_YEAR2_ROUND1", "GRADE_YEAR2_ROUND1", "POINT_ADJUST_YEAR2_ROUND1", "POINT_PCT_ADJUST_YEAR2_ROUND1", "GRADE_ADJUST_YEAR2_ROUND1", "CONCLUDE_DATE_YEAR2_ROUND1", "M_CONCLUDE_DATE_YEAR2_ROUND1", "CONFIRM_GRADE_YEAR2_ROUND1", "CONFIRM_GRADE_D_YEAR2_ROUND1", "EVAL_MONTH2_ROUND2", "EVAL_YEAR2_ROUND2", "EVAL_PERIOD2_ROUND2", "POINT_YEAR2_ROUND2", "POINT_PCT_YEAR2_ROUND2", "GRADE_YEAR2_ROUND2", "POINT_ADJUST_YEAR2_ROUND2", "POINT_PCT_ADJUST_YEAR2_ROUND2", "GRADE_ADJUST_YEAR2_ROUND2", "CONCLUDE_DATE_YEAR2_ROUND2", "M_CONCLUDE_DATE_YEAR2_ROUND2", "CONFIRM_GRADE_YEAR2_ROUND2", "CONFIRM_GRADE_D_YEAR2_ROUND2") AS 
  SELECT s1.store_id,                                     -- as "รหัสสาขา",
            ms.branch_name AS store_name,                    -- as "ชื่อสาขา",
            ms.region,                                            -- as "ภาค",
            s1.start_date,                         -- as "วันที่เป็นแฟรนไชส์",
            s2.store_id AS parent_store_id,             -- as "ย้ายร้านมาจาก",
            DECODE (ms.status_type,
                    'FPT1', 'PTT',
                    'FAM', 'A',
                    'FB1', 'B',
                    'FB2', 'EMP',
                    'FC1', 'C',
                    'FBGC', 'BGC',
                    NULL)
               AS fr_type,                                -- "ประเภทการลงทุน",
            DECODE (ms.status_type,
                    'FPT1', 'Type ปตท.',
                    'FAM', 'Type A',
                    'FB1', 'Type B',
                    'FB2', 'Type พนักงาน',
                    'FC1', 'Type C',
                    'FBGC', 'Type BGC',
                    NULL)
               AS fr_type_name,
            --YYYY #1
            MAX (DECODE (eval_month1, eval_month1, eval_month1))
               AS eval_month_round1,
            MAX (DECODE (eval_year1, eval_year1, eval_year1))
               AS eval_year_round1,
            MAX (period_year_round1) AS EVAL_PERIOD_round1,
            MAX (point_year_round1) AS point_year_round1,
            MAX (point_pct_year_round1) AS point_pct_year_round1,
            MAX (grade_year_round1) AS grade_year_round1,
            MAX (point_adjust_year_round1) AS point_adjust_year_round1,
            MAX (point_pct_adjust_year_round1) AS point_pct_adjust_year_round1,
            MAX (grade_adjust_year_round1) AS grade_adjust_year_round1,
            MAX (TO_CHAR (CONCLUDE_DATE_YEAR_ROUND1, 'DD/MM/YYYY'))
               AS CONCLUDE_DATE_YEAR_ROUND1,
            MAX (TO_CHAR (M_CONCLUDE_DATE_YEAR_ROUND1, 'DD/MM/YYYY'))
               AS M_CONCLUDE_DATE_YEAR_ROUND1,
            MAX (CONFIRM_GRADE_YEAR_ROUND1) AS CONFIRM_GRADE_YEAR_ROUND1,
            MAX (TO_CHAR (CONFIRM_GRADE_D_YEAR_ROUND1, 'DD/MM/YYYY'))
               AS CONFIRM_GRADE_D_YEAR_ROUND1,
            --YYYY #2
            MAX (DECODE (eval_month2, eval_month2, eval_month2))
               AS eval_month_round2,
            MAX (DECODE (eval_year2, eval_year2, eval_year2))
               AS eval_year_round2,
            MAX (period_year_round2) AS EVAL_PERIOD_round2,
            MAX (point_year_round2) AS point_year_round2,
            MAX (point_pct_year_round2) AS point_pct_year_round2,
            MAX (grade_year_round2) AS grade_year_round2,
            MAX (point_adjust_year_round2) AS point_adjust_year_round2,
            MAX (point_pct_adjust_year_round2) AS point_pct_adjust_year_round2,
            MAX (grade_adjust_year_round2) AS grade_adjust_year_round2,
            MAX (TO_CHAR (CONCLUDE_DATE_YEAR_ROUND2, 'DD/MM/YYYY'))
               AS CONCLUDE_DATE_YEAR_ROUND2,
            MAX (TO_CHAR (M_CONCLUDE_DATE_YEAR_ROUND2, 'DD/MM/YYYY'))
               AS M_CONCLUDE_DATE_YEAR_ROUND2,
            MAX (CONFIRM_GRADE_YEAR_ROUND2) AS CONFIRM_GRADE_YEAR_ROUND2,
            MAX (TO_CHAR (CONFIRM_GRADE_D_YEAR_ROUND2, 'DD/MM/YYYY'))
               AS CONFIRM_GRADE_D_YEAR_ROUND2,
            --(YYYY-1) #1
            MAX (
               DECODE (eval_month1_round1,
                       eval_month1_round1, eval_month1_round1))
               AS eval_month1_round1,
            MAX (
               DECODE (eval_year1_round1, eval_year1_round1, eval_year1_round1))
               AS eval_year1_round1,
            MAX (period_year1_round1) AS EVAL_PERIOD1_round1,
            MAX (point_year1_round1) AS point_year1_round1,
            MAX (point_pct_year1_round1) AS point_pct_year1_round1,
            MAX (grade_year1_round1) AS grade_year1_round1,
            MAX (point_adjust_year1_round1) AS point_adjust_year1_round1,
            MAX (point_pct_adjust_year1_round1)
               AS point_pct_adjust_year1_round1,
            MAX (grade_adjust_year1_round1) AS grade_adjust_year1_round1,
            MAX (TO_CHAR (CONCLUDE_DATE_YEAR1_ROUND1, 'DD/MM/YYYY'))
               AS CONCLUDE_DATE_YEAR1_ROUND1,
            MAX (TO_CHAR (M_CONCLUDE_DATE_YEAR1_ROUND1, 'DD/MM/YYYY'))
               AS M_CONCLUDE_DATE_YEAR1_ROUND1,
            MAX (CONFIRM_GRADE_YEAR1_ROUND1) AS CONFIRM_GRADE_YEAR1_ROUND1,
            MAX (TO_CHAR (CONFIRM_GRADE_D_YEAR1_ROUND1, 'DD/MM/YYYY'))
               AS CONFIRM_GRADE_D_YEAR1_ROUND1,
            --(YYYY-1) #2
            MAX (
               DECODE (eval_month1_round2,
                       eval_month1_round2, eval_month1_round2))
               AS eval_month1_round2,
            MAX (
               DECODE (eval_year1_round2, eval_year1_round2, eval_year1_round2))
               AS eval_year1_round2,
            MAX (period_year1_round2) AS EVAL_PERIOD1_round2,
            MAX (point_year1_round2) AS point_year1_round2,
            MAX (point_pct_year1_round2) AS point_pct_year1_round2,
            MAX (grade_year1_round2) AS grade_year1_round2,
            MAX (point_adjust_year1_round2) AS point_adjust_year1_round2,
            MAX (point_pct_adjust_year1_round2)
               AS point_pct_adjust_year1_round2,
            MAX (grade_adjust_year1_round2) AS grade_adjust_year1_round2,
            MAX (TO_CHAR (CONCLUDE_DATE_YEAR1_ROUND2, 'DD/MM/YYYY'))
               AS CONCLUDE_DATE_YEAR1_ROUND2,
            MAX (TO_CHAR (M_CONCLUDE_DATE_YEAR1_ROUND2, 'DD/MM/YYYY'))
               AS M_CONCLUDE_DATE_YEAR1_ROUND2,
            MAX (CONFIRM_GRADE_YEAR1_ROUND2) AS CONFIRM_GRADE_YEAR1_ROUND2,
            MAX (TO_CHAR (CONFIRM_GRADE_D_YEAR1_ROUND2, 'DD/MM/YYYY'))
               AS CONFIRM_GRADE_D_YEAR1_ROUND2,
            --(YYYY-2) #1
            MAX (
               DECODE (eval_month2_round1,
                       eval_month2_round1, eval_month2_round1))
               AS eval_month2_round1,
            MAX (
               DECODE (eval_year2_round1, eval_year2_round1, eval_year2_round1))
               AS eval_year2_round1,
            MAX (period_year2_round1) AS EVAL_PERIOD2_round1,
            MAX (point_year2_round1) AS point_year2_round1,
            MAX (point_pct_year2_round1) AS point_pct_year2_round1,
            MAX (grade_year2_round1) AS grade_year2_round1,
            MAX (point_adjust_year2_round1) AS point_adjust_year2_round1,
            MAX (point_pct_adjust_year2_round1)
               AS point_pct_adjust_year2_round1,
            MAX (grade_adjust_year2_round1) AS grade_adjust_year2_round1,
            MAX (TO_CHAR (CONCLUDE_DATE_YEAR2_ROUND1, 'DD/MM/YYYY'))
               AS CONCLUDE_DATE_YEAR2_ROUND1,
            MAX (TO_CHAR (M_CONCLUDE_DATE_YEAR2_ROUND1, 'DD/MM/YYYY'))
               AS M_CONCLUDE_DATE_YEAR2_ROUND1,
            MAX (CONFIRM_GRADE_YEAR2_ROUND1) AS CONFIRM_GRADE_YEAR2_ROUND1,
            MAX (TO_CHAR (CONFIRM_GRADE_D_YEAR2_ROUND1, 'DD/MM/YYYY'))
               AS CONFIRM_GRADE_D_YEAR2_ROUND1,
            --(YYYY-2) #2
            MAX (
               DECODE (eval_month2_round2,
                       eval_month2_round2, eval_month2_round2))
               AS eval_month2_round2,
            MAX (
               DECODE (eval_year2_round2, eval_year2_round2, eval_year2_round2))
               AS eval_year2_round2,
            MAX (period_year2_round2) AS EVAL_PERIOD2_round2,
            MAX (point_year2_round2) AS point_year2_round2,
            MAX (point_pct_year2_round2) AS point_pct_year2_round2,
            MAX (grade_year2_round2) AS grade_year2_round2,
            MAX (point_adjust_year2_round2) AS point_adjust_year2_round2,
            MAX (point_pct_adjust_year2_round2)
               AS point_pct_adjust_year2_round2,
            MAX (grade_adjust_year2_round2) AS grade_adjust_year2_round2,
            MAX (TO_CHAR (CONCLUDE_DATE_YEAR2_ROUND2, 'DD/MM/YYYY'))
               AS CONCLUDE_DATE_YEAR2_ROUND2,
            MAX (TO_CHAR (M_CONCLUDE_DATE_YEAR2_ROUND2, 'DD/MM/YYYY'))
               AS M_CONCLUDE_DATE_YEAR2_ROUND2,
            MAX (CONFIRM_GRADE_YEAR2_ROUND2) AS CONFIRM_GRADE_YEAR2_ROUND2,
            MAX (TO_CHAR (CONFIRM_GRADE_D_YEAR2_ROUND2, 'DD/MM/YYYY'))
               AS CONFIRM_GRADE_D_YEAR2_ROUND2
       FROM (SELECT eva.*,
                    --YYYY #1
                    DECODE (FLOOR (eva.eval_month / 7) || eva.eval_year,
                            0 || TO_CHAR (SYSDATE, 'YYYY'), eva.eval_month)
                       AS eval_month1,
                    DECODE (FLOOR (eva.eval_month / 7) || eva.eval_year,
                            0 || TO_CHAR (SYSDATE, 'YYYY'), eva.eval_year)
                       AS eval_year1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || TO_CHAR (SYSDATE, 'YYYY'), CASE
                                                          WHEN eva.start_date <=
                                                                  ADD_MONTHS (
                                                                     TO_DATE (
                                                                        '01/'
                                                                        || eva.eval_month
                                                                        || '/'
                                                                        || eva.eval_year,
                                                                        'DD/MM/YYYY'),
                                                                     -6)
                                                          THEN
                                                             TO_CHAR (
                                                                ADD_MONTHS (
                                                                   TO_DATE (
                                                                      LPAD (
                                                                         eva.eval_month,
                                                                         2,
                                                                         '0')
                                                                      || '/'
                                                                      || eva.eval_year,
                                                                      'MM/YYYY'),
                                                                   -6),
                                                                'FMMON YY',
                                                                'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                             || ' - '
                                                             || TO_CHAR (
                                                                   ADD_MONTHS (
                                                                      TO_DATE (
                                                                         LPAD (
                                                                            eva.eval_month,
                                                                            2,
                                                                            '0')
                                                                         || '/'
                                                                         || eva.eval_year,
                                                                         'MM/YYYY'),
                                                                      -1),
                                                                   'FMMON YY',
                                                                   'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                          ELSE
                                                             TO_CHAR (
                                                                ADD_MONTHS (
                                                                   TO_DATE (
                                                                      LPAD (
                                                                         eva.eval_month,
                                                                         2,
                                                                         '0')
                                                                      || '/'
                                                                      || eva.eval_year,
                                                                      'MM/YYYY'),
                                                                   -5),
                                                                'FMMON YY',
                                                                'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                             || ' - '
                                                             || TO_CHAR (
                                                                   ADD_MONTHS (
                                                                      TO_DATE (
                                                                         LPAD (
                                                                            eva.eval_month,
                                                                            2,
                                                                            '0')
                                                                         || '/'
                                                                         || eva.eval_year,
                                                                         'MM/YYYY'),
                                                                      -1),
                                                                   'FMMON YY',
                                                                   'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                       END)
                       period_year_round1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || TO_CHAR (SYSDATE, 'YYYY'), TO_CHAR (
                                                          eva.total_point,
                                                          '9999.99'))
                       point_year_round1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || TO_CHAR (SYSDATE, 'YYYY'), TO_CHAR (
                                                          (eva.total_point
                                                           * 100)
                                                          / eva.total_point_ef,
                                                          '9999.99'))
                       point_pct_year_round1,
                    DECODE (FLOOR (eva.eval_month / 7) || eva.eval_year,
                            0 || TO_CHAR (SYSDATE, 'YYYY'), eva.grade)
                       grade_year_round1,
                    --ADJUST
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || TO_CHAR (SYSDATE, 'YYYY'), TO_CHAR (
                                                          eva.total_point_adjust,
                                                          '9999.99'))
                       point_adjust_year_round1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || TO_CHAR (SYSDATE, 'YYYY'), TO_CHAR (
                                                          (eva.total_point_adjust
                                                           * 100)
                                                          / eva.total_point_ef,
                                                          '9999.99'))
                       point_pct_adjust_year_round1,
                    DECODE (FLOOR (eva.eval_month / 7) || eva.eval_year,
                            0 || TO_CHAR (SYSDATE, 'YYYY'), eva.grade_adjust)
                       grade_adjust_year_round1,
                    --CONFIRM_GRADE
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY')), eva.CONCLUDE_DATE)
                       CONCLUDE_DATE_YEAR_ROUND1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY')), eva.MODIFY_CONCLUDE_DATE)
                       M_CONCLUDE_DATE_YEAR_ROUND1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY')), eva.CONFIRM_GRADE_STATUS)
                       CONFIRM_GRADE_YEAR_ROUND1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY')), eva.CONFIRM_GRADE_DATE)
                       CONFIRM_GRADE_D_YEAR_ROUND1,
                    --YYYY #2
                    DECODE (FLOOR (eva.eval_month / 7) || eva.eval_year,
                            1 || TO_CHAR (SYSDATE, 'YYYY'), eva.eval_month)
                       AS eval_month2,
                    DECODE (FLOOR (eva.eval_month / 7) || eva.eval_year,
                            1 || TO_CHAR (SYSDATE, 'YYYY'), eva.eval_year)
                       AS eval_year2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || TO_CHAR (SYSDATE, 'YYYY'), CASE
                                                          WHEN eva.start_date <=
                                                                  ADD_MONTHS (
                                                                     TO_DATE (
                                                                        '01/'
                                                                        || eva.eval_month
                                                                        || '/'
                                                                        || eva.eval_year,
                                                                        'DD/MM/YYYY'),
                                                                     -6)
                                                          THEN
                                                             TO_CHAR (
                                                                ADD_MONTHS (
                                                                   TO_DATE (
                                                                      LPAD (
                                                                         eva.eval_month,
                                                                         2,
                                                                         '0')
                                                                      || '/'
                                                                      || eva.eval_year,
                                                                      'MM/YYYY'),
                                                                   -6),
                                                                'FMMON YY',
                                                                'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                             || ' - '
                                                             || TO_CHAR (
                                                                   ADD_MONTHS (
                                                                      TO_DATE (
                                                                         LPAD (
                                                                            eva.eval_month,
                                                                            2,
                                                                            '0')
                                                                         || '/'
                                                                         || eva.eval_year,
                                                                         'MM/YYYY'),
                                                                      -1),
                                                                   'FMMON YY',
                                                                   'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                          ELSE
                                                             TO_CHAR (
                                                                ADD_MONTHS (
                                                                   TO_DATE (
                                                                      LPAD (
                                                                         eva.eval_month,
                                                                         2,
                                                                         '0')
                                                                      || '/'
                                                                      || eva.eval_year,
                                                                      'MM/YYYY'),
                                                                   -5),
                                                                'FMMON YY',
                                                                'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                             || ' - '
                                                             || TO_CHAR (
                                                                   ADD_MONTHS (
                                                                      TO_DATE (
                                                                         LPAD (
                                                                            eva.eval_month,
                                                                            2,
                                                                            '0')
                                                                         || '/'
                                                                         || eva.eval_year,
                                                                         'MM/YYYY'),
                                                                      -1),
                                                                   'FMMON YY',
                                                                   'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                       END)
                       AS period_year_round2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || TO_CHAR (SYSDATE, 'YYYY'), TO_CHAR (
                                                          eva.total_point,
                                                          '9999.99'))
                       AS point_year_round2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || TO_CHAR (SYSDATE, 'YYYY'), TO_CHAR (
                                                          (eva.total_point
                                                           * 100)
                                                          / eva.total_point_ef,
                                                          '9999.99'))
                       point_pct_year_round2,
                    DECODE (FLOOR (eva.eval_month / 7) || eva.eval_year,
                            1 || TO_CHAR (SYSDATE, 'YYYY'), eva.grade)
                       AS grade_year_round2,
                    --ADJUST
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || TO_CHAR (SYSDATE, 'YYYY'), TO_CHAR (
                                                          eva.total_point_adjust,
                                                          '9999.99'))
                       point_adjust_year_round2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || TO_CHAR (SYSDATE, 'YYYY'), TO_CHAR (
                                                          (eva.total_point_adjust
                                                           * 100)
                                                          / eva.total_point_ef,
                                                          '9999.99'))
                       point_pct_adjust_year_round2,
                    DECODE (FLOOR (eva.eval_month / 7) || eva.eval_year,
                            1 || TO_CHAR (SYSDATE, 'YYYY'), eva.grade_adjust)
                       grade_adjust_year_round2,
                    --CONFIRM_GRADE
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY')), eva.CONCLUDE_DATE)
                       CONCLUDE_DATE_YEAR_ROUND2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY')), eva.MODIFY_CONCLUDE_DATE)
                       M_CONCLUDE_DATE_YEAR_ROUND2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY')), eva.CONFIRM_GRADE_STATUS)
                       CONFIRM_GRADE_YEAR_ROUND2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY')), eva.CONFIRM_GRADE_DATE)
                       CONFIRM_GRADE_D_YEAR_ROUND2,
                    --(YYYY-1) #1
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 1), eva.eval_month)
                       AS eval_month1_round1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 1), eva.eval_year)
                       AS eval_year1_round1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 1), CASE
                                                                WHEN eva.start_date <=
                                                                        ADD_MONTHS (
                                                                           TO_DATE (
                                                                              '01/'
                                                                              || eva.eval_month
                                                                              || '/'
                                                                              || eva.eval_year,
                                                                              'DD/MM/YYYY'),
                                                                           -6)
                                                                THEN
                                                                   TO_CHAR (
                                                                      ADD_MONTHS (
                                                                         TO_DATE (
                                                                            LPAD (
                                                                               eva.eval_month,
                                                                               2,
                                                                               '0')
                                                                            || '/'
                                                                            || eva.eval_year,
                                                                            'MM/YYYY'),
                                                                         -6),
                                                                      'FMMON YY',
                                                                      'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                                   || ' - '
                                                                   || TO_CHAR (
                                                                         ADD_MONTHS (
                                                                            TO_DATE (
                                                                               LPAD (
                                                                                  eva.eval_month,
                                                                                  2,
                                                                                  '0')
                                                                               || '/'
                                                                               || eva.eval_year,
                                                                               'MM/YYYY'),
                                                                            -1),
                                                                         'FMMON YY',
                                                                         'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                                ELSE
                                                                   TO_CHAR (
                                                                      ADD_MONTHS (
                                                                         TO_DATE (
                                                                            LPAD (
                                                                               eva.eval_month,
                                                                               2,
                                                                               '0')
                                                                            || '/'
                                                                            || eva.eval_year,
                                                                            'MM/YYYY'),
                                                                         -5),
                                                                      'FMMON YY',
                                                                      'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                                   || ' - '
                                                                   || TO_CHAR (
                                                                         ADD_MONTHS (
                                                                            TO_DATE (
                                                                               LPAD (
                                                                                  eva.eval_month,
                                                                                  2,
                                                                                  '0')
                                                                               || '/'
                                                                               || eva.eval_year,
                                                                               'MM/YYYY'),
                                                                            -1),
                                                                         'FMMON YY',
                                                                         'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                             END)
                       period_year1_round1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 1), TO_CHAR (
                                                                eva.total_point,
                                                                '9999.99'))
                       point_year1_round1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 1), TO_CHAR (
                                                                (eva.total_point
                                                                 * 100)
                                                                / eva.total_point_ef,
                                                                '9999.99'))
                       point_pct_year1_round1,
                    DECODE (FLOOR (eva.eval_month / 7) || eva.eval_year,
                            0 || (TO_CHAR (SYSDATE, 'YYYY') - 1), eva.grade)
                       grade_year1_round1,
                    --ADJUST
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 1), TO_CHAR (
                                                                eva.total_point_adjust,
                                                                '9999.99'))
                       point_adjust_year1_round1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 1), TO_CHAR (
                                                                (eva.total_point_adjust
                                                                 * 100)
                                                                / eva.total_point_ef,
                                                                '9999.99'))
                       point_pct_adjust_year1_round1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 1), eva.grade_adjust)
                       grade_adjust_year1_round1,
                    --CONFIRM_GRADE
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 1), eva.CONCLUDE_DATE)
                       CONCLUDE_DATE_YEAR1_ROUND1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 1), eva.MODIFY_CONCLUDE_DATE)
                       M_CONCLUDE_DATE_YEAR1_ROUND1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 1), eva.CONFIRM_GRADE_STATUS)
                       CONFIRM_GRADE_YEAR1_ROUND1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 1), eva.CONFIRM_GRADE_DATE)
                       CONFIRM_GRADE_D_YEAR1_ROUND1,
                    --(YYYY-1) #2
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 1), eva.eval_month)
                       AS eval_month1_round2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 1), eva.eval_year)
                       AS eval_year1_round2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 1), CASE
                                                                WHEN eva.start_date <=
                                                                        ADD_MONTHS (
                                                                           TO_DATE (
                                                                              '01/'
                                                                              || eva.eval_month
                                                                              || '/'
                                                                              || eva.eval_year,
                                                                              'DD/MM/YYYY'),
                                                                           -6)
                                                                THEN
                                                                   TO_CHAR (
                                                                      ADD_MONTHS (
                                                                         TO_DATE (
                                                                            LPAD (
                                                                               eva.eval_month,
                                                                               2,
                                                                               '0')
                                                                            || '/'
                                                                            || eva.eval_year,
                                                                            'MM/YYYY'),
                                                                         -6),
                                                                      'FMMON YY',
                                                                      'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                                   || ' - '
                                                                   || TO_CHAR (
                                                                         ADD_MONTHS (
                                                                            TO_DATE (
                                                                               LPAD (
                                                                                  eva.eval_month,
                                                                                  2,
                                                                                  '0')
                                                                               || '/'
                                                                               || eva.eval_year,
                                                                               'MM/YYYY'),
                                                                            -1),
                                                                         'FMMON YY',
                                                                         'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                                ELSE
                                                                   TO_CHAR (
                                                                      ADD_MONTHS (
                                                                         TO_DATE (
                                                                            LPAD (
                                                                               eva.eval_month,
