                                                                               || '/'
                                                                               || eva.eval_year,
                                                                               'MM/YYYY'),
                                                                            -1),
                                                                         'FMMON YY',
                                                                         'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                             END)
                       AS period_year1_round2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 1), TO_CHAR (
                                                                eva.total_point,
                                                                '9999.99'))
                       AS point_year1_round2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 1), TO_CHAR (
                                                                (eva.total_point
                                                                 * 100)
                                                                / eva.total_point_ef,
                                                                '9999.99'))
                       point_pct_year1_round2,
                    DECODE (FLOOR (eva.eval_month / 7) || eva.eval_year,
                            1 || (TO_CHAR (SYSDATE, 'YYYY') - 1), eva.grade)
                       AS grade_year1_round2,
                    --ADJUST
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 1), TO_CHAR (
                                                                eva.total_point_adjust,
                                                                '9999.99'))
                       point_adjust_year1_round2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 1), TO_CHAR (
                                                                (eva.total_point_adjust
                                                                 * 100)
                                                                / eva.total_point_ef,
                                                                '9999.99'))
                       point_pct_adjust_year1_round2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 1), eva.grade_adjust)
                       grade_adjust_year1_round2,
                    --CONFIRM_GRADE
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 1), eva.CONCLUDE_DATE)
                       CONCLUDE_DATE_YEAR1_ROUND2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 1), eva.MODIFY_CONCLUDE_DATE)
                       M_CONCLUDE_DATE_YEAR1_ROUND2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 1), eva.CONFIRM_GRADE_STATUS)
                       CONFIRM_GRADE_YEAR1_ROUND2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 1), eva.CONFIRM_GRADE_DATE)
                       CONFIRM_GRADE_D_YEAR1_ROUND2,
                    --(YYYY-2) #1
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 2), eva.eval_month)
                       AS eval_month2_round1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 2), eva.eval_year)
                       AS eval_year2_round1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 2), CASE
                                                                WHEN eva.start_date <=
                                                                        ADD_MONTHS (
                                                                           TO_DATE (
                                                                              '01/'
                                                                              || eva.eval_month
                                                                              || '/'
                                                                              || eva.eval_year,
                                                                              'DD/MM/YYYY'),
                                                                           -6)
                                                                THEN
                                                                   TO_CHAR (
                                                                      ADD_MONTHS (
                                                                         TO_DATE (
                                                                            LPAD (
                                                                               eva.eval_month,
                                                                               2,
                                                                               '0')
                                                                            || '/'
                                                                            || eva.eval_year,
                                                                            'MM/YYYY'),
                                                                         -6),
                                                                      'FMMON YY',
                                                                      'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                                   || ' - '
                                                                   || TO_CHAR (
                                                                         ADD_MONTHS (
                                                                            TO_DATE (
                                                                               LPAD (
                                                                                  eva.eval_month,
                                                                                  2,
                                                                                  '0')
                                                                               || '/'
                                                                               || eva.eval_year,
                                                                               'MM/YYYY'),
                                                                            -1),
                                                                         'FMMON YY',
                                                                         'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                                ELSE
                                                                   TO_CHAR (
                                                                      ADD_MONTHS (
                                                                         TO_DATE (
                                                                            LPAD (
                                                                               eva.eval_month,
                                                                               2,
                                                                               '0')
                                                                            || '/'
                                                                            || eva.eval_year,
                                                                            'MM/YYYY'),
                                                                         -5),
                                                                      'FMMON YY',
                                                                      'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                                   || ' - '
                                                                   || TO_CHAR (
                                                                         ADD_MONTHS (
                                                                            TO_DATE (
                                                                               LPAD (
                                                                                  eva.eval_month,
                                                                                  2,
                                                                                  '0')
                                                                               || '/'
                                                                               || eva.eval_year,
                                                                               'MM/YYYY'),
                                                                            -1),
                                                                         'FMMON YY',
                                                                         'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                             END)
                       AS period_year2_round1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 2), TO_CHAR (
                                                                eva.total_point,
                                                                '9999.99'))
                       point_year2_round1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 2), TO_CHAR (
                                                                (eva.total_point
                                                                 * 100)
                                                                / eva.total_point_ef,
                                                                '9999.99'))
                       point_pct_year2_round1,
                    DECODE (FLOOR (eva.eval_month / 7) || eva.eval_year,
                            0 || (TO_CHAR (SYSDATE, 'YYYY') - 2), eva.grade)
                       grade_year2_round1,
                    --ADJUST
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 2), TO_CHAR (
                                                                eva.total_point_adjust,
                                                                '9999.99'))
                       point_adjust_year2_round1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 2), TO_CHAR (
                                                                (eva.total_point_adjust
                                                                 * 100)
                                                                / eva.total_point_ef,
                                                                '9999.99'))
                       point_pct_adjust_year2_round1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 2), eva.grade_adjust)
                       grade_adjust_year2_round1,
                    --CONFIRM_GRADE
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 2), eva.CONCLUDE_DATE)
                       CONCLUDE_DATE_YEAR2_ROUND1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 2), eva.MODIFY_CONCLUDE_DATE)
                       M_CONCLUDE_DATE_YEAR2_ROUND1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 2), eva.CONFIRM_GRADE_STATUS)
                       CONFIRM_GRADE_YEAR2_ROUND1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 2), eva.CONFIRM_GRADE_DATE)
                       CONFIRM_GRADE_D_YEAR2_ROUND1,
                    --(YYYY-2) #2
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 2), eva.eval_month)
                       AS eval_month2_round2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 2), eva.eval_year)
                       AS eval_year2_round2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 2), CASE
                                                                WHEN eva.start_date <=
                                                                        ADD_MONTHS (
                                                                           TO_DATE (
                                                                              '01/'
                                                                              || eva.eval_month
                                                                              || '/'
                                                                              || eva.eval_year,
                                                                              'DD/MM/YYYY'),
                                                                           -6)
                                                                THEN
                                                                   TO_CHAR (
                                                                      ADD_MONTHS (
                                                                         TO_DATE (
                                                                            LPAD (
                                                                               eva.eval_month,
                                                                               2,
                                                                               '0')
                                                                            || '/'
                                                                            || eva.eval_year,
                                                                            'MM/YYYY'),
                                                                         -6),
                                                                      'FMMON YY',
                                                                      'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                                   || ' - '
                                                                   || TO_CHAR (
                                                                         ADD_MONTHS (
                                                                            TO_DATE (
                                                                               LPAD (
                                                                                  eva.eval_month,
                                                                                  2,
                                                                                  '0')
                                                                               || '/'
                                                                               || eva.eval_year,
                                                                               'MM/YYYY'),
                                                                            -1),
                                                                         'FMMON YY',
                                                                         'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                                ELSE
                                                                   TO_CHAR (
                                                                      ADD_MONTHS (
                                                                         TO_DATE (
                                                                            LPAD (
                                                                               eva.eval_month,
                                                                               2,
                                                                               '0')
                                                                            || '/'
                                                                            || eva.eval_year,
                                                                            'MM/YYYY'),
                                                                         -5),
                                                                      'FMMON YY',
                                                                      'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                                   || ' - '
                                                                   || TO_CHAR (
                                                                         ADD_MONTHS (
                                                                            TO_DATE (
                                                                               LPAD (
                                                                                  eva.eval_month,
                                                                                  2,
                                                                                  '0')
                                                                               || '/'
                                                                               || eva.eval_year,
                                                                               'MM/YYYY'),
                                                                            -1),
                                                                         'FMMON YY',
                                                                         'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                             END)
                       AS period_year2_round2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 2), TO_CHAR (
                                                                eva.total_point,
                                                                '9999.99'))
                       AS point_year2_round2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 2), TO_CHAR (
                                                                (eva.total_point
                                                                 * 100)
                                                                / eva.total_point_ef,
                                                                '9999.99'))
                       point_pct_year2_round2,
                    DECODE (FLOOR (eva.eval_month / 7) || eva.eval_year,
                            1 || (TO_CHAR (SYSDATE, 'YYYY') - 2), eva.grade)
                       AS grade_year2_round2,
                    --ADJUST
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 2), TO_CHAR (
                                                                eva.total_point_adjust,
                                                                '9999.99'))
                       point_adjust_year2_round2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 2), TO_CHAR (
                                                                (eva.total_point_adjust
                                                                 * 100)
                                                                / eva.total_point_ef,
                                                                '9999.99'))
                       point_pct_adjust_year2_round2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 2), eva.grade_adjust)
                       grade_adjust_year2_round2,
                    --CONFIRM_GRADE
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 2), eva.CONCLUDE_DATE)
                       CONCLUDE_DATE_YEAR2_ROUND2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 2), eva.MODIFY_CONCLUDE_DATE)
                       M_CONCLUDE_DATE_YEAR2_ROUND2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 2), eva.CONFIRM_GRADE_STATUS)
                       CONFIRM_GRADE_YEAR2_ROUND2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 2), eva.CONFIRM_GRADE_DATE)
                       CONFIRM_GRADE_D_YEAR2_ROUND2
               FROM (SELECT eva.evaluate_id,
                            eva.eval_month,
                            eva.eval_year,
                            eva.total_point,
                            eva.grade,
                            s.order_id,
                            s.start_date,
                            ag.total_point total_point_adjust,
                            ag.grade grade_adjust,
                            ag.eval_month eval_month_adjust,
                            ag.eval_year eval_year_adjust,
                            ef.TOTAL_POINT TOTAL_POINT_EF,
                            DENSE_RANK ()
                            OVER (
                               PARTITION BY s.order_id,
                                            eva.eval_year,
                                            eva.eval_month
                               ORDER BY
                                  eva.del_status NULLS FIRST,
                                  eva.evaluate_id DESC)
                               AS row_rank,
                            eva.CONCLUDE_DATE,
                            eva.MODIFY_CONCLUDE_DATE,
                            cgs.code_name AS CONFIRM_GRADE_STATUS,
                            eva.CONFIRM_GRADE_DATE
                       FROM fes_evaluate eva
                            INNER JOIN (SELECT *
                                          FROM (    SELECT order_id,
                                                           start_date,
                                                           REGEXP_SUBSTR (
                                                              SUBSTR (root_path, 2),
                                                              ',?([^,]*)',
                                                              1,
                                                              LEVEL,
                                                              'i',
                                                              1)
                                                              AS ref_order_id
                                                      FROM (    SELECT s.order_id,
                                                                       s.store_id,
                                                                       s.start_date,
                                                                       s.parent_order_id,
                                                                       SYS_CONNECT_BY_PATH (
                                                                          s.order_id,
                                                                          ',')
                                                                          AS root_path
                                                                  FROM fr_store s
                                                                 WHERE store_id !=
                                                                          '00000'
                                                                       AND (s.status
                                                                               IS NULL
                                                                            OR s.status !=
                                                                                  'D')
                                                                       AND s.cancel_date
                                                                              IS NULL
                                                            START WITH s.parent_order_id
                                                                          IS NULL
                                                            CONNECT BY PRIOR s.order_id =
                                                                          s.parent_order_id)
                                                CONNECT BY (REGEXP_COUNT (
                                                               root_path,
                                                               ',')
                                                            + 1 >= LEVEL
                                                            AND PRIOR order_id =
                                                                   order_id
                                                            AND PRIOR DBMS_RANDOM.VALUE
                                                                   IS NOT NULL))
                                         WHERE ref_order_id IS NOT NULL) s
                               ON s.ref_order_id = eva.fr_store_order_id
                                  AND eva.eval_type = 'MIDYEAR'
                                  --                    and eva.status = 'DO'  --if status older store not equal DO can't show this round  Supakit Madsathan
                                  AND eva.eval_year >=
                                         (TO_NUMBER (TO_CHAR (SYSDATE, 'YYYY'))
                                          - 6)
                                  AND eva.eval_year >= 2010
                                  /*minimum year for display is 2010*/
                                  AND (eva.eval_month =
                                          TO_CHAR (
                                             ADD_MONTHS (s.start_date, 6),
                                             'MM')
                                       OR eva.eval_month =
                                             TO_CHAR (s.start_date, 'MM'))
                                  AND TO_NUMBER (
                                         eva.eval_year
                                         || LPAD (eva.eval_month, 2, '0')) >=
                                         TO_NUMBER (
                                            TO_CHAR (
                                               ADD_MONTHS (s.start_date, 6),
                                               'YYYYMM'))
                            LEFT JOIN fes_adjust_grade ag
                               ON     ag.store_id = eva.order_id
                                  AND ag.eval_month = eva.eval_month
                                  AND ag.eval_year = eva.eval_year
                            LEFT JOIN FES_EVALUATEDFORM ef
                               ON ( (TO_DATE (eva.eval_year || eva.eval_month,
                                              'yyyymm') BETWEEN TO_DATE (
                                                                   ef.start_year
                                                                   || ef.start_month,
                                                                   'yyyymm')
                                                            AND TO_DATE (
                                                                   ef.end_year
                                                                   || ef.end_month,
                                                                   'yyyymm'))
                                   OR (TO_DATE (
                                          eva.eval_year || eva.eval_month,
                                          'yyyymm') >=
                                          TO_DATE (
                                             ef.start_year || ef.start_month,
                                             'yyyymm')
                                       AND ef.end_year IS NULL
                                       AND ef.end_month IS NULL))
                            LEFT JOIN COMMON_CODE cgs
                               ON     cgs.CODE_VALUE = eva.CONFIRM_GRADE_STATUS
                                  AND cgs.code_type = '00105'
                                  AND cgs.ACTIVE_FLAG = 'Y') eva
              WHERE eva.row_rank = 1) a
            INNER JOIN fr_store s1
               ON s1.order_id = a.order_id
            LEFT JOIN fr_store s2
               ON s2.order_id = s1.parent_order_id
            LEFT JOIN mas_store ms
               ON ms.branch_id = s1.store_id
   GROUP BY s1.store_id,
            ms.branch_name,
            ms.region,
            s1.start_date,
            s2.store_id,
            ms.status_type;

-- ---------- VIEW: V_FML_FES_EVALUATE_MIDYEAR_2 ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_FML_FES_EVALUATE_MIDYEAR_2" ("STORE_ID", "STORE_NAME", "REGION", "START_DATE", "PARENT_STORE_ID", "FR_TYPE", "FR_TYPE_NAME", "EVAL_MONTH_ROUND1", "EVAL_YEAR_ROUND1", "EVAL_PERIOD_ROUND1", "POINT_YEAR_ROUND1", "POINT_PCT_YEAR_ROUND1", "GRADE_YEAR_ROUND1", "POINT_ADJUST_YEAR_ROUND1", "POINT_PCT_ADJUST_YEAR_ROUND1", "GRADE_ADJUST_YEAR_ROUND1", "CONCLUDE_DATE_YEAR_ROUND1", "M_CONCLUDE_DATE_YEAR_ROUND1", "CONFIRM_GRADE_YEAR_ROUND1", "CONFIRM_GRADE_D_YEAR_ROUND1", "EVAL_MONTH_ROUND2", "EVAL_YEAR_ROUND2", "EVAL_PERIOD_ROUND2", "POINT_YEAR_ROUND2", "POINT_PCT_YEAR_ROUND2", "GRADE_YEAR_ROUND2", "POINT_ADJUST_YEAR_ROUND2", "POINT_PCT_ADJUST_YEAR_ROUND2", "GRADE_ADJUST_YEAR_ROUND2", "CONCLUDE_DATE_YEAR_ROUND2", "M_CONCLUDE_DATE_YEAR_ROUND2", "CONFIRM_GRADE_YEAR_ROUND2", "CONFIRM_GRADE_D_YEAR_ROUND2", "EVAL_MONTH1_ROUND1", "EVAL_YEAR1_ROUND1", "EVAL_PERIOD1_ROUND1", "POINT_YEAR1_ROUND1", "POINT_PCT_YEAR1_ROUND1", "GRADE_YEAR1_ROUND1", "POINT_ADJUST_YEAR1_ROUND1", "POINT_PCT_ADJUST_YEAR1_ROUND1", "GRADE_ADJUST_YEAR1_ROUND1", "CONCLUDE_DATE_YEAR1_ROUND1", "M_CONCLUDE_DATE_YEAR1_ROUND1", "CONFIRM_GRADE_YEAR1_ROUND1", "CONFIRM_GRADE_D_YEAR1_ROUND1", "EVAL_MONTH1_ROUND2", "EVAL_YEAR1_ROUND2", "EVAL_PERIOD1_ROUND2", "POINT_YEAR1_ROUND2", "POINT_PCT_YEAR1_ROUND2", "GRADE_YEAR1_ROUND2", "POINT_ADJUST_YEAR1_ROUND2", "POINT_PCT_ADJUST_YEAR1_ROUND2", "GRADE_ADJUST_YEAR1_ROUND2", "CONCLUDE_DATE_YEAR1_ROUND2", "M_CONCLUDE_DATE_YEAR1_ROUND2", "CONFIRM_GRADE_YEAR1_ROUND2", "CONFIRM_GRADE_D_YEAR1_ROUND2", "EVAL_MONTH2_ROUND1", "EVAL_YEAR2_ROUND1", "EVAL_PERIOD2_ROUND1", "POINT_YEAR2_ROUND1", "POINT_PCT_YEAR2_ROUND1", "GRADE_YEAR2_ROUND1", "POINT_ADJUST_YEAR2_ROUND1", "POINT_PCT_ADJUST_YEAR2_ROUND1", "GRADE_ADJUST_YEAR2_ROUND1", "CONCLUDE_DATE_YEAR2_ROUND1", "M_CONCLUDE_DATE_YEAR2_ROUND1", "CONFIRM_GRADE_YEAR2_ROUND1", "CONFIRM_GRADE_D_YEAR2_ROUND1", "EVAL_MONTH2_ROUND2", "EVAL_YEAR2_ROUND2", "EVAL_PERIOD2_ROUND2", "POINT_YEAR2_ROUND2", "POINT_PCT_YEAR2_ROUND2", "GRADE_YEAR2_ROUND2", "POINT_ADJUST_YEAR2_ROUND2", "POINT_PCT_ADJUST_YEAR2_ROUND2", "GRADE_ADJUST_YEAR2_ROUND2", "CONCLUDE_DATE_YEAR2_ROUND2", "M_CONCLUDE_DATE_YEAR2_ROUND2", "CONFIRM_GRADE_YEAR2_ROUND2", "CONFIRM_GRADE_D_YEAR2_ROUND2") AS 
  SELECT s1.store_id,                                     -- as "รหัสสาขา",
            ms.branch_name AS store_name,                    -- as "ชื่อสาขา",
            ms.region,                                            -- as "ภาค",
            s1.start_date,                         -- as "วันที่เป็นแฟรนไชส์",
            s2.store_id AS parent_store_id,             -- as "ย้ายร้านมาจาก",
            DECODE (ms.status_type,
                    'FPT1', 'PTT',
                    'FAM', 'A',
                    'FB1', 'B',
                    'FB2', 'EMP',
                    'FC1', 'C',
                    'FBGC', 'BGC',
                    NULL)
               AS fr_type,                                -- "ประเภทการลงทุน",
            DECODE (ms.status_type,
                    'FPT1', 'Type ปตท.',
                    'FAM', 'Type A',
                    'FB1', 'Type B',
                    'FB2', 'Type พนักงาน',
                    'FC1', 'Type C',
                    'FBGC', 'Type BGC',
                    NULL)
               AS fr_type_name,
            --YYYY #1
            MAX (DECODE (eval_month1, eval_month1, eval_month1))
               AS eval_month_round1,
            MAX (DECODE (eval_year1, eval_year1, eval_year1))
               AS eval_year_round1,
            MAX (period_year_round1) AS EVAL_PERIOD_round1,
            MAX (point_year_round1) AS point_year_round1,
            MAX (point_pct_year_round1) AS point_pct_year_round1,
            MAX (grade_year_round1) AS grade_year_round1,
            MAX (point_adjust_year_round1) AS point_adjust_year_round1,
            MAX (point_pct_adjust_year_round1) AS point_pct_adjust_year_round1,
            MAX (grade_adjust_year_round1) AS grade_adjust_year_round1,
            MAX (TO_CHAR (CONCLUDE_DATE_YEAR_ROUND1, 'DD/MM/YYYY'))
               AS CONCLUDE_DATE_YEAR_ROUND1,
            MAX (TO_CHAR (M_CONCLUDE_DATE_YEAR_ROUND1, 'DD/MM/YYYY'))
               AS M_CONCLUDE_DATE_YEAR_ROUND1,
            MAX (CONFIRM_GRADE_YEAR_ROUND1) AS CONFIRM_GRADE_YEAR_ROUND1,
            MAX (TO_CHAR (CONFIRM_GRADE_D_YEAR_ROUND1, 'DD/MM/YYYY'))
               AS CONFIRM_GRADE_D_YEAR_ROUND1,
            --YYYY #2
            MAX (DECODE (eval_month2, eval_month2, eval_month2))
               AS eval_month_round2,
            MAX (DECODE (eval_year2, eval_year2, eval_year2))
               AS eval_year_round2,
            MAX (period_year_round2) AS EVAL_PERIOD_round2,
            MAX (point_year_round2) AS point_year_round2,
            MAX (point_pct_year_round2) AS point_pct_year_round2,
            MAX (grade_year_round2) AS grade_year_round2,
            MAX (point_adjust_year_round2) AS point_adjust_year_round2,
            MAX (point_pct_adjust_year_round2) AS point_pct_adjust_year_round2,
            MAX (grade_adjust_year_round2) AS grade_adjust_year_round2,
            MAX (TO_CHAR (CONCLUDE_DATE_YEAR_ROUND2, 'DD/MM/YYYY'))
               AS CONCLUDE_DATE_YEAR_ROUND2,
            MAX (TO_CHAR (M_CONCLUDE_DATE_YEAR_ROUND2, 'DD/MM/YYYY'))
               AS M_CONCLUDE_DATE_YEAR_ROUND2,
            MAX (CONFIRM_GRADE_YEAR_ROUND2) AS CONFIRM_GRADE_YEAR_ROUND2,
            MAX (TO_CHAR (CONFIRM_GRADE_D_YEAR_ROUND2, 'DD/MM/YYYY'))
               AS CONFIRM_GRADE_D_YEAR_ROUND2,
            --(YYYY-1) #1
            MAX (
               DECODE (eval_month1_round1,
                       eval_month1_round1, eval_month1_round1))
               AS eval_month1_round1,
            MAX (
               DECODE (eval_year1_round1, eval_year1_round1, eval_year1_round1))
               AS eval_year1_round1,
            MAX (period_year1_round1) AS EVAL_PERIOD1_round1,
            MAX (point_year1_round1) AS point_year1_round1,
            MAX (point_pct_year1_round1) AS point_pct_year1_round1,
            MAX (grade_year1_round1) AS grade_year1_round1,
            MAX (point_adjust_year1_round1) AS point_adjust_year1_round1,
            MAX (point_pct_adjust_year1_round1)
               AS point_pct_adjust_year1_round1,
            MAX (grade_adjust_year1_round1) AS grade_adjust_year1_round1,
            MAX (TO_CHAR (CONCLUDE_DATE_YEAR1_ROUND1, 'DD/MM/YYYY'))
               AS CONCLUDE_DATE_YEAR1_ROUND1,
            MAX (TO_CHAR (M_CONCLUDE_DATE_YEAR1_ROUND1, 'DD/MM/YYYY'))
               AS M_CONCLUDE_DATE_YEAR1_ROUND1,
            MAX (CONFIRM_GRADE_YEAR1_ROUND1) AS CONFIRM_GRADE_YEAR1_ROUND1,
            MAX (TO_CHAR (CONFIRM_GRADE_D_YEAR1_ROUND1, 'DD/MM/YYYY'))
               AS CONFIRM_GRADE_D_YEAR1_ROUND1,
            --(YYYY-1) #2
            MAX (
               DECODE (eval_month1_round2,
                       eval_month1_round2, eval_month1_round2))
               AS eval_month1_round2,
            MAX (
               DECODE (eval_year1_round2, eval_year1_round2, eval_year1_round2))
               AS eval_year1_round2,
            MAX (period_year1_round2) AS EVAL_PERIOD1_round2,
            MAX (point_year1_round2) AS point_year1_round2,
            MAX (point_pct_year1_round2) AS point_pct_year1_round2,
            MAX (grade_year1_round2) AS grade_year1_round2,
            MAX (point_adjust_year1_round2) AS point_adjust_year1_round2,
            MAX (point_pct_adjust_year1_round2)
               AS point_pct_adjust_year1_round2,
            MAX (grade_adjust_year1_round2) AS grade_adjust_year1_round2,
            MAX (TO_CHAR (CONCLUDE_DATE_YEAR1_ROUND2, 'DD/MM/YYYY'))
               AS CONCLUDE_DATE_YEAR1_ROUND2,
            MAX (TO_CHAR (M_CONCLUDE_DATE_YEAR1_ROUND2, 'DD/MM/YYYY'))
               AS M_CONCLUDE_DATE_YEAR1_ROUND2,
            MAX (CONFIRM_GRADE_YEAR1_ROUND2) AS CONFIRM_GRADE_YEAR1_ROUND2,
            MAX (TO_CHAR (CONFIRM_GRADE_D_YEAR1_ROUND2, 'DD/MM/YYYY'))
               AS CONFIRM_GRADE_D_YEAR1_ROUND2,
            --(YYYY-2) #1
            MAX (
               DECODE (eval_month2_round1,
                       eval_month2_round1, eval_month2_round1))
               AS eval_month2_round1,
            MAX (
               DECODE (eval_year2_round1, eval_year2_round1, eval_year2_round1))
               AS eval_year2_round1,
            MAX (period_year2_round1) AS EVAL_PERIOD2_round1,
            MAX (point_year2_round1) AS point_year2_round1,
            MAX (point_pct_year2_round1) AS point_pct_year2_round1,
            MAX (grade_year2_round1) AS grade_year2_round1,
            MAX (point_adjust_year2_round1) AS point_adjust_year2_round1,
            MAX (point_pct_adjust_year2_round1)
               AS point_pct_adjust_year2_round1,
            MAX (grade_adjust_year2_round1) AS grade_adjust_year2_round1,
            MAX (TO_CHAR (CONCLUDE_DATE_YEAR2_ROUND1, 'DD/MM/YYYY'))
               AS CONCLUDE_DATE_YEAR2_ROUND1,
            MAX (TO_CHAR (M_CONCLUDE_DATE_YEAR2_ROUND1, 'DD/MM/YYYY'))
               AS M_CONCLUDE_DATE_YEAR2_ROUND1,
            MAX (CONFIRM_GRADE_YEAR2_ROUND1) AS CONFIRM_GRADE_YEAR2_ROUND1,
            MAX (TO_CHAR (CONFIRM_GRADE_D_YEAR2_ROUND1, 'DD/MM/YYYY'))
               AS CONFIRM_GRADE_D_YEAR2_ROUND1,
            --(YYYY-2) #2
            MAX (
               DECODE (eval_month2_round2,
                       eval_month2_round2, eval_month2_round2))
               AS eval_month2_round2,
            MAX (
               DECODE (eval_year2_round2, eval_year2_round2, eval_year2_round2))
               AS eval_year2_round2,
            MAX (period_year2_round2) AS EVAL_PERIOD2_round2,
            MAX (point_year2_round2) AS point_year2_round2,
            MAX (point_pct_year2_round2) AS point_pct_year2_round2,
            MAX (grade_year2_round2) AS grade_year2_round2,
            MAX (point_adjust_year2_round2) AS point_adjust_year2_round2,
            MAX (point_pct_adjust_year2_round2)
               AS point_pct_adjust_year2_round2,
            MAX (grade_adjust_year2_round2) AS grade_adjust_year2_round2,
            MAX (TO_CHAR (CONCLUDE_DATE_YEAR2_ROUND2, 'DD/MM/YYYY'))
               AS CONCLUDE_DATE_YEAR2_ROUND2,
            MAX (TO_CHAR (M_CONCLUDE_DATE_YEAR2_ROUND2, 'DD/MM/YYYY'))
               AS M_CONCLUDE_DATE_YEAR2_ROUND2,
            MAX (CONFIRM_GRADE_YEAR2_ROUND2) AS CONFIRM_GRADE_YEAR2_ROUND2,
            MAX (TO_CHAR (CONFIRM_GRADE_D_YEAR2_ROUND2, 'DD/MM/YYYY'))
               AS CONFIRM_GRADE_D_YEAR2_ROUND2
       FROM (SELECT eva.*,
                    --YYYY #1
                    DECODE (FLOOR (eva.eval_month / 7) || eva.eval_year,
                            0 || TO_CHAR (SYSDATE, 'YYYY'), eva.eval_month)
                       AS eval_month1,
                    DECODE (FLOOR (eva.eval_month / 7) || eva.eval_year,
                            0 || TO_CHAR (SYSDATE, 'YYYY'), eva.eval_year)
                       AS eval_year1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || TO_CHAR (SYSDATE, 'YYYY'), CASE
                                                          WHEN eva.start_date <=
                                                                  ADD_MONTHS (
                                                                     TO_DATE (
                                                                        '01/'
                                                                        || eva.eval_month
                                                                        || '/'
                                                                        || eva.eval_year,
                                                                        'DD/MM/YYYY'),
                                                                     -6)
                                                          THEN
                                                             TO_CHAR (
                                                                ADD_MONTHS (
                                                                   TO_DATE (
                                                                      LPAD (
                                                                         eva.eval_month,
                                                                         2,
                                                                         '0')
                                                                      || '/'
                                                                      || eva.eval_year,
                                                                      'MM/YYYY'),
                                                                   -6),
                                                                'FMMON YY',
                                                                'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                             || ' - '
                                                             || TO_CHAR (
                                                                   ADD_MONTHS (
                                                                      TO_DATE (
                                                                         LPAD (
                                                                            eva.eval_month,
                                                                            2,
                                                                            '0')
                                                                         || '/'
                                                                         || eva.eval_year,
                                                                         'MM/YYYY'),
                                                                      -1),
                                                                   'FMMON YY',
                                                                   'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                          ELSE
                                                             TO_CHAR (
                                                                ADD_MONTHS (
                                                                   TO_DATE (
                                                                      LPAD (
                                                                         eva.eval_month,
                                                                         2,
                                                                         '0')
                                                                      || '/'
                                                                      || eva.eval_year,
                                                                      'MM/YYYY'),
                                                                   -5),
                                                                'FMMON YY',
                                                                'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                             || ' - '
                                                             || TO_CHAR (
                                                                   ADD_MONTHS (
                                                                      TO_DATE (
                                                                         LPAD (
                                                                            eva.eval_month,
                                                                            2,
                                                                            '0')
                                                                         || '/'
                                                                         || eva.eval_year,
                                                                         'MM/YYYY'),
                                                                      -1),
                                                                   'FMMON YY',
                                                                   'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                       END)
                       period_year_round1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || TO_CHAR (SYSDATE, 'YYYY'), TO_CHAR (
                                                          eva.total_point,
                                                          '9999.99'))
                       point_year_round1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || TO_CHAR (SYSDATE, 'YYYY'), TO_CHAR (
                                                          (eva.total_point
                                                           * 100)
                                                          / eva.total_point_ef,
                                                          '9999.99'))
                       point_pct_year_round1,
                    DECODE (FLOOR (eva.eval_month / 7) || eva.eval_year,
                            0 || TO_CHAR (SYSDATE, 'YYYY'), eva.grade)
                       grade_year_round1,
                    --ADJUST
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || TO_CHAR (SYSDATE, 'YYYY'), TO_CHAR (
                                                          eva.total_point_adjust,
                                                          '9999.99'))
                       point_adjust_year_round1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || TO_CHAR (SYSDATE, 'YYYY'), TO_CHAR (
                                                          (eva.total_point_adjust
                                                           * 100)
                                                          / eva.total_point_ef,
                                                          '9999.99'))
                       point_pct_adjust_year_round1,
                    DECODE (FLOOR (eva.eval_month / 7) || eva.eval_year,
                            0 || TO_CHAR (SYSDATE, 'YYYY'), eva.grade_adjust)
                       grade_adjust_year_round1,
                    --CONFIRM_GRADE
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY')), eva.CONCLUDE_DATE)
                       CONCLUDE_DATE_YEAR_ROUND1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY')), eva.MODIFY_CONCLUDE_DATE)
                       M_CONCLUDE_DATE_YEAR_ROUND1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY')), eva.CONFIRM_GRADE_STATUS)
                       CONFIRM_GRADE_YEAR_ROUND1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY')), eva.CONFIRM_GRADE_DATE)
                       CONFIRM_GRADE_D_YEAR_ROUND1,
                    --YYYY #2
                    DECODE (FLOOR (eva.eval_month / 7) || eva.eval_year,
                            1 || TO_CHAR (SYSDATE, 'YYYY'), eva.eval_month)
                       AS eval_month2,
                    DECODE (FLOOR (eva.eval_month / 7) || eva.eval_year,
                            1 || TO_CHAR (SYSDATE, 'YYYY'), eva.eval_year)
                       AS eval_year2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || TO_CHAR (SYSDATE, 'YYYY'), CASE
                                                          WHEN eva.start_date <=
                                                                  ADD_MONTHS (
                                                                     TO_DATE (
                                                                        '01/'
                                                                        || eva.eval_month
                                                                        || '/'
                                                                        || eva.eval_year,
                                                                        'DD/MM/YYYY'),
                                                                     -6)
                                                          THEN
                                                             TO_CHAR (
                                                                ADD_MONTHS (
                                                                   TO_DATE (
                                                                      LPAD (
                                                                         eva.eval_month,
                                                                         2,
                                                                         '0')
                                                                      || '/'
                                                                      || eva.eval_year,
                                                                      'MM/YYYY'),
                                                                   -6),
                                                                'FMMON YY',
                                                                'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                             || ' - '
                                                             || TO_CHAR (
                                                                   ADD_MONTHS (
                                                                      TO_DATE (
                                                                         LPAD (
                                                                            eva.eval_month,
                                                                            2,
                                                                            '0')
                                                                         || '/'
                                                                         || eva.eval_year,
                                                                         'MM/YYYY'),
                                                                      -1),
                                                                   'FMMON YY',
                                                                   'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                          ELSE
                                                             TO_CHAR (
                                                                ADD_MONTHS (
                                                                   TO_DATE (
                                                                      LPAD (
                                                                         eva.eval_month,
                                                                         2,
                                                                         '0')
                                                                      || '/'
                                                                      || eva.eval_year,
                                                                      'MM/YYYY'),
                                                                   -5),
                                                                'FMMON YY',
                                                                'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                             || ' - '
                                                             || TO_CHAR (
                                                                   ADD_MONTHS (
                                                                      TO_DATE (
                                                                         LPAD (
                                                                            eva.eval_month,
                                                                            2,
                                                                            '0')
                                                                         || '/'
                                                                         || eva.eval_year,
                                                                         'MM/YYYY'),
                                                                      -1),
                                                                   'FMMON YY',
                                                                   'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                       END)
                       AS period_year_round2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || TO_CHAR (SYSDATE, 'YYYY'), TO_CHAR (
                                                          eva.total_point,
                                                          '9999.99'))
                       AS point_year_round2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || TO_CHAR (SYSDATE, 'YYYY'), TO_CHAR (
                                                          (eva.total_point
                                                           * 100)
                                                          / eva.total_point_ef,
                                                          '9999.99'))
                       point_pct_year_round2,
                    DECODE (FLOOR (eva.eval_month / 7) || eva.eval_year,
                            1 || TO_CHAR (SYSDATE, 'YYYY'), eva.grade)
                       AS grade_year_round2,
                    --ADJUST
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || TO_CHAR (SYSDATE, 'YYYY'), TO_CHAR (
                                                          eva.total_point_adjust,
                                                          '9999.99'))
                       point_adjust_year_round2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || TO_CHAR (SYSDATE, 'YYYY'), TO_CHAR (
                                                          (eva.total_point_adjust
                                                           * 100)
                                                          / eva.total_point_ef,
                                                          '9999.99'))
                       point_pct_adjust_year_round2,
                    DECODE (FLOOR (eva.eval_month / 7) || eva.eval_year,
                            1 || TO_CHAR (SYSDATE, 'YYYY'), eva.grade_adjust)
                       grade_adjust_year_round2,
                    --CONFIRM_GRADE
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY')), eva.CONCLUDE_DATE)
                       CONCLUDE_DATE_YEAR_ROUND2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY')), eva.MODIFY_CONCLUDE_DATE)
                       M_CONCLUDE_DATE_YEAR_ROUND2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY')), eva.CONFIRM_GRADE_STATUS)
                       CONFIRM_GRADE_YEAR_ROUND2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY')), eva.CONFIRM_GRADE_DATE)
                       CONFIRM_GRADE_D_YEAR_ROUND2,
                    --(YYYY-1) #1
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 1), eva.eval_month)
                       AS eval_month1_round1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 1), eva.eval_year)
                       AS eval_year1_round1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 1), CASE
                                                                WHEN eva.start_date <=
                                                                        ADD_MONTHS (
                                                                           TO_DATE (
                                                                              '01/'
                                                                              || eva.eval_month
                                                                              || '/'
                                                                              || eva.eval_year,
                                                                              'DD/MM/YYYY'),
                                                                           -6)
                                                                THEN
                                                                   TO_CHAR (
                                                                      ADD_MONTHS (
                                                                         TO_DATE (
                                                                            LPAD (
                                                                               eva.eval_month,
                                                                               2,
                                                                               '0')
                                                                            || '/'
                                                                            || eva.eval_year,
                                                                            'MM/YYYY'),
                                                                         -6),
                                                                      'FMMON YY',
                                                                      'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                                   || ' - '
                                                                   || TO_CHAR (
                                                                         ADD_MONTHS (
                                                                            TO_DATE (
                                                                               LPAD (
                                                                                  eva.eval_month,
                                                                                  2,
                                                                                  '0')
                                                                               || '/'
                                                                               || eva.eval_year,
                                                                               'MM/YYYY'),
                                                                            -1),
                                                                         'FMMON YY',
                                                                         'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                                ELSE
                                                                   TO_CHAR (
                                                                      ADD_MONTHS (
                                                                         TO_DATE (
                                                                            LPAD (
                                                                               eva.eval_month,
                                                                               2,
                                                                               '0')
                                                                            || '/'
                                                                            || eva.eval_year,
                                                                            'MM/YYYY'),
                                                                         -5),
                                                                      'FMMON YY',
                                                                      'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                                   || ' - '
                                                                   || TO_CHAR (
                                                                         ADD_MONTHS (
                                                                            TO_DATE (
                                                                               LPAD (
                                                                                  eva.eval_month,
                                                                                  2,
                                                                                  '0')
                                                                               || '/'
                                                                               || eva.eval_year,
                                                                               'MM/YYYY'),
                                                                            -1),
                                                                         'FMMON YY',
                                                                         'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                             END)
                       period_year1_round1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 1), TO_CHAR (
                                                                eva.total_point,
                                                                '9999.99'))
                       point_year1_round1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 1), TO_CHAR (
                                                                (eva.total_point
                                                                 * 100)
                                                                / eva.total_point_ef,
                                                                '9999.99'))
                       point_pct_year1_round1,
                    DECODE (FLOOR (eva.eval_month / 7) || eva.eval_year,
                            0 || (TO_CHAR (SYSDATE, 'YYYY') - 1), eva.grade)
                       grade_year1_round1,
                    --ADJUST
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 1), TO_CHAR (
                                                                eva.total_point_adjust,
                                                                '9999.99'))
                       point_adjust_year1_round1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 1), TO_CHAR (
                                                                (eva.total_point_adjust
                                                                 * 100)
                                                                / eva.total_point_ef,
                                                                '9999.99'))
                       point_pct_adjust_year1_round1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 1), eva.grade_adjust)
                       grade_adjust_year1_round1,
                    --CONFIRM_GRADE
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 1), eva.CONCLUDE_DATE)
                       CONCLUDE_DATE_YEAR1_ROUND1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 1), eva.MODIFY_CONCLUDE_DATE)
                       M_CONCLUDE_DATE_YEAR1_ROUND1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 1), eva.CONFIRM_GRADE_STATUS)
                       CONFIRM_GRADE_YEAR1_ROUND1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 1), eva.CONFIRM_GRADE_DATE)
                       CONFIRM_GRADE_D_YEAR1_ROUND1,
                    --(YYYY-1) #2
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 1), eva.eval_month)
                       AS eval_month1_round2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 1), eva.eval_year)
                       AS eval_year1_round2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 1), CASE
                                                                WHEN eva.start_date <=
                                                                        ADD_MONTHS (
                                                                           TO_DATE (
                                                                              '01/'
                                                                              || eva.eval_month
                                                                              || '/'
                                                                              || eva.eval_year,
                                                                              'DD/MM/YYYY'),
                                                                           -6)
                                                                THEN
                                                                   TO_CHAR (
                                                                      ADD_MONTHS (
                                                                         TO_DATE (
                                                                            LPAD (
                                                                               eva.eval_month,
                                                                               2,
                                                                               '0')
                                                                            || '/'
                                                                            || eva.eval_year,
                                                                            'MM/YYYY'),
                                                                         -6),
                                                                      'FMMON YY',
                                                                      'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                                   || ' - '
                                                                   || TO_CHAR (
                                                                         ADD_MONTHS (
                                                                            TO_DATE (
                                                                               LPAD (
                                                                                  eva.eval_month,
                                                                                  2,
                                                                                  '0')
                                                                               || '/'
                                                                               || eva.eval_year,
                                                                               'MM/YYYY'),
                                                                            -1),
                                                                         'FMMON YY',
                                                                         'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                                ELSE
                                                                   TO_CHAR (
                                                                      ADD_MONTHS (
                                                                         TO_DATE (
                                                                            LPAD (
                                                                               eva.eval_month,
                                                                               2,
                                                                               '0')
                                                                            || '/'
                                                                            || eva.eval_year,
                                                                            'MM/YYYY'),
                                                                         -5),
                                                                      'FMMON YY',
                                                                      'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                                   || ' - '
                                                                   || TO_CHAR (
                                                                         ADD_MONTHS (
                                                                            TO_DATE (
                                                                               LPAD (
                                                                                  eva.eval_month,
                                                                                  2,
                                                                                  '0')
                                                                               || '/'
                                                                               || eva.eval_year,
                                                                               'MM/YYYY'),
                                                                            -1),
                                                                         'FMMON YY',
                                                                         'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                             END)
                       AS period_year1_round2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 1), TO_CHAR (
                                                                eva.total_point,
                                                                '9999.99'))
                       AS point_year1_round2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 1), TO_CHAR (
                                                                (eva.total_point
                                                                 * 100)
                                                                / eva.total_point_ef,
                                                                '9999.99'))
                       point_pct_year1_round2,
                    DECODE (FLOOR (eva.eval_month / 7) || eva.eval_year,
                            1 || (TO_CHAR (SYSDATE, 'YYYY') - 1), eva.grade)
                       AS grade_year1_round2,
                    --ADJUST
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 1), TO_CHAR (
                                                                eva.total_point_adjust,
                                                                '9999.99'))
                       point_adjust_year1_round2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 1), TO_CHAR (
                                                                (eva.total_point_adjust
                                                                 * 100)
                                                                / eva.total_point_ef,
                                                                '9999.99'))
                       point_pct_adjust_year1_round2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 1), eva.grade_adjust)
                       grade_adjust_year1_round2,
                    --CONFIRM_GRADE
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 1), eva.CONCLUDE_DATE)
                       CONCLUDE_DATE_YEAR1_ROUND2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 1), eva.MODIFY_CONCLUDE_DATE)
                       M_CONCLUDE_DATE_YEAR1_ROUND2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 1), eva.CONFIRM_GRADE_STATUS)
                       CONFIRM_GRADE_YEAR1_ROUND2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 1), eva.CONFIRM_GRADE_DATE)
                       CONFIRM_GRADE_D_YEAR1_ROUND2,
                    --(YYYY-2) #1
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 2), eva.eval_month)
                       AS eval_month2_round1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 2), eva.eval_year)
                       AS eval_year2_round1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 2), CASE
                                                                WHEN eva.start_date <=
                                                                        ADD_MONTHS (
                                                                           TO_DATE (
                                                                              '01/'
                                                                              || eva.eval_month
                                                                              || '/'
                                                                              || eva.eval_year,
                                                                              'DD/MM/YYYY'),
                                                                           -6)
                                                                THEN
                                                                   TO_CHAR (
                                                                      ADD_MONTHS (
                                                                         TO_DATE (
                                                                            LPAD (
                                                                               eva.eval_month,
                                                                               2,
                                                                               '0')
                                                                            || '/'
                                                                            || eva.eval_year,
                                                                            'MM/YYYY'),
                                                                         -6),
                                                                      'FMMON YY',
                                                                      'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                                   || ' - '
                                                                   || TO_CHAR (
                                                                         ADD_MONTHS (
                                                                            TO_DATE (
                                                                               LPAD (
                                                                                  eva.eval_month,
                                                                                  2,
                                                                                  '0')
                                                                               || '/'
                                                                               || eva.eval_year,
                                                                               'MM/YYYY'),
                                                                            -1),
                                                                         'FMMON YY',
                                                                         'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                                ELSE
                                                                   TO_CHAR (
                                                                      ADD_MONTHS (
                                                                         TO_DATE (
                                                                            LPAD (
                                                                               eva.eval_month,
                                                                               2,
                                                                               '0')
                                                                            || '/'
                                                                            || eva.eval_year,
                                                                            'MM/YYYY'),
                                                                         -5),
                                                                      'FMMON YY',
                                                                      'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                                   || ' - '
                                                                   || TO_CHAR (
                                                                         ADD_MONTHS (
                                                                            TO_DATE (
                                                                               LPAD (
                                                                                  eva.eval_month,
                                                                                  2,
                                                                                  '0')
                                                                               || '/'
                                                                               || eva.eval_year,
                                                                               'MM/YYYY'),
                                                                            -1),
                                                                         'FMMON YY',
                                                                         'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                             END)
                       AS period_year2_round1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 2), TO_CHAR (
                                                                eva.total_point,
                                                                '9999.99'))
                       point_year2_round1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 2), TO_CHAR (
                                                                (eva.total_point
                                                                 * 100)
                                                                / eva.total_point_ef,
                                                                '9999.99'))
                       point_pct_year2_round1,
                    DECODE (FLOOR (eva.eval_month / 7) || eva.eval_year,
                            0 || (TO_CHAR (SYSDATE, 'YYYY') - 2), eva.grade)
                       grade_year2_round1,
                    --ADJUST
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 2), TO_CHAR (
                                                                eva.total_point_adjust,
                                                                '9999.99'))
                       point_adjust_year2_round1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 2), TO_CHAR (
                                                                (eva.total_point_adjust
                                                                 * 100)
                                                                / eva.total_point_ef,
                                                                '9999.99'))
                       point_pct_adjust_year2_round1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 2), eva.grade_adjust)
                       grade_adjust_year2_round1,
                    --CONFIRM_GRADE
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 2), eva.CONCLUDE_DATE)
                       CONCLUDE_DATE_YEAR2_ROUND1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 2), eva.MODIFY_CONCLUDE_DATE)
                       M_CONCLUDE_DATE_YEAR2_ROUND1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 2), eva.CONFIRM_GRADE_STATUS)
                       CONFIRM_GRADE_YEAR2_ROUND1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 2), eva.CONFIRM_GRADE_DATE)
                       CONFIRM_GRADE_D_YEAR2_ROUND1,
                    --(YYYY-2) #2
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 2), eva.eval_month)
                       AS eval_month2_round2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 2), eva.eval_year)
                       AS eval_year2_round2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 2), CASE
                                                                WHEN eva.start_date <=
                                                                        ADD_MONTHS (
                                                                           TO_DATE (
                                                                              '01/'
                                                                              || eva.eval_month
                                                                              || '/'
                                                                              || eva.eval_year,
                                                                              'DD/MM/YYYY'),
                                                                           -6)
                                                                THEN
                                                                   TO_CHAR (
                                                                      ADD_MONTHS (
                                                                         TO_DATE (
                                                                            LPAD (
                                                                               eva.eval_month,
                                                                               2,
                                                                               '0')
                                                                            || '/'
                                                                            || eva.eval_year,
                                                                            'MM/YYYY'),
                                                                         -6),
                                                                      'FMMON YY',
                                                                      'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                                   || ' - '
                                                                   || TO_CHAR (
                                                                         ADD_MONTHS (
                                                                            TO_DATE (
                                                                               LPAD (
                                                                                  eva.eval_month,
                                                                                  2,
                                                                                  '0')
                                                                               || '/'
                                                                               || eva.eval_year,
                                                                               'MM/YYYY'),
                                                                            -1),
                                                                         'FMMON YY',
                                                                         'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                                ELSE
                                                                   TO_CHAR (
                                                                      ADD_MONTHS (
                                                                         TO_DATE (
                                                                            LPAD (
                                                                               eva.eval_month,
                                                                               2,
                                                                               '0')
                                                                            || '/'
                                                                            || eva.eval_year,
                                                                            'MM/YYYY'),
                                                                         -5),
                                                                      'FMMON YY',
                                                                      'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                                   || ' - '
                                                                   || TO_CHAR (
                                                                         ADD_MONTHS (
                                                                            TO_DATE (
                                                                               LPAD (
                                                                                  eva.eval_month,
                                                                                  2,
                                                                                  '0')
                                                                               || '/'
                                                                               || eva.eval_year,
                                                                               'MM/YYYY'),
                                                                            -1),
                                                                         'FMMON YY',
                                                                         'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                             END)
                       AS period_year2_round2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 2), TO_CHAR (
                                                                eva.total_point,
                                                                '9999.99'))
                       AS point_year2_round2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 2), TO_CHAR (
                                                                (eva.total_point
                                                                 * 100)
                                                                / eva.total_point_ef,
                                                                '9999.99'))
                       point_pct_year2_round2,
                    DECODE (FLOOR (eva.eval_month / 7) || eva.eval_year,
                            1 || (TO_CHAR (SYSDATE, 'YYYY') - 2), eva.grade)
                       AS grade_year2_round2,
                    --ADJUST
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 2), TO_CHAR (
                                                                eva.total_point_adjust,
                                                                '9999.99'))
                       point_adjust_year2_round2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 2), TO_CHAR (
                                                                (eva.total_point_adjust
                                                                 * 100)
                                                                / eva.total_point_ef,
                                                                '9999.99'))
                       point_pct_adjust_year2_round2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 2), eva.grade_adjust)
                       grade_adjust_year2_round2,
                    --CONFIRM_GRADE
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 2), eva.CONCLUDE_DATE)
                       CONCLUDE_DATE_YEAR2_ROUND2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 2), eva.MODIFY_CONCLUDE_DATE)
                       M_CONCLUDE_DATE_YEAR2_ROUND2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 2), eva.CONFIRM_GRADE_STATUS)
                       CONFIRM_GRADE_YEAR2_ROUND2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 2), eva.CONFIRM_GRADE_DATE)
                       CONFIRM_GRADE_D_YEAR2_ROUND2
               FROM (SELECT eva.evaluate_id,
                            eva.eval_month,
                            eva.eval_year,
                            eva.total_point,
                            eva.grade,
                            s.order_id,
                            s.start_date,
                            ag.total_point total_point_adjust,
                            ag.grade grade_adjust,
                            ag.eval_month eval_month_adjust,
                            ag.eval_year eval_year_adjust,
                            ef.TOTAL_POINT TOTAL_POINT_EF,
                            DENSE_RANK ()
                            OVER (
                               PARTITION BY s.order_id,
                                            eva.eval_year,
                                            eva.eval_month
                               ORDER BY
                                  eva.del_status NULLS FIRST,
                                  eva.evaluate_id DESC)
                               AS row_rank,
                            eva.CONCLUDE_DATE,
                            eva.MODIFY_CONCLUDE_DATE,
                            cgs.code_name AS CONFIRM_GRADE_STATUS,
                            eva.CONFIRM_GRADE_DATE
                       FROM fes_evaluate eva
                            INNER JOIN (SELECT *
                                          FROM (    SELECT order_id,
                                                           start_date,
                                                           REGEXP_SUBSTR (
                                                              SUBSTR (root_path, 2),
                                                              ',?([^,]*)',
                                                              1,
                                                              LEVEL,
                                                              'i',
                                                              1)
                                                              AS ref_order_id
                                                      FROM (    SELECT s.order_id,
                                                                       s.store_id,
                                                                       s.start_date,
                                                                       s.parent_order_id,
                                                                       SYS_CONNECT_BY_PATH (
                                                                          s.order_id,
                                                                          ',')
                                                                          AS root_path
                                                                  FROM fr_store s
                                                                 WHERE store_id !=
                                                                          '00000'
                                                                       AND (s.status
                                                                               IS NULL
                                                                            OR s.status !=
                                                                                  'D')
                                                                       AND s.cancel_date
                                                                              IS NULL
                                                            START WITH s.parent_order_id
                                                                          IS NULL
                                                            CONNECT BY PRIOR s.order_id =
                                                                          s.parent_order_id)
                                                CONNECT BY (REGEXP_COUNT (
                                                               root_path,
                                                               ',')
                                                            + 1 >= LEVEL
                                                            AND PRIOR order_id =
                                                                   order_id
                                                            AND PRIOR DBMS_RANDOM.VALUE
                                                                   IS NOT NULL))
                                         WHERE ref_order_id IS NOT NULL) s
                               ON s.ref_order_id = eva.fr_store_order_id
                                  AND eva.eval_type = 'MIDYEAR'
                                  --                    and eva.status = 'DO'  --if status older store not equal DO can't show this round  Supakit Madsathan
                                  AND eva.eval_year >=
                                         (TO_NUMBER (TO_CHAR (SYSDATE, 'YYYY'))
                                          - 6)
                                  AND eva.eval_year >= 2010
                                  /*minimum year for display is 2010*/
                                  AND (eva.eval_month =
                                          TO_CHAR (
                                             ADD_MONTHS (s.start_date, 6),
                                             'MM')
                                       OR eva.eval_month =
                                             TO_CHAR (s.start_date, 'MM'))
                                  AND TO_NUMBER (
                                         eva.eval_year
                                         || LPAD (eva.eval_month, 2, '0')) >=
                                         TO_NUMBER (
                                            TO_CHAR (
                                               ADD_MONTHS (s.start_date, 6),
                                               'YYYYMM'))
                            LEFT JOIN fes_adjust_grade ag
                               ON     ag.store_id = eva.order_id
                                  AND ag.eval_month = eva.eval_month
                                  AND ag.eval_year = eva.eval_year
                            LEFT JOIN FES_EVALUATEDFORM ef
                               ON ( (TO_DATE (eva.eval_year || eva.eval_month,
                                              'yyyymm') BETWEEN TO_DATE (
                                                                   ef.start_year
                                                                   || ef.start_month,
                                                                   'yyyymm')
                                                            AND TO_DATE (
                                                                   ef.end_year
                                                                   || ef.end_month,
                                                                   'yyyymm'))
                                   OR (TO_DATE (
                                          eva.eval_year || eva.eval_month,
                                          'yyyymm') >=
                                          TO_DATE (
                                             ef.start_year || ef.start_month,
                                             'yyyymm')
                                       AND ef.end_year IS NULL
                                       AND ef.end_month IS NULL))
                            LEFT JOIN COMMON_CODE cgs
                               ON     cgs.CODE_VALUE = eva.CONFIRM_GRADE_STATUS
                                  AND cgs.code_type = '00105'
                                  AND cgs.ACTIVE_FLAG = 'Y') eva
              WHERE eva.row_rank = 1) a
            INNER JOIN fr_store s1
               ON s1.order_id = a.order_id
            LEFT JOIN fr_store s2
               ON s2.order_id = s1.parent_order_id
            LEFT JOIN mas_store ms
               ON ms.branch_id = s1.store_id
   GROUP BY s1.store_id,
            ms.branch_name,
            ms.region,
            s1.start_date,
            s2.store_id,
            ms.status_type;

-- ---------- VIEW: V_FML_FES_EVALUATE_MIDYEAR_BAK ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_FML_FES_EVALUATE_MIDYEAR_BAK" ("STORE_ID", "STORE_NAME", "REGION", "START_DATE", "PARENT_STORE_ID", "FR_TYPE", "FR_TYPE_NAME", "EVAL_MONTH_ROUND1", "EVAL_YEAR_ROUND1", "EVAL_PERIOD_ROUND1", "POINT_YEAR_ROUND1", "GRADE_YEAR_ROUND1", "EVAL_MONTH_ROUND2", "EVAL_YEAR_ROUND2", "EVAL_PERIOD_ROUND2", "POINT_YEAR_ROUND2", "GRADE_YEAR_ROUND2", "EVAL_MONTH1_ROUND1", "EVAL_YEAR1_ROUND1", "EVAL_PERIOD1_ROUND1", "POINT_YEAR1_ROUND1", "GRADE_YEAR1_ROUND1", "EVAL_MONTH1_ROUND2", "EVAL_YEAR1_ROUND2", "EVAL_PERIOD1_ROUND2", "POINT_YEAR1_ROUND2", "GRADE_YEAR1_ROUND2", "EVAL_MONTH2_ROUND1", "EVAL_YEAR2_ROUND1", "EVAL_PERIOD2_ROUND1", "POINT_YEAR2_ROUND1", "GRADE_YEAR2_ROUND1", "EVAL_MONTH2_ROUND2", "EVAL_YEAR2_ROUND2", "EVAL_PERIOD2_ROUND2", "POINT_YEAR2_ROUND2", "GRADE_YEAR2_ROUND2") AS 
  SELECT s1.store_id,                                     -- as "รหัสสาขา",
            ms.branch_name AS store_name,                    -- as "ชื่อสาขา",
            ms.region,                                            -- as "ภาค",
            s1.start_date,                         -- as "วันที่เป็นแฟรนไชส์",
            s2.store_id AS parent_store_id,             -- as "ย้ายร้านมาจาก",
            DECODE (ms.status_type,
                    'FPT1', 'PTT',
                    'FAM', 'A',
                    'FB1', 'B',
                    'FB2', 'EMP',
                    'FC1', 'C',
                    'FBGC', 'BGC',
                    NULL)
               AS fr_type,                                -- "ประเภทการลงทุน",
            DECODE (ms.status_type,
                    'FPT1', 'Type ปตท.',
                    'FAM', 'Type A',
                    'FB1', 'Type B',
                    'FB2', 'Type พนักงาน',
                    'FC1', 'Type C',
                    'FBGC', 'Type BGC',
                    NULL)
               AS fr_type_name,
            MAX (DECODE (eval_month1, eval_month1, eval_month1))
               AS eval_month_round1,
            MAX (DECODE (eval_year1, eval_year1, eval_year1))
               AS eval_year_round1,
            --YYYY #1
            MAX (period_year_round1) AS EVAL_PERIOD_round1,
            MAX (point_year_round1) AS point_year_round1,
            MAX (grade_year_round1) AS grade_year_round1,
            MAX (DECODE (eval_month2, eval_month2, eval_month2))
               AS eval_month_round2,
            MAX (DECODE (eval_year2, eval_year2, eval_year2))
               AS eval_year_round2,
            --YYYY #2
            MAX (period_year_round2) AS EVAL_PERIOD_round2,
            MAX (point_year_round2) AS point_year_round2,
            MAX (grade_year_round2) AS grade_year_round2,
            MAX (
               DECODE (eval_month1_round1,
                       eval_month1_round1, eval_month1_round1))
               AS eval_month1_round1,
            MAX (
               DECODE (eval_year1_round1, eval_year1_round1, eval_year1_round1))
               AS eval_year1_round1,
            --(YYYY-1) #1
            MAX (period_year1_round1) AS EVAL_PERIOD1_round1,
            MAX (point_year1_round1) AS point_year1_round1,
            MAX (grade_year1_round1) AS grade_year1_round1,
            MAX (
               DECODE (eval_month1_round2,
                       eval_month1_round2, eval_month1_round2))
               AS eval_month1_round2,
            MAX (
               DECODE (eval_year1_round2, eval_year1_round2, eval_year1_round2))
               AS eval_year1_round2,
            --(YYYY-1) #2
            MAX (period_year1_round2) AS EVAL_PERIOD1_round2,
            MAX (point_year1_round2) AS point_year1_round2,
            MAX (grade_year1_round2) AS grade_year1_round2,
            MAX (
               DECODE (eval_month2_round1,
                       eval_month2_round1, eval_month2_round1))
               AS eval_month2_round1,
            MAX (
               DECODE (eval_year2_round1, eval_year2_round1, eval_year2_round1))
               AS eval_year2_round1,
            --(YYYY-2) #1
            MAX (period_year2_round1) AS EVAL_PERIOD2_round1,
            MAX (point_year2_round1) AS point_year2_round1,
            MAX (grade_year2_round1) AS grade_year2_round1,
            MAX (
               DECODE (eval_month2_round2,
                       eval_month2_round2, eval_month2_round2))
               AS eval_month2_round2,
            MAX (
               DECODE (eval_year2_round2, eval_year2_round2, eval_year2_round2))
               AS eval_year2_round2,
            --(YYYY-2) #2
            MAX (period_year2_round2) AS EVAL_PERIOD2_round2,
            MAX (point_year2_round2) AS point_year2_round2,
            MAX (grade_year2_round2) AS grade_year2_round2
       FROM (SELECT eva.*,
                    --YYYY #1
                    DECODE (FLOOR (eva.eval_month / 7) || eva.eval_year,
                            0 || TO_CHAR (SYSDATE, 'YYYY'), eva.eval_month)
                       AS eval_month1,
                    DECODE (FLOOR (eva.eval_month / 7) || eva.eval_year,
                            0 || TO_CHAR (SYSDATE, 'YYYY'), eva.eval_year)
                       AS eval_year1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || TO_CHAR (SYSDATE, 'YYYY'), CASE
                                                          WHEN eva.start_date <=
                                                                  ADD_MONTHS (
                                                                     TO_DATE (
                                                                        '01/'
                                                                        || eva.eval_month
                                                                        || '/'
                                                                        || eva.eval_year,
                                                                        'DD/MM/YYYY'),
                                                                     -6)
                                                          THEN
                                                             TO_CHAR (
                                                                ADD_MONTHS (
                                                                   TO_DATE (
                                                                      LPAD (
                                                                         eva.eval_month,
                                                                         2,
                                                                         '0')
                                                                      || '/'
                                                                      || eva.eval_year,
                                                                      'MM/YYYY'),
                                                                   -6),
                                                                'FMMON YY',
                                                                'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                             || ' - '
                                                             || TO_CHAR (
                                                                   ADD_MONTHS (
                                                                      TO_DATE (
                                                                         LPAD (
                                                                            eva.eval_month,
                                                                            2,
                                                                            '0')
                                                                         || '/'
                                                                         || eva.eval_year,
                                                                         'MM/YYYY'),
                                                                      -1),
                                                                   'FMMON YY',
                                                                   'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                          ELSE
                                                             TO_CHAR (
                                                                ADD_MONTHS (
                                                                   TO_DATE (
                                                                      LPAD (
                                                                         eva.eval_month,
                                                                         2,
                                                                         '0')
                                                                      || '/'
                                                                      || eva.eval_year,
                                                                      'MM/YYYY'),
                                                                   -5),
                                                                'FMMON YY',
                                                                'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                             || ' - '
                                                             || TO_CHAR (
                                                                   ADD_MONTHS (
                                                                      TO_DATE (
                                                                         LPAD (
                                                                            eva.eval_month,
                                                                            2,
                                                                            '0')
                                                                         || '/'
                                                                         || eva.eval_year,
                                                                         'MM/YYYY'),
                                                                      -1),
                                                                   'FMMON YY',
                                                                   'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                       END)
                       period_year_round1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || TO_CHAR (SYSDATE, 'YYYY'), TO_CHAR (
                                                          eva.total_point,
                                                          '9999.99'))
                       point_year_round1,
                    DECODE (FLOOR (eva.eval_month / 7) || eva.eval_year,
                            0 || TO_CHAR (SYSDATE, 'YYYY'), eva.grade)
                       grade_year_round1,
                    --YYYY #2
                    DECODE (FLOOR (eva.eval_month / 7) || eva.eval_year,
                            1 || TO_CHAR (SYSDATE, 'YYYY'), eva.eval_month)
                       AS eval_month2,
                    DECODE (FLOOR (eva.eval_month / 7) || eva.eval_year,
                            1 || TO_CHAR (SYSDATE, 'YYYY'), eva.eval_year)
                       AS eval_year2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || TO_CHAR (SYSDATE, 'YYYY'), CASE
                                                          WHEN eva.start_date <=
                                                                  ADD_MONTHS (
                                                                     TO_DATE (
                                                                        '01/'
                                                                        || eva.eval_month
                                                                        || '/'
                                                                        || eva.eval_year,
                                                                        'DD/MM/YYYY'),
                                                                     -6)
                                                          THEN
                                                             TO_CHAR (
                                                                ADD_MONTHS (
                                                                   TO_DATE (
                                                                      LPAD (
                                                                         eva.eval_month,
                                                                         2,
                                                                         '0')
                                                                      || '/'
                                                                      || eva.eval_year,
                                                                      'MM/YYYY'),
                                                                   -6),
                                                                'FMMON YY',
                                                                'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                             || ' - '
                                                             || TO_CHAR (
                                                                   ADD_MONTHS (
                                                                      TO_DATE (
                                                                         LPAD (
                                                                            eva.eval_month,
                                                                            2,
                                                                            '0')
                                                                         || '/'
                                                                         || eva.eval_year,
                                                                         'MM/YYYY'),
                                                                      -1),
                                                                   'FMMON YY',
                                                                   'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                          ELSE
