                       AS point_year_round2,
                    DECODE (FLOOR (eva.eval_month / 7) || eva.eval_year,
                            1 || TO_CHAR (SYSDATE, 'YYYY'), eva.grade)
                       AS grade_year_round2,
                    --(YYYY-1) #1
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 1), eva.eval_month)
                       AS eval_month1_round1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 1), eva.eval_year)
                       AS eval_year1_round1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 1), CASE
                                                                WHEN eva.start_date <=
                                                                        ADD_MONTHS (
                                                                           TO_DATE (
                                                                              '01/'
                                                                              || eva.eval_month
                                                                              || '/'
                                                                              || eva.eval_year,
                                                                              'DD/MM/YYYY'),
                                                                           -6)
                                                                THEN
                                                                   TO_CHAR (
                                                                      ADD_MONTHS (
                                                                         TO_DATE (
                                                                            LPAD (
                                                                               eva.eval_month,
                                                                               2,
                                                                               '0')
                                                                            || '/'
                                                                            || eva.eval_year,
                                                                            'MM/YYYY'),
                                                                         -6),
                                                                      'FMMON YY',
                                                                      'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                                   || ' - '
                                                                   || TO_CHAR (
                                                                         ADD_MONTHS (
                                                                            TO_DATE (
                                                                               LPAD (
                                                                                  eva.eval_month,
                                                                                  2,
                                                                                  '0')
                                                                               || '/'
                                                                               || eva.eval_year,
                                                                               'MM/YYYY'),
                                                                            -1),
                                                                         'FMMON YY',
                                                                         'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                                ELSE
                                                                   TO_CHAR (
                                                                      ADD_MONTHS (
                                                                         TO_DATE (
                                                                            LPAD (
                                                                               eva.eval_month,
                                                                               2,
                                                                               '0')
                                                                            || '/'
                                                                            || eva.eval_year,
                                                                            'MM/YYYY'),
                                                                         -5),
                                                                      'FMMON YY',
                                                                      'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                                   || ' - '
                                                                   || TO_CHAR (
                                                                         ADD_MONTHS (
                                                                            TO_DATE (
                                                                               LPAD (
                                                                                  eva.eval_month,
                                                                                  2,
                                                                                  '0')
                                                                               || '/'
                                                                               || eva.eval_year,
                                                                               'MM/YYYY'),
                                                                            -1),
                                                                         'FMMON YY',
                                                                         'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                             END)
                       period_year1_round1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 1), TO_CHAR (
                                                                eva.total_point,
                                                                '9999.99'))
                       point_year1_round1,
                    DECODE (FLOOR (eva.eval_month / 7) || eva.eval_year,
                            0 || (TO_CHAR (SYSDATE, 'YYYY') - 1), eva.grade)
                       grade_year1_round1,
                    --(YYYY-1) #2
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 1), eva.eval_month)
                       AS eval_month1_round2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 1), eva.eval_year)
                       AS eval_year1_round2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 1), CASE
                                                                WHEN eva.start_date <=
                                                                        ADD_MONTHS (
                                                                           TO_DATE (
                                                                              '01/'
                                                                              || eva.eval_month
                                                                              || '/'
                                                                              || eva.eval_year,
                                                                              'DD/MM/YYYY'),
                                                                           -6)
                                                                THEN
                                                                   TO_CHAR (
                                                                      ADD_MONTHS (
                                                                         TO_DATE (
                                                                            LPAD (
                                                                               eva.eval_month,
                                                                               2,
                                                                               '0')
                                                                            || '/'
                                                                            || eva.eval_year,
                                                                            'MM/YYYY'),
                                                                         -6),
                                                                      'FMMON YY',
                                                                      'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                                   || ' - '
                                                                   || TO_CHAR (
                                                                         ADD_MONTHS (
                                                                            TO_DATE (
                                                                               LPAD (
                                                                                  eva.eval_month,
                                                                                  2,
                                                                                  '0')
                                                                               || '/'
                                                                               || eva.eval_year,
                                                                               'MM/YYYY'),
                                                                            -1),
                                                                         'FMMON YY',
                                                                         'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                                ELSE
                                                                   TO_CHAR (
                                                                      ADD_MONTHS (
                                                                         TO_DATE (
                                                                            LPAD (
                                                                               eva.eval_month,
                                                                               2,
                                                                               '0')
                                                                            || '/'
                                                                            || eva.eval_year,
                                                                            'MM/YYYY'),
                                                                         -5),
                                                                      'FMMON YY',
                                                                      'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                                   || ' - '
                                                                   || TO_CHAR (
                                                                         ADD_MONTHS (
                                                                            TO_DATE (
                                                                               LPAD (
                                                                                  eva.eval_month,
                                                                                  2,
                                                                                  '0')
                                                                               || '/'
                                                                               || eva.eval_year,
                                                                               'MM/YYYY'),
                                                                            -1),
                                                                         'FMMON YY',
                                                                         'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                             END)
                       AS period_year1_round2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 1), TO_CHAR (
                                                                eva.total_point,
                                                                '9999.99'))
                       AS point_year1_round2,
                    DECODE (FLOOR (eva.eval_month / 7) || eva.eval_year,
                            1 || (TO_CHAR (SYSDATE, 'YYYY') - 1), eva.grade)
                       AS grade_year1_round2,
                    --(YYYY-2) #1
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 2), eva.eval_month)
                       AS eval_month2_round1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 2), eva.eval_year)
                       AS eval_year2_round1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 2), CASE
                                                                WHEN eva.start_date <=
                                                                        ADD_MONTHS (
                                                                           TO_DATE (
                                                                              '01/'
                                                                              || eva.eval_month
                                                                              || '/'
                                                                              || eva.eval_year,
                                                                              'DD/MM/YYYY'),
                                                                           -6)
                                                                THEN
                                                                   TO_CHAR (
                                                                      ADD_MONTHS (
                                                                         TO_DATE (
                                                                            LPAD (
                                                                               eva.eval_month,
                                                                               2,
                                                                               '0')
                                                                            || '/'
                                                                            || eva.eval_year,
                                                                            'MM/YYYY'),
                                                                         -6),
                                                                      'FMMON YY',
                                                                      'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                                   || ' - '
                                                                   || TO_CHAR (
                                                                         ADD_MONTHS (
                                                                            TO_DATE (
                                                                               LPAD (
                                                                                  eva.eval_month,
                                                                                  2,
                                                                                  '0')
                                                                               || '/'
                                                                               || eva.eval_year,
                                                                               'MM/YYYY'),
                                                                            -1),
                                                                         'FMMON YY',
                                                                         'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                                ELSE
                                                                   TO_CHAR (
                                                                      ADD_MONTHS (
                                                                         TO_DATE (
                                                                            LPAD (
                                                                               eva.eval_month,
                                                                               2,
                                                                               '0')
                                                                            || '/'
                                                                            || eva.eval_year,
                                                                            'MM/YYYY'),
                                                                         -5),
                                                                      'FMMON YY',
                                                                      'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                                   || ' - '
                                                                   || TO_CHAR (
                                                                         ADD_MONTHS (
                                                                            TO_DATE (
                                                                               LPAD (
                                                                                  eva.eval_month,
                                                                                  2,
                                                                                  '0')
                                                                               || '/'
                                                                               || eva.eval_year,
                                                                               'MM/YYYY'),
                                                                            -1),
                                                                         'FMMON YY',
                                                                         'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                             END)
                       AS period_year2_round1,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       0 || (TO_CHAR (SYSDATE, 'YYYY') - 2), TO_CHAR (
                                                                eva.total_point,
                                                                '9999.99'))
                       point_year2_round1,
                    DECODE (FLOOR (eva.eval_month / 7) || eva.eval_year,
                            0 || (TO_CHAR (SYSDATE, 'YYYY') - 2), eva.grade)
                       grade_year2_round1,
                    --(YYYY-1) #2
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 2), eva.eval_month)
                       AS eval_month2_round2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 2), eva.eval_year)
                       AS eval_year2_round2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 2), CASE
                                                                WHEN eva.start_date <=
                                                                        ADD_MONTHS (
                                                                           TO_DATE (
                                                                              '01/'
                                                                              || eva.eval_month
                                                                              || '/'
                                                                              || eva.eval_year,
                                                                              'DD/MM/YYYY'),
                                                                           -6)
                                                                THEN
                                                                   TO_CHAR (
                                                                      ADD_MONTHS (
                                                                         TO_DATE (
                                                                            LPAD (
                                                                               eva.eval_month,
                                                                               2,
                                                                               '0')
                                                                            || '/'
                                                                            || eva.eval_year,
                                                                            'MM/YYYY'),
                                                                         -6),
                                                                      'FMMON YY',
                                                                      'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                                   || ' - '
                                                                   || TO_CHAR (
                                                                         ADD_MONTHS (
                                                                            TO_DATE (
                                                                               LPAD (
                                                                                  eva.eval_month,
                                                                                  2,
                                                                                  '0')
                                                                               || '/'
                                                                               || eva.eval_year,
                                                                               'MM/YYYY'),
                                                                            -1),
                                                                         'FMMON YY',
                                                                         'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                                ELSE
                                                                   TO_CHAR (
                                                                      ADD_MONTHS (
                                                                         TO_DATE (
                                                                            LPAD (
                                                                               eva.eval_month,
                                                                               2,
                                                                               '0')
                                                                            || '/'
                                                                            || eva.eval_year,
                                                                            'MM/YYYY'),
                                                                         -5),
                                                                      'FMMON YY',
                                                                      'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                                   || ' - '
                                                                   || TO_CHAR (
                                                                         ADD_MONTHS (
                                                                            TO_DATE (
                                                                               LPAD (
                                                                                  eva.eval_month,
                                                                                  2,
                                                                                  '0')
                                                                               || '/'
                                                                               || eva.eval_year,
                                                                               'MM/YYYY'),
                                                                            -1),
                                                                         'FMMON YY',
                                                                         'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                                                             END)
                       AS period_year2_round2,
                    DECODE (
                       FLOOR (eva.eval_month / 7) || eva.eval_year,
                       1 || (TO_CHAR (SYSDATE, 'YYYY') - 2), TO_CHAR (
                                                                eva.total_point,
                                                                '9999.99'))
                       AS point_year2_round2,
                    DECODE (FLOOR (eva.eval_month / 7) || eva.eval_year,
                            1 || (TO_CHAR (SYSDATE, 'YYYY') - 2), eva.grade)
                       AS grade_year2_round2
               FROM (SELECT eva.evaluate_id,
                            eva.eval_month,
                            eva.eval_year,
                            eva.total_point,
                            eva.grade,
                            s.order_id,
                            s.start_date,
                            DENSE_RANK ()
                            OVER (
                               PARTITION BY s.order_id,
                                            eva.eval_year,
                                            eva.eval_month
                               ORDER BY
                                  eva.del_status NULLS FIRST,
                                  eva.evaluate_id DESC)
                               AS row_rank
                       FROM    fes_evaluate eva
                            INNER JOIN
                               (SELECT *
                                  FROM (    SELECT order_id,
                                                   start_date,
                                                   REGEXP_SUBSTR (
                                                      SUBSTR (root_path, 2),
                                                      ',?([^,]*)',
                                                      1,
                                                      LEVEL,
                                                      'i',
                                                      1)
                                                      AS ref_order_id
                                              FROM (    SELECT s.order_id,
                                                               s.store_id,
                                                               s.start_date,
                                                               s.parent_order_id,
                                                               SYS_CONNECT_BY_PATH (
                                                                  s.order_id,
                                                                  ',')
                                                                  AS root_path
                                                          FROM fr_store s
                                                         WHERE store_id != '00000'
                                                               AND (s.status IS NULL
                                                                    OR s.status != 'D')
                                                               AND s.cancel_date
                                                                      IS NULL
                                                    START WITH s.parent_order_id
                                                                  IS NULL
                                                    CONNECT BY PRIOR s.order_id =
                                                                  s.parent_order_id)
                                        CONNECT BY (REGEXP_COUNT (root_path,
                                                                  ',')
                                                    + 1 >= LEVEL
                                                    AND PRIOR order_id =
                                                           order_id
                                                    AND PRIOR DBMS_RANDOM.VALUE
                                                           IS NOT NULL))
                                 WHERE ref_order_id IS NOT NULL) s
                            ON s.ref_order_id = eva.fr_store_order_id
                               AND eva.eval_type = 'MIDYEAR'
                               --                    and eva.status = 'DO'  --if status older store not equal DO can't show this round  Supakit Madsathan
                               AND eva.eval_year >=
                                      (TO_NUMBER (TO_CHAR (SYSDATE, 'YYYY'))
                                       - 6)
                               AND eva.eval_year >= 2010 /*minimum year for display is 2010*/
                               AND (eva.eval_month =
                                       TO_CHAR (ADD_MONTHS (s.start_date, 6),
                                                'MM')
                                    OR eva.eval_month =
                                          TO_CHAR (s.start_date, 'MM'))
                               AND TO_NUMBER (
                                      eva.eval_year
                                      || LPAD (eva.eval_month, 2, '0')) >=
                                      TO_NUMBER (
                                         TO_CHAR (ADD_MONTHS (s.start_date, 6),
                                                  'YYYYMM'))) eva
              WHERE eva.row_rank = 1) a
            INNER JOIN fr_store s1
               ON s1.order_id = a.order_id
            LEFT JOIN fr_store s2
               ON s2.order_id = s1.parent_order_id
            LEFT JOIN mas_store ms
               ON ms.branch_id = s1.store_id
   GROUP BY s1.store_id,
            ms.branch_name,
            ms.region,
            s1.start_date,
            s2.store_id,
            ms.status_type;

-- ---------- VIEW: V_FML_FES_EVALUATE_STORE_ID ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_FML_FES_EVALUATE_STORE_ID" ("รหัสร้าน") AS 
  SELECT param_value
     FROM MAS_PARAM
    WHERE param_name = 'FML_FES_EVALUATE_STORE_ID';

-- ---------- VIEW: V_FML_FES_EVALUATE_THREE ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_FML_FES_EVALUATE_THREE" ("STORE_ID", "STORE_NAME", "REGION", "START_DATE", "PARENT_STORE_ID", "FR_TYPE", "FR_TYPE_NAME", "EVAL_MONTH", "EVAL_YEAR", "EVAL_PERIOD", "POINT_YEAR", "GRADE_YEAR", "EVAL_PERIOD1", "POINT_YEAR1", "GRADE_YEAR1", "EVAL_PERIOD2", "POINT_YEAR2", "GRADE_YEAR2") AS 
  SELECT s1.store_id,                                          -- "รหัสสาขา",
          ms.branch_name AS store_name,                         -- "ชื่อสาขา",
          ms.region,                                                 -- "ภาค",
          s1.start_date,                              -- "วันที่เป็นแฟรนไชส์",
          s2.store_id AS parent_store_id,                  -- "ย้ายร้านมาจาก",
          DECODE (ms.status_type,
                  'FPT1', 'PTT',
                  'FAM', 'A',
                  'FB1', 'B',
                  'FB2', 'EMP',
                  'FC1', 'C',
                  'FBGC', 'BGC',
				  'FVB', 'VB',
                  'FVC', 'VC',
                  NULL)
             AS fr_type,                                  -- "ประเภทการลงทุน",
          DECODE (ms.status_type,
                  'FPT1', 'Type ปตท.',
                  'FAM', 'Type A',
                  'FB1', 'Type B',
                  'FB2', 'Type พนักงาน',
                  'FC1', 'Type C',
                  'FBGC', 'Type BGC',
				  'FVB', 'Type VB',
                  'FVC', 'Type VC',
                  NULL)
             AS fr_type_name,
          eva.eval_month,
          eva.eval_year,
          --current year
          CASE
             WHEN eva.eval_year = TO_CHAR (SYSDATE, 'YYYY')
             THEN
                TO_CHAR (
                   ADD_MONTHS (
                      TO_DATE (
                            LPAD (eva.eval_month, 2, '0')
                         || '/'
                         || eva.eval_year,
                         'MM/YYYY'),
                      -3),
                   'FMMON YY',
                   'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                || ' - '
                || TO_CHAR (
                      ADD_MONTHS (
                         TO_DATE (
                               LPAD (eva.eval_month, 2, '0')
                            || '/'
                            || eva.eval_year,
                            'MM/YYYY'),
                         -1),
                      'FMMON YY',
                      'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
          END
             AS eval_period,                               -- "ช่วงการประเมิน"
          CASE
             WHEN eva.eval_year = TO_CHAR (SYSDATE, 'YYYY')
             THEN
                TO_CHAR (eva.total_point, '9999.99')
          END
             AS point_year,                                         -- "คะแนน"
          CASE
             WHEN eva.eval_year = TO_CHAR (SYSDATE, 'YYYY') THEN eva.grade
          END
             AS grade_year,                                          -- "เกรด"
          --1 year ago
          CASE
             WHEN eva.eval_year = TO_CHAR (SYSDATE, 'YYYY') - 1
             THEN
                TO_CHAR (
                   ADD_MONTHS (
                      TO_DATE (
                            LPAD (eva.eval_month, 2, '0')
                         || '/'
                         || eva.eval_year,
                         'MM/YYYY'),
                      -3),
                   'FMMON YY',
                   'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                || ' - '
                || TO_CHAR (
                      ADD_MONTHS (
                         TO_DATE (
                               LPAD (eva.eval_month, 2, '0')
                            || '/'
                            || eva.eval_year,
                            'MM/YYYY'),
                         -1),
                      'FMMON YY',
                      'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
          END
             AS eval_period1,                              -- "ช่วงการประเมิน"
          CASE
             WHEN eva.eval_year = TO_CHAR (SYSDATE, 'YYYY') - 1
             THEN
                TO_CHAR (eva.total_point, '9999.99')
          END
             AS point_year1,                                        -- "คะแนน"
          CASE
             WHEN eva.eval_year = TO_CHAR (SYSDATE, 'YYYY') - 1
             THEN
                eva.grade
          END
             AS grade_year1,                                         -- "เกรด"
          --2 year ago
          CASE
             WHEN eva.eval_year = TO_CHAR (SYSDATE, 'YYYY') - 2
             THEN
                TO_CHAR (
                   ADD_MONTHS (
                      TO_DATE (
                            LPAD (eva.eval_month, 2, '0')
                         || '/'
                         || eva.eval_year,
                         'MM/YYYY'),
                      -3),
                   'FMMON YY',
                   'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
                || ' - '
                || TO_CHAR (
                      ADD_MONTHS (
                         TO_DATE (
                               LPAD (eva.eval_month, 2, '0')
                            || '/'
                            || eva.eval_year,
                            'MM/YYYY'),
                         -1),
                      'FMMON YY',
                      'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
          END
             AS eval_period2,                              -- "ช่วงการประเมิน"
          CASE
             WHEN eva.eval_year = TO_CHAR (SYSDATE, 'YYYY') - 2
             THEN
                TO_CHAR (eva.total_point, '9999.99')
          END
             AS point_year2,                                        -- "คะแนน"
          CASE
             WHEN eva.eval_year = TO_CHAR (SYSDATE, 'YYYY') - 2
             THEN
                eva.grade
          END
             AS grade_year2                                          -- "เกรด"
     FROM (SELECT *
             FROM (SELECT eva.evaluate_id,
                          eva.eval_month,
                          eva.eval_year,
                          eva.total_point,
                          eva.grade,
                          s.order_id,
                          DENSE_RANK ()
                          OVER (
                             PARTITION BY s.order_id
                             ORDER BY
                                eva.del_status NULLS FIRST,
                                eva.eval_year DESC,
                                eva.eval_month DESC)
                             AS row_rank
                     FROM    fes_evaluate eva
                          INNER JOIN
                             (SELECT *
                                FROM (    SELECT order_id,
                                                 REGEXP_SUBSTR (
                                                    SUBSTR (root_path, 2),
                                                    ',?([^,]*)',
                                                    1,
                                                    LEVEL,
                                                    'i',
                                                    1)
                                                    AS ref_order_id
                                            FROM (    SELECT s.order_id,
                                                             s.store_id,
                                                             s.start_date,
                                                             s.parent_order_id,
                                                             SYS_CONNECT_BY_PATH (
                                                                s.order_id,
                                                                ',')
                                                                AS root_path
                                                        FROM fr_store s
                                                       WHERE store_id != '00000'
                                                             AND (s.status IS NULL
                                                                  OR s.status != 'D')
                                                             AND s.cancel_date
                                                                    IS NULL
                                                  START WITH s.parent_order_id
                                                                IS NULL
                                                  CONNECT BY PRIOR s.order_id =
                                                                s.parent_order_id)
                                      CONNECT BY (REGEXP_COUNT (root_path,
                                                                ',')
                                                  + 1 >= LEVEL
                                                  AND PRIOR order_id =
                                                         order_id
                                                  AND PRIOR DBMS_RANDOM.VALUE
                                                         IS NOT NULL))
                               WHERE ref_order_id IS NOT NULL) s
                          ON     s.ref_order_id = eva.fr_store_order_id
                             AND eva.eval_type = 'THREE'
                             AND eva.status = 'DO'
                             AND eva.eval_year >=
                                    (TO_NUMBER (TO_CHAR (SYSDATE, 'YYYY'))
                                     - 2)
                             AND eva.eval_year >= 2010 /*minimum year for display is 2010*/
                                                      )
            WHERE row_rank = 1) eva
          INNER JOIN fr_store s1
             ON s1.order_id = eva.order_id
          LEFT JOIN fr_store s2
             ON s2.order_id = s1.parent_order_id
          LEFT JOIN mas_store ms
             ON ms.branch_id = s1.store_id
--order by s1.store_id, eva.year desc;
;

-- ---------- VIEW: V_FML_FES_EVALUATE_TWO ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_FML_FES_EVALUATE_TWO" ("STORE_ID", "STORE_NAME", "REGION", "START_DATE", "PARENT_STORE_ID", "FR_TYPE", "FR_TYPE_NAME", "EVAL_MONTH", "EVAL_YEAR", "TOTAL_POINT_YEAR", "TOTAL_POINT_YEAR1", "TOTAL_POINT_YEAR2") AS 
  SELECT s1.store_id,                                          -- "รหัสสาขา",
          ms.branch_name AS store_name,                         -- "ชื่อสาขา",
          ms.region,                                                 -- "ภาค",
          s1.start_date,                              -- "วันที่เป็นแฟรนไชส์",
          s2.store_id AS parent_store_id,                  -- "ย้ายร้านมาจาก",
          DECODE (ms.status_type,
                  'FPT1', 'PTT',
                  'FAM', 'A',
                  'FB1', 'B',
                  'FB2', 'EMP',
                  'FC1', 'C',
                  'FBGC', 'BGC',
				  'FVB', 'VB',
                  'FVC', 'VC',
                  NULL)
             AS fr_type,                                  -- "ประเภทการลงทุน",
          DECODE (ms.status_type,
                  'FPT1', 'Type ปตท.',
                  'FAM', 'Type A',
                  'FB1', 'Type B',
                  'FB2', 'Type พนักงาน',
                  'FC1', 'Type C',
                  'FBGC', 'Type BGC',
				  'FVB', 'Type VB',
                  'FVC', 'Type VC',
                  NULL)
             AS fr_type_name,
          a.eval_month,
          a.eval_year,
          CASE
             WHEN a.eval_year = TO_CHAR (SYSDATE, 'YYYY')
             THEN
                TO_CHAR (a.total_point, '9999.99')
          END
             AS total_point_year,                         -- "คะแนน (ปี YYYY)"
          CASE
             WHEN a.eval_year = (TO_CHAR (SYSDATE, 'YYYY') - 1)
             THEN
                TO_CHAR (a.total_point, '9999.99')
          END
             AS total_point_year1,                      -- "คะแนน (ปี YYYY-1)"
          CASE
             WHEN a.eval_year = (TO_CHAR (SYSDATE, 'YYYY') - 2)
             THEN
                TO_CHAR (a.total_point, '9999.99')
          END
             AS total_point_year2                       -- "คะแนน (ปี YYYY-2)"
     FROM (SELECT *
             FROM (SELECT eva.evaluate_id,
                          eva.eval_month,
                          eva.eval_year,
                          eva.total_point,
                          eva.grade,
                          s.order_id,
                          DENSE_RANK ()
                          OVER (
                             PARTITION BY s.order_id
                             ORDER BY
                                eva.del_status NULLS FIRST,
                                eva.eval_year DESC,
                                eva.eval_month DESC)
                             AS row_rank
                     FROM    fes_evaluate eva
                          INNER JOIN
                             (SELECT *
                                FROM (    SELECT order_id,
                                                 REGEXP_SUBSTR (
                                                    SUBSTR (root_path, 2),
                                                    ',?([^,]*)',
                                                    1,
                                                    LEVEL,
                                                    'i',
                                                    1)
                                                    AS ref_order_id
                                            FROM (    SELECT s.order_id,
                                                             s.store_id,
                                                             s.start_date,
                                                             s.parent_order_id,
                                                             SYS_CONNECT_BY_PATH (
                                                                s.order_id,
                                                                ',')
                                                                AS root_path
                                                        FROM fr_store s
                                                       WHERE store_id != '00000'
                                                             AND (s.status IS NULL
                                                                  OR s.status != 'D')
                                                             AND s.cancel_date
                                                                    IS NULL
                                                  START WITH s.parent_order_id
                                                                IS NULL
                                                  CONNECT BY PRIOR s.order_id =
                                                                s.parent_order_id)
                                      CONNECT BY (REGEXP_COUNT (root_path,
                                                                ',')
                                                  + 1 >= LEVEL
                                                  AND PRIOR order_id =
                                                         order_id
                                                  AND PRIOR DBMS_RANDOM.VALUE
                                                         IS NOT NULL))
                               WHERE ref_order_id IS NOT NULL) s
                          ON     s.ref_order_id = eva.fr_store_order_id
                             AND eva.eval_type = 'TWO'
                             AND eva.status = 'DO'
                             AND eva.eval_year >=
                                    (TO_NUMBER (TO_CHAR (SYSDATE, 'YYYY'))
                                     - 2)
                             AND eva.eval_year >= 2010 /*minimum year for display is 2010*/
                                                      )
            WHERE row_rank = 1) a
          INNER JOIN fr_store s1
             ON s1.order_id = a.order_id
          LEFT JOIN fr_store s2
             ON s2.order_id = s1.parent_order_id
          LEFT JOIN mas_store ms
             ON ms.branch_id = s1.store_id
--order by s1.store_id, a.eval_year desc;
;

-- ---------- VIEW: V_FML_FRANCHISE_STMT ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_FML_FRANCHISE_STMT" ("PROCESS_ID", "REPORT_TYPE", "YEAR", "MONTH", "REPORT_NAME", "SUM_PROCESS", "TOTAL_STACC_WS", "TOTAL_FML_IMPORT", "TOTAL_CUR_STACC_WS", "TOTAL_CUR_FML_IMPORT", "BRANCH", "REMARK") AS 
  SELECT fsfs.process_id,
    fsfs.report_type,
    fsfs.YEAR,
    fsfs.MONTH,
    fsfs.report_name,
    fsfse.sum_process - NVL(tt.co,0) - NVL(total_skip_report,0) AS sum_process,
    a.total_stacc_ws - NVL(total_skip_report,0)                 AS total_stacc_ws,
    b.total_fml_import,
    c.total_cur_stacc_ws,
    d.total_cur_fml_import,
    e.branch,
    fsfse.remark
    || (
    CASE
      WHEN f.report_type = 'RLEECFM'
      THEN DECODE(f.remark, NULL, NULL, 'พบรหัสร้านที่มีการนำเข้า แต่ไม่มีข้อมูล QTY ติดลบหรือบวก คือ '
        || f.remark)
      ELSE f.remark
    END ) AS remark
  FROM
    ( SELECT DISTINCT fsfs.process_id,
      fsfs.report_type,
      fsfs.year,
      fsfs.month,
      cc.code_name AS report_name
    FROM fml_stacc_fr_stmt fsfs
    INNER JOIN common_code cc
    ON cc.code_value = fsfs.report_type
    AND cc.code_type LIKE 'FML%'
    JOIN STORE_TAXPAYER ms
    ON ms.branch = fsfs.branch
    AND fsfs.year
      ||fsfs.month = ms.period
    WHERE to_number (fsfs.year
      || fsfs.month) >= to_number (TO_CHAR (add_months (sysdate, -7), 'YYYYMM'))
    ) fsfs
  INNER JOIN fml_stacc_fr_stmt_end fsfse
  ON fsfse.process_id   = fsfs.process_id
  AND fsfse.report_type = fsfs.report_type
  LEFT JOIN
    (SELECT YEAR,
      MONTH,
      report_type,
      COUNT (*) AS total_stacc_ws
    FROM
      ( SELECT DISTINCT fsr.report_type,
        fsr.branch,
        fsr.year,
        fsr.month
      FROM fml_stacc_fr_stmt fsr
      JOIN STORE_TAXPAYER ms
      ON ms.branch = fsr.branch
      AND fsr.year
        ||fsr.month = ms.period
      WHERE to_number (fsr.year
        || fsr.month) >= to_number (TO_CHAR (add_months (sysdate, -7), 'YYYYMM'))
      )
    GROUP BY YEAR,
      MONTH,
      report_type
    ) a ON a.year   = fsfs.year
  AND a.month       = fsfs.month
  AND a.report_type = fsfs.report_type
  LEFT JOIN
    (SELECT YEAR,
      MONTH,
      report_type,
      COUNT (*) AS total_fml_import
    FROM fml_franchise_statement frs
    JOIN STORE_TAXPAYER ms
    ON ms.branch = frs.store_id
    AND frs.year
      ||frs.month = ms.period
    WHERE to_number (frs.year
      || frs.month) >= to_number (TO_CHAR (add_months (sysdate, -7), 'yyyymm'))
    GROUP BY YEAR,
      MONTH,
      report_type
    ) b ON b.year   = fsfs.year
  AND b.month       = fsfs.month
  AND b.report_type = fsfs.report_type
  LEFT JOIN
    (SELECT YEAR,
      MONTH,
      report_type,
      COUNT (*) AS total_cur_stacc_ws
    FROM
      ( SELECT DISTINCT fsr.report_type,
        fsr.branch,
        fsr.year,
        fsr.month
      FROM fml_stacc_fr_stmt fsr
      JOIN STORE_TAXPAYER ms
      ON ms.branch = fsr.branch
      AND fsr.year
        ||fsr.month = ms.period
      WHERE to_number (fsr.year
        || fsr.month)             >= to_number (TO_CHAR (add_months (sysdate, -7), 'YYYYMM'))
      AND NVL (send_mail_flag, 0) != 1
      AND 
        (
          EXISTS
          (
            select 1 from FML_SBP_SHOW_REPORT show
            where show.period = fsr.year||fsr.month
            and show.report_type = fsr.report_type
            and show.active_flag = 'Y'
          )
          
          OR
          NOT EXISTS
          (
            select 1 from FML_SBP_SKIP_REPORT_STORE srs
            where srs.period =  fsr.year||fsr.month
            and srs.store_id = fsr.branch
            and srs.active_flag = 'Y'
          ) 
        )
      )
    GROUP BY report_type,
      YEAR,
      MONTH
    ) c ON c.year   = fsfs.year
  AND c.month       = fsfs.month
  AND c.report_type = fsfs.report_type
  LEFT JOIN
    (SELECT YEAR,
      MONTH,
      report_type,
      COUNT (*) AS total_cur_fml_import
    FROM
      ( SELECT DISTINCT fsr.process_id,
        fsr.report_type,
        fsr.branch,
        fsr.year,
        fsr.month
      FROM fml_stacc_fr_stmt fsr
      JOIN STORE_TAXPAYER ms
      ON ms.branch = fsr.branch
      AND fsr.year
        ||fsr.month = ms.period
      WHERE to_number (fsr.year
        || fsr.month)                 >= to_number (TO_CHAR (add_months (sysdate, -7),'YYYYMM'))
      AND NVL (fsr.send_mail_flag, 0) != 1
      AND NVL (fsr.import_flag, 0)     = 1
      AND 
        (
          EXISTS
          (
            select 1 from FML_SBP_SHOW_REPORT show
            where show.period = fsr.year||fsr.month
            and show.report_type = fsr.report_type
            and show.active_flag = 'Y'
          )
          
          OR
          NOT EXISTS
          (
            select 1 from FML_SBP_SKIP_REPORT_STORE srs
            where srs.period =  fsr.year||fsr.month
            and srs.store_id = fsr.branch
            and srs.active_flag = 'Y'
          ) 
        )
      )
    GROUP BY report_type,
      YEAR,
      MONTH
    ) d ON d.year   = fsfs.year
  AND d.month       = fsfs.month
  AND d.report_type = fsfs.report_type
  LEFT JOIN
    (SELECT ee.report_type,
      ee.year,
      ee.month,
      listagg (ee.branch, ', ') within GROUP (
    ORDER BY ee.branch) AS branch
    FROM
      (SELECT e1.*,
        row_number() over (partition BY e1.report_type, e1.year, e1.month order by e1.branch) AS row_num
      FROM
        ( SELECT DISTINCT fsr.report_type,
          fsr.year,
          fsr.month,
          fsr.branch
        FROM fml_stacc_fr_stmt fsr
        JOIN STORE_TAXPAYER ms
        ON ms.branch = fsr.branch
        AND fsr.year
          ||fsr.month = ms.period
        WHERE to_number (fsr.year
          || fsr.month)             >= to_number (TO_CHAR (add_months (sysdate, -7), 'YYYYMM'))
        AND NVL (fsr.import_flag, 0) = 0
        ) e1
      ) ee
    WHERE ee.row_num <= 100
    GROUP BY ee.report_type,
      ee.year,
      ee.month
    ) e ON e.year   = fsfs.year
  AND e.month       = fsfs.month
  AND e.report_type = fsfs.report_type
  LEFT JOIN
    (SELECT ff.report_type,
      ff.year,
      ff.month,
      listagg (ff.branch, ', ') within GROUP (
    ORDER BY ff.branch) AS remark
    FROM
      (SELECT f1.*,
        row_number() over (partition BY f1.report_type, f1.year, f1.month order by f1.branch) AS row_num
      FROM
        ( SELECT DISTINCT stmt.branch,
          stmt.year,
          stmt.month,
          stmt.report_type
        FROM fml_stacc_fr_stmt stmt
        INNER JOIN fml_tmp_importdata_stmt tmp
        ON tmp.report_type = stmt.report_type
        JOIN STORE_TAXPAYER ms
        ON ms.branch = stmt.branch
        AND stmt.year
          ||stmt.month = ms.period
        WHERE to_number (stmt.year
          || stmt.month) >= to_number (TO_CHAR (add_months (sysdate, -7), 'YYYYMM'))
        AND NOT EXISTS
          (SELECT tmp2.col01
          FROM fml_tmp_importdata_stmt tmp2
          WHERE tmp2.report_type   = stmt.report_type
          AND tmp2.col01           = stmt.branch
          AND tmp2.filename_period = TO_CHAR (to_date (stmt.month
            || '/'
            || stmt.year, 'MM/YYYY'), 'MM/YY','NLS_CALENDAR=''THAI BUDDHA')
          )
        ) f1
      ) ff
    WHERE ff.row_num <= 100
    GROUP BY ff.year,
      ff.month,
      ff.report_type
    ) f ON f.year   = fsfs.year
  AND f.month       = fsfs.month
  AND f.report_type = fsfs.report_type
  LEFT JOIN
    (SELECT s.process_id,
      s.report_type,
      s.year,
      s.month,
      COUNT(*) AS co
    FROM
      (SELECT s.process_id,
        s.report_type,
        s.year,
        s.month,
        branch
      FROM fml_stacc_fr_stmt s
      GROUP BY s.process_id,
        s.report_type,
        s.year,
        s.month,
        branch
      ) s
    WHERE NOT EXISTS
      (SELECT 1
      FROM STORE_TAXPAYER mc
      WHERE mc.branch = s.branch
      AND s.year
        ||s.month = mc.period
      )
    GROUP BY s.process_id,
      s.report_type,
      s.year,
      s.month
    ) tt
  ON tt.process_id   = fsfse.process_id
  AND tt.report_type = fsfse.report_type
  LEFT JOIN
    (SELECT YEAR,
      MONTH,
      report_type,
      COUNT (*) AS total_skip_report
    FROM fml_franchise_skip_statement frss
    JOIN STORE_TAXPAYER ms
    ON ms.branch = frss.store_id
    AND frss.year
      ||frss.month = ms.period
    WHERE to_number (frss.year
      || frss.month) >= to_number (TO_CHAR (add_months (sysdate, -7), 'yyyymm'))
    GROUP BY YEAR,
      MONTH,
      report_type
    ) b ON b.year   = fsfs.year
  AND b.month       = fsfs.month
  AND b.report_type = fsfs.report_type  
  WHERE TO_NUMBER (fsfs.year
    || fsfs.month) >= TO_NUMBER (TO_CHAR (ADD_MONTHS (SYSDATE, -7), 'YYYYMM'));

-- ---------- VIEW: V_FML_FRANCHISE_STMT_KH ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_FML_FRANCHISE_STMT_KH" ("PROCESS_ID", "REPORT_TYPE", "YEAR", "MONTH", "REPORT_NAME", "SUM_PROCESS", "TOTAL_STACC_WS", "TOTAL_FML_IMPORT", "TOTAL_CUR_STACC_WS", "TOTAL_CUR_FML_IMPORT", "BRANCH", "REMARK") AS 
  SELECT fsfs.process_id,
    fsfs.report_type,
    fsfs.YEAR,
    fsfs.MONTH,
    fsfs.report_name,
    tt.sum_process,
    a.total_stacc_ws,
    b.total_fml_import,
    c.total_cur_stacc_ws,
    d.total_cur_fml_import,
    e.branch,
    fsfse.remark
    || (
    CASE
      WHEN f.report_type = 'RLEECFM'
      THEN DECODE(f.remark, NULL, NULL, 'พบรหัสร้านที่มีการนำเข้า แต่ไม่มีข้อมูล QTY ติดลบหรือบวก คือ '
        || f.remark)
      ELSE f.remark
    END ) AS remark
 FROM
    ( SELECT DISTINCT fsfs.process_id,fsfs.report_type,fsfs.year,fsfs.month,cc.code_name AS report_name
    FROM fml_stacc_fr_stmt fsfs
    INNER JOIN common_code cc
    ON cc.code_value = fsfs.report_type
    AND cc.code_type LIKE 'CAMBODIA%'
    INNER JOIN mas_store_cambodia msc1 
    ON fsfs.branch = msc1.branch_id
    WHERE to_number (fsfs.year
      || fsfs.month) >= to_number (TO_CHAR (add_months (sysdate, -7), 'YYYYMM'))
    ) fsfs
  INNER JOIN fml_stacc_fr_stmt_end fsfse
  ON fsfse.process_id   = fsfs.process_id
  AND fsfse.report_type = fsfs.report_type
  LEFT JOIN
    (SELECT s.process_id,s.report_type,s.year,s.month,
      COUNT(*) AS sum_process
    FROM
      (SELECT s.process_id,s.report_type,s.year,s.month,branch
      FROM fml_stacc_fr_stmt s 
      INNER JOIN mas_store_cambodia msc2 
      ON s.branch = msc2.branch_id
      GROUP BY s.process_id,s.report_type,s.year,s.month,s.branch
      ) s
    GROUP BY s.process_id,s.report_type,s.year,s.month
    ) tt
  ON tt.process_id   = fsfse.process_id
  AND tt.report_type = fsfse.report_type
  LEFT JOIN
    (SELECT YEAR,MONTH,report_type,
      COUNT (*) AS total_stacc_ws
    FROM
      ( SELECT DISTINCT fsr.report_type,fsr.branch,fsr.year,fsr.month
      FROM fml_stacc_fr_stmt fsr
      INNER JOIN mas_store_cambodia msc3 
      ON fsr.branch = msc3.branch_id
      WHERE to_number (fsr.year
        || fsr.month) >= to_number (TO_CHAR (add_months (sysdate, -7), 'YYYYMM'))
      )
    GROUP BY YEAR,MONTH,report_type
    ) a ON a.year   = fsfs.year
  AND a.month       = fsfs.month
  AND a.report_type = fsfs.report_type
  LEFT JOIN
    (SELECT YEAR,MONTH,report_type,
      COUNT (*) AS total_fml_import
    FROM fml_franchise_statement frs
    INNER JOIN mas_store_cambodia msc4 
    ON frs.store_id = msc4.branch_id
    WHERE to_number (frs.year
      || frs.month) >= to_number (TO_CHAR (add_months (sysdate, -7), 'yyyymm'))
    GROUP BY YEAR,MONTH,report_type
    ) b ON b.year   = fsfs.year
  AND b.month       = fsfs.month
  AND b.report_type = fsfs.report_type
  LEFT JOIN
    (SELECT YEAR,MONTH,report_type,
      COUNT (*) AS total_cur_stacc_ws
    FROM
      ( SELECT DISTINCT fsr.report_type,fsr.branch,fsr.year,fsr.month
      FROM fml_stacc_fr_stmt fsr
      INNER JOIN mas_store_cambodia msc5 
      ON fsr.branch = msc5.branch_id
      WHERE to_number (fsr.year
        || fsr.month)             >= to_number (TO_CHAR (add_months (sysdate, -7), 'YYYYMM'))
      AND NVL (send_mail_flag, 0) != 1)
    GROUP BY report_type,YEAR,MONTH
    ) c ON c.year   = fsfs.year
  AND c.month       = fsfs.month
  AND c.report_type = fsfs.report_type
  LEFT JOIN
    (SELECT YEAR,MONTH,report_type,
      COUNT (*) AS total_cur_fml_import
    FROM
      ( SELECT DISTINCT fsr.process_id,fsr.report_type,fsr.branch,fsr.year,fsr.month
      FROM fml_stacc_fr_stmt fsr
      INNER JOIN mas_store_cambodia msc6 
      ON fsr.branch = msc6.branch_id
      WHERE to_number (fsr.year
        || fsr.month)                 >= to_number (TO_CHAR (add_months (sysdate, -7),'YYYYMM'))
      AND NVL (fsr.send_mail_flag, 0) != 1
      AND NVL (fsr.import_flag, 0)     = 1)
    GROUP BY report_type,YEAR,MONTH
    ) d ON d.year   = fsfs.year
  AND d.month       = fsfs.month
  AND d.report_type = fsfs.report_type
  LEFT JOIN
    (SELECT ee.report_type,ee.year,ee.month,listagg (ee.branch, ', ') within GROUP (ORDER BY ee.branch) AS branch
    FROM
      (SELECT e1.*,row_number() over (partition BY e1.report_type, e1.year, e1.month order by e1.branch) AS row_num
      FROM
        ( SELECT DISTINCT fsr.report_type,fsr.year,fsr.month,fsr.branch
        FROM fml_stacc_fr_stmt fsr
        INNER JOIN mas_store_cambodia msc6 
        ON fsr.branch = msc6.branch_id
        WHERE to_number (fsr.year
          || fsr.month)             >= to_number (TO_CHAR (add_months (sysdate, -7), 'YYYYMM'))
        AND NVL (fsr.import_flag, 0) = 0
        ) e1
      ) ee
    WHERE ee.row_num <= 100
    GROUP BY ee.report_type,ee.year,ee.month
    ) e ON e.year   = fsfs.year
  AND e.month       = fsfs.month
  AND e.report_type = fsfs.report_type
  LEFT JOIN
    (SELECT ff.report_type,ff.year,ff.month,listagg (ff.branch, ', ') within GROUP (ORDER BY ff.branch) AS remark
    FROM
      (SELECT f1.*,
        row_number() over (partition BY f1.report_type, f1.year, f1.month order by f1.branch) AS row_num
      FROM
        ( SELECT DISTINCT stmt.branch,stmt.year,stmt.month,stmt.report_type
        FROM fml_stacc_fr_stmt stmt
        INNER JOIN fml_tmp_importdata_stmt tmp
        ON tmp.report_type = stmt.report_type
        INNER JOIN mas_store_cambodia msc7 
        ON stmt.branch = msc7.branch_id
        WHERE to_number (stmt.year
          || stmt.month) >= to_number (TO_CHAR (add_months (sysdate, -7), 'YYYYMM'))
        AND NOT EXISTS
          (SELECT tmp2.col01
          FROM fml_tmp_importdata_stmt tmp2
          WHERE tmp2.report_type   = stmt.report_type
          AND tmp2.col01           = stmt.branch
          AND tmp2.filename_period = TO_CHAR (to_date (stmt.month
            || '/'
            || stmt.year, 'MM/YYYY'), 'MM/YY','NLS_CALENDAR=''THAI BUDDHA')
          )
        ) f1
      ) ff
    WHERE ff.row_num <= 100
    GROUP BY ff.year,ff.month,ff.report_type
    ) f ON f.year   = fsfs.year
  AND f.month       = fsfs.month
  AND f.report_type = fsfs.report_type
;

-- ---------- VIEW: V_FML_FRANCHISE_STMT_LA ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_FML_FRANCHISE_STMT_LA" ("PROCESS_ID", "REPORT_TYPE", "YEAR", "MONTH", "REPORT_NAME", "SUM_PROCESS", "TOTAL_STACC_WS", "TOTAL_FML_IMPORT", "TOTAL_CUR_STACC_WS", "TOTAL_CUR_FML_IMPORT", "BRANCH", "REMARK") AS 
  SELECT fsfs.process_id,
    fsfs.report_type,
    fsfs.YEAR,
    fsfs.MONTH,
    fsfs.report_name,
    tt.sum_process,
    a.total_stacc_ws,
    b.total_fml_import,
    c.total_cur_stacc_ws,
    d.total_cur_fml_import,
    e.branch,
    fsfse.remark
    || (
    CASE
      WHEN f.report_type = 'RLEECFM'
      THEN DECODE(f.remark, NULL, NULL, 'พบรหัสร้านที่มีการนำเข้า แต่ไม่มีข้อมูล QTY ติดลบหรือบวก คือ '
        || f.remark)
      ELSE f.remark
    END ) AS remark
 FROM
    ( SELECT DISTINCT fsfs.process_id,fsfs.report_type,fsfs.year,fsfs.month,cc.code_name AS report_name
    FROM fml_stacc_fr_stmt fsfs
    INNER JOIN common_code cc
    ON cc.code_value = fsfs.report_type
    AND cc.code_type LIKE 'LAOS%'
    INNER JOIN mas_store_laos msl1 
    ON fsfs.branch = msl1.branch_id
    WHERE to_number (fsfs.year
      || fsfs.month) >= to_number (TO_CHAR (add_months (sysdate, -7), 'YYYYMM'))
    ) fsfs
  INNER JOIN fml_stacc_fr_stmt_end fsfse
  ON fsfse.process_id   = fsfs.process_id
  AND fsfse.report_type = fsfs.report_type
  LEFT JOIN
    (SELECT s.process_id,s.report_type,s.year,s.month,
      COUNT(*) AS sum_process
    FROM
      (SELECT s.process_id,s.report_type,s.year,s.month,branch
      FROM fml_stacc_fr_stmt s 
      INNER JOIN mas_store_laos msl2 
      ON s.branch = msl2.branch_id
      GROUP BY s.process_id,s.report_type,s.year,s.month,s.branch
      ) s
    GROUP BY s.process_id,s.report_type,s.year,s.month
    ) tt
  ON tt.process_id   = fsfse.process_id
  AND tt.report_type = fsfse.report_type
  LEFT JOIN
    (SELECT YEAR,MONTH,report_type,
      COUNT (*) AS total_stacc_ws
    FROM
      ( SELECT DISTINCT fsr.report_type,fsr.branch,fsr.year,fsr.month
      FROM fml_stacc_fr_stmt fsr
      INNER JOIN mas_store_laos msl3 
      ON fsr.branch = msl3.branch_id
      WHERE to_number (fsr.year
        || fsr.month) >= to_number (TO_CHAR (add_months (sysdate, -7), 'YYYYMM'))
      )
    GROUP BY YEAR,MONTH,report_type
    ) a ON a.year   = fsfs.year
  AND a.month       = fsfs.month
  AND a.report_type = fsfs.report_type
  LEFT JOIN
    (SELECT YEAR,MONTH,report_type,
      COUNT (*) AS total_fml_import
    FROM fml_franchise_statement frs
    INNER JOIN mas_store_laos msl4 
    ON frs.store_id = msl4.branch_id
    WHERE to_number (frs.year
      || frs.month) >= to_number (TO_CHAR (add_months (sysdate, -7), 'yyyymm'))
    GROUP BY YEAR,MONTH,report_type
    ) b ON b.year   = fsfs.year
  AND b.month       = fsfs.month
  AND b.report_type = fsfs.report_type
  LEFT JOIN
    (SELECT YEAR,MONTH,report_type,
      COUNT (*) AS total_cur_stacc_ws
    FROM
      ( SELECT DISTINCT fsr.report_type,fsr.branch,fsr.year,fsr.month
      FROM fml_stacc_fr_stmt fsr
      INNER JOIN mas_store_laos msl5 
      ON fsr.branch = msl5.branch_id
      WHERE to_number (fsr.year
        || fsr.month)             >= to_number (TO_CHAR (add_months (sysdate, -7), 'YYYYMM'))
      AND NVL (send_mail_flag, 0) != 1)
    GROUP BY report_type,YEAR,MONTH
    ) c ON c.year   = fsfs.year
  AND c.month       = fsfs.month
  AND c.report_type = fsfs.report_type
  LEFT JOIN
    (SELECT YEAR,MONTH,report_type,
      COUNT (*) AS total_cur_fml_import
    FROM
      ( SELECT DISTINCT fsr.process_id,fsr.report_type,fsr.branch,fsr.year,fsr.month
      FROM fml_stacc_fr_stmt fsr
      INNER JOIN mas_store_laos msl6 
      ON fsr.branch = msl6.branch_id
      WHERE to_number (fsr.year
        || fsr.month)                 >= to_number (TO_CHAR (add_months (sysdate, -7),'YYYYMM'))
      AND NVL (fsr.send_mail_flag, 0) != 1
      AND NVL (fsr.import_flag, 0)     = 1)
    GROUP BY report_type,YEAR,MONTH
    ) d ON d.year   = fsfs.year
  AND d.month       = fsfs.month
  AND d.report_type = fsfs.report_type
  LEFT JOIN
    (SELECT ee.report_type,ee.year,ee.month,listagg (ee.branch, ', ') within GROUP (ORDER BY ee.branch) AS branch
    FROM
      (SELECT e1.*,row_number() over (partition BY e1.report_type, e1.year, e1.month order by e1.branch) AS row_num
      FROM
        ( SELECT DISTINCT fsr.report_type,fsr.year,fsr.month,fsr.branch
        FROM fml_stacc_fr_stmt fsr
        INNER JOIN mas_store_laos msl6 
        ON fsr.branch = msl6.branch_id
        WHERE to_number (fsr.year
          || fsr.month)             >= to_number (TO_CHAR (add_months (sysdate, -7), 'YYYYMM'))
        AND NVL (fsr.import_flag, 0) = 0
        ) e1
      ) ee
    WHERE ee.row_num <= 100
    GROUP BY ee.report_type,ee.year,ee.month
    ) e ON e.year   = fsfs.year
  AND e.month       = fsfs.month
  AND e.report_type = fsfs.report_type
  LEFT JOIN
    (SELECT ff.report_type,ff.year,ff.month,listagg (ff.branch, ', ') within GROUP (ORDER BY ff.branch) AS remark
    FROM
      (SELECT f1.*,
        row_number() over (partition BY f1.report_type, f1.year, f1.month order by f1.branch) AS row_num
      FROM
        ( SELECT DISTINCT stmt.branch,stmt.year,stmt.month,stmt.report_type
        FROM fml_stacc_fr_stmt stmt
        INNER JOIN fml_tmp_importdata_stmt tmp
        ON tmp.report_type = stmt.report_type
        INNER JOIN mas_store_laos msl7 
        ON stmt.branch = msl7.branch_id
        WHERE to_number (stmt.year
          || stmt.month) >= to_number (TO_CHAR (add_months (sysdate, -7), 'YYYYMM'))
        AND NOT EXISTS
          (SELECT tmp2.col01
          FROM fml_tmp_importdata_stmt tmp2
          WHERE tmp2.report_type   = stmt.report_type
          AND tmp2.col01           = stmt.branch
          AND tmp2.filename_period = TO_CHAR (to_date (stmt.month
            || '/'
            || stmt.year, 'MM/YYYY'), 'MM/YY','NLS_CALENDAR=''THAI BUDDHA')
          )
        ) f1
      ) ff
    WHERE ff.row_num <= 100
    GROUP BY ff.year,ff.month,ff.report_type
    ) f ON f.year   = fsfs.year
  AND f.month       = fsfs.month
  AND f.report_type = fsfs.report_type
;

-- ---------- VIEW: V_FML_RESPONSIBLE_SBP ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_FML_RESPONSIBLE_SBP" ("STORE_PTT", "REGION", "NAME", "POSITION", "EMAIL", "TEL") AS 
  SELECT STORE_PTT,
         REGION,
         NAME,
         POSITION,
         EMAIL,
         TEL
    FROM FML_RESPONSIBLE_SBP
ORDER BY RESPONSIBLE_SBP_ID;

-- ---------- VIEW: V_FML_SHOW_MENU ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_FML_SHOW_MENU" ("รหัสร้าน") AS 
  SELECT p.param_value AS "รหัสร้าน"
     FROM mas_param p
    WHERE INSTR (p.param_name, 'FML_STORE_ID_ITEM_ID955') > 0;

-- ---------- VIEW: V_FML_STACC_FR_STMT ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_FML_STACC_FR_STMT" ("YEAR", "MONTH", "BRANCH", "REPORT_TYPE", "TOTAL_STACC", "TOTAL_RECEIVE", "TOTAL_FML") AS 
  SELECT a.YEAR,
    a.MONTH,
    a.BRANCH,
    a.REPORT_TYPE,
    a.TOTAL_STACC,
    b.TOTAL_RECEIVE,
    c.TOTAL_FML
  FROM
    ( SELECT DISTINCT a2.REPORT_TYPE,
      a1.BRANCH,
      a1.YEAR,
      a1.MONTH,
      a2.SUM_PROCESS TOTAL_STACC
    FROM
      (SELECT *
      FROM FML_STACC_FR_STMT a
      WHERE (a.SEND_MAIL_FLAG IS NULL
      OR a.SEND_MAIL_FLAG     != 1)
      AND a.IMPORT_FLAG       IS NOT NULL
      AND a.PROCESS_ID NOT    IN
        (SELECT DISTINCT PROCESS_ID FROM FML_STACC_FR_STMT WHERE IMPORT_FLAG IS NULL
        )
      ) a1,
      FML_STACC_FR_STMT_END a2
    WHERE (a1.SEND_MAIL_FLAG IS NULL
    OR a1.SEND_MAIL_FLAG     != 1)
    AND a1.PROCESS_ID         = a2.PROCESS_ID
    AND a1.REPORT_TYPE        = a2.REPORT_TYPE
    ) a,
    ( SELECT DISTINCT a1.REPORT_TYPE,
      COUNT(*) TOTAL_RECEIVE
    FROM
      (SELECT *
      FROM FML_STACC_FR_STMT a
      WHERE (a.SEND_MAIL_FLAG IS NULL
      OR a.SEND_MAIL_FLAG     != 1)
      AND a.IMPORT_FLAG       IS NOT NULL
      AND a.PROCESS_ID NOT    IN
        (SELECT DISTINCT PROCESS_ID FROM FML_STACC_FR_STMT WHERE IMPORT_FLAG IS NULL
        )
      ) a1,
      FML_STACC_FR_STMT_END a2
    WHERE (a1.SEND_MAIL_FLAG IS NULL
    OR a1.SEND_MAIL_FLAG     != 1)
    AND a1.PROCESS_ID         = a2.PROCESS_ID
    AND a1.REPORT_TYPE        = a2.REPORT_TYPE
    GROUP BY a1.REPORT_TYPE
    ) b,
    ( SELECT DISTINCT a1.REPORT_TYPE,
      a1.BRANCH,
      a1.YEAR,
      a1.MONTH,
      COUNT(*) TOTAL_FML
    FROM
      (SELECT *
      FROM FML_STACC_FR_STMT a
      WHERE (a.SEND_MAIL_FLAG IS NULL
      OR a.SEND_MAIL_FLAG     != 1)
      AND a.IMPORT_FLAG       IS NOT NULL
      AND a.PROCESS_ID NOT    IN
        (SELECT DISTINCT PROCESS_ID FROM FML_STACC_FR_STMT WHERE IMPORT_FLAG IS NULL
        )
      ) a1,
      FML_STACC_FR_STMT_END a2
    WHERE (a1.SEND_MAIL_FLAG IS NULL
    OR a1.SEND_MAIL_FLAG     != 1)
    AND a1.PROCESS_ID         = a2.PROCESS_ID
    AND a1.IMPORT_FLAG        = 1
    AND a1.REPORT_TYPE        = a2.REPORT_TYPE
    GROUP BY a1.REPORT_TYPE,
      a1.BRANCH,
      a1.YEAR,
      a1.MONTH
    ) c
  WHERE a.REPORT_TYPE = c.REPORT_TYPE
  AND a.BRANCH        = c.BRANCH
  AND a.YEAR          = c.YEAR
  AND a.MONTH         = c.MONTH
  AND a.REPORT_TYPE   = b.REPORT_TYPE;

-- ---------- VIEW: V_FMP_DC_IN ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_FMP_DC_IN" ("ID", "STORE_ID", "FIRST_NAME", "LAST_NAME", "ID_CARD", "EMPLOYEE_TYPE_ID", "ROLE_ID", "START_DATE", "SALARY", "BENEFIT", "CREATE_DATE", "CREATE_USER", "DEPARTMENT_ID", "UPDATE_DATE", "UPDATE_USER", "NO", "STATUS_ID", "ROLE", "YEAR", "MONTH", "EMPLOYEE_ID", "TITLE_NAME", "SEX_ID", "EDUCATION", "TURN_ID", "POSITION_ID", "WORK_NO", "STRUCTURE_FORMAT", "TRAIN_LOG", "FC_CONFIRM_DATE", "END_DATE", "CREATE_FILE_DATE", "DEPARTMENT_NAME", "SEX_NAME", "EMPLOYEE_TYPE_NAME", "POSITION_NAME", "OPT_DELETE_FLAG", "TITLE_NAME_EN", "FIRST_NAME_EN", "LAST_NAME_EN") AS 
