            "STORE_ID",
            "FIRST_NAME",
            "LAST_NAME",
            "ID_CARD",
            "EMPLOYEE_TYPE_ID",
            "ROLE_ID",
            "START_DATE",
            "SALARY",
            "BENEFIT",
            "CREATE_DATE",
            "CREATE_USER",
            "DEPARTMENT_ID",
            "UPDATE_DATE",
            "UPDATE_USER",
