-- ---------- VIEW: V_FMP_MANPOWER ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_FMP_MANPOWER" ("NO", "STORE_ID", "STORE_NAME", "REGION", "CODE_NAME", "STRAT_DATE", "SALES", "STRUCTURE_FORMAT", "FC_STRUCTURE_FORMAT_FT", "FC_STRUCTURE_FORMAT_PT", "OPT_STRUCTURE_FORMAT_FT", "OPT_STRUCTURE_FORMAT_PT", "FC_NAME", "MN_NAME", "OPT_FULLNAME", "FC_CONFIRM_DATE", "OPT_CONFIRM_DATE", "FC_CONFIRM_FLAG", "OPT_CONFIRM_FLAG", "STATUS_NAME", "EMPLOYEE_ID", "ID_CARD", "FULL_NAME", "DEPARTMENT_NAME", "SEX_NAME", "EDUCATION_NAME", "EMPLOYEE_TYPE_NAME", "ROLE_NAME", "POSITION_NAME", "FROM_SYSTEM", "CANCEL_DATE", "START_DATE", "YEAR", "MONTH") AS 
  SELECT ROW_NUMBER () OVER (ORDER BY a.store_id) NO,
          a."STORE_ID",
          a."STORE_NAME",
          a."REGION",
          a."CODE_NAME",
          a."STRAT_DATE",
          a."SALES",
          a."STRUCTURE_FORMAT",
          a."FC_STRUCTURE_FORMAT_FT",
          a."FC_STRUCTURE_FORMAT_PT",
          a."OPT_STRUCTURE_FORMAT_FT",
          a."OPT_STRUCTURE_FORMAT_PT",
          a."FC_NAME",
          a."MN_NAME",
          a."OPT_FULLNAME",
          a."FC_CONFIRM_DATE",
          a."OPT_CONFIRM_DATE",
          a."FC_CONFIRM_FLAG",
          a."OPT_CONFIRM_FLAG",
          a."STATUS_NAME",
          a."EMPLOYEE_ID",
          a."ID_CARD",
          a."FULL_NAME",
          a."DEPARTMENT_NAME",
          a."SEX_NAME",
          a."EDUCATION_NAME",
          a."EMPLOYEE_TYPE_NAME",
          a."ROLE_NAME",
          a."POSITION_NAME",
          a."FROM_SYSTEM",
          a."CANCEL_DATE",
          a."START_DATE",
          a."YEAR",
          a."MONTH"
     FROM (SELECT *
             FROM (  SELECT DISTINCT
                            mp.store_id,
                            fs.branch_name store_name,
                            fs.region,
                            cc2.code_name,
                            TO_CHAR (
                               fr.start_date,
                               'DD/MM/YYYY',
                               'NLS_CALENDAR=''Thai Buddha'' NLS_DATE_LANGUAGE=THAI')
                               AS strat_date,
                            sd.sales,
                            b.structure_format,
                            DECODE (b.employee_type_id,
                                    'F', b.fc_structure_format,
                                    '0.00')
                               AS fc_structure_format_ft,
                            DECODE (b.employee_type_id,
                                    'P', b.fc_structure_format,
                                    '0.00')
                               AS fc_structure_format_pt,
                            DECODE (b.employee_type_id,
                                    'F', b.opt_structure_format,
                                    '0.00')
                               AS opt_structure_format_ft,
                            DECODE (b.employee_type_id,
                                    'P', b.opt_structure_format,
                                    '0.00')
                               AS opt_structure_format_pt,
                            fs.fc_name,
                            fs.mn_name,
                            dv_first_name || ' ' || dv_last_name opt_fullname,
                            TO_CHAR (
                               mp.fc_confirm_date,
                               'DD/MM/YYYY',
                               'NLS_CALENDAR=''Thai Buddha'' NLS_DATE_LANGUAGE=THAI')
                               AS fc_confirm_date,
                            TO_CHAR (
                               mp.opt_confirm_date,
                               'DD/MM/YYYY',
                               'NLS_CALENDAR=''Thai Buddha'' NLS_DATE_LANGUAGE=THAI')
                               AS opt_confirm_date,
                            mp.fc_confirm_flag,
                            mp.opt_confirm_flag,
                            cc.code_name status_name,
                            b.employee_id,
                            b.id_card,
                            d.first_name || ' ' || d.last_name full_name,
                            b.department_name,
                            d.sex_name,
                            d.education_name,
                            b.employee_type_name,
                            b.role_name,
                            b.position_name,
                            'Y' AS from_system,
                            fr.cancel_date,
                            fr.start_date,
                            mp.year,
                            mp.month
                       FROM (SELECT * FROM fmp_man_power --WHERE YEAR = '2014' AND MONTH = '06'
                                                        ) mp
                            INNER JOIN fs_sevenshop fs
                               ON TO_NUMBER (fs.branch_id) =
                                     TO_NUMBER (mp.store_id)
                            LEFT JOIN fmp_employee_detail b
                               ON     mp.store_id = b.store_id
                                  AND mp.YEAR = b.YEAR
                                  AND mp.MONTH = b.MONTH
                            LEFT JOIN fmp_employee d
                               ON (b.fmp_employee_id = d.ID)
                            LEFT JOIN fr_store fr
                               ON TO_NUMBER (fr.store_id) =
                                     TO_NUMBER (mp.store_id)
                            LEFT JOIN fmp_daily_sales sd
                               ON (    sd.store_id = mp.store_id
                                   AND sd.MONTH = mp.MONTH
                                   AND sd.YEAR = mp.YEAR)
                            LEFT JOIN fmp_organization org
                               ON (sd.sales BETWEEN org.sales_from
                                                AND org.sales_to
                                   AND NVL (delete_flag, '-') != 'Y')
                            LEFT JOIN common_code cc
                               ON (cc.code_type = 'FMP02'
                                   AND cc.code_value = mp.status_id)
                            LEFT JOIN common_code cc2
                               ON cc2.code_type = '00019'
                                  AND cc2.code_value = mp.fr_type_id
                      WHERE     NVL (fr.status, '-') != 'D'
                            AND TO_NUMBER (fr.store_id) != 0
                            AND fr.start_date IS NOT NULL
                   --                              AND (fr.cancel_date IS NULL
                   --                                   OR TO_CHAR (ADD_MONTHS (fr.cancel_date, 1),
                   --                                               'YYYYMMDD') >= '201406' || '21')
                   --                              AND fr.start_date IS NOT NULL
                   --                              AND TO_CHAR (fr.start_date, 'YYYYMMDD') <
                   --                                     '201406' || '20'
                   ORDER BY store_id)
           UNION ALL
           SELECT *
             FROM (  SELECT DISTINCT
                            mp.store_id,
                            fs.branch_name store_name,
                            fs.region,
                            cc2.code_name,
                            TO_CHAR (
                               fr.start_date,
                               'DD/MM/YYYY',
                               'NLS_CALENDAR=''Thai Buddha'' NLS_DATE_LANGUAGE=THAI')
                               AS strat_date,
                            sd.sales,
                            NULL AS structure_format,
                            DECODE (b.employee_type_id,
                                    'F', b.fc_structure_format,
                                    '0.00')
                               AS fc_structure_format_ft,
                            DECODE (b.employee_type_id,
                                    'P', b.fc_structure_format,
                                    '0.00')
                               AS fc_structure_format_pt,
                            DECODE (b.employee_type_id,
                                    'F', b.opt_structure_format,
                                    '0.00')
                               AS opt_structure_format_ft,
                            DECODE (b.employee_type_id,
                                    'P', b.opt_structure_format,
                                    '0.00')
                               AS opt_structure_format_pt,
                            fs.fc_name,
                            fs.mn_name,
                            dv_first_name || ' ' || dv_last_name opt_fullname,
                            TO_CHAR (
                               mp.fc_confirm_date,
                               'DD/MM/YYYY',
                               'NLS_CALENDAR=''Thai Buddha'' NLS_DATE_LANGUAGE=THAI')
                               AS fc_confirm_date,
                            TO_CHAR (
                               mp.opt_confirm_date,
                               'DD/MM/YYYY',
                               'NLS_CALENDAR=''Thai Buddha'' NLS_DATE_LANGUAGE=THAI')
                               AS opt_confirm_date,
                            mp.fc_confirm_flag,
                            mp.opt_confirm_flag,
                            cc.code_name status_name,
                            NULL AS employee_id,
                            NULL AS id_card,
                            b.full_name,
                            b.department_name,
                            NULL AS sex_name,
                            NULL AS education_name,
                            b.employee_type_name,
                            NULL AS role_name,
                            NULL AS position_name,
                            'N' AS from_system,
                            fr.cancel_date,
                            fr.start_date,
                            mp.year,
                            mp.month
                       FROM (SELECT *
                               FROM fmp_man_power
                              WHERE 1 = 1     --YEAR = '2014' AND MONTH = '06'
                                         ) mp
                            INNER JOIN fs_sevenshop fs
                               ON TO_NUMBER (fs.branch_id) =
                                     TO_NUMBER (mp.store_id)
                            INNER JOIN fmp_employee_extra b
                               ON     mp.store_id = b.store_id
                                  AND mp.YEAR = b.YEAR
                                  AND mp.MONTH = b.MONTH
                            LEFT JOIN fr_store fr
                               ON TO_NUMBER (fr.store_id) =
                                     TO_NUMBER (mp.store_id)
                            LEFT JOIN fmp_daily_sales sd
                               ON (    sd.store_id = mp.store_id
                                   AND sd.MONTH = mp.MONTH
                                   AND sd.YEAR = mp.YEAR)
                            LEFT JOIN fmp_organization org
                               ON (sd.sales BETWEEN org.sales_from
                                                AND org.sales_to
                                   AND NVL (delete_flag, '-') != 'Y')
                            LEFT JOIN common_code cc
                               ON (cc.code_type = 'FMP02'
                                   AND cc.code_value = mp.status_id)
                            LEFT JOIN common_code cc2
                               ON cc2.code_type = '00019'
                                  AND cc2.code_value = mp.fr_type_id
                      WHERE NVL (fr.status, '-') != 'D'
                            AND TO_NUMBER (fr.store_id) != 0
                   --                              AND (fr.cancel_date IS NULL
                   --                                   OR TO_CHAR (ADD_MONTHS (fr.cancel_date, 1),
                   --                                               'YYYYMMDD') >= '201406' || '21')
                   --                              AND fr.start_date IS NOT NULL
                   --                              AND TO_CHAR (fr.start_date, 'YYYYMMDD') <
                   --                                     '201406' || '20'
                   ORDER BY store_id)) a;

-- ---------- VIEW: V_FMS_ATTACHMENTBYASSETID ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_FMS_ATTACHMENTBYASSETID" ("ASSET_ID", "FILE_NAME", "CM_URL", "CREATE_DATE", "DOCATTACH_ID") AS 
  SELECT
		CA.CUST_ASSET_ID,CM.FILE_NAME,CM.CM_URL,CM.CREATE_DATE,CM.DOCATTACH_ID
	FROM
		CUSTOMER_ASSET CA
    JOIN  FCS_FILE_MAPPING  FP ON FP.TRANSACTION_PK = CA.CUST_ASSET_ID AND FP.TABLE_TRANSACTION_PK = 'CUSTOMER_ASSET'
    JOIN  FMS_CM_ATTACH CM ON CM.DOCATTACH_ID = FP.FILE_ID AND CM.DELETE_FLAG = 'N' ;

-- ---------- VIEW: V_FMS_ATTACHMENTBYBANKID ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_FMS_ATTACHMENTBYBANKID" ("ASSET_ID", "FILE_NAME", "CM_URL", "CREATE_DATE", "DOCATTACH_ID") AS 
  SELECT
		CA.CUST_BANK_ACC_ID,CM.FILE_NAME,CM.CM_URL,CM.CREATE_DATE,CM.DOCATTACH_ID
	FROM
		CUSTOMER_BANK_ACCOUNT CA
    JOIN  FCS_FILE_MAPPING  FP ON FP.TRANSACTION_PK = CA.CUST_BANK_ACC_ID AND FP.TABLE_TRANSACTION_PK = 'CUSTOMER_BANK_ACCOUNT'
    JOIN  FMS_CM_ATTACH CM ON CM.DOCATTACH_ID = FP.FILE_ID AND CM.DELETE_FLAG = 'N' ;

-- ---------- VIEW: V_FMS_CUSTOMERBUSINESS_LIST ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_FMS_CUSTOMERBUSINESS_LIST" ("BUSINESS_NAME", "BUSINESS_TYPE", "POSITION", "INCOME", "CAPITAL", "ADDRESS", "OWNER_TYPE", "BUSINESS_STATUS", "CLOSE_DOWN_REASON", "CUST_ID", "SEQ_NO") AS 
  SELECT CB.BUSINESS_NAME,
          P.CODE_NAME,
          C.CODE_NAME,
          CB.INCOME,
          CB.CAPITAL,
          CB.ADDRESS,
          A.CODE_NAME,
          CB.BUSINESS_STATUS,
          CB.CLOSE_DOWN_REASON,
          CB.CUST_ID,
          CB.CUST_BUSINESS_ID
     FROM CUSTOMER_BUSINESS CB
          JOIN COMMON_CODE P
             ON     CB.BUSINESS_TYPE = P.CODE_VALUE
                AND P.CODE_TYPE = '00068'
                AND P.ACTIVE_FLAG = 'Y'
          JOIN COMMON_CODE C
             ON     CB.POSITION = C.CODE_VALUE
                AND C.CODE_MAPPING = 'EMP'
                AND C.CODE_TYPE = '00027'
                AND C.ACTIVE_FLAG = 'Y'
          JOIN COMMON_CODE A
             ON     CB.OWNER_TYPE = A.CODE_VALUE
                AND A.CODE_TYPE = '00024A'
                AND A.ACTIVE_FLAG = 'Y';

-- ---------- VIEW: V_FMS_CUSTOMEREDUCATION_LIST ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_FMS_CUSTOMEREDUCATION_LIST" ("CUST_ID", "CUSTEDU_ID", "SEQNO", "PROCESSID", "DEGREE", "DEGREENAME", "MAJOR", "INSTITUE", "GRADUATEYEAR", "DEGREE_ID") AS 
  SELECT CE.CUST_ID,
          CE.CUST_EDU_ID,
          CE.SEQ,
          CE.PROCESS_ID,
          P.CODE_NAME,
          CE.DEGREE_NAME,
          CE.MAJOR,
          CE.INSTITUTE,
          CE.GRADUATE_YEAR,
          CE.DEGREE
     FROM    CUSTOMER_EDUCATION CE
          JOIN
             COMMON_CODE P
          ON     CE.DEGREE = P.CODE_VALUE
             AND P.CODE_TYPE = '00003'
             AND P.ACTIVE_FLAG = 'Y';

-- ---------- VIEW: V_FMS_CUSTOMEREJOBEXP_LIST ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_FMS_CUSTOMEREJOBEXP_LIST" ("CUST_ID", "SEQNO", "POSITIONDATE", "POSITIONENDDATE", "POSITION", "JOB_DESC", "BOSS_NAME", "STORE_ID", "STORE_NAME", "INCOME", "LEAVE_REASON", "COMPANY_NAME", "OFFICE", "OFFICE_TEL", "EMPLOY_PERIOD_MONTH", "EMPLOY_PERION_YEAR", "ALLOW_INQUIRY", "INQUIRY_REASON", "JOB_EXP_TYPE", "SEQ") AS 
  SELECT CJ.CUST_ID,
          CJ.CUST_JOB_EXP_ID,
          CJ.POSITION_START_DATE,
          CJ.POSITION_END_DATE,
          P.CODE_NAME,
          CJ.JOB_DESC,
          CJ.BOSS_NAME,
          CJ.STORE_ID,
          CJ.STORE_NAME,
          CJ.INCOME,
          CJ.LEAVE_REASON,
          CJ.COMPANY_NAME,
          CJ.OFFICE,
          CJ.OFFICE_TEL,
          CJ.EMPLOY_PERIOD_MONTH,
          CJ.EMPLOY_PERIOD_YEAR,
          CJ.ALLOW_INQUIRY,
          CJ.INQUIRY_REASON,
          CJ.JOB_EXP_TYPE,
          CJ.SEQ
     FROM    CUSTOMER_JOB_EXP CJ
          LEFT JOIN
             COMMON_CODE P
          ON     CJ.POSITION = P.CODE_VALUE
             AND P.CODE_TYPE = '00027'
             AND P.ACTIVE_FLAG = 'Y';

-- ---------- VIEW: V_FMS_CUSTOMER_ASSET_LIST ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_FMS_CUSTOMER_ASSET_LIST" ("ASSET_TYPE", "ASSET_DESC", "ASSET_UNIT", "ASSET_AMOUNT", "SEQ", "CUST_ID", "PROCESS_ID", "CUST_ASSET_ID") AS 
  SELECT
		P.CODE_NAME,A.ASSET_DESC,A.ASSET_UNIT,A.ASSET_AMOUNT,A.SEQ,A.CUST_ID,A.PROCESS_ID,A.CUST_ASSET_ID
	FROM
	CUSTOMER_ASSET A
	JOIN COMMON_CODE P ON A.ASSET_TYPE = P.CODE_VALUE AND P.CODE_TYPE = '00085' AND P.CODE_MAPPING = 'ASSET' AND P.ACTIVE_FLAG = 'Y' ;

-- ---------- VIEW: V_FMS_CUSTOMER_BANK_LIST ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_FMS_CUSTOMER_BANK_LIST" ("BANK_NAME", "BRANCH", "ACCOUNT_NO", "ACCOUNT_TYPE", "ACCOUNT_AMOUNT", "CUST_ID", "SEQ", "PROCESS_ID", "CUST_BANK_ACC_ID") AS 
  SELECT
		P.CODE_NAME,CB.BRANCH,CB.ACCOUNT_NO,C.CODE_NAME,CB.ACCOUNT_AMOUNT,CB.CUST_ID,CB.SEQ,CB.PROCESS_ID,CB.CUST_BANK_ACC_ID
	FROM
	CUSTOMER_BANK_ACCOUNT CB
	JOIN COMMON_CODE P ON CB.BANK_NAME = P.CODE_VALUE AND P.CODE_TYPE = '00072' AND P.ACTIVE_FLAG = 'Y'
	JOIN COMMON_CODE C ON CB.ACCOUNT_TYPE = C.CODE_VALUE AND C.CODE_TYPE = '00070' AND C.ACTIVE_FLAG = 'Y' ;

-- ---------- VIEW: V_FMS_CUSTOMER_BUSINESS_LIST ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_FMS_CUSTOMER_BUSINESS_LIST" ("BUSINESS_NAME", "BUSINESS_TYPE", "POSITION", "INCOME", "CAPITAL", "ADDRESS", "OWNER_TYPE", "BUSINESS_STATUS", "CLOSE_DOWN_REASON", "CUST_ID", "SEQ_NO") AS 
  SELECT CB.BUSINESS_NAME,
          P.CODE_NAME,
          C.CODE_NAME,
          CB.INCOME,
          CB.CAPITAL,
          CB.ADDRESS,
          CB.OWNER_TYPE,
          CB.BUSINESS_STATUS,
          CB.CLOSE_DOWN_REASON,
          CB.CUST_ID,
          CB.SEQ
     FROM CUSTOMER_BUSINESS CB
          LEFT JOIN COMMON_CODE P
             ON     P.CODE_VALUE = CB.BUSINESS_TYPE
                AND P.CODE_TYPE = '00068'
                AND P.ACTIVE_FLAG = 'Y'
          JOIN COMMON_CODE C
             ON     C.CODE_VALUE = CB.POSITION_TYPE
                AND C.CODE_MAPPING = 'EMP'
                AND C.ACTIVE_FLAG = 'Y';

-- ---------- VIEW: V_FMS_CUSTOMER_EXPENSE_LIST ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_FMS_CUSTOMER_EXPENSE_LIST" ("EXPENSE_TYPE", "EXPENSE_TYPE_ID", "EXPENSE_DESC", "EXPENSE_AMOUNT", "REPAY_AMOUNT", "REPAY_PERIOD_MONTH", "REPAY_PERIOD_YEAR", "SEQ", "CUST_ID", "PROCESS_ID", "CUST_EXPENSE_ID") AS 
  SELECT P.CODE_NAME,
          E.EXPENSE_TYPE,
          E.EXPENSE_DESC,
          E.EXPENSE_AMOUNT,
          E.REPAY_AMOUNT,
          E.REPAY_PERIOD_MONTH,
          E.REPAY_PERIOD_YEAR,
          E.SEQ,
          E.CUST_ID,
          E.PROCESS_ID,
          E.CUST_EXPENSE_ID
     FROM    CUSTOMER_EXPENSE E
          JOIN
             COMMON_CODE P
          ON     E.EXPENSE_TYPE = P.CODE_VALUE
             AND P.CODE_TYPE = '00085'
             AND P.CODE_MAPPING = 'EXPENSE'
             AND P.ACTIVE_FLAG = 'Y';

-- ---------- VIEW: V_FMS_CUSTOMER_MANAGE_LIST ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_FMS_CUSTOMER_MANAGE_LIST" ("SEQ", "RELATED_CUST_ID", "CUST_ID", "MEMBER_TYPE", "FIRST_NAME", "LAST_NAME", "ID_CARD", "ADDRESS_NO", "SOI", "STREET", "MOO", "DISTRICT", "PROVINCE", "CITY", "ZIP", "RELATION_TYPE", "RELATION", "RELATION_TYPE_ID", "OCCP_CODE", "OFFICE", "MOBILE", "RELATED_TYPE", "CITIZENFILENAME", "CITIZENFILEURL", "CITIZENFILECREATEDATE", "HOUSEREGISFILENAME", "HOUSEREGISURL", "HOUSEREGISCREATEDATE", "JURASTIXFILENAME", "JURASTICURL", "JURASTIXFILECRATEDATE") AS 
  SELECT DISTINCT CMR.SEQ,
                   CMR.RELATED_CUST_ID,
                   CMR.CUST_ID,
                   CMR.MEMBER_TYPE,
                   CR.FIRST_NAME,
                   CR.LAST_NAME,
                   CR.ID_CARD,
                   CR.ADDRESS_NO,
                   CR.SOI,
                   CR.STREET,
                   CR.MOO,
                   D.SUB_DISTRICT_NAME,
                   P.PROVINCE_NAME,
                   A.DISTRICT_NAME,
                   CR.ZIP,
                   CM.CODE_NAME,
                   CMR.RELATION,
                   CMR.RELATION_TYPE,
                   CM2.CODE_NAME,
                   CR.OFFICE,
                   CR.MOBILE,
                   RL.RELATED_TYPE,
                   F1.FILE_NAME,
                   F1.CM_URL,
                   F1.CREATE_DATE,
                   F2.FILE_NAME,
                   F2.CM_URL,
                   F2.CREATE_DATE,
                   F3.FILE_NAME,
                   F3.CM_URL,
                   F3.CREATE_DATE
     FROM CUSTOMER_MEMBER_RELATION CMR
          LEFT JOIN CUSTOMER CR
             ON CMR.RELATED_CUST_ID = CR.CUST_ID
          LEFT JOIN CUSTOMER_RELATED RL
             ON RL.RELATED_CUST_ID = CMR.RELATED_CUST_ID
          LEFT JOIN COMMON_CODE CM
             ON     CMR.RELATION_TYPE = CM.CODE_VALUE
                AND CM.CODE_TYPE = '00028'
                AND CM.ACTIVE_FLAG = 'Y'
          LEFT JOIN COMMON_CODE CM2
             ON     CR.OCCP_CODE = CM2.CODE_VALUE
                AND CM2.CODE_TYPE = '00002'
                AND CM2.ACTIVE_FLAG = 'Y'
          LEFT JOIN MAS_DISTRICT A
             ON CR.CITY = A.DISTRICT_ID
          LEFT JOIN MAS_SUB_DISTRICT D
             ON CR.DISTRICT = D.SUB_DISTRICT_ID
          LEFT JOIN MAS_PROVINCE P
             ON CR.PROVINCE = P.PROVINCE_ID
          LEFT JOIN FMS_CM_ATTACH F1
             ON     CMR.RELATED_CUST_ID = F1.CUST_ID
                AND F1.DOC_TYPE_ID = 'doc01'
                AND F1.DOC_SUB_TYPE_ID = 2
                AND F1.DELETE_FLAG = 'N'
          LEFT JOIN FMS_CM_ATTACH F2
             ON     CMR.RELATED_CUST_ID = F2.CUST_ID
                AND F2.DOC_TYPE_ID = 'doc01'
                AND F2.DOC_SUB_TYPE_ID = 4
                AND F2.DELETE_FLAG = 'N'
          LEFT JOIN FMS_CM_ATTACH F3
             ON     CMR.RELATED_CUST_ID = F3.CUST_ID
                AND F3.DOC_TYPE_ID = 'doc06'
                AND F3.DOC_SUB_TYPE_ID = 9
                AND F3.DELETE_FLAG = 'N';

-- ---------- VIEW: V_FMS_CUSTOMER_ON_PROCESS ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_FMS_CUSTOMER_ON_PROCESS" ("PROCESS_ID", "FR_TYPE", "FR_TYPE_NAME", "FR_SUBTYPE_NAME", "STEP_ID", "STEP_NAME", "CUST_ID", "ID_CARD", "TITLE_CODE", "TITLE_NAME", "FIRST_NAME", "LAST_NAME", "EMAIL", "MOBILE", "MAIN_CUST_ID", "MAIN_CUST_ID_CARD", "MAIN_CUST_TITLE_CODE", "MAIN_CUST_TITLE_NAME", "MAIN_CUST_FIRST_NAME", "MAIN_CUST_LAST_NAME", "MAIN_RELATION_TYPE", "MAIN_RELATION", "CREATE_DATE", "RELATED_TYPE", "RELATED_TYPE_NAME", "FRANCHISEE_ID", "PRESENT_REGISTER_ID", "PRESENT_COURSE_ID", "PRESENT_COURSE_CODE", "PRESENT_DATE", "PRESENT_STATUS_CODE", "PRESENT_STATUS", "STORE_TOUR_REGISTER_ID", "STORE_TOUR_COURSE_ID", "STORE_TOUR_COURSE_CODE", "STORE_TOUR_DATE", "STORE_TOUR_STATUS_CODE", "STORE_TOUR_STATUS", "STORE_TOUR_EMP_REGISTER_ID", "STORE_TOUR_EMP_COURSE_ID", "STORE_TOUR_EMP_COURSE_CODE", "STORE_TOUR_EMP_DATE", "STORE_TOUR_EMP_STATUS_CODE", "STORE_TOUR_EMP_STATUS") AS 
  WITH max_step_id AS
  (SELECT p.process_id,
    MAX(t1.step_id) AS step_id
  FROM fr_process p
  INNER JOIN fr_process_trn t1
  ON NVL(p.update_func, '-') != 'D'
  AND NVL(t1.status, '1')     = '1'
  AND t1.process_id           = p.process_id
  GROUP BY p.process_id
  ),
  step_id_on_process AS
  (SELECT p.process_id,
    NULL AS step_id,
    p.cust_id,
    p.fr_type,
    p.fr_subtype,
    p.create_date,
    p.process_version
  FROM fr_process p
  WHERE NVL(p.update_func,'-') != 'D'
  AND p.process_id NOT         IN
    ( SELECT DISTINCT pt.process_id FROM fr_process_trn pt
    )
  UNION ALL
  SELECT t1.process_id,
    t1.step_id,
    t1.cust_id,
    p1.fr_type,
    p1.fr_subtype,
    p1.create_date,
    p1.process_version
  FROM fr_process p1
  INNER JOIN fr_process_trn t1
  ON NVL(p1.update_func, '-') != 'D'
  AND NVL(t1.status, '1')      = '1'
  AND t1.process_id            = p1.process_id
  AND EXISTS
    (SELECT t.*
    FROM max_step_id t
    WHERE t.process_id = t1.process_id
    AND t.step_id      = t1.step_id
    )
  ),
  param_course AS
  (SELECT MAX(DECODE(param_name, 'FMS_SEMINAR', param_name))       AS present_param,
    MAX(DECODE(param_name, 'FMS_SEMINAR', course_code))            AS present_course_code,
    MAX(DECODE(param_name, 'FMS_STORE_TOUR', param_name))          AS store_tour_param,
    MAX(DECODE(param_name, 'FMS_STORE_TOUR', course_code))         AS store_tour_course_code,
    MAX(DECODE(param_name, 'FMS_STORE_TOUR_PTT', param_name))      AS store_tour_ptt_param,
    MAX(DECODE(param_name, 'FMS_STORE_TOUR_PTT', course_code))     AS store_tour_ptt_course_code,
    MAX(DECODE(param_name, 'FMS_STORE_TOUR_EMP', param_name))      AS store_tour_emp_param,
    MAX(DECODE(param_name, 'FMS_STORE_TOUR_EMP', course_code))     AS store_tour_emp_course_code,
    MAX(DECODE(param_name, 'FMS_STORE_TOUR_NON_EMP', param_name))  AS store_tour_non_emp_param,
    MAX(DECODE(param_name, 'FMS_STORE_TOUR_NON_EMP', course_code)) AS store_tour_non_emp_course_code,
    MAX(DECODE(param_name, 'FMS_SM_AND_ST', param_name))           AS present_and_store_tour_param,
    MAX(DECODE(param_name, 'FMS_SM_AND_ST', course_code))          AS present_and_store_tour_course_code
  FROM
    (SELECT p1.param_name,
      p1.param_value AS course_code,
      p2.param_value AS target_type
    FROM mas_param p1
    INNER JOIN mas_param p2
    ON p1.ref_name  = 'FMS_REGISTER_COURSE'
    AND p2.ref_name = p1.param_name
    AND p2.param_name LIKE 'FMS%TARGET'
    )
  ),
  customer_on_process AS
  (
  /*main customer*/
  SELECT 1,
    sop.process_id,
    sop.step_id,
    sop.fr_type,
    sop.fr_subtype,
    sop.create_date,
    c1.cust_id,
    c1.id_card,
    c1.title_code,
    c1.first_name,
    c1.last_name,
    c1.email,
    c1.mobile,
    NULL     AS main_cust_id,
    NULL     AS main_cust_id_card,
    NULL     AS main_cust_title_code,
    NULL     AS main_cust_first_name,
    NULL     AS main_cust_last_name,
    NULL     AS relation_type,
    NULL     AS relation,
    NULL     AS related_type,
    'คนหลัก' AS related_type_name,
    NULL     AS franchisee_id,
    c1.present_register_id,
    c1.store_tour_register_id,
    c1.store_tour_emp_register_id,
    sop.process_version
  FROM step_id_on_process sop
  INNER JOIN customer c1
  ON c1.cust_id                 = sop.cust_id
  AND NVL(c1.update_func, '-') != 'D'
  UNION ALL
  
  /*related customer*/
  SELECT 2,
    sop.process_id,
    sop.step_id,
    sop.fr_type,
    sop.fr_subtype,
    sop.create_date,
    c2.cust_id,
    c2.id_card,
    c2.title_code,
    c2.first_name,
    c2.last_name,
    c1.email, --ใช้ email คนหลัก เพื่อลงทะเบียนอบรม (ผู้ติดตาม/ผู้ช่วย/เจ้าของเงินลงทุน ไม่ได้มี email ทุกคน)
    c2.mobile,
    c1.cust_id    AS main_cust_id,
    c1.id_card    AS main_cust_id_card,
    c1.title_code AS main_cust_title_code,
    c1.first_name AS main_cust_first_name,
    c1.last_name  AS main_cust_last_name,
    cr1.relation_type,
    cr1.relation,
    cr1.related_type,
    NULL AS related_type_name,
    NULL AS franchisee_id,
    c2.present_register_id,
    c2.store_tour_register_id,
    c2.store_tour_emp_register_id,
    sop.process_version
  FROM step_id_on_process sop
  INNER JOIN customer c1
  ON c1.cust_id                 = sop.cust_id --คนหลัก
  AND NVL(c1.update_func, '-') != 'D'
  INNER JOIN
    ( SELECT DISTINCT process_id,
      cust_id,
      related_cust_id,
      relation,
      relation_type,
      related_type
    FROM customer_related
    WHERE NVL(update_func, '-') != 'D'
    ) cr1
  ON cr1.cust_id = c1.cust_id
  INNER JOIN customer c2
  ON c2.cust_id                 = cr1.related_cust_id --ผู้ติดตาม/ผู้ช่วย/เจ้าของเงินลงทุน
  AND NVL(c2.update_func, '-') != 'D'
  UNION ALL
  
  /*main spouse*/
  /*related customer*/
  SELECT 2,
    sop.process_id,
    sop.step_id,
    sop.fr_type,
    sop.fr_subtype,
    sop.create_date,
    c2.cust_id,
    c2.id_card,
    c2.title_code,
    c2.first_name,
    c2.last_name,
    c1.email, --ใช้ email คนหลัก เพื่อลงทะเบียนอบรม (ผู้ติดตาม/ผู้ช่วย/เจ้าของเงินลงทุน ไม่ได้มี email ทุกคน)
    c2.mobile,
    c1.cust_id    AS main_cust_id,
    c1.id_card    AS main_cust_id_card,
    c1.title_code AS main_cust_title_code,
    c1.first_name AS main_cust_first_name,
    c1.last_name  AS main_cust_last_name,
    cr1.relation_type,
    cr1.relation,
    NULL      AS related_type,
    'คู่สมรส' AS related_type_name,
    NULL      AS franchisee_id,
    c2.present_register_id,
    c2.store_tour_register_id,
    c2.store_tour_emp_register_id,
    sop.process_version
  FROM step_id_on_process sop
  INNER JOIN customer c1
  ON c1.cust_id                 = sop.cust_id --คนหลัก
  AND NVL(c1.update_func, '-') != 'D'
  INNER JOIN
    ( SELECT DISTINCT process_id,
      cust_id,
      related_cust_id,
      relation,
      relation_type
    FROM customer_member_relation
    WHERE member_type = '4'
    ) cr1
  ON cr1.cust_id = c1.cust_id
  INNER JOIN customer c2
  ON c2.cust_id                 = cr1.related_cust_id --ผู้ติดตาม/ผู้ช่วย/เจ้าของเงินลงทุน
  AND NVL(c2.update_func, '-') != 'D'
  )
SELECT TO_CHAR (c.process_id) AS process_id,
  c.fr_type,
  cc6.code_name AS fr_type_name,
  cc7.code_name AS fr_subtype_name,
  c.step_id,
  cc5.code_name AS step_name,
  c.cust_id,
  c.id_card,
  c.title_code,
  cc2.code_name AS title_name,
  c.first_name,
  c.last_name,
  c.email,
  c.mobile,
  c.main_cust_id,
  c.main_cust_id_card,
  c.main_cust_title_code,
  cc1.code_name AS main_cust_title_name,
  c.main_cust_first_name,
  c.main_cust_last_name,
  cc3.code_name AS main_relation_type,
  c.relation    AS main_relation,
  c.create_date,
  c.related_type,
  DECODE (c.related_type_name, NULL, cc4.code_name, c.related_type_name) AS related_type_name,
  c.franchisee_id,
  rg1.register_id                                                                                                                                                                                                                                                                                                                                                               AS present_register_id,
  pm1.course_id                                                                                                                                                                                                                                                                                                                                                                 AS present_course_id,
  DECODE(c.process_version,2,DECODE( c.fr_type, 'A', pc.present_and_store_tour_course_code, 'B', pc.present_and_store_tour_course_code, 'C', present_and_store_tour_course_code, NULL ),DECODE( c.fr_type, 'A', pc.present_course_code, 'B', pc.present_course_code, 'C', pc.present_course_code, NULL ))                                                                       AS present_course_code,
  pm1.start_date                                                                                                                                                                                                                                                                                                                                                                AS present_date,
  NVL(rg1.register_status, DECODE(rg1.register_id, NULL, NULL, 'P'))                                                                                                                                                                                                                                                                                                            AS present_status_code,
  cc8.code_name                                                                                                                                                                                                                                                                                                                                                                 AS present_status,
  rg2.register_id                                                                                                                                                                                                                                                                                                                                                               AS store_tour_register_id,
  pm2.course_id                                                                                                                                                                                                                                                                                                                                                                 AS store_tour_course_id,
  DECODE(c.process_version,2, DECODE( c.fr_type, 'PTT', pc.store_tour_ptt_course_code, 'EMP', DECODE(c.fr_subtype, '02', pc.store_tour_non_emp_course_code, NULL), pc.present_and_store_tour_course_code ) , DECODE( c.fr_type, 'PTT', pc.store_tour_ptt_course_code, 'EMP', DECODE(c.fr_subtype, '02', pc.store_tour_non_emp_course_code, NULL), pc.store_tour_course_code ) ) AS store_tour_course_code,
  pm2.start_date                                                                                                                                                                                                                                                                                                                                                                AS store_tour_date,
  NVL(rg2.register_status, DECODE(rg2.register_id, NULL, NULL, 'P'))                                                                                                                                                                                                                                                                                                            AS store_tour_status_code,
  cc9.code_name                                                                                                                                                                                                                                                                                                                                                                 AS store_tour_status,
  rg3.register_id                                                                                                                                                                                                                                                                                                                                                               AS store_tour_emp_register_id,
  pm3.course_id                                                                                                                                                                                                                                                                                                                                                                 AS store_tour_emp_course_id,
  DECODE(c.fr_type, 'EMP', pc.store_tour_emp_course_code, NULL)                                                                                                                                                                                                                                                                                                                 AS store_tour_emp_course_code,
  pm3.start_date                                                                                                                                                                                                                                                                                                                                                                AS store_tour_emp_date,
  NVL(rg3.register_status, DECODE(rg3.register_id, NULL, NULL, 'P'))                                                                                                                                                                                                                                                                                                            AS store_tour_emp_status_code,
  cc10.code_name                                                                                                                                                                                                                                                                                                                                                                AS store_tour_emp_status
FROM customer_on_process c
INNER JOIN param_course pc
ON c.process_id IS NOT NULL
LEFT JOIN common_code cc1
ON cc1.code_type    = '00001'
AND cc1.active_flag = 'Y'
AND cc1.code_value  = c.main_cust_title_code
LEFT JOIN common_code cc2
ON cc2.code_type    = '00001'
AND cc2.active_flag = 'Y'
AND cc2.code_value  = c.title_code
LEFT JOIN common_code cc3
ON cc3.code_type    = '00028'
AND cc3.active_flag = 'Y'
AND cc3.code_value  = c.relation_type
LEFT JOIN common_code cc4
ON cc4.code_type    = '00012_1'
AND cc4.active_flag = 'Y'
AND cc4.code_value  = c.related_type
LEFT JOIN common_code cc5
ON cc5.code_type    = '00018'
AND cc5.active_flag = 'Y'
AND cc5.code_value  = TO_CHAR(c.step_id)
LEFT JOIN
  (SELECT code_name,
    code_value
  FROM
    (SELECT code_type,
      code_name,
      code_value
    FROM common_code
    WHERE code_type = '00019'
    AND active_flag = 'Y'
    UNION ALL
    SELECT code_type,
      code_name,
      code_value
    FROM common_code
    WHERE code_type     = '00019A'
    AND code_value NOT IN
      (SELECT code_value
      FROM common_code
      WHERE code_type = '00019'
      AND active_flag = 'Y'
      )
    AND active_flag = 'Y'
    )
  ) cc6
ON cc6.code_value = c.fr_type
LEFT JOIN common_code cc7
ON cc7.code_type    = c.fr_type
AND cc7.active_flag = 'Y'
AND cc7.code_value  = c.fr_subtype
  /*===seminar===*/
LEFT JOIN fts_register rg1
ON rg1.register_id = case when c.process_version = 2 and c.fr_type in ('B','C') then c.store_tour_register_id else c.present_register_id end
LEFT JOIN fts_plan_month pm1
ON pm1.plan_month_id = rg1.plan_month_id
LEFT JOIN common_code cc8
ON cc8.code_type   = 'FTS_REGISTER_STATUS'
AND cc8.code_value = NVL(rg1.register_status, DECODE(rg1.register_id, NULL, NULL, 'P'))
  /*===store tour public ===*/
LEFT JOIN fts_register rg2
ON rg2.register_id = c.store_tour_register_id
LEFT JOIN fts_plan_month pm2
ON pm2.plan_month_id = rg2.plan_month_id
LEFT JOIN common_code cc9
ON cc9.code_type   = 'FTS_REGISTER_STATUS'
AND cc9.code_value = NVL(rg2.register_status, DECODE(rg2.register_id, NULL, NULL, 'P'))
  /*===store tour EMP===*/
LEFT JOIN fts_register rg3
ON rg3.register_id = c.store_tour_emp_register_id
LEFT JOIN fts_plan_month pm3
ON pm3.plan_month_id = rg3.plan_month_id
LEFT JOIN common_code cc10
ON cc10.code_type   = 'FTS_REGISTER_STATUS'
AND cc10.code_value = NVL(rg3.register_status, DECODE(rg3.register_id, NULL, NULL, 'P'))
UNION ALL

/*===FRANCHISEE===*/
SELECT 'ผ่านขั้นตอนสมัคร' AS process_id,
  NULL                    AS fr_type,
  NULL                    AS fr_type_name,
  NULL                    AS fr_subtype_name,
  NULL                    AS step_id,
  NULL                    AS step_name,
  fz.cust_id,
  fz.id_card,
  fz.title_code,
  cc1.code_name AS title_name,
  fz.first_name,
  fz.last_name,
  fz.email,
  fz.mobile,
  NULL AS main_cust_id,
  NULL AS main_cust_id_card,
  NULL AS main_cust_title_code,
  NULL AS main_cust_title_name,
  NULL AS main_cust_first_name,
  NULL AS main_cust_last_name,
  NULL AS main_relation_type,
  NULL AS main_relation,
  NULL AS create_date,
  NULL AS related_type,
  ft.position_name,
  fz.franchisee_id,
  NULL AS present_register_id,
  NULL AS present_course_id,
  NULL AS present_course_code,
  NULL AS present_date,
  NULL AS present_status_code,
  NULL AS present_status,
  NULL AS store_tour_register_id,
  NULL AS store_tour_course_id,
  NULL AS store_tour_course_code,
  NULL AS store_tour_date,
  NULL AS store_tour_status_code,
  NULL AS store_tour_status,
  NULL AS store_tour_emp_register_id,
  NULL AS store_tour_emp_course_id,
  NULL AS store_tour_emp_course_code,
  NULL AS store_tour_emp_date,
  NULL AS store_tour_emp_status_code,
  NULL AS store_tour_emp_status
FROM franchisee fz
LEFT JOIN
  (SELECT ft2.franchisee_id,
    listagg( cc.code_name, ', ' ) within GROUP (
  ORDER BY ft2.franchisee_type_code) AS position_name
  FROM franchisee_type ft2
  INNER JOIN common_code cc
  ON cc.code_type          = '00012'
  AND cc.active_flag       = 'Y'
  AND cc.code_value        = ft2.franchisee_type_code
  WHERE ft2.franchisee_id IN
    (SELECT fz2.franchisee_id
    FROM franchisee fz2
    WHERE NVL(fz2.status, '-') != 'D'
    )
  GROUP BY ft2.franchisee_id
  ) ft ON ft.franchisee_id = fz.franchisee_id
LEFT JOIN common_code cc1
ON cc1.code_type            = '00001'
AND cc1.active_flag         = 'Y'
AND cc1.code_value          = fz.title_code
WHERE NVL (fz.status, '-') != 'D'
AND fz.id_card             IS NOT NULL
AND EXISTS
  (SELECT s.owner_id1
  FROM fr_store s
  WHERE NVL(s.status, '-') != 'D'
  AND s.cancel_type         = '00' --ยังดำเนินการอยู่ (ไม่รวม "กรุณาเลือก")
  AND fz.franchisee_id     IN (s.owner_id1, s.owner_id2, s.owner_id3, s.cur_owner_id)
  );

-- ---------- VIEW: V_FMS_CUSTOMER_RELATE_LIST ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_FMS_CUSTOMER_RELATE_LIST" ("PROCESS_ID", "CUST_ID", "OWNNAME", "OWNLASTNAME", "OWNCITIZENID", "RELATED_CUST_ID", "RELATION", "STEP_ID", "SEQ_NO", "RELATED_TYPE", "COOPNAME", "COOPLASTNAME", "COOPCITIZENID", "COOPMOBILE", "COOPCAPITAL", "COOPAMPHUR", "COOPDISTRICT", "COOPPROVINCE", "COOPADDRESS_NO", "COOPMOO", "COOPSOI", "COOPSTREET", "COOPZIP", "COOPOCCUPATION", "COOPOFFICE", "SEX", "EMAIL", "TEL", "AGE") AS 
  SELECT FRP.PROCESS_ID,
            FRP.CUST_ID,
            C.FIRST_NAME OWNName,
            C.LAST_NAME OWNLastname,
            C.ID_CARD OWNCitizenID,
            CR.RELATED_CUST_ID,
            CR.RELATION,
            CR.STEP_ID,
            CR.RELATED_CUST_ID,
            CR.RELATED_TYPE,
            CCR.FIRST_NAME COOPName,
            CCR.LAST_NAME COOPLastname,
            CCR.ID_CARD COOPCitizenID,
            CCR.MOBILE,
            CCR.CAPITAL,
            A.DISTRICT_NAME,
            D.SUB_DISTRICT_NAME,
            P.PROVINCE_NAME,
            CCR.ADDRESS_NO,
            CCR.MOO,
            CCR.SOI,
            CCR.STREET,
            CCR.ZIP,
            CM.CODE_NAME,
            CCR.OFFICE,
            CASE CCR.SEX
               WHEN 'M' THEN 'ชาย'
               WHEN 'F' THEN 'หญิง'
               ELSE ''
            END
               AS SEX,
            CCR.EMAIL,
            CCR.TEL,
            CCR.AGE
       FROM FR_PROCESS FRP
            JOIN CUSTOMER C
               ON FRP.CUST_ID = C.CUST_ID AND NVL (FRP.UPDATE_FUNC, 'A') <> 'D'
            JOIN CUSTOMER_RELATED CR
               ON CR.PROCESS_ID = FRP.PROCESS_ID AND CR.CUST_ID = FRP.CUST_ID
            LEFT JOIN CUSTOMER CCR
               ON CR.RELATED_CUST_ID = CCR.CUST_ID
            LEFT JOIN MAS_DISTRICT A
               ON CCR.CITY = A.DISTRICT_ID
            LEFT JOIN MAS_SUB_DISTRICT D
               ON CCR.DISTRICT = D.SUB_DISTRICT_ID
            LEFT JOIN MAS_PROVINCE P
               ON CCR.PROVINCE = P.PROVINCE_ID
            LEFT JOIN COMMON_CODE CM
               ON     CCR.OCCP_CODE = CM.CODE_VALUE
                  AND CM.CODE_TYPE = '00002'
                  AND CM.ACTIVE_FLAG = 'Y'
   ORDER BY PROCESS_ID;

-- ---------- VIEW: V_FMS_CUSTOMER_RELATION ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_FMS_CUSTOMER_RELATION" ("PROCESS_ID", "CUST_ID", "OWNNAME", "OWNLASTNAME", "OWNCITIZENID", "RELATED_CUST_ID", "RELATION", "SEQ_NO", "RELATION_TYPE", "MEMBER_TYPE", "COOPNAME", "COOPLASTNAME", "COOPCITIZENID", "COOPMOBILE", "COOPCAPITAL", "COOPBIRTHDAY", "IS_ALIVE", "SEX", "EMAIL", "TEL", "AGE") AS 
  SELECT CMR.PROCESS_ID,
          CMR.CUST_ID,
          CCR.FIRST_NAME OWNName,
          CCR.LAST_NAME OWNLastname,
          CCR.ID_CARD,
          CMR.RELATED_CUST_ID,
          CMR.RELATION,
          CMR.SEQ,
          CMR.RELATION_TYPE,
          CMR.MEMBER_TYPE,
          CCR.FIRST_NAME COOPName,
          CCR.LAST_NAME COOPLastname,
          CCR.ID_CARD COOPCitizenID,
          CCR.MOBILE,
          CCR.CAPITAL,
          CCR.BIRTHDAY,
          CCR.IS_ALIVE,
          CASE CCR.SEX
             WHEN 'M' THEN 'ชาย'
             WHEN 'F' THEN 'หญิง'
             ELSE 'หญิง'
          END
             AS SEX,
          CCR.EMAIL,
          CCR.TEL,
          CCR.AGE
     FROM    CUSTOMER_MEMBER_RELATION CMR
          LEFT JOIN
             CUSTOMER CCR
          ON CMR.RELATED_CUST_ID = CCR.CUST_ID;

-- ---------- VIEW: V_FMS_CUSTOMER_SEMINAR_LIST ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_FMS_CUSTOMER_SEMINAR_LIST" ("RELATED_CUST_ID", "CUSTOMERID", "CUSTOMERNAME") AS 
  SELECT CR.RELATED_CUST_ID, CR.CUST_ID, C.FIRST_NAME
     FROM    CUSTOMER_RELATED CR
          JOIN
             CUSTOMER C
          ON CR.RELATED_CUST_ID = C.CUST_ID
    WHERE CR.RELATED_TYPE = 1 AND CR.RELATED_CUST_ID = C.CUST_ID
   UNION
   SELECT C2.CUST_ID, C2.CUST_ID, C2.FIRST_NAME
     FROM CUSTOMER C2 JOIN CUSTOMER_RELATED CR2 ON CR2.CUST_ID = C2.CUST_ID
    WHERE CR2.RELATED_TYPE = 1 AND CR2.CUST_ID = C2.CUST_ID;

-- ---------- VIEW: V_FMS_CUSTOMER_STORE_TOUR_LIST ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_FMS_CUSTOMER_STORE_TOUR_LIST" ("RELATED_CUST_ID", "CUST_ID", "FIRST_NAME", "FULLNAME") AS 
  SELECT DISTINCT CR.RELATED_CUST_ID,
    CR.CUST_ID,
    C.FIRST_NAME,
    CASE CR.RELATED_TYPE
      WHEN '1'
      THEN C.FIRST_NAME
        ||' (ผู้เข้าร่วมฟังสัมนา)'
      WHEN '2'
      THEN C.FIRST_NAME
        ||' (ผู้ร่วมลงทุน)'
      WHEN '3'
      THEN C.FIRST_NAME
        ||' (ผู้ช่วย)'
      ELSE ''
    END
  FROM CUSTOMER C
  LEFT JOIN CUSTOMER_RELATED CR
  ON CR.RELATED_CUST_ID = C.CUST_ID
  --    WHERE CR.RELATED_CUST_ID = C.CUST_ID
  UNION
  SELECT C2.CUST_ID,
    C2.CUST_ID,
    C2.FIRST_NAME,
    C2.FIRST_NAME
  FROM CUSTOMER C2
  LEFT JOIN FR_PROCESS FR
  ON FR.CUST_ID = C2.CUST_ID;

-- ---------- VIEW: V_FMS_CUST_MANAGE_STORE_LIST ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_FMS_CUST_MANAGE_STORE_LIST" ("SEQ", "RELATED_CUST_ID", "CUST_ID", "MEMBER_TYPE", "FIRST_NAME", "LAST_NAME", "ID_CARD", "ADDRESS_NO", "SOI", "STREET", "MOO", "DISTRICT", "PROVINCE", "CITY", "ZIP", "RELATION_TYPE", "RELATION", "OFFICE", "MOBILE", "TEL", "OFFICE_TEL", "EMAIL", "RELATED_TYPE") AS 
  SELECT CMR.SEQ,
          CMR.RELATED_CUST_ID,
          CMR.CUST_ID,
          CMR.MEMBER_TYPE,
          CR.FIRST_NAME,
          CR.LAST_NAME,
          CR.ID_CARD,
          CR.ADDRESS_NO,
          CR.SOI,
          CR.STREET,
          CR.MOO,
          CR.DISTRICT,
          CR.PROVINCE,
          CR.CITY,
          CR.ZIP,
          CM.CODE_NAME,
          CMR.RELATION,
          CR.OFFICE,
          CR.MOBILE,
          CR.TEL,
          CR.OFFICE_TEL,
          CR.EMAIL,
          RL.RELATED_TYPE
     FROM CUSTOMER_MEMBER_RELATION CMR
          LEFT JOIN CUSTOMER CR
             ON CMR.RELATED_CUST_ID = CR.CUST_ID
          LEFT JOIN CUSTOMER_RELATED RL
             ON RL.RELATED_CUST_ID = CMR.RELATED_CUST_ID
          JOIN COMMON_CODE CM
             ON CMR.RELATION_TYPE = CM.CODE_VALUE AND CM.CODE_TYPE = '00028';

-- ---------- VIEW: V_FMS_CUST_ON_PROCESS150820 ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_FMS_CUST_ON_PROCESS150820" ("PROCESS_ID", "ID_CARD", "FIRST_NAME", "LAST_NAME", "MAIN_CUST_ID_CARD", "MAIN_CUST_FIRST_NAME", "MAIN_CUST_LAST_NAME", "MAIN_RELATION_TYPE", "MAIN_RELATION", "FR_PROCESS_DATE", "RELATED_TYPE") AS 
  SELECT TO_CHAR (p.process_id) AS process_id,
          c1.id_card,
          c1.first_name,
          c1.last_name,                                              -- คนหลัก
          NULL AS main_cust_id_card,
          NULL AS main_cust_first_name,
          NULL AS main_cust_last_name,
          NULL AS main_relation_type,
          NULL AS main_relation,
          NULL AS create_date,
          NULL AS related_type
     FROM    customer c1
          INNER JOIN
             (SELECT *
                FROM (SELECT p.process_id, p.cust_id, pt.status
                        FROM    fr_process p
                             LEFT JOIN
                                fr_process_trn pt
                             ON pt.process_id = p.process_id) p
               WHERE NVL (p.status, '1') = 1                   --1=รอดำเนินการ
                                            ) p
          ON p.cust_id = c1.cust_id AND c1.id_card IS NOT NULL
   UNION ALL
   SELECT TO_CHAR (p.process_id),
          c2.id_card,                     --ผู้ติดตาม/เจ้าของเงินลงทุน/ผู้ช่วย
          c2.first_name,
          c2.last_name,
          c1.id_card,
          c1.first_name,
          c1.last_name,
          cc.code_name,
          cr.relation,                                                --คนหลัก
          p.create_date,
          DECODE (cr.related_type, '2', cr.related_type, NULL)
     FROM customer c1
          INNER JOIN customer_related cr
             ON cr.cust_id = c1.cust_id
          INNER JOIN customer c2
             ON c2.cust_id = cr.related_cust_id
          INNER JOIN (SELECT p.process_id, p.cust_id, p.create_date
                        FROM    fr_process p
                             LEFT JOIN
                                fr_process_trn pt
                             ON pt.process_id = p.process_id
                                AND NVL (pt.status, '1') = 1   --1=รอดำเนินการ
                                                            ) p
             ON p.cust_id = c1.cust_id AND c2.id_card IS NOT NULL
          LEFT JOIN (SELECT code_name, code_value
                       FROM common_code
                      WHERE code_type = '00028' AND active_flag = 'Y') cc
             ON cc.code_value = cr.relation_type
   UNION ALL
   SELECT '-',
          fz.id_card,                                             --Franchisee
          fz.first_name,
          fz.last_name,
          NULL,
          NULL,
          NULL,
          NULL,
          NULL,
          NULL,
          NULL
     FROM franchisee fz
    WHERE fz.id_card IS NOT NULL AND NVL (fz.status, '-') != 'D';

-- ---------- VIEW: V_FMS_CUST_ON_PROCESS160614 ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_FMS_CUST_ON_PROCESS160614" ("PROCESS_ID", "ID_CARD", "FIRST_NAME", "LAST_NAME", "MAIN_CUST_ID_CARD", "MAIN_CUST_FIRST_NAME", "MAIN_CUST_LAST_NAME", "MAIN_RELATION_TYPE", "MAIN_RELATION", "FR_PROCESS_DATE", "RELATED_TYPE") AS 
  SELECT TO_CHAR (p.process_id) AS process_id,
          c1.id_card,
          c1.first_name,
          c1.last_name,                                              -- คนหลัก
          NULL AS main_cust_id_card,
          NULL AS main_cust_first_name,
          NULL AS main_cust_last_name,
          NULL AS main_relation_type,
          NULL AS main_relation,
          NULL AS create_date,
          NULL AS related_type
     FROM    customer c1
          INNER JOIN
             (SELECT p.process_id,
                     NVL (pt.cust_id, p.cust_id) AS cust_id,
                     pt.status
                FROM    fr_process p
                     LEFT JOIN
                        fr_process_trn pt
                     ON pt.process_id = p.process_id
                        AND NVL (pt.status, '1') IN (1, 2) --1=รอดำเนินการ; 2=ดำเนินการ
               WHERE EXISTS
                        (SELECT pt3.*
                           FROM (  SELECT pt2.process_id,
                                          MAX (pt2.step_id) AS step_id
                                     FROM fr_process_trn pt2
                                 GROUP BY pt2.process_id) pt3
                          WHERE pt3.process_id = pt.process_id
                                AND pt3.step_id = pt.step_id)) p
          ON p.cust_id = c1.cust_id AND c1.id_card IS NOT NULL
   UNION ALL
   SELECT TO_CHAR (p.process_id),
          c2.id_card,                     --ผู้ติดตาม/เจ้าของเงินลงทุน/ผู้ช่วย
          c2.first_name,
          c2.last_name,
          c1.id_card,
          c1.first_name,
          c1.last_name,
          cc.code_name,
          cr.relation,                                                --คนหลัก
          p.create_date,
          DECODE (cr.related_type, '2', cr.related_type, NULL)
     FROM customer c1
          INNER JOIN customer_related cr
             ON cr.cust_id = c1.cust_id
          INNER JOIN customer c2
             ON c2.cust_id = cr.related_cust_id
          INNER JOIN (SELECT p.process_id, p.cust_id, p.create_date
                        FROM    fr_process p
                             LEFT JOIN
                                fr_process_trn pt
                             ON pt.process_id = p.process_id
                                AND NVL (pt.status, '1') = 1   --1=รอดำเนินการ
                                                            ) p
             ON p.cust_id = c1.cust_id AND c2.id_card IS NOT NULL
          LEFT JOIN (SELECT code_name, code_value
                       FROM common_code
                      WHERE code_type = '00028' AND active_flag = 'Y') cc
             ON cc.code_value = cr.relation_type
   UNION ALL
   SELECT '-',
          fz.id_card,                                             --Franchisee
          fz.first_name,
          fz.last_name,
          NULL,
          NULL,
          NULL,
          NULL,
          NULL,
          NULL,
          NULL
     FROM franchisee fz
    WHERE fz.id_card IS NOT NULL AND NVL (fz.status, '-') != 'D';

-- ---------- VIEW: V_FMS_EMAIL_STORE_TOUR ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_FMS_EMAIL_STORE_TOUR" ("FRANCHISEE_ID", "REGISTER_ID", "ID_CARD", "EMPLOYEE_NAME", "CUST_ID", "FIRST_NAME", "REGISTER_STATUS", "COURSE_CODE", "START_DATE", "END_DATE", "CLASS_NO", "PARAM_NAME", "LOCATION_DETAIL", "RELATED_TYPE_ID", "RELATED_TYPE", "PASS", "EMAIL") AS 
  SELECT R.PROCESS_ID,
          R.REGISTER_ID,
          R.ID_CARD,
          '- ' || R.EMPLOYEE_NAME || '   (ผู้ลงทุน)</br>',
          R.CUST_ID,
          R.FIRST_NAME,
          R.REGISTER_STATUS,
          R.COURSE_CODE,
          P.START_DATE,
          P.END_DATE,
          P.CLASS_NO,
          PA.PARAM_NAME,
          P.LOCATION_DETAIL,
          RL.RELATED_TYPE AS related_type_id,
          CASE RL.RELATED_TYPE
             WHEN '1' THEN 'ผู้ติดตาม'
             WHEN '2' THEN 'ผู้ร่วมลงทุน'
             WHEN '3' THEN 'ผู้ช่วย'
             ELSE 'คนหลัก'
          END
             AS RELATED_TYPE,
          ap.pass,
          c.EMAIL
     FROM FTS_REGISTER R
          INNER JOIN FTS_PLAN_MONTH P
             ON R.PLAN_MONTH_ID = P.PLAN_MONTH_ID
          INNER JOIN (SELECT p1.param_name,
                             p1.param_value AS course_code,
                             p2.param_value AS target_type
                        FROM    mas_param p1
                             INNER JOIN
                                mas_param p2
                             ON p2.ref_name = p1.param_name
                       WHERE p1.ref_name = 'FMS_REGISTER_COURSE') PA
             ON p.COURSE_CODE = PA.course_code
                AND p.target_type = pa.target_type
          LEFT JOIN CUSTOMER_RELATED RL
             ON RL.RELATED_CUST_ID = R.CUST_ID AND RL.RELATED_TYPE = 2
          INNER JOIN fts_course fc
             ON fc.course_code = p.course_code
                AND fc.target_type = p.target_type
          --          INNER JOIN mas_param mp
          --             ON mp.param_value = fc.course_code
          --                AND mp.ref_name = 'FMS_REGISTER_COURSE'         
          INNER JOIN customer c on c.cust_id = r.cust_id
          LEFT JOIN fmp_train_ap ap
             ON     ap.train_code = fc.train_code
                AND ap.train_group = fc.train_group
                AND ap.train_period = p.train_period
                AND ap.id_card = r.id_card;

-- ---------- VIEW: V_FMS_EMAIL_STORE_TOUR_TYPE3 ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_FMS_EMAIL_STORE_TOUR_TYPE3" ("FRANCHISEE_ID", "REGISTER_ID", "ID_CARD", "EMPLOYEE_NAME", "CUST_ID", "FIRST_NAME", "REGISTER_STATUS", "COURSE_CODE", "START_DATE", "END_DATE", "CLASS_NO", "PARAM_NAME", "LOCATION_DETAIL", "RELATED_TYPE_ID", "RELATED_TYPE", "PASS", "EMAIL") AS 
  SELECT R.PROCESS_ID,
          R.REGISTER_ID,
          R.ID_CARD,
             '- '
          || R.EMPLOYEE_NAME
          || '   (ผู้เข้าร่วมบริหาร)<br/>',
          R.CUST_ID,
          R.FIRST_NAME,
          R.REGISTER_STATUS,
          R.COURSE_CODE,
          P.START_DATE,
          P.END_DATE,
          P.CLASS_NO,
          PA.PARAM_NAME,
          P.LOCATION_DETAIL,
          RL.RELATED_TYPE AS related_type_id,
          CASE RL.RELATED_TYPE
             WHEN '1' THEN 'ผู้ติดตาม'
             WHEN '2' THEN 'ผู้ร่วมลงทุน'
             WHEN '3' THEN 'ผู้ช่วย'
             ELSE 'คนหลัก'
          END
             AS RELATED_TYPE,
          ap.pass,
          c.EMAIL
     FROM FTS_REGISTER R
          INNER JOIN FTS_PLAN_MONTH P
             ON R.PLAN_MONTH_ID = P.PLAN_MONTH_ID
          INNER JOIN (SELECT p1.param_name,
                             p1.param_value AS course_code,
                             p2.param_value AS target_type
                        FROM    mas_param p1
                             INNER JOIN
                                mas_param p2
                             ON p2.ref_name = p1.param_name
                       WHERE p1.ref_name = 'FMS_REGISTER_COURSE') PA
             ON p.COURSE_CODE = PA.course_code
                AND p.target_type = pa.target_type
          LEFT JOIN CUSTOMER_RELATED RL
             ON RL.RELATED_CUST_ID = R.CUST_ID AND RL.RELATED_TYPE = 3
          INNER JOIN fts_course fc
             ON fc.course_code = p.course_code
                AND fc.target_type = p.target_type
          --          INNER JOIN mas_param mp
          --             ON mp.param_value = fc.course_code
          --                AND mp.ref_name = 'FMS_REGISTER_COURSE'
          LEFT JOIN fmp_train_ap ap
             ON     ap.train_code = fc.train_code
                AND ap.train_group = fc.train_group
                AND ap.train_period = p.train_period
                AND ap.id_card = r.id_card     
          INNER JOIN customer c on c.cust_id = r.cust_id;

-- ---------- VIEW: V_FMS_FRACHISE_REPORT ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_FMS_FRACHISE_REPORT" ("COURSE_TYPE", "COURSE_NAME", "START_DATE", "END_DATE", "LOCATION_DETAIL", "PROCESS_ID", "FULLNAME", "FIRSTNAME", "IDCARD", "EMPLOYEE_ID", "MOBILE", "EMAIL", "AREA", "RELATED_TYPE") AS 
  SELECT DISTINCT
            p.PARAM_NAME,
            fc.COURSE_NAME,
            PM.START_DATE,
            PM.END_DATE,
            PM.LOCATION_DETAIL,
            FR.PROCESS_ID,
            RE.EMPLOYEE_NAME,
            C.FIRST_NAME,
            RE.ID_CARD,
            RE.EMPLOYEE_ID,
            C.MOBILE,
            C.EMAIL,
            P.PROVINCE_NAME,
            CASE RL.RELATED_TYPE
               WHEN '1' THEN 'ผู้ติดตาม'
               WHEN '2' THEN 'ผู้ร่วมลงทุน'
               WHEN '3' THEN 'ผู้ช่วย'
               ELSE 'คนหลัก'
            END
       FROM FR_PROCESS FR
            JOIN FTS_REGISTER RE
               ON RE.PROCESS_ID = FR.PROCESS_ID
            LEFT JOIN CUSTOMER C
               ON C.CUST_ID = RE.CUST_ID
            LEFT JOIN FTS_REGISTER R
               ON R.CUST_ID = C.CUST_ID
            LEFT JOIN CUSTOMER_RELATED RL
               ON RL.RELATED_CUST_ID = RE.CUST_ID
            LEFT JOIN CUSTOMER_INTEREST_AREA A
               ON A.CUST_ID = RE.CUST_ID
            LEFT JOIN MAS_PROVINCE P
               ON P.PROVINCE_ID = A.PROVINCE
            JOIN FTS_COURSE fc
               ON fc.COURSE_CODE = RE.COURSE_CODE
            JOIN MAS_PARAM p
               ON p.param_value = fc.COURSE_CODE
            LEFT JOIN COMMON_CODE cc_ct
               ON cc_ct.CODE_TYPE = 'FTS_COURSE_TYPE'
                  AND cc_ct.CODE_VALUE = fc.COURSE_TYPE
            LEFT JOIN FTS_PLAN_MONTH PM
               ON PM.PLAN_MONTH_ID = R.PLAN_MONTH_ID
   ORDER BY FR.PROCESS_ID;

-- ---------- VIEW: V_FMS_FRANCHISE_CUSTOMER_LIST ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_FMS_FRANCHISE_CUSTOMER_LIST" ("PROCESS_ID", "FIRST_NAME", "LAST_NAME", "TITLE_NAME", "ID_CARD", "CUST_ID") AS 
  SELECT FR.PROCESS_ID,
            C.FIRST_NAME,
            C.LAST_NAME,
            CM.CODE_NAME,
            C.ID_CARD,
            C.CUST_ID
       FROM FR_PROCESS FR
            JOIN CUSTOMER C
               ON C.CUST_ID = FR.CUST_ID
            LEFT JOIN COMMON_CODE CM
               ON     C.TITLE_CODE = CM.CODE_VALUE
                  AND CM.CODE_TYPE = '00001'
                  AND CM.ACTIVE_FLAG = 'Y'
   ORDER BY FR.CREATE_DATE;

-- ---------- VIEW: V_FMS_INTERESTAREA_LIST ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_FMS_INTERESTAREA_LIST" ("CUST_ID", "SEQNO", "PROCESSID", "PROVINCE", "AMPHUR", "DISTRICT") AS 
  SELECT CA.CUST_ID,
          CA.SEQ,
          CA.PROCESS_ID,
          P.PROVINCE_NAME,
          A.DISTRICT_NAME,
          D.SUB_DISTRICT_NAME
     FROM CUSTOMER_INTEREST_AREA CA
          LEFT JOIN MAS_PROVINCE P
             ON CA.PROVINCE = P.PROVINCE_ID
          LEFT JOIN MAS_DISTRICT A
             ON CA.DISTRICT = A.DISTRICT_ID AND CA.PROVINCE = A.PROVINCE_ID
          LEFT JOIN MAS_SUB_DISTRICT D
             ON CA.SUB_DISTRICT = D.SUB_DISTRICT_ID;

-- ---------- VIEW: V_FMS_REGISTERCOURSE_DETAIL ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_FMS_REGISTERCOURSE_DETAIL" ("COURSE_NAME", "COURSE_CODE", "EMPLOYEE_NAME", "ID_CARD", "REGISTER_ID", "COURSE_TYPE", "REGISTER_STATUS", "COURSE_TYPE_NAME", "FRANCHISEE_ID") AS 
  SELECT fc.COURSE_NAME,
          fm.COURSE_CODE,
          fm.EMPLOYEE_NAME,
          fm.ID_CARD,
          fm.REGISTER_ID,
          fc.COURSE_TYPE,
          fm.REGISTER_STATUS,
          p.PARAM_NAME,
          fm.FRANCHISEE_ID
     FROM FTS_REGISTER fm
          LEFT JOIN FTS_COURSE fc
             ON fc.COURSE_CODE = fm.COURSE_CODE
          JOIN (
                SELECT p1.param_name,
                     p1.param_value AS course_code,
                     p2.param_value AS target_type
                FROM    mas_param p1
                     INNER JOIN
                        mas_param p2
                     ON p2.ref_name = p1.param_name
               WHERE p1.ref_name = 'FMS_REGISTER_COURSE'          
          ) p ON p.course_code = fc.course_code
            and p.target_type = fc.target_type
          LEFT JOIN COMMON_CODE cc_ct
             ON cc_ct.CODE_TYPE = 'FTS_COURSE_TYPE'
                AND cc_ct.CODE_VALUE = fc.COURSE_TYPE
                
/*SELECT
    fc.COURSE_NAME,fm.COURSE_CODE,fm.EMPLOYEE_NAME,fm.ID_CARD,fm.REGISTER_ID,fc.COURSE_TYPE,fm.REGISTER_STATUS,p.PARAM_NAME,fm.FRANCHISEE_ID
    FROM FTS_REGISTER  fm
    LEFT JOIN FTS_COURSE fc ON fc.COURSE_CODE = fm.COURSE_CODE
    JOIN MAS_PARAM p on p.param_value = fc.course_code









    LEFT JOIN COMMON_CODE cc_ct
             ON cc_ct.CODE_TYPE = 'FTS_COURSE_TYPE'
                AND cc_ct.CODE_VALUE = fc.COURSE_TYPE*/;

-- ---------- VIEW: V_FMS_REGISTER_COURSE ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_FMS_REGISTER_COURSE" ("PLAN_MONTH_ID", "RELATED_PLAN_MONTH_ID", "LOCATION_ID", "LOCATION_NAME", "TRAIN_CODE", "COURSE_ID", "COURSE_TYPE", "COURSE_TYPE_NAME", "TARGET_TYPE", "TARGET_TYPE_NAME", "YEAR", "MONTH", "COURSE_CODE", "COURSE_NAME", "TRAIN_GROUP", "TOTAL_CLASS", "CLASS_NO", "CLASS_STATUS", "CLASS_STATUS_NAME", "OPEN_STATUS", "OPEN_STATUS_NAME", "REGISTER_END_DATE", "DURATION_AMOUNT", "START_DATE", "END_DATE", "TOTAL_SEAT", "RESERVE_SEAT", "TRAIN_PERIOD", "REGISTER_AMOUNT", "TRAINER_NAME", "RESPONSE_NAME", "LOCATION_DETAIL", "DESCRIPTION", "CLASS_FILE_ID", "CLASS_FILE_NAME", "COURSE_FILE_ID", "COURSE_FILE_NAME", "FMS_COURSE_TYPE") AS 
  with plan_month_register_id as (
    select pm.plan_month_id
    from    fts_plan_month pm
        inner join (
             select p1.param_value as course_code, p4.param_value as target_type, to_number(p2.param_value) as register_end_date, to_number(p3.param_value) as register_end_time
             from mas_param p1
                 inner join mas_param p2 on p1.ref_name = 'FMS_REGISTER_COURSE'
                     and instr(p1.param_name, p2.ref_name) > 0 
                     and p2.param_name like '%REGISTER_END_DATE'
                 inner join mas_param p3 on p1.ref_name = 'FMS_REGISTER_COURSE'
                     and instr(p1.param_name, p3.ref_name) > 0 
                     and p3.param_name like '%REGISTER_END_TIME'                                    
                 inner join mas_param p4 on p4.ref_name = p1.param_name
                     and p4.param_name like '%TARGET'
        ) pr on pr.course_code = pm.course_code
            and pr.target_type = pm.target_type                                
    where nvl (pm.class_status, '-') = 'A'
          and nvl (pm.open_status, '-') = 'A'
          and nvl (pm.delete_flag, 'N') != 'Y'
          and (pm.register_end_date >= trunc (sysdate)
               or (pm.register_end_date is null
                       and sysdate < (trunc(pm.start_date - pr.register_end_date) + pr.register_end_time)
                )
          )  
)

select
     fm.plan_month_id,
     fm2.plan_month_id as related_plan_month_id,
     fm.location_id,
     cc_lc.code_name location_name,
     fc.train_code,
     fc.course_id,
     fc.course_type,
     cc_ct.code_name course_type_name,
     fc.target_type,
     cc_tt.code_name target_type_name,
     fm.year,
     fm.month,
     fm.course_code,
     fc.course_name,
     fc.train_group,
     fm.total_class,
     fm.class_no,
     nvl (fm.class_status, 'N') as class_status,
     cc_cs.code_name as class_status_name,
     nvl (fm.open_status, 'N') as open_status,
     cc_rs.code_name as open_status_name,
     fm.register_end_date,
     fm.duration_amount,
     fm.start_date,
     fm.end_date,
     rg.amount as total_seat,
     rg.reserve_amount as reserve_seat,
     fm.train_period,
     rg.register_amount,
     fm.trainer_name,
     fm.response_name,
     fm.location_detail,
     fm.description,
     fd.file_id class_file_id,
     fd.file_name class_file_name,
     fdc.file_id course_file_id,
     fdc.file_name course_file_name,
     p.param_name as fms_course_type
from fts_plan_month fm
    inner join fts_course fc on fc.course_code = fm.course_code
        and fc.target_type = fm.target_type
     inner join (
           select p1.param_name, p1.param_value as course_code, p2.param_value as target_type
           from mas_param p1
               inner join mas_param p2 on p1.ref_name = 'FMS_REGISTER_COURSE'
                   and p2.ref_name = p1.param_name
                   and p2.param_name like '%TARGET'               
     ) p on p.course_code = fc.course_code
        and p.target_type = fc.target_type
        and p.param_name != 'FMS_STORE_TOUR_NON_EMP'    --'FMS_STORE_TOUR_NON_EMP' will come with 'fms_register_course'                  
     left join fts_plan_month fm2 on fm2.class_status = 'A'
        and fm2.open_status = 'A'
        and fm2.year = fm.year
        and fm2.month = fm.month
        and fm2.class_no = fm.class_no
        and exists(
            select p1.param_value, p2.param_value
            from mas_param p1
                inner join mas_param p2 on p1.ref_name = 'FMS_REGISTER_COURSE'
                    and p1.param_name = 'FMS_STORE_TOUR_NON_EMP'
                    and p2.ref_name = p1.param_name
                    and p2.param_name like '%TARGET'   
            where p1.param_value = fm2.course_code
                and p2.param_value = fm2.target_type        
        )
        and p.param_name = 'FMS_STORE_TOUR_EMP'                                  
    inner join (
        select reg.*,
            dense_rank () over (partition by reg.course_code order by reg.year, reg.month, reg.class_no) as rnum
        from (
            select pm.plan_month_id, pm.course_code, --nvl(r.register_amount, 0) as register_amount,
                pm.year, pm.month, pm.class_no,            
                pm.non_emp_plan_month_id, pm.non_emp_course_code, r.register_amount as reg_amt,
                nvl(sum(r.register_amount) over(partition by nvl(pm.non_emp_plan_month_id, pm.plan_month_id)), 0) as register_amount,
                pm.amount, pm.reserve_amount
            from (
                    select fm.plan_month_id, fm.course_code, fm2.plan_month_id as non_emp_plan_month_id, fm2.course_code as non_emp_course_code, fm.target_type, fm.class_no,  fm.year, fm.month, 
                        fm.amount as amt, fm.reserve_amount as reserve_amt,
                        sum(fm.amount) over(partition by nvl(fm2.plan_month_id, fm.plan_month_id)) as amount,
                        sum(fm.reserve_amount) over(partition by nvl(fm2.plan_month_id, fm.plan_month_id)) as reserve_amount
                    from    fts_plan_month fm
                        left join fts_plan_month fm2 on fm2.class_status = 'A'
                           and fm2.open_status = 'A'
                           and fm2.year = fm.year
                           and fm2.month = fm.month
                           and fm2.class_no = fm.class_no
                           and exists(
                               select p1.param_value, p2.param_value
                               from mas_param p1
                                   inner join mas_param p2 on p1.ref_name = 'FMS_REGISTER_COURSE'
                                       and p1.param_name = 'FMS_STORE_TOUR_NON_EMP'
                                       and p2.ref_name = p1.param_name
                                       and p2.param_name like '%TARGET'   
                               where p1.param_value = fm2.course_code
                                   and p2.param_value = fm2.target_type        
                           )
                           and exists (     --'related_plan_month_id' ('plan_month_id' of 'FMS_STORE_TOUR_NON_EMP') have results only with 'FMS_STORE_TOUR_EMP' 
                               select p1.param_value, p2.param_value
                               from mas_param p1
                                   inner join mas_param p2 on  p1.ref_name = 'FMS_REGISTER_COURSE'
                                       and p1.param_name = 'FMS_STORE_TOUR_EMP'
                                       and p2.ref_name = p1.param_name
                                       and p2.param_name like '%TARGET'
                               where p1.param_value = fm.course_code
                                   and p2.param_value = fm.target_type                                                
                           )                    
                    where fm.plan_month_id in (  
                        select * from plan_month_register_id  
                    )
                ) pm
                left join (
                    select r.plan_month_id, count (r.plan_month_id) as register_amount
                    from fts_register r
                    where r.plan_month_id in (
                            select * from plan_month_register_id
                        )
                        and r.register_status in ('W', 'Y')    --[Kiet] 26/01/2017 'Y' -> 'W', 'Y'
                     group by r.plan_month_id      
                ) r on r.plan_month_id = pm.plan_month_id    
        ) reg
        where nvl(reg.register_amount, -1) < reg.amount    --[Kiet] 26/01/2017 (pm.amount + nvl (pm.reserve_amount, 0))
    ) rg on rg.plan_month_id = fm.plan_month_id and rg.rnum = 1
        left join fts_document fd on fm.plan_month_id = fd.transaction_id
            and nvl (fd.delete_flag, 'N') != 'Y'
            and fd.table_name = 'FTS_PLAN_MONTH'
        left join fts_document fdc on fc.course_id = fdc.transaction_id
            and nvl (fdc.delete_flag, 'N') != 'Y'
            and fdc.table_name = 'FTS_COURSE'
        left join common_code cc_lc on cc_lc.code_type = 'FTS_LOCATION'
            and cc_lc.code_value = fm.location_id
        left join common_code cc_ct on cc_ct.code_type = 'FTS_COURSE_TYPE'
            and cc_ct.code_value = fc.course_type
        left join common_code cc_tt on cc_tt.code_type = 'FTS_TARGET_TYPE'
            and cc_tt.code_value = fc.target_type
        left join common_code cc_cs on cc_cs.code_type = 'FTS_CLASS_STATUS'
              and cc_cs.code_value = nvl (fm.class_status, 'N')
        left join common_code cc_rs on cc_rs.code_type = 'FTS_OPEN_STATUS'
              and cc_rs.code_value = nvl (fm.open_status, 'N')
    where nvl (fc.course_status, '-') = 'A'
        and nvl (fc.delete_flag, 'N') != 'Y' ;

-- ---------- VIEW: V_FMS_REGISTER_ON_PROCESS ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_FMS_REGISTER_ON_PROCESS" ("PLAN_MONTH_ID", "REGISTER_ID", "PROCESS_ID", "CUST_ID") AS 
  with plan_month_register_id as (
    select pm.plan_month_id
    from    fts_plan_month pm
        inner join (
             select p1.param_value as course_code, p4.param_value as target_type, to_number(p2.param_value) as register_end_date, to_number(p3.param_value) as register_end_time
             from mas_param p1
                 inner join mas_param p2 on p1.ref_name = 'FMS_REGISTER_COURSE'
                     and instr(p1.param_name, p2.ref_name) > 0 
                     and p2.param_name like '%REGISTER_END_DATE'
                 inner join mas_param p3 on p1.ref_name = 'FMS_REGISTER_COURSE'
                     and instr(p1.param_name, p3.ref_name) > 0 
                     and p3.param_name like '%REGISTER_END_TIME'                                    
                 inner join mas_param p4 on p4.ref_name = p1.param_name
                     and p4.param_name like '%TARGET'
        ) pr on pr.course_code = pm.course_code
            and pr.target_type = pm.target_type                                
    where nvl (pm.class_status, '-') = 'A'
          and nvl (pm.delete_flag, 'N') != 'Y'
          and (pm.register_end_date >= trunc (sysdate)
               or (pm.register_end_date is null
                       and sysdate < (trunc(pm.start_date - pr.register_end_date) + pr.register_end_time)
                )
          )  
)
 
select r.plan_month_id, r.register_id, r.process_id, r.cust_id
from fts_register r
where exists (
    select pm.plan_month_id
    from plan_month_register_id pm
    where pm.plan_month_id = r.plan_month_id
)
    and nvl(r.register_status,'-') != 'N' ;

-- ---------- VIEW: V_FMS_SEMINAR_DETAIL_LIST ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_FMS_SEMINAR_DETAIL_LIST" ("FRANCHISEE_ID", "REGISTER_ID", "ID_CARD", "EMPLOYEE_NAME", "CUST_ID", "FIRST_NAME", "REGISTER_STATUS", "COURSE_CODE", "START_DATE", "END_DATE", "CLASS_NO", "PARAM_NAME", "LOCATION_DETAIL", "PASS") AS 
  SELECT 
          R.PROCESS_ID,
          R.REGISTER_ID,
          R.ID_CARD,
          R.EMPLOYEE_NAME,
          R.CUST_ID,
          R.FIRST_NAME,
          R.REGISTER_STATUS,
          R.COURSE_CODE,
          P.START_DATE,
          P.END_DATE,
          P.CLASS_NO,
          PA.PARAM_NAME,
          P.LOCATION_DETAIL,
          ap.pass
     FROM FTS_REGISTER R
          INNER JOIN FTS_PLAN_MONTH P
             ON R.PLAN_MONTH_ID = P.PLAN_MONTH_ID
          INNER JOIN (
               select p1.param_name, p1.param_value as course_code, p2.param_value as target_type
               from mas_param p1
                   inner join mas_param p2 on p1.ref_name = 'FMS_REGISTER_COURSE'
                       and p2.ref_name = p1.param_name
                       and p2.param_name like 'FMS%TARGET'                  
          ) PA ON p.COURSE_CODE = PA.course_code
                and p.target_type = pa.target_type
          INNER JOIN fts_course fc
             ON fc.course_code = p.course_code
                AND fc.target_type = p.target_type
--          INNER JOIN mas_param mp
--             ON mp.param_value = fc.course_code
--                AND mp.ref_name = 'FMS_REGISTER_COURSE'
          LEFT JOIN fmp_train_ap ap
             ON     ap.train_code = fc.train_code
                AND ap.train_group = fc.train_group
                AND ap.train_period = p.train_period
                AND ap.id_card = r.id_card
--    WHERE     NVL (fc.course_status, '-') = 'A'
--          AND NVL (fc.delete_flag, 'N') != 'Y'
--          AND r.register_status = 'Y'

