-- ---------- VIEW: V_FMS_TRAIN_RESULT ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_FMS_TRAIN_RESULT" ("REGISTER_ID", "COURSE_CODE", "PLAN_MONTH_ID", "ID_CARD", "REGISTER_STATUS", "REGISTER_END_DATE", "POINT", "PASS") AS 
  select a.register_id, a.course_code, a.plan_month_id, a.id_card, a.register_status,
    nvl(a.register_end_date, (trunc(a.start_date - p2.param_value) + p3.param_value)) as register_end_date,
    a.point, a.pass
from (

    select
        rg.register_id, rg.course_code, rg.plan_month_id, rg.id_card, rg.register_status,
        fm.register_end_date, fm.start_date,
        /*
            DATA_COMMENT {0=absent}
        */
        case when ap.pass = 'F' then     
            decode(ap.data_comment, '0', 0, null)      
        end as point,
        ap.pass

    from fts_register rg
        inner join fts_plan_month fm on fm.plan_month_id = rg.plan_month_id
        inner join fts_course fc on fc.course_code = fm.course_code
            and fc.target_type = fm.target_type
         left join (
               select p1.param_name, p1.param_value as course_code, p2.param_value as target_type
               from mas_param p1
                   inner join mas_param p2 on p1.ref_name = 'FMS_REGISTER_COURSE'
                       and p2.ref_name = p1.param_name
                       and p2.param_name like '%TARGET'               
         ) p on p.course_code = fc.course_code
            and p.target_type = fc.target_type
            and p.param_name != 'FMS_STORE_TOUR_NON_EMP'    --'FMS_STORE_TOUR_NON_EMP' will come with 'fms_register_course'    
                          
         left join fts_plan_month fm2 on fm2.year = fm.year
            and fm2.month = fm.month
            and fm2.class_no = fm.class_no
            and exists(
                select p1.param_value, p2.param_value
                from mas_param p1
                    inner join mas_param p2 on p1.ref_name = 'FMS_REGISTER_COURSE'
                        and p1.param_name = 'FMS_STORE_TOUR_NON_EMP'
                        and p2.ref_name = p1.param_name
                        and p2.param_name like '%TARGET'   
                where p1.param_value = fm2.course_code
                    and p2.param_value = fm2.target_type        
            )
            and p.param_name = 'FMS_STORE_TOUR_EMP'
        left join fts_course fc2 on fc2.course_code = fm2.course_code
            and fc2.target_type = fm2.target_type

        left join fmp_train_ap ap on (
                (     
                    ap.train_code in (fc.train_code, fc2.train_code)
                    and ap.train_group in (fc.train_group, fc2.train_group)
                    and ap.train_period in (fm.train_period, fm2.train_period)
                )
                or ap.register_id = rg.register_id                    
            )
            and ap.id_card = rg.id_card         
    where nvl (fc.delete_flag, 'N') != 'Y'
        and trunc(nvl(rg.update_date, rg.create_date)) > trunc(add_months(sysdate, -6))    
) a
    inner join mas_param p1 on p1.param_value = a.course_code
        and p1.ref_name = 'FMS_REGISTER_COURSE'
    left join mas_param p2 on p1.ref_name = 'FMS_REGISTER_COURSE'
        and p1.param_name is not null
        and instr(p1.param_name, p2.ref_name) > 0 
        and p2.param_name like '%REGISTER_END_DATE'
    left join mas_param p3 on p1.ref_name = 'FMS_REGISTER_COURSE'
        and p1.param_name is not null
        and instr(p1.param_name, p3.ref_name) > 0 
        and p3.param_name like '%REGISTER_END_TIME'                                    
    left join mas_param p4 on p4.ref_name = p1.param_name
        and p4.param_name like '%TARGET'   

