-- ---------- VIEW: V_FRANCHISEE ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_FRANCHISEE" ("FRANCHISEE_ID", "TITLE_NAME", "FIRST_NAME", "LAST_NAME", "CDATE", "SEX", "STATUS", "RELIGION", "EDU", "OCCP_NAME", "OCCP2_NAME", "OCCP3_NAME", "OCCP_OTHER", "FRANCHISE_SOURCE", "MEDIA_SOURCE", "MEDIA_SOURCE_CATEGORY", "MEDIA_SOURCE_OTHER", "ID_CARD", "BIRTHDAY", "MOBILE", "TEL", "EMAIL", "ADDRESS_NO", "TOWER", "FLOOR", "MOO", "SOI", "STREET", "SUB_DISTRICT_NAME", "DISTRICT_NAME", "PROVINCE_NAME", "ZIP", "FRANCHISEE_STATUS", "STATUS_RELIGION", "STATUS_MARKET", "STATUS_CONSENT") AS 
  SELECT f.franchisee_id, c1.code_name AS title_name, f.first_name, f.last_name, TO_CHAR(f.birthday, 'DD/MM/YYYY') AS cdate, sex, c2.code_name AS status, c10.code_name AS religion, c3.code_name AS edu, c4.code_name AS occp_name, c7.code_name AS occp2_name, c8.code_name AS occp3_name, f.occp_other, c5.code_name AS franchise_source, c6.code_name AS media_source, c9.code_name AS media_source_category, f.media_source_other, f.id_card, TO_CHAR(f.birthday, 'DD/MM/') || (TO_CHAR(f.birthday, 'YYYY') + 543) AS birthday, f.mobile, f.tel, f.email, f.address_no, f.tower, f.FLOOR, f.moo, f.soi, f.street, dd.sub_district_name, a.district_name, p.province_name, f.zip, decode(s.owner_id1, null, 'inactive', 'active') FRANCHISEE_STATUS, CASE WHEN sbp_consent.status_religion = 'Y' then 'ยินยอม' WHEN sbp_consent.status_religion = 'N' then 'ไม่ยินยอม' ELSE NULL END AS status_religion, CASE WHEN sbp_consent.status_market = 'Y' then 'ยินยอม' WHEN sbp_consent.status_market = 'N' then 'ไม่ยินยอม' ELSE NULL END AS status_market, CASE WHEN sbp_consent.status_consent = 'Y' then 'ยินยอม' WHEN sbp_consent.status_consent = 'N' then 'ไม่ยินยอม' ELSE NULL END AS status_consent FROM franchisee f LEFT JOIN (select distinct owner_id1 from fr_store where nvl(cancel_type, '-') = '00' and nvl(status, '-') != 'D' and cancel_date is null ) s on f.franchisee_id = s.owner_id1 LEFT JOIN (SELECT code_value, code_name FROM common_code WHERE code_type = '00001') c1 ON c1.code_value = f.title_code LEFT JOIN (SELECT code_value, code_name FROM common_code WHERE code_type = '00004') c2 ON c2.code_value = f.status_code LEFT JOIN (SELECT code_value, code_name FROM common_code WHERE code_type = '00003') c3 ON f.edu_code = c3.code_value LEFT JOIN (SELECT code_value, code_name, code_mapping FROM common_code WHERE code_type = '00002' AND active_flag = 'Y') c4 ON f.occp_code = c4.code_value LEFT JOIN (SELECT code_value, code_name, code_mapping FROM common_code WHERE code_type = '00002' AND active_flag = 'Y') c7 ON c7.code_value = f.occp_code2 LEFT JOIN (SELECT code_value, code_name, code_type FROM common_code WHERE code_type IN ('00002_4', '00068') AND active_flag = 'Y') c8 ON c8.code_value = f.occp_code3 AND (c8.code_type = c4.code_mapping OR c8.code_type = c7.code_mapping) LEFT JOIN (SELECT code_value, code_name FROM common_code WHERE code_type = '00033') c5 ON f.franchisee_source = c5.code_value LEFT JOIN (SELECT code_value, code_name FROM common_code WHERE code_type = '00054' AND code_mapping IS NULL AND active_flag = 'Y') c9 ON c9.code_value = f.media_source_category LEFT JOIN (SELECT code_value, code_name FROM common_code WHERE code_type = '00054' AND code_mapping IS NOT NULL AND active_flag = 'Y') c6 ON c6.code_value = f.media_source LEFT JOIN mas_province p ON p.province_id = f.province LEFT JOIN mas_district a ON a.district_id = f.city AND a.province_id = f.province LEFT JOIN mas_sub_district dd ON dd.sub_district_id = f.district AND dd.district_id = f.city AND dd.province_id = f.province LEFT JOIN common_code c10 on c10.code_type = '00013' and c10.active_flag = 'Y' and c10.code_value = f.religion LEFT JOIN sbp_consent on sbp_consent.key_id = f.id_card and sbp_consent.type_table = 'FRANCHISEE' ORDER BY f.franchisee_id;

-- ---------- VIEW: V_FR_STORE ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_FR_STORE" ("ORDER_ID", "PARENT_ORDER_ID", "STORE_ID", "STORE_NAME", "REGION", "AREA_NAME", "TEL", "START_DATE", "CHR_START_DATE", "TRANSFER_DATE", "CHR_TRANSFER_DATE", "OPEN_DATE", "CHR_OPEN_DATE", "JURISTIC_ID", "JURISTIC_NAME", "FZ_ID_CARD", "OWNER_ID1", "TITLE1", "FIRST_NAME1", "LAST_NAME1", "FR_TYPE_NAME", "STORE_TYPE_NAME", "OP_TYPE_NAME", "OPERATE_TYPE_NAME", "DETAIL_TYPE_NAME", "OWNER_TYPE_NAME", "CANCEL_TYPE", "CANCEL_TYPE_NAME", "CANCEL_REASON_NAME", "CANCEL_REASON_OTHER", "CANCEL_DATE", "CHR_CANCEL_DATE", "TO_STORE_ID", "CANCEL_DETAIL", "CONTRACT_START_DATE", "CONTRACT_END_DATE", "EDIT_END_DATE", "SIGN_DATE", "REMAIN_AGE", "SEQ_NO", "JURISTIC_NO") AS 
  SELECT  
    FS.ORDER_ID, FS.PARENT_ORDER_ID, FS.STORE_ID, S.BRANCH_NAME as STORE_NAME, S.REGION,
    S.AREA_NAME, S.TEL, 
--    TO_CHAR(FS.START_DATE,'DD/MM/YYYY') as START_DATE, 
--    TO_CHAR(FS.TRANSFER_DATE,'DD/MM/YYYY') as CDATE, 
--    TO_CHAR(S.OPEN_DATE,'DD/MM/YYYY') as OPEN_DATE,
    fs.start_date,
    TO_CHAR(FS.START_DATE,'DD/MM/YYYY') as CHR_START_DATE, 
    fs.transfer_date,
    TO_CHAR(FS.TRANSFER_DATE,'DD/MM/YYYY') as CHR_TRANSFER_DATE, 
    fs.open_date,
    TO_CHAR(S.OPEN_DATE,'DD/MM/YYYY') as CHR_OPEN_DATE,
    FS.JURISTIC_ID, J.JURISTIC_NAME,     
    f.id_card as fz_id_card,
    FS.OWNER_ID1, C1.CODE_NAME TITLE1, F.FIRST_NAME FIRST_NAME1, F.LAST_NAME LAST_NAME1,
--    C2.CODE_NAME FR_TYPE,
--    C3.CODE_NAME STORE_TYPE,
--    C4.CODE_NAME OP_TYPE,
--    C5.CODE_NAME OPERATE_TYPE, 
--    C6.CODE_NAME  DETAIL_TYPE,
--    C7.CODE_NAME OWNER_TYPE,
    C2.CODE_NAME as FR_TYPE_NAME,
    C3.CODE_NAME as STORE_TYPE_NAME,
    C4.CODE_NAME as OP_TYPE_NAME,
    C5.CODE_NAME as OPERATE_TYPE_NAME, 
    C6.CODE_NAME as DETAIL_TYPE_NAME,
    C7.CODE_NAME as OWNER_TYPE_NAME,
--    C8.CODE_NAME CANCEL_TYPE, C9.CODE_NAME CANCEL_REASON,  FS.CANCEL_REASON_OTHER CANCEL_REASON_OTHER, 
    fs.cancel_type,
    C8.CODE_NAME as CANCEL_TYPE_NAME, C9.CODE_NAME as CANCEL_REASON_NAME,  FS.CANCEL_REASON_OTHER as CANCEL_REASON_OTHER, 
    fs.cancel_date,
    TO_CHAR(FS.CANCEL_DATE,'DD/MM/YYYY') as CHR_CANCEL_DATE,
    FS.TO_STORE_ID,
    FS.CANCEL_DETAIL,
    TO_CHAR(FSCH.START_DATE,'DD/MM/YYYY') as CONTRACT_START_DATE,
    TO_CHAR(FSCH.END_DATE,'DD/MM/YYYY') AS CONTRACT_END_DATE,
    TO_CHAR(FSCH.EDIT_END_DATE ,'DD/MM/YYYY') AS EDIT_END_DATE,
    TO_CHAR(FS.SIGN_DATE,'DD/MM/YYYY') as SIGN_DATE,
    ROUND((TRUNC(FSCH.END_DATE) - TRUNC(sysdate))/365.25) as REMAIN_AGE,
	  CASE
	    WHEN FSCH.SEQ_NO IS NULL THEN NULL
	    ELSE FSCH.SEQ_NO - 1
	  END AS SEQ_NO,
	J.JURISTIC_NO
FROM FR_STORE FS
    LEFT JOIN SEVENSHOP S ON FS.STORE_ID = S.BRANCH_ID
    LEFT JOIN FRANCHISEE F ON FS.OWNER_ID1 = F.FRANCHISEE_ID
        and nvl(F.status, '-') != 'D'
    LEFT JOIN JURISTIC J ON FS.JURISTIC_ID = J.JURISTIC_ID
    LEFT JOIN (select code_value, code_name from common_code where  code_type = '00001') C1 ON F.TITLE_CODE = C1.CODE_VALUE
    LEFT JOIN (select code_value, code_name from common_code where  code_type = '00019') C2 ON FS.FR_TYPE = C2.CODE_VALUE
    LEFT JOIN (select code_value, code_name from common_code where  code_type = '00031') C3 ON FS.STORE_TYPE = C3.CODE_VALUE
    LEFT JOIN (select code_value, code_name from common_code where  code_type = '00035') C4 ON FS.OP_TYPE = C4.CODE_VALUE
    LEFT JOIN (select code_value, code_name from common_code where  code_type = 'SP') C5 ON FS.OPERATE_TYPE = C5.CODE_VALUE
    LEFT JOIN (select code_value, code_name from common_code where  code_type in ('SP_01',  'SP_02', 'SP_03')) C6 ON FS.DETAIL_TYPE = C6.CODE_VALUE
    LEFT JOIN (select code_value, code_name from common_code where  code_type = '00036') C7 ON FS.OWNER_TYPE = C7.CODE_VALUE
    LEFT JOIN (select code_value, code_name from common_code where  code_type = '00053') C8 ON FS.CANCEL_REASON  = C8.CODE_VALUE
    LEFT JOIN (select code_value, code_name from common_code where  code_type = '00034') C9 ON FS.CANCEL_TYPE= C9.CODE_VALUE
    LEFT JOIN FR_STORE_CONTRACT_HISTORY FSCH 
    	ON FS.STORE_ID  = FSCH.STORE_ID  
    	AND FS.CONTRACT_START_DATE = FSCH.START_DATE 
    	AND FS.CONTRACT_END_DATE  = FSCH.END_DATE 
    	AND FS.SIGN_DATE  = FSCH.SIGNED_DATE  
WHERE (nvl(FS.STATUS,'-') != 'D') 
order by FS.ORDER_ID,FS.STORE_ID;

-- ---------- VIEW: V_FR_STORE_ACTIVE ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_FR_STORE_ACTIVE" ("ORDER_ID", "PARENT_ORDER_ID", "STORE_ID", "STORE_NAME", "REGION", "START_DATE", "TRANSFER_DATE", "OPEN_DATE", "SIGN_DATE", "CONTRACT_START_DATE", "CONTRACT_END_DATE", "JURISTIC_ID", "JURISTIC_GROUP_ID", "TOWER", "FLOOR", "ADDRESS_NO", "MOO", "SOI", "STREET", "DISTRICT", "CITY", "PROVINCE", "ZIP", "MOBILE", "TEL", "FAX", "OWNER_ID1", "OWNER_ID2", "OWNER_ID3", "CUR_OWNER_ID", "CUR_OWNER_TITLE_CODE", "CUR_OWNER_FIRST_NAME", "CUR_OWNER_LAST_NAME", "CUR_OWNER_TEL", "CUR_OWNER_RELATION", "FR_TYPE", "FR_SUBTYPE", "STORE_TYPE", "OP_TYPE", "OPERATE_TYPE", "DETAIL_TYPE", "OWNER_TYPE", "STORE_SOURCE", "TO_STORE_ID", "ASSESS1", "ASSESS2", "ASSESS3", "ASSESS3_GRADE", "STATUS", "CREATE_DATE", "CREATE_USER", "UPDATE_DATE", "UPDATE_USER", "AUTHORIZATION_PERSON1", "AUTHORIZATION_PERSON2", "AUTHORIZATION_PERSON3", "REF_PROCESS_ID", "AMPHUR_ID", "PROVINCE_ID", "EXTEND_ROUND", "CANCEL_DATE", "FR_TYPE_NAME", "FR_SUBTYPE_NAME") AS 
  SELECT ORDER_ID, PARENT_ORDER_ID, LPAD(STORE_ID, 5, '0') STORE_ID, STORE_NAME, REGION, START_DATE, TRANSFER_DATE, 
       OPEN_DATE, SIGN_DATE, CONTRACT_START_DATE, CONTRACT_END_DATE, JURISTIC_ID,
       JURISTIC_GROUP_ID, TOWER, FLOOR, ADDRESS_NO, MOO, SOI, STREET, DISTRICT, CITY,
       PROVINCE, ZIP, MOBILE, TEL, FAX, OWNER_ID1, OWNER_ID2, OWNER_ID3, CUR_OWNER_ID,
       CUR_OWNER_TITLE_CODE, CUR_OWNER_FIRST_NAME, CUR_OWNER_LAST_NAME, CUR_OWNER_TEL,
       CUR_OWNER_RELATION, FR_TYPE, FR_SUBTYPE, STORE_TYPE, OP_TYPE, OPERATE_TYPE,
       DETAIL_TYPE, OWNER_TYPE, STORE_SOURCE, TO_STORE_ID, ASSESS1, ASSESS2, ASSESS3,
       ASSESS3_GRADE, STATUS, CREATE_DATE, CREATE_USER, UPDATE_DATE, UPDATE_USER, 
       AUTHORIZATION_PERSON1, AUTHORIZATION_PERSON2, AUTHORIZATION_PERSON3, REF_PROCESS_ID,
       AMPHUR_ID, PROVINCE_ID, EXTEND_ROUND, CANCEL_DATE, cc_fr_type.CODE_NAME FR_TYPE_NAME,




















































       cc_fr_subtype.CODE_NAME FR_SUBTYPE_NAME
FROM FR_STORE fr
LEFT JOIN (SELECT CODE_TYPE, CODE_NAME, CODE_VALUE FROM COMMON_CODE) cc_fr_type 
    ON ( cc_fr_type.CODE_TYPE = '00019' AND fr.FR_TYPE = cc_fr_type.CODE_VALUE )
LEFT JOIN (SELECT CODE_TYPE, CODE_NAME, CODE_VALUE FROM COMMON_CODE WHERE CODE_TYPE IN
     (SELECT CODE_VALUE FROM COMMON_CODE WHERE CODE_TYPE = '00019')
) cc_fr_subtype ON (cc_fr_subtype.CODE_TYPE = fr.FR_TYPE AND cc_fr_subtype.CODE_VALUE = fr.FR_SUBTYPE)
WHERE TO_NUMBER(STORE_ID) != 0





  AND START_DATE IS NOT NULL
  AND NVL(STATUS, '-') != 'D'
  AND (CANCEL_DATE IS NULL OR TO_CHAR(CANCEL_DATE, 'YYYYMM') = TO_CHAR(ADD_MONTHS(SYSDATE, -1), 'YYYYMM'));

-- ---------- VIEW: V_FR_STORE_ALL ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_FR_STORE_ALL" ("ORDER_ID", "PARENT_ORDER_ID", "STORE_ID", "STORE_NAME", "REGION", "START_DATE", "TRANSFER_DATE", "OPEN_DATE", "SIGN_DATE", "CONTRACT_START_DATE", "CONTRACT_END_DATE", "JURISTIC_ID", "JURISTIC_GROUP_ID", "TOWER", "FLOOR", "ADDRESS_NO", "MOO", "SOI", "STREET", "DISTRICT", "CITY", "PROVINCE", "ZIP", "MOBILE", "TEL", "FAX", "OWNER_ID1", "OWNER_ID2", "OWNER_ID3", "CUR_OWNER_ID", "CUR_OWNER_TITLE_CODE", "CUR_OWNER_FIRST_NAME", "CUR_OWNER_LAST_NAME", "CUR_OWNER_TEL", "CUR_OWNER_RELATION", "FR_TYPE", "FR_SUBTYPE", "STORE_TYPE", "OP_TYPE", "OPERATE_TYPE", "DETAIL_TYPE", "OWNER_TYPE", "STORE_SOURCE", "TO_STORE_ID", "ASSESS1", "ASSESS2", "ASSESS3", "ASSESS3_GRADE", "STATUS", "CREATE_DATE", "CREATE_USER", "UPDATE_DATE", "UPDATE_USER", "AUTHORIZATION_PERSON1", "AUTHORIZATION_PERSON2", "AUTHORIZATION_PERSON3", "REF_PROCESS_ID", "AMPHUR_ID", "PROVINCE_ID", "EXTEND_ROUND", "CANCEL_DATE", "FR_TYPE_NAME", "FR_SUBTYPE_NAME") AS 
  SELECT ORDER_ID,
          PARENT_ORDER_ID,
          LPAD (STORE_ID, 5, '0') STORE_ID,
          STORE_NAME,
          REGION,
          START_DATE,
          TRANSFER_DATE,
          OPEN_DATE,
          SIGN_DATE,
          CONTRACT_START_DATE,
          CONTRACT_END_DATE,
          JURISTIC_ID,
          JURISTIC_GROUP_ID,
          TOWER,
          FLOOR,
          ADDRESS_NO,
          MOO,
          SOI,
          STREET,
          DISTRICT,
          CITY,
          PROVINCE,
          ZIP,
          MOBILE,
          TEL,
          FAX,
          OWNER_ID1,
          OWNER_ID2,
          OWNER_ID3,
          CUR_OWNER_ID,
          CUR_OWNER_TITLE_CODE,
          CUR_OWNER_FIRST_NAME,
          CUR_OWNER_LAST_NAME,
          CUR_OWNER_TEL,
          CUR_OWNER_RELATION,
          FR_TYPE,
          FR_SUBTYPE,
          STORE_TYPE,
          OP_TYPE,
          OPERATE_TYPE,
          DETAIL_TYPE,
          OWNER_TYPE,
          STORE_SOURCE,
          TO_STORE_ID,
          ASSESS1,
          ASSESS2,
          ASSESS3,
          ASSESS3_GRADE,
          STATUS,
          CREATE_DATE,
          CREATE_USER,
          UPDATE_DATE,
          UPDATE_USER,
          AUTHORIZATION_PERSON1,
          AUTHORIZATION_PERSON2,
          AUTHORIZATION_PERSON3,
          REF_PROCESS_ID,
          AMPHUR_ID,
          PROVINCE_ID,
          EXTEND_ROUND,
          CANCEL_DATE,
          cc_fr_type.CODE_NAME FR_TYPE_NAME,
          cc_fr_subtype.CODE_NAME FR_SUBTYPE_NAME
     FROM FR_STORE fr
          LEFT JOIN (SELECT CODE_TYPE, CODE_NAME, CODE_VALUE FROM COMMON_CODE) cc_fr_type
             ON (cc_fr_type.CODE_TYPE = '00019'
                 AND fr.FR_TYPE = cc_fr_type.CODE_VALUE)
          LEFT JOIN (SELECT CODE_TYPE, CODE_NAME, CODE_VALUE
                       FROM COMMON_CODE
                      WHERE CODE_TYPE IN (SELECT CODE_VALUE
                                            FROM COMMON_CODE
                                           WHERE CODE_TYPE = '00019')) cc_fr_subtype
             ON (cc_fr_subtype.CODE_TYPE = fr.FR_TYPE
                 AND cc_fr_subtype.CODE_VALUE = fr.FR_SUBTYPE)
    WHERE     TO_NUMBER (STORE_ID) != 0
          AND START_DATE IS NOT NULL
          AND NVL (STATUS, '-') != 'D';

-- ---------- VIEW: V_FS_SEVENSHOP ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_FS_SEVENSHOP" ("STORE_ID", "STORE_NAME", "BRANCH_TYPE", "AREA_ID", "AREA_NAME", "REGION", "TEL", "ADDRESS_NO", "SOI", "STREET", "DISTRICT_ID", "DISTRICT", "AMPHUR_ID", "AMPHUR", "PROVINCE_ID", "PROVINCE", "ZIP", "OPEN_DATE", "CLOSE_DATE", "MGR_NAME", "FC_NAME", "FC_TEL", "FC_PAGE", "MN_NAME", "MN_TEL", "MN_PAGE", "DV_NAME", "DV_TEL", "DV_PAGE", "DV_EMAIL", "AVP_NAME", "AVP_TEL", "AVP_PAGE", "AVP_EMAIL", "GM_NAME", "GM_TEL", "GM_PAGE", "GM_EMAIL", "STATUS", "MN_EMAIL", "FC_EMAIL", "ZONE_CD") AS 
  SELECT LPAD (BRANCH_ID, 5, '0') STORE_ID,
          BRANCH_NAME STORE_NAME,
          BRANCH_TYPE,
          AREA_ID,
          AREA_NAME,
          REGION,
          TEL,
          ADDRESS_NO,
          SOI,
          STREET,
          DISTRICT_ID,
