-- ---------- VIEW: V_FTS_PLAN_MONTH_EXPORT ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_FTS_PLAN_MONTH_EXPORT" ("PLAN_MONTH_ID", "LOCATION_ID", "LOCATION_NAME", "CLASS_NO", "YEAR", "MONTH", "DURATION_AMOUNT", "COURSE_CODE", "COURSE_NAME", "COURSE_TYPE", "COURSE_TYPE_NAME", "TARGET_TYPE", "TARGET_TYPE_NAME", "CLASS_STATUS", "CLASS_STATUS_NAME", "OPEN_STATUS", "OPEN_STATUS_NAME", "TOTAL_CLASS", "START_DATE", "END_DATE", "AMOUNT", "RESERVE_AMOUNT", "TRAINER_NAME", "RESPONSE_NAME", "LOCATION_DETAIL", "REGISTER_END_DATE", "TRAINING_DATE") AS 
  SELECT "PLAN_MONTH_ID",
            "LOCATION_ID",
            "LOCATION_NAME",
            "CLASS_NO",
            "YEAR",
            "MONTH",
            "DURATION_AMOUNT",
            "COURSE_CODE",
            "COURSE_NAME",
            "COURSE_TYPE",
            "COURSE_TYPE_NAME",
            "TARGET_TYPE",
            "TARGET_TYPE_NAME",
            "CLASS_STATUS",
            "CLASS_STATUS_NAME",
            "OPEN_STATUS",
            "OPEN_STATUS_NAME",
            "TOTAL_CLASS",
            "START_DATE",
            "END_DATE",
            "AMOUNT",
            "RESERVE_AMOUNT",
            "TRAINER_NAME",
            "RESPONSE_NAME",
            "LOCATION_DETAIL",
            "REGISTER_END_DATE",
            "TRAINING_DATE"
       FROM (SELECT fm.PLAN_MONTH_ID,
                    fm.LOCATION_ID,
                    cc_lc.CODE_NAME LOCATION_NAME,
                    fm.CLASS_NO,
                    fm.YEAR,
                    fm.MONTH,
                    DURATION_AMOUNT,
                    fm.COURSE_CODE,
                    fc.COURSE_NAME,
                    fc.COURSE_TYPE,
                    cc_ct.CODE_NAME COURSE_TYPE_NAME,
                    fc.TARGET_TYPE,
                    cc_tt.CODE_NAME TARGET_TYPE_NAME,
                    NVL (fm.CLASS_STATUS, 'N') CLASS_STATUS,
                    cc_cs.CODE_NAME CLASS_STATUS_NAME,
                    NVL (fm.OPEN_STATUS, 'N') OPEN_STATUS,
                    cc_rs.CODE_NAME OPEN_STATUS_NAME,
                    fm.TOTAL_CLASS,
                    fm.START_DATE,
                    fm.END_DATE,
                    fm.AMOUNT,
                    fm.RESERVE_AMOUNT,
                    fm.TRAINER_NAME,
                    fm.RESPONSE_NAME,
                    fm.LOCATION_DETAIL,
                    fm.REGISTER_END_DATE,
                    CASE
                       WHEN fm.START_DATE = fm.END_DATE
                       THEN
                          TO_CHAR (fm.START_DATE,
                                   'DD/MM/YYYY',
                                   'NLS_CALENDAR=''THAI BUDDHA')
                       ELSE
                          TO_CHAR (fm.START_DATE,
                                   'DD/MM/YYYY',
                                   'NLS_CALENDAR=''THAI BUDDHA')
                          || '-'
                          || TO_CHAR (fm.END_DATE,
                                      'DD/MM/YYYY',
                                      'NLS_CALENDAR=''THAI BUDDHA')
                    END
                       TRAINING_DATE
               FROM FTS_PLAN_MONTH fm
                    LEFT JOIN FTS_COURSE fc
                       ON fc.COURSE_CODE = fm.COURSE_CODE
                          AND fc.TARGET_TYPE = fm.TARGET_TYPE
                    LEFT JOIN COMMON_CODE cc_lc
                       ON cc_lc.CODE_TYPE = 'FTS_LOCATION'
                          AND cc_lc.CODE_VALUE = fm.LOCATION_ID
                    LEFT JOIN COMMON_CODE cc_ct
                       ON cc_ct.CODE_TYPE = 'FTS_COURSE_TYPE'
                          AND cc_ct.CODE_VALUE = fc.COURSE_TYPE
                    LEFT JOIN COMMON_CODE cc_tt
                       ON cc_tt.CODE_TYPE = 'FTS_TARGET_TYPE'
                          AND cc_tt.CODE_VALUE = fc.TARGET_TYPE
                    LEFT JOIN COMMON_CODE cc_cs
                       ON cc_cs.CODE_TYPE = 'FTS_CLASS_STATUS'
                          AND cc_cs.CODE_VALUE = NVL (fm.CLASS_STATUS, 'N')
                    LEFT JOIN COMMON_CODE cc_rs
                       ON cc_rs.CODE_TYPE = 'FTS_OPEN_STATUS'
                          AND cc_rs.CODE_VALUE = NVL (fm.OPEN_STATUS, 'N')
              WHERE 1 = 1 AND NVL (fm.DELETE_FLAG, 'N') != 'Y')
   ORDER BY LOCATION_NAME,
            COURSE_NAME,
            START_DATE,
            CLASS_NO;

-- ---------- VIEW: V_FTS_PLAN_YEAR_EXPORT ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_FTS_PLAN_YEAR_EXPORT" ("PLAN_ID", "LOCATION_ID", "LOCATION_NAME", "COURSE_TYPE", "COURSE_TYPE_NAME", "TARGET_TYPE", "TARGET_TYPE_NAME", "YEAR", "COURSE_CODE", "COURSE_NAME", "DURATION_DATE", "TOTAL_CLASS", "SEAT_CPALL", "SEAT_NON_CPALL", "SEQ_NO", "JAN", "FEB", "MAR", "APR", "MAY", "JUN", "JUL", "AUG", "SEP", "OCT", "NOV", "DEC") AS 
  SELECT "PLAN_ID",
            "LOCATION_ID",
            "LOCATION_NAME",
            "COURSE_TYPE",
            "COURSE_TYPE_NAME",
            "TARGET_TYPE",
            "TARGET_TYPE_NAME",
            "YEAR",
            "COURSE_CODE",
            "COURSE_NAME",
            "DURATION_DATE",
            "TOTAL_CLASS",
            "SEAT_CPALL",
            "SEAT_NON_CPALL",
            "SEQ_NO",
            "JAN",
            "FEB",
            "MAR",
            "APR",
            "MAY",
            "JUN",
            "JUL",
            "AUG",
            "SEP",
            "OCT",
            "NOV",
            "DEC"
       FROM (SELECT fp.PLAN_ID,
                    fp.LOCATION_ID,
                    cc_lc.CODE_NAME LOCATION_NAME,
                    fc.COURSE_TYPE,
                    DECODE (dt.SEQ_NO, 1, cc_ct.CODE_NAME, NULL)
                       COURSE_TYPE_NAME,
                    fc.TARGET_TYPE,
                    DECODE (dt.SEQ_NO, 1, cc_tt.CODE_NAME, NULL)
                       TARGET_TYPE_NAME,
                    fp.YEAR,
                    fp.COURSE_CODE,
                    fc.COURSE_NAME,
                    DECODE (dt.SEQ_NO, 1, fp.DURATION_DATE, NULL) DURATION_DATE,
                    DECODE (dt.SEQ_NO, 1, fp.TOTAL_CLASS, NULL) TOTAL_CLASS,
                    DECODE (dt.SEQ_NO, 1, fp.SEAT_CPALL, NULL) SEAT_CPALL,
                    DECODE (dt.SEQ_NO, 1, fp.SEAT_NON_CPALL, NULL)
                       SEAT_NON_CPALL,
                    dt.SEQ_NO,
                    dt.JAN,
                    dt.FEB,
                    dt.MAR,
                    dt.APR,
                    dt.MAY,
                    dt.JUN,
                    dt.JUL,
                    dt.AUG,
                    dt.SEP,
                    dt.OCT,
                    dt.NOV,
                    dt.DEC
               FROM FTS_PLAN_YEAR fp
                    LEFT JOIN FTS_COURSE fc
                       ON fc.COURSE_CODE = fp.COURSE_CODE
                    LEFT JOIN COMMON_CODE cc_lc
                       ON cc_lc.CODE_TYPE = 'FTS_LOCATION'
                          AND cc_lc.CODE_VALUE = fp.LOCATION_ID
                    LEFT JOIN COMMON_CODE cc_ct
                       ON cc_ct.CODE_TYPE = 'FTS_COURSE_TYPE'
                          AND cc_ct.CODE_VALUE = fc.COURSE_TYPE
                    LEFT JOIN COMMON_CODE cc_tt
                       ON cc_tt.CODE_TYPE = 'FTS_TARGET_TYPE'
                          AND cc_tt.CODE_VALUE = fc.TARGET_TYPE
                    LEFT JOIN (SELECT SEQ.PLAN_ID,
                                      SEQ.SEQ_NO,
                                      JAN,
                                      FEB,
                                      MAR,
                                      APR,
                                      MAY,
                                      JUN,
                                      JUL,
                                      AUG,
                                      SEP,
                                      OCT,
                                      NOV,
                                      DEC
                                 FROM (SELECT DISTINCT PLAN_ID, SEQ_NO
                                         FROM FTS_PLAN_YEAR_DETAIL) SEQ
                                      LEFT JOIN (SELECT SEQ_NO,
                                                        PLAN_ID,
                                                        DESCRIPTION JAN
                                                   FROM FTS_PLAN_YEAR_DETAIL
                                                  WHERE MONTH = '01') JAN
                                         ON SEQ.SEQ_NO = JAN.SEQ_NO
                                            AND SEQ.PLAN_ID = JAN.PLAN_ID
                                      LEFT JOIN (SELECT SEQ_NO,
                                                        PLAN_ID,
                                                        DESCRIPTION FEB
                                                   FROM FTS_PLAN_YEAR_DETAIL
                                                  WHERE MONTH = '02') FEB
                                         ON SEQ.SEQ_NO = FEB.SEQ_NO
                                            AND SEQ.PLAN_ID = FEB.PLAN_ID
                                      LEFT JOIN (SELECT SEQ_NO,
                                                        PLAN_ID,
                                                        DESCRIPTION MAR
                                                   FROM FTS_PLAN_YEAR_DETAIL
                                                  WHERE MONTH = '03') MAR
                                         ON SEQ.SEQ_NO = MAR.SEQ_NO
                                            AND SEQ.PLAN_ID = MAR.PLAN_ID
                                      LEFT JOIN (SELECT SEQ_NO,
                                                        PLAN_ID,
                                                        DESCRIPTION APR
                                                   FROM FTS_PLAN_YEAR_DETAIL
                                                  WHERE MONTH = '04') APR
                                         ON SEQ.SEQ_NO = APR.SEQ_NO
                                            AND SEQ.PLAN_ID = APR.PLAN_ID
                                      LEFT JOIN (SELECT SEQ_NO,
                                                        PLAN_ID,
                                                        DESCRIPTION MAY
                                                   FROM FTS_PLAN_YEAR_DETAIL
                                                  WHERE MONTH = '05') MAY
                                         ON SEQ.SEQ_NO = MAY.SEQ_NO
                                            AND SEQ.PLAN_ID = MAY.PLAN_ID
                                      LEFT JOIN (SELECT SEQ_NO,
                                                        PLAN_ID,
                                                        DESCRIPTION JUN
                                                   FROM FTS_PLAN_YEAR_DETAIL
                                                  WHERE MONTH = '06') JUN
                                         ON SEQ.SEQ_NO = JUN.SEQ_NO
                                            AND SEQ.PLAN_ID = JUN.PLAN_ID
                                      LEFT JOIN (SELECT SEQ_NO,
                                                        PLAN_ID,
                                                        DESCRIPTION JUL
                                                   FROM FTS_PLAN_YEAR_DETAIL
                                                  WHERE MONTH = '07') JUL
                                         ON SEQ.SEQ_NO = JUL.SEQ_NO
                                            AND SEQ.PLAN_ID = JUL.PLAN_ID
                                      LEFT JOIN (SELECT SEQ_NO,
                                                        PLAN_ID,
                                                        DESCRIPTION AUG
                                                   FROM FTS_PLAN_YEAR_DETAIL
                                                  WHERE MONTH = '08') AUG
                                         ON SEQ.SEQ_NO = AUG.SEQ_NO
                                            AND SEQ.PLAN_ID = AUG.PLAN_ID
                                      LEFT JOIN (SELECT SEQ_NO,
                                                        PLAN_ID,
                                                        DESCRIPTION SEP
                                                   FROM FTS_PLAN_YEAR_DETAIL
                                                  WHERE MONTH = '09') SEP
                                         ON SEQ.SEQ_NO = SEP.SEQ_NO
                                            AND SEQ.PLAN_ID = SEP.PLAN_ID
                                      LEFT JOIN (SELECT SEQ_NO,
                                                        PLAN_ID,
                                                        DESCRIPTION OCT
                                                   FROM FTS_PLAN_YEAR_DETAIL
                                                  WHERE MONTH = '10') OCT
                                         ON SEQ.SEQ_NO = OCT.SEQ_NO
                                            AND SEQ.PLAN_ID = OCT.PLAN_ID
                                      LEFT JOIN (SELECT SEQ_NO,
                                                        PLAN_ID,
                                                        DESCRIPTION NOV
                                                   FROM FTS_PLAN_YEAR_DETAIL
                                                  WHERE MONTH = '11') NOV
                                         ON SEQ.SEQ_NO = NOV.SEQ_NO
                                            AND SEQ.PLAN_ID = NOV.PLAN_ID
                                      LEFT JOIN (SELECT SEQ_NO,
                                                        PLAN_ID,
                                                        DESCRIPTION DEC
                                                   FROM FTS_PLAN_YEAR_DETAIL
                                                  WHERE MONTH = '12') DEC
                                         ON SEQ.SEQ_NO = DEC.SEQ_NO
                                            AND SEQ.PLAN_ID = DEC.PLAN_ID) dt
                       ON dt.PLAN_ID = fp.PLAN_ID
              WHERE 1 = 1 AND NVL (fp.DELETE_FLAG, 'N') != 'Y')
   ORDER BY LOCATION_NAME,
            COURSE_NAME,
            COURSE_CODE,
            YEAR,
            SEQ_NO;

-- ---------- VIEW: V_FZ_STORE_ACTIVE ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_FZ_STORE_ACTIVE" ("ORDER_ID", "BRANCH_ID", "BRANCH_NAME", "BRANCH_TYPE", "FR_TYPE", "FR_SUBTYPE", "FR_SUBTYPE_NAME", "AD_STORE_TYPE", "REGION", "START_DATE", "CANCEL_DATE", "FRANCHISEE_ID", "FZ_ID_CARD", "FZ_TITLE_NAME", "FZ_FIRST_NAME", "FZ_LAST_NAME", "FZ_FIRST_NAME_EN", "FZ_LAST_NAME_EN", "FZ_SEX", "FZ_SEX_NAME", "FZ_EMAIL", "FZ_MOBILE", "FZ_REGISTER_DATE", "FC_EMP_ID", "FC_FULLNAME", "FC_FIRST_NAME", "FC_LAST_NAME", "FC_USERNAME", "FC_EMAIL", "MN_EMP_ID", "MN_FULLNAME", "MN_FIRST_NAME", "MN_LAST_NAME", "MN_USERNAME", "MN_EMAIL", "DV_EMP_ID", "DV_FULLNAME", "DV_FIRST_NAME", "DV_LAST_NAME", "DV_USERNAME", "DV_EMAIL", "GM_EMP_ID", "GM_FULLNAME", "GM_FIRST_NAME", "GM_LAST_NAME", "GM_USERNAME", "GM_EMAIL", "VP_EMP_ID", "VP_FULLNAME", "VP_FIRST_NAME", "VP_LAST_NAME", "VP_USERNAME", "VP_EMAIL") AS 
  SELECT fs.order_id,
    ms.branch_id,
    ms.branch_name,
    ms.status_type AS branch_type,
    fs.fr_type,
    fs.fr_subtype,
    cc_st.code_name AS fr_subtype_name,
    cc_ad.code_name AS ad_store_type,
    ms.region,
    fs.start_date,
    fs.cancel_date,
    fz.franchisee_id,
    fz.id_card       AS fz_id_card,
    cc1.code_name    AS fz_title_name,
    fz.first_name    AS fz_first_name,
    fz.last_name     AS fz_last_name,
    fz.first_name_en AS fz_first_name_en,
    fz.last_name_en  AS fz_last_name_en,
    fz.sex           AS fz_sex,
    cc5.code_name    AS fz_sex_name,
    fz.email         AS fz_email,
    fz.mobile        AS fz_mobile,
    rg.create_date   AS fz_register_date,
    --========FC=======
    fc.emp_id     AS fc_emp_id,
    mso1.fullname AS fc_fullname,
    fc.first_name AS fc_first_name,
    fc.last_name  AS fc_last_name,
    fc.user_name  AS fc_username,
    fc.email      AS fc_email,
    --========MN=======
    mn.emp_id     AS mn_emp_id,
    mso2.fullname AS mn_fullname,
    mn.first_name AS mn_first_name,
    mn.last_name  AS mn_last_name,
    mn.user_name  AS mn_username,
    mn.email      AS mn_email,
    --========DV=======
    dv.emp_id     AS dv_emp_id,
    mso3.fullname AS dv_fullname,
    dv.first_name AS dv_first_name,
    dv.last_name  AS dv_last_name,
    dv.user_name  AS dv_username,
    dv.email      AS dv_email,
    --========GM=======
    gm.emp_id     AS gm_emp_id,
    mso4.fullname AS gm_fullname,
    gm.first_name AS gm_first_name,
    gm.last_name  AS gm_last_name,
    gm.user_name  AS gm_username,
    gm.email      AS gm_email,
    --========VP=======
    vp.emp_id     AS vp_emp_id,
    mso5.fullname AS vp_fullname,
    vp.first_name AS vp_first_name,
    vp.last_name  AS vp_last_name,
    vp.user_name  AS vp_username,
    vp.email      AS vp_email
  FROM franchisee fz
  INNER JOIN fr_store fs
  ON NVL(fz.status, '-')  != 'D'
  AND NVL(fs.status, '-') != 'D'
  AND fs.cancel_type       = '00'
  AND ( fs.cancel_date    IS NULL
  OR fs.cancel_date       >= sysdate )
  AND fs.owner_id1         = fz.franchisee_id
  INNER JOIN mas_store ms
  ON ms.branch_id    = fs.store_id
  AND ms.active_flag = 'Y'
  INNER JOIN mas_store_organize mso1
  ON mso1.branch_id    = ms.branch_id
  AND mso1.active_flag = 'Y'
  AND mso1.group_id    = 2000
  LEFT JOIN business_user fc
  ON fc.group_id                          = mso1.group_id
  AND ( fc.emp_id                         = mso1.emp_id
  OR ( mso1.emp_id                       IS NULL
  AND instr(mso1.fullname, fc.first_name) > 0
  AND instr(mso1.fullname, fc.last_name)  > 0 ) )
  AND fc.active_flag                      = 'Y'
  INNER JOIN mas_store_organize mso2
  ON mso2.branch_id    = ms.branch_id
  AND mso2.active_flag = 'Y'
  AND mso2.group_id    = 70
  LEFT JOIN business_user mn
  ON mn.group_id                          = mso2.group_id
  AND ( mn.emp_id                         = mso2.emp_id
  OR ( mso2.emp_id                       IS NULL
  AND instr(mso2.fullname, mn.first_name) > 0
  AND instr(mso2.fullname, mn.last_name)  > 0 ) )
  AND mn.active_flag                      = 'Y'
  INNER JOIN mas_store_organize mso3
  ON mso3.branch_id    = ms.branch_id
  AND mso3.active_flag = 'Y'
  AND mso3.group_id    = 15
  LEFT JOIN business_user dv
  ON dv.group_id                          = mso3.group_id
  AND ( dv.emp_id                         = mso3.emp_id
  OR ( mso3.emp_id                       IS NULL
  AND instr(mso3.fullname, dv.first_name) > 0
  AND instr(mso3.fullname, dv.last_name)  > 0 ) )
  AND dv.active_flag                      = 'Y'
  INNER JOIN mas_store_organize mso4
  ON mso4.branch_id    = ms.branch_id
  AND mso4.active_flag = 'Y'
  AND mso4.group_id    = 38
  LEFT JOIN business_user gm
  ON gm.group_id                          = mso4.group_id
  AND ( gm.emp_id                         = mso4.emp_id
  OR ( mso4.emp_id                       IS NULL
  AND instr(mso4.fullname, gm.first_name) > 0
  AND instr(mso4.fullname, gm.last_name)  > 0 ) )
  AND gm.active_flag                      = 'Y'
  INNER JOIN mas_store_organize mso5
  ON mso5.branch_id    = ms.branch_id
  AND mso5.active_flag = 'Y'
  AND mso5.group_id    = 28
  LEFT JOIN business_user vp
  ON vp.group_id                          = mso5.group_id
  AND ( vp.emp_id                         = mso5.emp_id
  OR ( mso5.emp_id                       IS NULL
  AND instr(mso5.fullname, vp.first_name) > 0
  AND instr(mso5.fullname, vp.last_name)  > 0 ) )
  AND vp.active_flag                      = 'Y'
  LEFT JOIN fml_franchisee_register rg
  ON rg.current_franchisee_id = fz.franchisee_id
  LEFT JOIN common_code cc1
  ON cc1.code_type    = '00001'
  AND cc1.code_value  = fz.title_code
  AND cc1.active_flag = 'Y'
  LEFT JOIN common_code cc5
  ON cc5.code_type    = '00005'
  AND cc5.code_value  = fz.sex
  AND cc5.active_flag = 'Y'
  LEFT JOIN common_code cc_st
  ON cc_st.code_type    = fs.fr_type
  AND cc_st.code_value  = fs.fr_subtype
  AND cc_st.active_flag = 'Y'
  LEFT JOIN common_code cc_ad
  ON cc_ad.code_type                          = 'STORE_TYPE_AD'
  AND cc_ad.code_value                        = ms.status_type
  AND ( cc_ad.code_mapping                   IS NULL
  OR instr(cc_ad.code_mapping, fs.fr_subtype) > 0 )
  AND cc_ad.active_flag                       = 'Y';

-- ---------- VIEW: V_MEMO_APPROVE_FZ ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_MEMO_APPROVE_FZ" ("WF_ID", "WF_VERSION_ID", "TRANSACTION_PK", "TO_STEP_ID", "WF_USER_ID", "WF_GROUP_ID", "MEMO_NO", "CREATE_DATE", "APPROVE_REMARK", "WF_STATUS_NAME", "CREATE_FIRSTNAME", "CREATE_LASTNAME", "APPROVE_FIRSTNAME", "APPROVE_LASTNAME", "STORE_AREA") AS 
  SELECT v.wf_id,
          sh.wf_version_id,
          sh.transaction_pk,
          sh.to_step_id,
          t.wf_user_id,
          t.wf_group_id,
          m.memo_no,
          TO_CHAR (m.create_date,
                   'DD/MM/YYYY',
                   'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
             create_date,
          sh.wf_remark approve_remark,
          wfs.wf_status_name wf_status_name,
          bu.first_name create_firstname,
          bu.last_name create_lastname,
          bu2.first_name approve_firstname,
          bu2.last_name approve_lastname,
          m.store_area

     FROM fms_memo_approve_fz m
          INNER JOIN wf_version v
             ON v.wf_id = 1
          INNER JOIN business_user bu
             ON bu.user_id = m.create_by
          INNER JOIN wf_transaction t
             ON t.transaction_pk = m.memo_id
                AND t.wf_version_id = v.wf_version_id
          INNER JOIN wf_step_history sh
             ON sh.transaction_pk = m.memo_id
                AND sh.wf_version_id = v.wf_version_id
          INNER JOIN wf_status wfs
             ON wfs.wf_status_id = t.wf_status_id
                AND sh.to_step_id = t.wf_step_id
                AND sh.wf_step_history_id IN
                       (  SELECT MAX (sh2.wf_step_history_id)
                            FROM wf_step_history sh2
                           WHERE     sh2.transaction_pk = t.transaction_pk
                                 AND sh2.wf_version_id = v.wf_version_id
                                 AND sh2.to_step_id = t.wf_step_id
                        GROUP BY sh2.transaction_pk)
          LEFT JOIN business_user bu2
             ON bu2.user_id = t.wf_user_id;

-- ---------- VIEW: V_MEMO_MANPOWER ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_MEMO_MANPOWER" ("WF_ID", "WF_VERSION_ID", "TRANSACTION_PK", "TO_STEP_ID", "WF_USER_ID", "WF_GROUP_ID", "MEMO_NO", "STORE_ID", "STORE_NAME", "STORE_AREA", "OPEN_DATE", "CREATE_DATE", "APPROVE_REMARK", "WF_STATUS_NAME", "CREATE_FIRSTNAME", "CREATE_LASTNAME", "APPROVE_FIRSTNAME", "APPROVE_LASTNAME") AS 
  SELECT v.wf_id, 
          sh.wf_version_id,
          sh.transaction_pk,
          sh.to_step_id,
          t.wf_user_id,
          t.wf_group_id,
          m.memo_no,
          m.store_id,
          m.store_name,
          m.store_area,
          nvl(to_char(m.open_date, 'DD/MM/YYYY', 'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI'), open_date_char) open_date,
          to_char(m.create_date, 'DD/MM/YYYY', 'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI') create_date,
          sh.wf_remark approve_remark,
          wfs.wf_status_name wf_status_name,
          bu.first_name create_firstname,
          bu.last_name create_lastname,
          bu2.first_name approve_firstname,
          bu2.last_name approve_lastname
--          floor(sysdate - max (sh.created_date) over (partition by sh.wf_version_id, sh.transaction_pk)) waiting_day
 FROM fms_memo_manpower m
    inner join wf_version v on v.wf_id = 2                
      INNER JOIN business_user bu
         ON bu.user_id = m.create_by
      INNER JOIN wf_transaction t
         ON t.transaction_pk = m.memo_id
            AND t.wf_version_id = v.wf_version_id
      INNER JOIN wf_step_history sh
         ON sh.transaction_pk = m.memo_id
            AND sh.wf_version_id =  v.wf_version_id
      INNER JOIN wf_status wfs on wfs.wf_status_id = t.wf_status_id   
            AND sh.to_step_id = t.wf_step_id
            AND sh.wf_step_history_id IN
                   (  SELECT MAX (sh2.wf_step_history_id)
                        FROM wf_step_history sh2
                       WHERE sh2.transaction_pk = t.transaction_pk
                             AND sh2.wf_version_id =  v.wf_version_id
                             AND sh2.to_step_id = t.wf_step_id
                    GROUP BY sh2.transaction_pk)
      LEFT JOIN business_user bu2
         ON bu2.user_id = t.wf_user_id;

-- ---------- VIEW: V_MEMO_ON_PROCESS ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_MEMO_ON_PROCESS" ("WF_ID", "WF_VERSION_ID", "TRANSACTION_PK", "TO_STEP_ID", "WF_USER_ID", "WF_GROUP_ID", "MEMO_NO", "CREATE_DATE", "APPROVE_REMARK", "WF_STATUS_NAME", "CREATE_FIRSTNAME", "CREATE_LASTNAME", "APPROVE_FIRSTNAME", "APPROVE_LASTNAME", "WAITING_DAY") AS 
  SELECT v.wf_id, 
          sh.wf_version_id,
          sh.transaction_pk,
          sh.to_step_id,
          t.wf_user_id,
          t.wf_group_id,
          m.memo_no,
          to_char(m.create_date, 'DD/MM/YYYY', 'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI') create_date,
          sh.wf_remark approve_remark,
          wfs.wf_status_name wf_status_name,
          bu.first_name create_firstname,
          bu.last_name create_lastname,
          bu2.first_name approve_firstname,
          bu2.last_name approve_lastname,
          floor(sysdate - max (sh.created_date) over (partition by sh.wf_version_id, sh.transaction_pk)) waiting_day
 FROM (
        select 1 as  memo_type, m1.memo_id, m1.memo_no, m1.create_by, m1.create_date from fms_memo_approve_fz m1 where m1.status = 'N'
        union all
        select 2 as  memo_type, m2.memo_id, m2.memo_no, m2.create_by, m2.create_date from fms_memo_manpower m2  where m2.status = 'N'            
        union all
        select 3 as  memo_type, m3.memo_id, m3.memo_no, m3.create_by, m3.create_date from FMS_MEMO_OPEN_STORE m3  where m3.status = 'N'              
        union all                                                        
         select 4 as  memo_type, m4.memo_id, m4.memo_no, m4.create_by, m4.create_date from FMS_MEMO_REFUND m4  where m4.status = 'N'                        
    ) m
    inner join wf_version v on v.wf_id = memo_type                
      INNER JOIN business_user bu
         ON bu.user_id = m.create_by
      INNER JOIN wf_transaction t
         ON t.transaction_pk = m.memo_id
            AND t.wf_version_id = v.wf_version_id
      INNER JOIN wf_step_history sh
         ON sh.transaction_pk = m.memo_id
            AND sh.wf_version_id =  v.wf_version_id
      INNER JOIN wf_status wfs on wfs.wf_status_id = t.wf_status_id   
            AND sh.to_step_id = t.wf_step_id
            AND sh.wf_step_history_id IN
                   (  SELECT MAX (sh2.wf_step_history_id)
                        FROM wf_step_history sh2
                       WHERE sh2.transaction_pk = t.transaction_pk
                             AND sh2.wf_version_id =  v.wf_version_id
                             AND sh2.to_step_id = t.wf_step_id
                    GROUP BY sh2.transaction_pk)
      INNER JOIN business_user bu2
         ON bu2.user_id = t.wf_user_id;

-- ---------- VIEW: V_MEMO_OPEN_STORE ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_MEMO_OPEN_STORE" ("WF_ID", "WF_VERSION_ID", "TRANSACTION_PK", "TO_STEP_ID", "WF_USER_ID", "WF_GROUP_ID", "MEMO_NO", "STORE_ID", "STORE_NAME", "STORE_AREA", "OPEN_DATE", "CREATE_DATE", "APPROVE_REMARK", "WF_STATUS_NAME", "CREATE_FIRSTNAME", "CREATE_LASTNAME", "APPROVE_FIRSTNAME", "APPROVE_LASTNAME", "FR_TYPE") AS 
  SELECT v.wf_id, 
          sh.wf_version_id,
          sh.transaction_pk,
          sh.to_step_id,
          t.wf_user_id,
          t.wf_group_id,   
          m.memo_no,
          m.store_id,
          m.store_name,
          m.store_area,
          nvl(to_char(m.open_date, 'DD/MM/YYYY', 'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI'), open_date_char) open_date,
          to_char(m.create_date, 'DD/MM/YYYY', 'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI') create_date,
          sh.wf_remark approve_remark,
          wfs.wf_status_name wf_status_name,
          bu.first_name create_firstname,
          bu.last_name create_lastname,
          bu2.first_name approve_firstname,
          bu2.last_name approve_lastname,
          cc.code_name fr_type
          --floor(sysdate - max (sh.created_date) over (partition by sh.wf_version_id, sh.transaction_pk)) waiting_day
 FROM fms_memo_open_store m
    inner join common_code cc on cc.code_value = m.fr_type
        and cc.code_type = '00019'
    inner join wf_version v on v.wf_id = 3                
      INNER JOIN business_user bu
         ON bu.user_id = m.create_by
      INNER JOIN wf_transaction t
         ON t.transaction_pk = m.memo_id
            AND t.wf_version_id = v.wf_version_id
      INNER JOIN wf_step_history sh
         ON sh.transaction_pk = m.memo_id
            AND sh.wf_version_id =  v.wf_version_id
      INNER JOIN wf_status wfs on wfs.wf_status_id = t.wf_status_id   
            AND sh.to_step_id = t.wf_step_id
            AND sh.wf_step_history_id IN
                   (  SELECT MAX (sh2.wf_step_history_id)
                        FROM wf_step_history sh2
                       WHERE sh2.transaction_pk = t.transaction_pk
                             AND sh2.wf_version_id =  v.wf_version_id
                             AND sh2.to_step_id = t.wf_step_id
                    GROUP BY sh2.transaction_pk)
      LEFT JOIN business_user bu2
         ON bu2.user_id = t.wf_user_id;

-- ---------- VIEW: V_MEMO_REFUND ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_MEMO_REFUND" ("WF_ID", "WF_VERSION_ID", "TRANSACTION_PK", "TO_STEP_ID", "WF_USER_ID", "WF_GROUP_ID", "MEMO_NO", "CREATE_DATE", "APPROVE_REMARK", "WF_STATUS_NAME", "CREATE_FIRSTNAME", "CREATE_LASTNAME", "APPROVE_FIRSTNAME", "APPROVE_LASTNAME") AS 
  SELECT v.wf_id, 
          sh.wf_version_id,
          sh.transaction_pk,
          sh.to_step_id,
          t.wf_user_id,
          t.wf_group_id,
          m.memo_no,
--          m.store_id,
--          m.store_name,
--          m.store_area,
--          nvl(to_char(m.open_date, 'DD/MM/YYYY', 'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI'), open_date_char) open_date,
          to_char(m.create_date, 'DD/MM/YYYY', 'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI') create_date,
          sh.wf_remark approve_remark,
          wfs.wf_status_name wf_status_name,
          bu.first_name create_firstname,
          bu.last_name create_lastname,
          bu2.first_name approve_firstname,
          bu2.last_name approve_lastname
          --floor(sysdate - max (sh.created_date) over (partition by sh.wf_version_id, sh.transaction_pk)) waiting_day
 FROM fms_memo_refund m
    inner join wf_version v on v.wf_id = 4                
      INNER JOIN business_user bu
         ON bu.user_id = m.create_by
      INNER JOIN wf_transaction t
         ON t.transaction_pk = m.memo_id
            AND t.wf_version_id = v.wf_version_id
      INNER JOIN wf_step_history sh
         ON sh.transaction_pk = m.memo_id
            AND sh.wf_version_id =  v.wf_version_id
      INNER JOIN wf_status wfs on wfs.wf_status_id = t.wf_status_id   
            AND sh.to_step_id = t.wf_step_id
            AND sh.wf_step_history_id IN
                   (  SELECT MAX (sh2.wf_step_history_id)
                        FROM wf_step_history sh2
                       WHERE sh2.transaction_pk = t.transaction_pk
                             AND sh2.wf_version_id =  v.wf_version_id
                             AND sh2.to_step_id = t.wf_step_id
                    GROUP BY sh2.transaction_pk)
      LEFT JOIN business_user bu2
         ON bu2.user_id = t.wf_user_id;

-- ---------- VIEW: V_MIXED_MEMO_PROMOTE ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_MIXED_MEMO_PROMOTE" ("WF_ID", "WF_VERSION_ID", "TRANSACTION_PK", "TO_STEP_ID", "WF_USER_ID", "WF_GROUP_ID", "MEMO_NO", "STORE_ID", "STORE_NAME", "STORE_AREA", "CREATE_DATE", "WF_STATUS_ID", "WF_STATUS_NAME", "CUR_CUST_FIRST_NAME", "CUR_CUST_LAST_NAME", "CREATE_FIRSTNAME", "CREATE_LASTNAME", "APPROVE_FIRSTNAME", "APPROVE_LASTNAME", "APPROVE_REMARK", "WAITING_DAY") AS 
  SELECT v.wf_id, 
          sh.wf_version_id,
          sh.transaction_pk,
          sh.to_step_id,
          t.wf_user_id,
          t.wf_group_id,
          m.memo_no,
          m.store_id,                  
          m.store_name,
          m.store_area,
          to_char(m.create_date, 'DD/MM/YYYY', 'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI') as create_date,
          t.wf_status_id,
          wfs.wf_status_name as wf_status_name,
          c.first_name as cur_cust_first_name,
          c.last_name as cur_cust_last_name,
          bu.first_name as create_firstname,
          bu.last_name as create_lastname,
          bu2.first_name as approve_firstname,
          bu2.last_name as approve_lastname,
          sh.wf_remark approve_remark,
          case when t.wf_step_id != v.cancel_step_id then
                floor(sysdate - max (sh.created_date) over (partition by sh.wf_version_id, sh.transaction_pk))          
          end as waiting_day
 FROM (
    select 1 as wf_id, mm.process_id, mm.memo_id, mm.memo_no, mm.create_date, mm.create_by, null as store_id, null as store_name, mm.store_area from fms_memo_approve_fz mm
    union all
    select 2 as wf_id, mm.process_id, mm.memo_id, mm.memo_no, mm.create_date, mm.create_by, mm.store_id, null as store_name, mm.store_area from fms_memo_manpower mm
    union all
    select 3 as wf_id, mm.process_id, mm.memo_id, mm.memo_no, mm.create_date, mm.create_by, mm.store_id, null as store_name, mm.store_area from fms_memo_open_store mm
    union all
    select 4 as wf_id, mm.process_id, mm.memo_id, mm.memo_no, mm.create_date, mm.create_by, null as store_id, null as store_name, null as store_area from fms_memo_refund mm
  ) m 
        inner join (
            select trn2.process_id, trn2.cust_id         
            from fr_process_trn trn2
            where trn2.step_id in (
                select max(trn3.step_id)
                from fr_process_trn trn3
                where trn3.process_id = trn2.process_id    
            )
        ) trn on trn.process_id = m.process_id          
      INNER JOIN customer c on c.cust_id = trn.cust_id
      INNER JOIN wf_version v on v.wf_id = m.wf_id --v.wf_id = 1                
      INNER JOIN business_user bu
         ON bu.user_id = m.create_by
      INNER JOIN wf_transaction t
         ON t.transaction_pk = m.memo_id
            AND t.wf_version_id = v.wf_version_id
      INNER JOIN wf_step_history sh
         ON sh.transaction_pk = m.memo_id
            AND sh.wf_version_id =  v.wf_version_id
      INNER JOIN wf_status wfs on wfs.wf_status_id = t.wf_status_id   
            AND sh.to_step_id = t.wf_step_id
            AND sh.wf_step_history_id IN
                   (  SELECT MAX (sh2.wf_step_history_id)
                        FROM wf_step_history sh2
                       WHERE sh2.transaction_pk = t.transaction_pk
                             AND sh2.wf_version_id =  v.wf_version_id
                             AND sh2.to_step_id = t.wf_step_id
                    GROUP BY sh2.transaction_pk)
      LEFT JOIN business_user bu2
         ON bu2.user_id = t.wf_user_id;

-- ---------- VIEW: V_SBP_CONSENT ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_SBP_CONSENT" ("KEY_ID", "STATUS_CONSENT", "STATUS_MARKET") AS 
  select KEY_ID,STATUS_CONSENT,STATUS_MARKET from SBP_CONSENT;

-- ---------- VIEW: V_SEVENSHOP ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_SEVENSHOP" ("STORE_ID", "DV_NAME", "DV_EMAIL", "CDATE") AS 
  SELECT BRANCH_ID,
            DV_NAME,
            DV_EMAIL,
            OPEN_DATE AS CDATE
       FROM SEVENSHOP
   ORDER BY BRANCH_ID;

-- ---------- VIEW: V_SIS_COORDINATE_REGION ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_SIS_COORDINATE_REGION" ("EMAIL", "NAME", "AREA") AS 
  select email, BU.FIRST_NAME||' '||BU.LAST_NAME name ,bug.STORE_AREA AREA from BUSINESS_USER bu
    inner join BUSINESS_USER_GROUP bug on bu.user_id = bug.user_id
    where bug.GROUP_ID = '2003' and bug.store_area <> 'not' order by 3 ,1 ,2 asc;

-- ---------- VIEW: V_SML_NEWS_AUTH_DATE_ONLY ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_SML_NEWS_AUTH_DATE_ONLY" ("AUTH_ID", "TRANSACTION_PK") AS 
  SELECT A.AUTH_ID, A.TRANSACTION_PK
     FROM FCS_AUTHORIZE A
          LEFT JOIN FCS_AUTHORIZE_GROUP_TRANS G
             ON G.AUTH_GROUP_ID = A.AUTH_GROUP_ID
          LEFT JOIN FCS_AUTHORIZE_TRANS T
             ON T.AUTH_ID = A.AUTH_ID
    WHERE     A.TRANSACTION_PK IS NOT NULL
          AND A.TABLE_TRANSACTION_PK = 'FCS_CONTENT'
          AND TO_DATE(TO_CHAR(A.START_DATE,'DD/MM/YYYY')||' 00:00:00','DD/MM/YYYY HH24:MI:SS') <= SYSDATE
          AND TO_DATE(TO_CHAR(A.END_DATE,'DD/MM/YYYY')||' 23:59:59','DD/MM/YYYY HH24:MI:SS') >= SYSDATE
          AND T.AUTH_ID IS NULL
          AND G.AUTH_GROUP_ID IS NULL;

-- ---------- VIEW: V_SML_NEWS_AUTH_GROUP_ONLY ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_SML_NEWS_AUTH_GROUP_ONLY" ("AUTH_ID", "TRANSACTION_PK", "GROUP_ID") AS 
  SELECT A.AUTH_ID, A.TRANSACTION_PK, T.GROUP_ID
     FROM FCS_AUTHORIZE A
          INNER JOIN FCS_AUTHORIZE_GROUP_TRANS T
             ON A.AUTH_GROUP_ID = T.AUTH_GROUP_ID
          LEFT JOIN (  SELECT AUTH_ID, COUNT (1) AS RULE_AUTH
                         FROM FCS_AUTHORIZE_TRANS
                     GROUP BY AUTH_ID) AT
             ON AT.AUTH_ID = A.AUTH_ID
    WHERE     A.TRANSACTION_PK IS NOT NULL
          AND A.TABLE_TRANSACTION_PK = 'FCS_CONTENT'
          AND TO_DATE(TO_CHAR(A.START_DATE,'DD/MM/YYYY')||' 00:00:00','DD/MM/YYYY HH24:MI:SS') <= SYSDATE
          AND TO_DATE(TO_CHAR(A.END_DATE,'DD/MM/YYYY')||' 23:59:59','DD/MM/YYYY HH24:MI:SS') >= SYSDATE
          AND RULE_AUTH IS NULL;

-- ---------- VIEW: V_SML_NEWS_AUTH_RULE_AND_GROUP_DEL ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_SML_NEWS_AUTH_RULE_AND_GROUP_DEL" ("AUTH_ID", "TRANSACTION_PK", "USER_ID", "GROUP_ID") AS 
  SELECT auth."AUTH_ID",
    AUTH.TRANSACTION_PK,
    U.user_id,
    U.GROUP_ID
  FROM
    (SELECT au.auth_id,
      agt.GROUP_ID AS auth_group_id,
      au.system_code,
      au.transaction_pk,
      au.table_transaction_pk,
      au.start_date,
      au.end_date,
      au1.auth_value AS auth_branch_type,
      au2.auth_value AS auth_region,
      au3.auth_value AS auth_branch_id,
      au4.auth_value AS auth_fc_emp_id,
      au5.auth_value AS auth_mn_emp_id,
      au6.auth_value AS auth_dv_emp_id
    FROM fcs_authorize au
    INNER JOIN fcs_authorize_group ag
    ON ag.auth_group_id = au.auth_group_id
    AND ag.system_code  = 'FML'
    INNER JOIN fcs_authorize_group_trans agt
    ON agt.auth_group_id = ag.auth_group_id
    LEFT JOIN
      (SELECT aut1.* FROM fcs_authorize_trans aut1 WHERE aut1.auth_type = 1
      ) au1
    ON au1.auth_id = au.auth_id
    LEFT JOIN
      (SELECT aut1.* FROM fcs_authorize_trans aut1 WHERE aut1.auth_type = 2
      ) au2
    ON au2.auth_id = au.auth_id
    LEFT JOIN
      (SELECT aut1.* FROM fcs_authorize_trans aut1 WHERE aut1.auth_type = 3
      ) au3
    ON au3.auth_id = au.auth_id
    LEFT JOIN
      (SELECT aut1.* FROM fcs_authorize_trans aut1 WHERE aut1.auth_type = 4 
        and AUTH_VALUE like '2000%'
      ) au4
    ON au4.auth_id = au.auth_id
    LEFT JOIN
      (SELECT aut1.* FROM fcs_authorize_trans aut1 WHERE aut1.auth_type = 4
         and AUTH_VALUE like '70%'
     ) au5
    ON au5.auth_id = au.auth_id
    LEFT JOIN
      (SELECT aut1.* FROM fcs_authorize_trans aut1 WHERE aut1.auth_type = 4
        and AUTH_VALUE like '15%'
      ) au6
    ON au6.auth_id       = au.auth_id
    WHERE au.system_code = 'FML'
    AND TRUNC (SYSDATE) BETWEEN NVL (au.start_date, TRUNC (SYSDATE)) AND NVL (au.end_date, TRUNC (SYSDATE))
     ) auth
  INNER JOIN
    (SELECT s.branch_id,
      s.branch_name,
      s.branch_type,
      cc.code_value status_type,
      s.region,
      s.data_type,
      fc.emp_id   AS fc_emp_id,
      fc.fullname AS fc_full_name,
      mn.emp_id   AS mn_emp_id,
      mn.fullname AS mn_fullname,
      dv.emp_id   AS dv_emp_id,
      dv.fullname AS dv_fullname,
      S.ACTIVE_FLAG
    FROM mas_store s
    left join common_code cc 
    on cc.code_mapping = s.status_type
    and cc.code_type = '00019'
    LEFT JOIN mas_store_organize fc
    ON fc.branch_id    = s.branch_id
    AND s.active_flag  = 'Y'
    AND fc.active_flag = 'Y'
    AND fc.GROUP_ID    = 2000
    LEFT JOIN mas_store_organize mn
    ON mn.branch_id    = s.branch_id
    AND s.active_flag  = 'Y'
    AND mn.active_flag = 'Y'
    AND mn.GROUP_ID    = 70
    LEFT JOIN mas_store_organize dv
    ON dv.branch_id                      = s.branch_id
    AND s.active_flag                    = 'Y'
    AND dv.active_flag                   = 'Y'
    AND dv.GROUP_ID                      = 15
    ) ms ON NOT ( auth.auth_branch_type IS NULL
  AND auth.auth_region                  IS NULL
  AND auth.auth_branch_id               IS NULL
  AND auth.auth_fc_emp_id               IS NULL
  AND auth.auth_mn_emp_id               IS NULL
  AND auth.auth_dv_emp_id               IS NULL)
  AND ( 
        ( 
          (( 
              ( ms.status_type                   = auth.auth_branch_type AND auth.auth_region IS NULL )
                OR 
              ( ms.region                           = auth.auth_region  AND auth.auth_branch_type IS NULL )
               OR
               ( ms.region                           = auth.auth_region 
                  AND ms.status_type                   = auth.auth_branch_type  
                  AND auth.auth_branch_type IS NOT NULL 
                  AND auth.auth_region IS NOT NULL
                )
            ) 
            and auth.auth_branch_id IS NULL 
           )
          OR (  ms.branch_id = auth.auth_branch_id
                and auth.auth_branch_id IS NOT NULL 
              ) 
          OR (auth.auth_region IS NULL AND auth.auth_branch_type IS NULL and auth.auth_branch_id IS NULL AND (auth.auth_fc_emp_id IS NOT NULL
              or auth.auth_mn_emp_id IS NOT NULL
              or auth.auth_dv_emp_id IS NOT NULL))
      ) 
      AND (
        ( auth.auth_fc_emp_id IS NULL
          and auth.auth_mn_emp_id IS NULL
          and auth.auth_dv_emp_id IS NULL
        )
        OR (
            (
               '2000'||REPLACE(ms.fc_full_name , ' ', '')  like   nvl(auth.auth_fc_emp_id,'-')||'%'               
              OR '70'||REPLACE(ms.mn_fullname, ' ', '') like  nvl(auth.auth_mn_emp_id,'-')||'%'                       
              OR '15'||REPLACE(ms.dv_fullname , ' ', '') like nvl(auth.auth_dv_emp_id,'-')||'%'      
            )
            and ( auth.auth_fc_emp_id IS NOT NULL
              or auth.auth_mn_emp_id IS NOT NULL
              or auth.auth_dv_emp_id IS NOT NULL
            )
          )
      
      )
  )
  INNER JOIN V_SML_NEWS_AUTH_STORE_USER U
  ON U.BRANCH_ID     = MS.BRANCH_ID 
  and u.group_id = auth.auth_group_id
  WHERE ms.data_type = '1'
  AND MS.ACTIVE_FLAG = 'Y';

-- ---------- VIEW: V_SML_NEWS_AUTH_RULE_ONLY_DEL ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_SML_NEWS_AUTH_RULE_ONLY_DEL" ("AUTH_ID", "TRANSACTION_PK", "USER_ID") AS 
  SELECT auth."AUTH_ID",
    AUTH.TRANSACTION_PK,
    U.user_id
  FROM
    (SELECT au.auth_id,
      au.system_code,
      AU.AUTH_GROUP_ID,
      au.transaction_pk,
      au.table_transaction_pk,
      au.start_date,
      au.end_date,
      au1.auth_value AS auth_branch_type,
      au2.auth_value AS auth_region,
      au3.auth_value AS auth_branch_id,
      au4.auth_value AS auth_fc_emp_id,
      au5.auth_value AS auth_mn_emp_id,
      au6.auth_value AS auth_dv_emp_id
    FROM fcs_authorize au
    LEFT JOIN
      (SELECT aut1.* FROM fcs_authorize_trans aut1 WHERE aut1.auth_type = 1
      ) au1
    ON au1.auth_id = au.auth_id
    LEFT JOIN
      (SELECT aut1.* FROM fcs_authorize_trans aut1 WHERE aut1.auth_type = 2
      ) au2
    ON au2.auth_id = au.auth_id
    LEFT JOIN
      (SELECT aut1.* FROM fcs_authorize_trans aut1 WHERE aut1.auth_type = 3
      ) au3
    ON au3.auth_id = au.auth_id
    LEFT JOIN
      (SELECT aut1.* FROM fcs_authorize_trans aut1 WHERE aut1.auth_type = 4 
        and AUTH_VALUE like '2000%'
      ) au4
    ON au4.auth_id = au.auth_id
    LEFT JOIN
      (SELECT aut1.* FROM fcs_authorize_trans aut1 WHERE aut1.auth_type = 4
         and AUTH_VALUE like '70%'
     ) au5
    ON au5.auth_id = au.auth_id
    LEFT JOIN
      (SELECT aut1.* FROM fcs_authorize_trans aut1 WHERE aut1.auth_type = 4
        and AUTH_VALUE like '15%'
      ) au6
    ON au6.auth_id       = au.auth_id
    WHERE au.system_code = 'FML'
    AND TRUNC (SYSDATE) BETWEEN NVL (au.start_date, TRUNC (SYSDATE)) AND NVL (au.end_date, TRUNC (SYSDATE))
    ) auth
  INNER JOIN
    (SELECT s.branch_id,
      s.branch_name,
      s.branch_type,
      cc.code_value status_type,
      s.region,
      s.data_type,
      fc.emp_id   AS fc_emp_id,
      fc.fullname AS fc_full_name,
      mn.emp_id   AS mn_emp_id,
      mn.fullname AS mn_fullname,
      dv.emp_id   AS dv_emp_id,
      dv.fullname AS dv_fullname,
      S.ACTIVE_FLAG
    FROM mas_store s
    left join common_code cc 
    on cc.code_mapping = s.status_type
    and cc.code_type = '00019'
    LEFT JOIN mas_store_organize fc
    ON fc.branch_id    = s.branch_id
    AND s.active_flag  = 'Y'
    AND fc.active_flag = 'Y'
    AND fc.GROUP_ID    = 2000
    LEFT JOIN mas_store_organize mn
    ON mn.branch_id    = s.branch_id
    AND s.active_flag  = 'Y'
    AND mn.active_flag = 'Y'
    AND mn.GROUP_ID    = 70
    LEFT JOIN mas_store_organize dv
    ON dv.branch_id                      = s.branch_id
    AND s.active_flag                    = 'Y'
    AND dv.active_flag                   = 'Y'
    AND dv.GROUP_ID                      = 15
    ) ms ON NOT ( auth.auth_branch_type IS NULL
  AND auth.auth_region                  IS NULL
  AND auth.auth_branch_id               IS NULL
  AND auth.auth_fc_emp_id               IS NULL
  AND auth.auth_mn_emp_id               IS NULL
  AND auth.auth_dv_emp_id               IS NULL)
  AND ( 
        ( 
          (( 
              ( ms.status_type                   = auth.auth_branch_type AND auth.auth_region IS NULL )
                OR 
              ( ms.region                           = auth.auth_region  AND auth.auth_branch_type IS NULL )
               OR
               ( ms.region                           = auth.auth_region 
                  AND ms.status_type                   = auth.auth_branch_type  
                  AND auth.auth_branch_type IS NOT NULL 
                  AND auth.auth_region IS NOT NULL
                )
            ) 
            and auth.auth_branch_id IS NULL 
           )
          OR (  ms.branch_id = auth.auth_branch_id
                and auth.auth_branch_id IS NOT NULL 
              ) 
          OR (auth.auth_region IS NULL AND auth.auth_branch_type IS NULL and auth.auth_branch_id IS NULL AND (auth.auth_fc_emp_id IS NOT NULL
              or auth.auth_mn_emp_id IS NOT NULL
              or auth.auth_dv_emp_id IS NOT NULL))
      ) 
      AND (
        ( auth.auth_fc_emp_id IS NULL
          and auth.auth_mn_emp_id IS NULL
          and auth.auth_dv_emp_id IS NULL
        )
        OR (
            (
               '2000'||REPLACE(ms.fc_full_name , ' ', '')  like   nvl(auth.auth_fc_emp_id,'-')||'%'               
              OR '70'||REPLACE(ms.mn_fullname, ' ', '') like  nvl(auth.auth_mn_emp_id,'-')||'%'                       
              OR '15'||REPLACE(ms.dv_fullname , ' ', '') like nvl(auth.auth_dv_emp_id,'-')||'%'                     
            )
            and ( auth.auth_fc_emp_id IS NOT NULL
              or auth.auth_mn_emp_id IS NOT NULL
              or auth.auth_dv_emp_id IS NOT NULL
            )
          )
      
      )
  )
  LEFT JOIN
    (SELECT AUTH_GROUP_ID,
      COUNT (1) AS GROUP_AUTH
    FROM FCS_AUTHORIZE_GROUP_TRANS
    GROUP BY AUTH_GROUP_ID
    ) AT
  ON AT.AUTH_GROUP_ID = AUTH.AUTH_GROUP_ID
  INNER JOIN V_SML_NEWS_AUTH_STORE_USER U
  ON U.BRANCH_ID     = MS.BRANCH_ID
  WHERE GROUP_AUTH  IS NULL
  AND ms.data_type   = '1'
  AND MS.ACTIVE_FLAG = 'Y';

-- ---------- VIEW: V_SML_NEWS_AUTH_STORE_USER_DEL ----------
CREATE OR REPLACE FORCE EDITIONABLE VIEW "FCS_FRN"."V_SML_NEWS_AUTH_STORE_USER_DEL" ("BRANCH_ID", "USER_ID", "GROUP_ID") AS 
  SELECT MSO.BRANCH_ID,
    U.USER_ID,
    U.GROUP_ID
  FROM mas_store_organize mso
  INNER JOIN
    (SELECT bu.user_id,
      bu.emp_id,
      bu.first_name,
      bu.last_name,
      NVL (bug.GROUP_ID, bu.GROUP_ID) AS GROUP_ID
    FROM business_user bu
    LEFT JOIN
      (SELECT DISTINCT user_id,
        GROUP_ID
      FROM business_user_group
      WHERE GROUP_ID IN (2000, 70, 15, 38, 28) --2000=FC, 70=MN, 15=DV, 38=GM, 28=VP
      ) bug
    ON bug.user_id                       = bu.user_id
    WHERE bu.active_flag                 = 'Y'
    AND (bu.GROUP_ID                    IN (2000, 70, 15, 38, 28)
    OR bug.GROUP_ID                     IN (2000, 70, 15, 38, 28))
    ) u ON u.GROUP_ID                    = mso.GROUP_ID
  AND (u.emp_id                          = mso.emp_id
  OR (INSTR (mso.fullname, u.first_name) > 0
  AND INSTR (mso.fullname, u.last_name)  > 0))
  WHERE mso.data_type                    = '1'
  AND mso.active_flag                    = 'Y'
  UNION ALL
  SELECT DISTINCT F.STORE_ID AS BRANCH_ID,
    u.user_id                AS USER_ID,
    U.GROUP_ID
  FROM FR_STORE F
  INNER JOIN
    (SELECT bu.user_id,
      bu.franchisee_id,
      bu.emp_id,
      bu.first_name,
      bu.last_name,
      NVL (bug.GROUP_ID, bu.GROUP_ID) AS GROUP_ID
    FROM business_user bu
    LEFT JOIN
      (SELECT DISTINCT user_id, GROUP_ID FROM business_user_group
      ) bug
    ON bug.user_id         = bu.user_id 
    WHERE bu.active_flag   = 'Y' 
    ) u ON U.franchisee_id = F.OWNER_ID1
  WHERE NVL(F.STATUS,'-') != 'D'
      and f.cancel_type = '00';

