-- ---------- MATERIALIZED_VIEW: FMP_EMP_TRAIN_MVIEW ----------
CREATE MATERIALIZED VIEW "FCS_FRN"."FMP_EMP_TRAIN_MVIEW" ("RN", "ID_CARD", "011001", "011002", "011003")
  SEGMENT CREATION IMMEDIATE
  ORGANIZATION HEAP PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255 
 NOCOMPRESS LOGGING  NO INMEMORY 
  BUILD IMMEDIATE
  USING INDEX 
  REFRESH COMPLETE ON DEMAND
  USING DEFAULT LOCAL ROLLBACK SEGMENT
  USING ENFORCED CONSTRAINTS DISABLE ON QUERY COMPUTATION DISABLE QUERY REWRITE
  AS SELECT  DISTINCT t.* FROM
(
SELECT *
  FROM
    (SELECT ROW_NUMBER () OVER (PARTITION BY op.TRAIN_CODE , ap.id_card ORDER BY op.train_strdate DESC) rn ,
      tc.TRAIN_CODE ,
      ap.id_card ,
      NVL(ap.pass,'P') pass
    FROM
      (SELECT *
      FROM fmp_train_course
      WHERE regexp_like(course_category, '''B|C|D(\d{2})''')
      ) tc
    INNER JOIN FMP_TRAIN_OP op
    ON tc.TRAIN_CODE = op.train_code
    INNER JOIN FMP_TRAIN_AP ap
    ON ap.TRAIN_CODE                     = tc.TRAIN_CODE
    AND ap.TRAIN_PERIOD                  = op.TRAIN_PERIOD
    AND ap.train_group                   = op.train_group
    ) PIVOT (MIN(pass) FOR (train_code) IN ( '011001' AS "011001" , '011002' AS "011002" , '011003' AS "011003" ))
  WHERE rn    = 1
) t
INNER JOIN FMP_EMPLOYEE_DETAIL d
ON d.ID_CARD = t.ID_CARD;

-- ---------- MATERIALIZED_VIEW: FMP_REPORT_MAN_PW_MV ----------
CREATE MATERIALIZED VIEW "FCS_FRN"."FMP_REPORT_MAN_PW_MV" ("NO", "STORE_ID", "STORE_NAME", "REGION", "CODE_NAME", "STRAT_DATE", "SALES", "STRUCTURE_FORMAT", "FC_STRUCTURE_FORMAT_FT", "FC_STRUCTURE_FORMAT_PT", "OPT_STRUCTURE_FORMAT_FT", "OPT_STRUCTURE_FORMAT_PT", "FC_NAME", "MN_NAME", "OPT_FULLNAME", "FC_CONFIRM_DATE", "OPT_CONFIRM_DATE", "FC_CONFIRM_FLAG", "OPT_CONFIRM_FLAG", "STATUS_NAME", "EMPLOYEE_ID", "ID_CARD", "FULL_NAME", "DEPARTMENT_NAME", "SEX_NAME", "EDUCATION_NAME", "EMPLOYEE_TYPE_NAME", "ROLE_NAME", "POSITION_NAME", "WORK_HOUR", "WORK_DAY", "WORK_STRUCTURE", "FROM_SYSTEM", "SC_IN_START_DATE", "SC_IN_END_DATE", "WORKING_STATUS", "SC_RESIGN_REASON", "SC_RESIGN_REASON_DESC", "FMP_RESIGN_REASON", "FMP_RESIGN_REASON_DESC", "BIRTHDATE", "AGE", "GROUP_AGE_NAME", "SHIFT_STATUS_COUNT_DATE", "SHIFT_STATUS_NAME_FROM_COUNT_DATE", "SHIFT_CONCLUDE_FROM_COUNT_DATE", "SHIFT_STATUS_NAME", "SHIFT_AGE_NAME", "CONCLUDE_NAME", "011001", "011002", "011003", "FC_TRAIN_DESC")
  SEGMENT CREATION IMMEDIATE
  ORGANIZATION HEAP PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255 
 NOCOMPRESS LOGGING  NO INMEMORY 
  BUILD IMMEDIATE
  USING INDEX 
  REFRESH COMPLETE ON DEMAND
  USING DEFAULT LOCAL ROLLBACK SEGMENT
  USING ENFORCED CONSTRAINTS DISABLE ON QUERY COMPUTATION DISABLE QUERY REWRITE
  AS WITH employee AS
         (SELECT ed.id,
                 ed.store_id,
                 ed.month,
                 ed.year,
                 ed.structure_format,
                 DECODE(ed.employee_type_id, 'F', ed.fc_structure_format, '0.00')            AS fc_structure_format_ft,
                 DECODE(NVL(p.param_value, '0.00'), '0.00', '0.00', ed.fc_structure_format)  AS fc_structure_format_pt,
                 DECODE(ed.employee_type_id, 'F', ed.opt_structure_format, '0.00')           AS opt_structure_format_ft,
                 DECODE(NVL(p.param_value, '0.00'), '0.00', '0.00', ed.opt_structure_format) AS opt_structure_format_pt,
                 ed.employee_id,
                 ed.id_card,
                 e.first_name
                     || ' '
                     || e.last_name                                                             full_name,
                 ed.department_name,
                 e.sex_name,
                 e.education_name,
                 ed.employee_type_name,
                 ed.role_name,
                 ed.position_name,
                 'Y'                                                                         AS from_system,
                 ed.start_date                                                               AS sc_in_start_date,
                 ed.end_date                                                                 AS sc_in_end_date,
                 e.first_name,
                 e.last_name,
                 ed.resign_detail,
                 ed.resign_id,
                 ed.opt_structure_format,
                 e.birthdate,
                 ed.shift_status,
                 ed.create_date,
                 ed.fc_train_desc,
                 ed.SHIFT_DATE_COUNT,
                 ed.SHIFT_DATE
          FROM (select * from fmp_employee_detail where month = '07' and year = '2020') ed
                   LEFT JOIN fmp_employee e
                             ON ed.fmp_employee_id = e.ID
                   LEFT JOIN mas_param p
                             ON p.param_name = 'PART_TIME_FORMAT'
                                 AND p.param_value = ed.employee_type_id
         ),
     employee_extra AS
         (SELECT b.id,
                 b.store_id,
                 b.month,
                 b.year,
                 NULL                                                                       AS structure_format,
                 DECODE(b.employee_type_id, 'F', b.fc_structure_format, '0.00')             AS fc_structure_format_ft,
                 DECODE(NVL(p.param_value, '0.00'), '0.00', '0.00', b.fc_structure_format)  AS fc_structure_format_pt,
                 DECODE(b.employee_type_id, 'F', b.opt_structure_format, '0.00')            AS opt_structure_format_ft,
                 DECODE(NVL(p.param_value, '0.00'), '0.00', '0.00', b.opt_structure_format) AS opt_structure_format_pt,
                 NULL                                                                       AS employee_id,
                 NULL                                                                       AS id_card,
                 b.full_name,
                 b.department_name,
                 NULL                                                                       AS sex_name,
                 NULL                                                                       AS education_name,
                 b.employee_type_name,
                 NULL                                                                       AS role_name,
                 NULL                                                                       AS position_name,
                 'N'                                                                        AS from_system,
                 NULL                                                                       AS sc_in_start_date,
                 NULL                                                                       AS sc_in_end_date,
                 NULL                                                                       AS first_name,
                 NULL                                                                       AS last_name,
                 NULL                                                                       AS resign_detail,
                 NULL                                                                       AS resign_id,
                 opt_structure_format,
                 NULL                                                                       AS birthdate,
                 '3'                                                                        AS shift_status,
                 b.create_date,
                 NULL                                                                       AS fc_train_desc,
                 0                                                                          AS SHIFT_DATE_COUNT,
                 NULL                                                                       AS SHIFT_DATE
          FROM (select * from fmp_employee_extra where month = '07' and year = '2020') b
                   LEFT JOIN mas_param p
                             ON p.param_name = 'PART_TIME_FORMAT'
                                 AND p.param_value = b.employee_type_id
         ),
     employee_extra_not_dup AS
         (SELECT id,
                 store_id,
                 MONTH,
                 YEAR,
                 structure_format,
                 fc_structure_format_ft,
                 fc_structure_format_pt,
                 opt_structure_format_ft,
                 opt_structure_format_pt,
                 employee_id,
                 id_card,
                 full_name,
                 department_name,
                 sex_name,
                 education_name,
                 employee_type_name,
                 role_name,
                 position_name,
                 from_system,
                 sc_in_start_date,
                 sc_in_end_date,
                 first_name,
                 last_name,
                 resign_detail,
                 resign_id,
                 opt_structure_format,
                 birthdate,
                 shift_status,
                 create_date,
                 fc_train_desc,
                 SHIFT_DATE_COUNT,
                 SHIFT_DATE
          FROM (SELECT ee1.*,
                       RANK()
                               OVER ( PARTITION BY ee1.year, ee1.month, ee1.store_id, ee1.full_name ORDER BY ee1.year, ee1.month, ee1.store_id, DECODE(
                                       ee1.opt_structure_format_ft, '0.00', ee1.opt_structure_format_pt,
                                       ee1.opt_structure_format_ft) DESC, id DESC ) AS D_RANK_NUM
                FROM employee_extra ee1
               ) e11
          WHERE e11.D_RANK_NUM = 1
         ),
     all_employee AS
         (SELECT *
          FROM (SELECT ee.*,
                       RANK()
                               OVER ( PARTITION BY ee.year, ee.month, ee.store_id, ee.full_name ORDER BY ee.year, ee.month, ee.store_id, DECODE(
                                       opt_structure_format_ft, '0.00', opt_structure_format_pt,
                                       opt_structure_format_ft) DESC, from_system DESC, create_date DESC ) AS D_RANK_NUM
                FROM (SELECT *
                      FROM employee
                      UNION
                      SELECT *
                      FROM employee_extra_not_dup
                     ) ee
               ) e1
          WHERE D_RANK_NUM = 1
         ),
     all_data AS
         (SELECT DISTINCT mp.store_id,
                          fs.branch_name                                                    store_name,
                          fs.region,
                          CASE
                              WHEN cc2.code_value = 'BGC'
                                  THEN 'D'
                              WHEN cc2.code_value = 'EMP'
                                  THEN 'E'
                              WHEN cc2.code_value = 'PTT'
                                  THEN 'PTTOR'
                              ELSE cc2.code_value
                              END                                                           code_name,
                          TO_CHAR(fr.start_date, 'DD/MM/YYYY',
                                  'NLS_CALENDAR=''Thai Buddha'' NLS_DATE_LANGUAGE=THAI') AS strat_date,
                          sd.sales,
                          b.structure_format,
                          b.fc_structure_format_ft,
                          b.fc_structure_format_pt,
                          b.opt_structure_format_ft,
                          b.opt_structure_format_pt,
                          fs.fc_name,
                          fs.mn_name,
                          mp.dv_first_name
                              || ' '
                              || mp.dv_last_name                                            opt_fullname,
                          TO_CHAR(mp.fc_confirm_date, 'DD/MM/YYYY',
                                  'NLS_CALENDAR=''Thai Buddha'' NLS_DATE_LANGUAGE=THAI') AS fc_confirm_date,
                          TO_CHAR(mp.opt_confirm_date, 'DD/MM/YYYY',
                                  'NLS_CALENDAR=''Thai Buddha'' NLS_DATE_LANGUAGE=THAI') AS opt_confirm_date,
                          mp.fc_confirm_flag,
                          mp.opt_confirm_flag,
                          cc.code_name                                                      status_name,
                          b.employee_id,
                          b.id_card,
                          b.full_name,
                          b.department_name,
                          b.sex_name,
                          b.education_name,
                          b.employee_type_name,
                          b.role_name,
                          b.position_name,
                          b.from_system,
                          fr.cancel_date,
                          fr.start_date,
                          mp.YEAR,
                          mp.MONTH,
                          DECODE(b.from_system, 'N', 0, fma.total_time)                     total_time,
                          b.sc_in_start_date,
                          b.sc_in_end_date,
                          b.first_name,
                          b.last_name,
                          fr.owner_id1,
                          b.resign_detail,
                          b.resign_id,
                          b.opt_structure_format,
                          b.birthdate,
                          b.shift_status,
                          to_date('20/07/2020', 'dd/mm/yyyy')                               END_OF_ROUND,
                          fc_train_desc,
                          b.SHIFT_DATE_COUNT
          FROM (select * from fmp_man_power where month = '07' and year = '2020') mp
                   INNER JOIN fs_sevenshop fs
                              ON fs.branch_id = mp.store_id
                   LEFT JOIN
               (SELECT *
                FROM all_employee
                UNION
                SELECT em.*,
                       1 AS D_RANK_NUM
                FROM all_employee ae
                         INNER JOIN employee em
                                    ON em.from_system = ae.from_system
                                        AND em.store_id = ae.store_id
                                        AND em.month = ae.month
                                        AND em.year = ae.year
                                        AND em.full_name = ae.full_name
                                        AND em.employee_id <> ae.employee_id
               ) b
               ON mp.store_id = b.store_id
                   AND mp.YEAR = b.YEAR
                   AND mp.MONTH = b.MONTH
                   LEFT JOIN fr_store fr
                             ON fr.store_id = mp.store_id
                   LEFT JOIN fmp_daily_sales sd
                             ON (sd.store_id = mp.store_id
                                 AND sd.MONTH = mp.MONTH
                                 AND sd.YEAR = mp.YEAR)
                   LEFT JOIN common_code cc
                             ON (cc.code_type = 'FMP02'
                                 AND cc.code_value = mp.status_id)
                   LEFT JOIN common_code cc2
                             ON cc2.code_type = '00019'
                                 AND cc2.code_value = fr.fr_type
                   LEFT JOIN
               (SELECT store_id,
                       employee_id,
                       SUM(func_manpower_adjust_time(DECODE(fma.adjust_ck_hour, 0, ck_hour, adjust_ck_hour))) total_time
                FROM fmp_employee_attendance fma
                WHERE business_date BETWEEN TO_DATE('202006'
                                                        || '21', 'yyyymmdd')
                    AND TO_DATE('202007'
                                    || '20', 'yyyymmdd')
                  AND DECODE(fma.adjust_ck_hour, '0', fma.ck_hour, fma.adjust_ck_hour) > 0
                GROUP BY store_id,
                         employee_id
               ) fma
               ON mp.store_id = fma.store_id
                   AND b.employee_id = fma.employee_id
          WHERE mp.month = '07'
            AND mp.year = '2020'
            AND NVL(fr.status, '-') != 'D'
            AND fr.store_id != '00000'
            AND (NVL(fr.cancel_type, '-') = '00'
                     AND fr.cancel_date IS NULL
              OR fr.CANCEL_DATE > to_date('20200720', 'yyyymmdd'))
            AND fr.start_date IS NOT NULL
            AND TO_CHAR(fr.start_date, 'YYYYMMDD') <= '202007'
              || '20'
         )
SELECT ROW_NUMBER() OVER (ORDER BY a.store_id, a.employee_id, a.full_name)                              NO,
       a.store_id,
       a.store_name,
       a.region,
       a.code_name,
       a.strat_date,
       a.sales,
       a.structure_format,
       a.fc_structure_format_ft,
       a.fc_structure_format_pt,
       a.opt_structure_format_ft,
       a.opt_structure_format_pt,
       a.fc_name,
       a.mn_name,
       a.opt_fullname,
       a.fc_confirm_date,
       a.opt_confirm_date,
       a.fc_confirm_flag,
       a.opt_confirm_flag,
       a.status_name,
       a.employee_id,
       a.id_card,
       a.full_name,
       a.department_name,
       a.sex_name,
       a.education_name,
       a.employee_type_name,
       a.role_name,
       CASE
           WHEN fcs.franchisee_id IS NULL
               THEN a.position_name
           ELSE '?????????(Store Partner)'
           END                                                                                   AS     position_name,
       CASE
           WHEN fmz.franchisee_id IS NOT NULL
               AND fcs.franchisee_id IS NOT NULL
               THEN a.total_time
           WHEN fmz.franchisee_id IS NULL
               AND fcs.franchisee_id IS NOT NULL
               THEN 0
           WHEN fmz.franchisee_id IS NULL
               AND fcs.franchisee_id IS NULL
               THEN a.total_time
           END                                                                                   AS     work_hour,
       CASE
           WHEN fmz.franchisee_id IS NOT NULL
               AND fcs.franchisee_id IS NOT NULL
               THEN ROUND(a.total_time / 8, 3)
           WHEN fmz.franchisee_id IS NULL
               AND fcs.franchisee_id IS NOT NULL
               THEN 0
           WHEN fmz.franchisee_id IS NULL
               AND fcs.franchisee_id IS NULL
               THEN ROUND(a.total_time / 8, 3)
           END                                                                                   AS     work_day,
       CASE
           WHEN fmz.franchisee_id IS NOT NULL
               AND fcs.franchisee_id IS NOT NULL
               THEN ROUND(ROUND(a.total_time / 8, 3) / 26, 2)
           WHEN fmz.franchisee_id IS NULL
               AND fcs.franchisee_id IS NOT NULL
               THEN 0
           WHEN fmz.franchisee_id IS NULL
               AND fcs.franchisee_id IS NULL
               THEN ROUND(ROUND(a.total_time / 8, 3) / 26, 2)
           END                                                                                   AS     work_structure,
       a.from_system,
       TO_CHAR(a.sc_in_start_date, 'DD/MM/YYYY',
               'NLS_CALENDAR=''Thai Buddha'' NLS_DATE_LANGUAGE=THAI')                                   sc_in_start_date,
       TO_CHAR(a.sc_in_end_date, 'DD/MM/YYYY', 'NLS_CALENDAR=''Thai Buddha'' NLS_DATE_LANGUAGE=THAI')   sc_in_end_date,
       FUNC_FMP_DISPLAY_STATUS_EMP(a.opt_structure_format, a.sc_in_end_date, to_date('21/06/2020', 'dd/mm/yyyy'),
                                   to_date('20/07/2020', 'dd/mm/yyyy'), fehr.resign_reason_code) AS     working_status,
       cc1.code_name                                                                             AS     SC_RESIGN_REASON,
       fehr.resign_reason_desc                                                                   AS     SC_RESIGN_REASON_DESC,
       cc2.code_name                                                                             AS     FMP_RESIGN_REASON,
       TRANSLATE(a.resign_detail, 'x'
           || CHR(10)
           || CHR(13),
                 'x')                                                                            AS     FMP_RESIGN_REASON_DESC,
       CASE
           WHEN sc_in_end_date <= end_of_round
               THEN mp1.param_value
           ELSE TO_CHAR(birthdate, 'DD/MM/YYYY', 'NLS_CALENDAR=''Thai Buddha'' NLS_DATE_LANGUAGE=THAI')
           END                                                                                          birthdate,
       CASE
           WHEN sc_in_end_date <= end_of_round
               THEN mp1.param_value
           ELSE TO_CHAR(TRUNC(months_between(to_date('20/07/2020', 'dd/mm/yyyy'), birthdate) / 12))
           END                                                                                          age,
       CASE
           WHEN sc_in_end_date <= end_of_round
               THEN mp1.param_value
           ELSE cc3.CONDITION1
           END                                                                                          group_age_name,
       cc10.CONDITION1                                                                                  shift_status_count_date,
       CASE
           WHEN sc_in_end_date <= end_of_round
               THEN mp1.param_value
           ELSE cc11.DETAIL_CONDITION1
           END                                                                                          shift_status_name_from_count_date,
       CASE
           WHEN sc_in_end_date <= end_of_round
               THEN mp1.param_value
           ELSE cc11.CONDITION1
           END                                                                                          shift_conclude_from_count_date,
       CASE
           WHEN sc_in_end_date <= end_of_round
               THEN mp1.param_value
           ELSE cc4.CONDITION1
           END                                                                                          shift_status_name,
       CASE
           WHEN sc_in_end_date <= end_of_round
               THEN mp1.param_value
           ELSE
               CASE
                   WHEN 'FMP00005'
                            || '|'
                            || shift_status = cc3.CONDITION2
                       THEN cc3.DETAIL_CONDITION2
                   WHEN 'FMP00005'
                            || '|'
                            || shift_status = cc3.CONDITION3
                       THEN cc3.DETAIL_CONDITION3
                   WHEN 'FMP00005'
                            || '|'
                            || shift_status = cc3.CONDITION4
                       THEN cc3.DETAIL_CONDITION4
                   ELSE ''
                   END
           END                                                                                          shift_age_name,
       CASE
           WHEN sc_in_end_date <= end_of_round
               THEN mp1.param_value
           ELSE cc6.CONDITION1
           END                                                                                          conclude_name,
       cc7.code_name                                                                             AS     "011001",
       cc8.code_name                                                                             AS     "011002",
       cc9.code_name                                                                             AS     "011003",
       REPLACE(a.fc_train_desc, CHR(13)
           || CHR(10), ' ')                                                                             fc_train_desc
FROM all_data a
         LEFT JOIN franchisee fcs
                   ON ((fcs.id_card = a.id_card
                       OR (a.first_name = fcs.first_name
                           AND a.last_name = fcs.last_name))
                       AND fcs.franchisee_id = a.owner_id1)
         LEFT JOIN (select * from fmp_max_attendance_time_fz where month = '07' and year = '2020') fmz
                   ON fcs.franchisee_id = fmz.franchisee_id
                       AND fmz.store_id = a.store_id
         LEFT JOIN FMP_EMPLOYEE_HISTORY_RESIGN fehr
                   ON a.store_id = fehr.store_id
                       AND a.employee_id = fehr.employee_id
                       AND a.SC_IN_START_DATE = fehr.START_DATE
                       AND a.SC_IN_END_DATE = fehr.END_DATE
         LEFT JOIN common_code cc1
                   ON cc1.code_value = fehr.resign_reason_code
                       AND cc1.code_type = 'FMP00001'
         LEFT JOIN common_code cc2
                   ON cc2.code_value = a.resign_id
                       AND cc2.code_type = 'RESIGN'
         LEFT JOIN SRM_CONDITION cc3
                   ON cc3.SEQ = (
                       CASE
                           WHEN TRUNC(months_between(END_OF_ROUND, birthdate) / 12) IS NULL
                               THEN 3
                           WHEN TRUNC(months_between(END_OF_ROUND, birthdate) / 12) < 0
                               THEN 0
                           WHEN TRUNC(months_between(END_OF_ROUND, birthdate) / 12) BETWEEN 0 AND 10
                               THEN 1
                           WHEN TRUNC(months_between(END_OF_ROUND, birthdate) / 12) BETWEEN 11 AND 14
                               THEN 2
                           WHEN TRUNC(months_between(END_OF_ROUND, birthdate) / 12) BETWEEN 15 AND 17
                               THEN 4
                           WHEN TRUNC(months_between(END_OF_ROUND, birthdate) / 12) BETWEEN 18 AND 60
                               THEN 5
                           WHEN TRUNC(months_between(END_OF_ROUND, birthdate) / 12) > 60
                               THEN 6
                           END)
                       AND cc3.code = 'FMP00004'
         LEFT JOIN SRM_CONDITION cc4
                   ON cc4.seq = shift_status
                       AND cc4.code = 'FMP00005'
         LEFT JOIN SRM_CONDITION cc6
                   ON cc6.code
                          || '|'
                          || cc6.seq = (
                          CASE
                              WHEN 'FMP00005'
                                       || '|'
                                       || shift_status = cc3.CONDITION5
                                  THEN cc3.DETAIL_CONDITION5
                              WHEN 'FMP00005'
                                       || '|'
                                       || shift_status = cc3.CONDITION6
                                  THEN cc3.DETAIL_CONDITION6
                              WHEN 'FMP00005'
                                       || '|'
                                       || shift_status = cc3.CONDITION7
                                  THEN cc3.DETAIL_CONDITION7
                              ELSE ''
                              END)
                       AND cc6.code = 'FMP00007'
         LEFT JOIN srm_condition cc10
                   ON cc10.seq = (
                       CASE
                           WHEN a.SHIFT_DATE_COUNT IS NULL
                               THEN 1
                           WHEN a.SHIFT_DATE_COUNT = 0
                               THEN 1
                           WHEN a.SHIFT_DATE_COUNT BETWEEN 1 AND 2
                               THEN 2
                           WHEN a.SHIFT_DATE_COUNT BETWEEN 3 AND 6
                               THEN 3
                           WHEN a.SHIFT_DATE_COUNT > 6
                               THEN 4
                           END)
                       AND cc10.code = 'FMP00009'
         LEFT JOIN
     (SELECT ss.code code1,
             ss.seq  sq1,
             sc.code code2,
             sc.seq  sq2,
             sc.condition1,
             ss.detail_condition1
      FROM srm_condition ss
               INNER JOIN srm_condition sc
                          ON ss.code = 'FMP00010'
                              AND ss.condition1 = sc.code
                                  || '|'
                                  || sc.seq
     ) cc11 ON cc11.code1
                   || '|'
                   || cc11.sq1 = (
                   CASE
                       WHEN cc10.code
                                || '|'
                                || cc10.seq = cc3.condition8
                           THEN cc3.detail_condition8
                       WHEN cc10.code
                                || '|'
                                || cc10.seq = cc3.condition9
                           THEN cc3.detail_condition9
                       WHEN cc10.code
                                || '|'
                                || cc10.seq = cc3.condition10
                           THEN cc3.detail_condition10
                       WHEN cc10.code
                                || '|'
                                || cc10.seq = cc3.condition11
                           THEN cc3.detail_condition11
                       END)
         LEFT JOIN
     (SELECT *
      FROM
          (SELECT ROW_NUMBER() OVER (PARTITION BY op.TRAIN_CODE , ap.id_card ORDER BY op.train_strdate DESC) rn,
                  tc.TRAIN_CODE,
                  ap.id_card,
                  NVL(ap.pass, 'P')                                                                          pass
           FROM (SELECT *
                 FROM fmp_train_course
                 WHERE regexp_like(course_category, '''B|C|D(\\d{2})''')
                ) tc
                    INNER JOIN FMP_TRAIN_OP op
                               ON tc.TRAIN_CODE = op.train_code
                    INNER JOIN FMP_TRAIN_AP ap
                               ON ap.TRAIN_CODE = tc.TRAIN_CODE
                                   AND ap.TRAIN_PERIOD = op.TRAIN_PERIOD
                                   AND ap.train_group = op.train_group
          ) PIVOT (MIN(pass) FOR (train_code) IN ( '011001' AS "011001" , '011002' AS "011002" , '011003' AS "011003" ))
      WHERE rn = 1
     ) t ON t.id_card = a.id_card
         LEFT JOIN common_code cc7
                   ON cc7.code_value = (
                       CASE
                           WHEN UPPER("011001") != 'F'
                               THEN 1
                           WHEN UPPER("011001") = 'F'
                               THEN 2
                           WHEN UPPER("011001") IS NULL
                               THEN 3
                           END)
                       AND cc7.code_type = 'FMP00008'
         LEFT JOIN common_code cc8
                   ON cc8.code_value = (
                       CASE
                           WHEN UPPER("011002") != 'F'
                               THEN 1
                           WHEN UPPER("011002") = 'F'
                               THEN 2
                           WHEN UPPER("011002") IS NULL
                               THEN 3
                           END)
                       AND cc8.code_type = 'FMP00008'
         LEFT JOIN common_code cc9
                   ON cc9.code_value = (
                       CASE
                           WHEN UPPER("011003") != 'F'
                               THEN 1
                           WHEN UPPER("011003") = 'F'
                               THEN 2
                           WHEN UPPER("011003") IS NULL
                               THEN 3
                           END)
                       AND cc9.code_type = 'FMP00008'
         LEFT JOIN MAS_PARAM mp1
                   ON PARAM_NAME = 'FMP_RESIGN_DESCRIPTION'
WHERE a.MONTH = '07'
  AND a.YEAR = '2020'
;

-- ---------- MATERIALIZED_VIEW: FMP_ROTATE_SC ----------
CREATE MATERIALIZED VIEW "FCS_FRN"."FMP_ROTATE_SC" ("ID_CARD", "NO", "EMPLOYEE_ID", "START_DATE", "END_DATE", "STORE_ID", "STORE_NAME")
  SEGMENT CREATION IMMEDIATE
  ORGANIZATION HEAP PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255 
 NOCOMPRESS LOGGING  NO INMEMORY 
  BUILD IMMEDIATE
  USING INDEX 
  REFRESH COMPLETE ON DEMAND
  USING DEFAULT LOCAL ROLLBACK SEGMENT
  USING ENFORCED CONSTRAINTS DISABLE ON QUERY COMPUTATION DISABLE QUERY REWRITE
  AS select  id_card,max(no) no, employee_id,min(start_date) start_date,max(end_date) end_date,max(store_id) store_id, max(store_name) store_name 
         from fcs_frn.fmp_rotation_emp
         where id_card is not null 
         and employee_id is not null 
         and store_id is not null
         and start_date is not null
         group by store_id, id_card, employee_id 
         union
         select  id_card,max(no), employee_id,min(start_date),max(end_date),max(store_id) store_id, max(store_name) 
         from fcs_frn.fmp_rotation_emp
         where id_card is not null and employee_id is null 
         and store_id is not null
         and start_date is not null
         group by store_id, id_card, employee_id 
         union
         select  id_card,max(no), employee_id,min(start_date),max(end_date),max(store_id) store_id, max(store_name)  
         from fcs_frn.fmp_rotation_emp
         where id_card is null and employee_id is not null 
         and store_id is not null
         and start_date is not null
         group by store_id, id_card, employee_id ;

-- ---------- MATERIALIZED_VIEW: FMP_SC_EMP_HISTORY ----------
CREATE MATERIALIZED VIEW "FCS_FRN"."FMP_SC_EMP_HISTORY" ("ID", "STORE_ID", "FIRST_NAME", "LAST_NAME", "ID_CARD", "EMPLOYEE_TYPE_ID", "ROLE_ID", "START_DATE", "SALARY", "BENEFIT", "CREATE_DATE", "CREATE_USER", "DEPARTMENT_ID", "UPDATE_DATE", "UPDATE_USER", "NO", "STATUS_ID", "ROLE", "YEAR", "MONTH", "EMPLOYEE_ID", "TITLE_NAME", "SEX_ID", "EDUCATION", "TURN_ID", "POSITION_ID", "WORK_NO", "STRUCTURE_FORMAT", "TRAIN_LOG", "FC_CONFIRM_DATE", "END_DATE", "CREATE_FILE_DATE", "DEPARTMENT_NAME", "SEX_NAME", "EMPLOYEE_TYPE_NAME", "POSITION_NAME")
  SEGMENT CREATION IMMEDIATE
  ORGANIZATION HEAP PCTFREE 10 PCTUSED 0 INITRANS 1 MAXTRANS 255 
 NOCOMPRESS LOGGING  NO INMEMORY 
  BUILD IMMEDIATE
  USING INDEX 
  REFRESH COMPLETE ON DEMAND
  USING DEFAULT LOCAL ROLLBACK SEGMENT
  USING ENFORCED CONSTRAINTS DISABLE ON QUERY COMPUTATION DISABLE QUERY REWRITE
  AS select sc.id, sc_current.store_id, sc.first_name,sc.last_name, sc.id_card, sc.employee_type_id, sc.role_id,
sc.start_date, sc.salary, sc.benefit, sc.create_date , sc.create_user, sc.department_id, 
sc.update_date, sc.update_user, sc.no, sc.status_id, sc.role, sc.year, sc.month, sc.employee_id, 
sc.title_name, sc.sex_id, sc.education, sc.turn_id, sc.position_id, sc.work_no, sc.structure_format,
sc.train_log, sc.fc_confirm_date, sc.end_date, sc.create_file_date, sc.department_name, sc.sex_name,
sc.employee_type_name, sc.position_name from (
         select  id_card,max(id) id, max(employee_id) employee_id,max(store_id) store_id
         from fcs_frn.fmp_sc_in
         where id_card is not null
         and store_id is not null
         and start_date is not null
         group by store_id, id_card
         union
         select  max(id_card),max(id) , max(employee_id) employee_id,max(store_id) store_id
         from fcs_frn.fmp_sc_in
         where id_card is null and employee_id is not null 
         and store_id is not null
         and start_date is not null
         group by store_id, employee_id) sc_current
         left join fcs_frn.fmp_sc_in sc
         on sc_current.id = sc.id ;

-- ---------- MATERIALIZED_VIEW: FMP_SC_EMP_UPDATE ----------
CREATE MATERIALIZED VIEW "FCS_FRN"."FMP_SC_EMP_UPDATE" ("ID", "STORE_ID", "FIRST_NAME", "LAST_NAME", "ID_CARD", "EMPLOYEE_TYPE_ID", "ROLE_ID", "START_DATE", "SALARY", "BENEFIT", "CREATE_DATE", "CREATE_USER", "DEPARTMENT_ID", "UPDATE_DATE", "UPDATE_USER", "NO", "STATUS_ID", "ROLE", "YEAR", "MONTH", "EMPLOYEE_ID", "TITLE_NAME", "SEX_ID", "EDUCATION", "TURN_ID", "POSITION_ID", "WORK_NO", "STRUCTURE_FORMAT", "TRAIN_LOG", "FC_CONFIRM_DATE", "END_DATE", "CREATE_FILE_DATE", "DEPARTMENT_NAME", "SEX_NAME", "EMPLOYEE_TYPE_NAME", "POSITION_NAME")
  SEGMENT CREATION IMMEDIATE
  ORGANIZATION HEAP PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255 
 NOCOMPRESS LOGGING  NO INMEMORY 
  BUILD IMMEDIATE
  USING INDEX 
  REFRESH COMPLETE ON DEMAND
  USING DEFAULT LOCAL ROLLBACK SEGMENT
  USING ENFORCED CONSTRAINTS DISABLE ON QUERY COMPUTATION DISABLE QUERY REWRITE
  AS select sc.id, sc.store_id, sc.first_name,sc.last_name, sc.id_card, sc.employee_type_id, sc.role_id,
sc.start_date, sc.salary, sc.benefit, sc.create_date , sc.create_user, sc.department_id, 
sc.update_date, sc.update_user, sc.no, sc.status_id, sc.role, sc.year, sc.month, sc.employee_id, 
sc.title_name, sc.sex_id, sc.education, sc.turn_id, sc.position_id, sc.work_no, sc.structure_format,
sc.train_log, sc.fc_confirm_date, sc.end_date, sc.create_file_date, sc.department_name, sc.sex_name,
sc.employee_type_name, sc.position_name from fcs_frn.fmp_sc_in sc
where  EXISTS  (
select id from (
    select max(id) id
    from fcs_frn.fmp_sc_in
    where id_card is not null
    group by id_card
    union
    select max(id)
    from fcs_frn.fmp_sc_in
    where id_card is null
    group by employee_id
  )
  where id = sc.id
  ) ;

