-- ---------- MATERIALIZED_VIEW: STORE_TAXPAYER ----------
CREATE MATERIALIZED VIEW "FCS_FRN"."STORE_TAXPAYER" ("BRANCH", "PERIOD")
  SEGMENT CREATION IMMEDIATE
  ORGANIZATION HEAP PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255 
 COMPRESS BASIC LOGGING  NO INMEMORY 
  BUILD IMMEDIATE
  USING INDEX 
  REFRESH COMPLETE ON DEMAND
  USING DEFAULT LOCAL ROLLBACK SEGMENT
  USING ENFORCED CONSTRAINTS DISABLE ON QUERY COMPUTATION DISABLE QUERY REWRITE
  AS select m.branch_id AS branch,TO_CHAR(add_months(sysdate,-1),'yyyyMM') AS PERIOD from   mas_store m 
where not exists (select 1 from mas_taxpayer t where m.branch_id = t.branch_id and t.period =TO_CHAR(add_months(sysdate,-1),'yyyyMM') )
union
SELECT m.branch_id                                       AS branch,
    NVL(t.period,TO_CHAR(add_months(sysdate,-1),'yyyyMM')) AS PERIOD
  FROM mas_store m
  LEFT JOIN mas_taxpayer t
  ON m.branch_id = t.branch_id
  GROUP BY m.branch_id,
    NVL(t.period,TO_CHAR(add_months(sysdate,-1),'yyyyMM'))
  UNION
  SELECT t.taxpayer_id                                     AS branch,
    NVL(t.period,TO_CHAR(add_months(sysdate,-1),'yyyyMM')) AS PERIOD
  FROM mas_store m
  JOIN mas_taxpayer t
  ON m.branch_id = t.branch_id
  GROUP BY t.taxpayer_id,
    NVL(t.period,TO_CHAR(add_months(sysdate,-1),'yyyyMM'));

-- ---------- MATERIALIZED_VIEW: TEST1 ----------
CREATE MATERIALIZED VIEW "FCS_FRN"."TEST1" ("RN", "ID_CARD", "011001", "011002", "011003")
  SEGMENT CREATION IMMEDIATE
  ORGANIZATION HEAP PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255 
 NOCOMPRESS LOGGING  NO INMEMORY 
  BUILD IMMEDIATE
  USING INDEX 
  REFRESH COMPLETE ON DEMAND
  USING DEFAULT LOCAL ROLLBACK SEGMENT
  USING ENFORCED CONSTRAINTS DISABLE ON QUERY COMPUTATION DISABLE QUERY REWRITE
  AS SELECT  DISTINCT t.* FROM
(
SELECT *
  FROM
    (SELECT ROW_NUMBER () OVER (PARTITION BY op.TRAIN_CODE , ap.id_card ORDER BY op.train_strdate DESC) rn ,
      tc.TRAIN_CODE ,
      ap.id_card ,
      NVL(ap.pass,'P') pass
    FROM
      (SELECT *
      FROM fmp_train_course
      WHERE regexp_like(course_category, '''B|C|D(\\d{2})''')
      ) tc
    INNER JOIN FMP_TRAIN_OP op
    ON tc.TRAIN_CODE = op.train_code
    INNER JOIN FMP_TRAIN_AP ap
    ON ap.TRAIN_CODE                     = tc.TRAIN_CODE
    AND ap.TRAIN_PERIOD                  = op.TRAIN_PERIOD
    AND ap.train_group                   = op.train_group
    ) PIVOT (MIN(pass) FOR (train_code) IN ( '011001' AS "011001" , '011002' AS "011002" , '011003' AS "011003" ))
  WHERE rn    = 1
) t
INNER JOIN FMP_EMPLOYEE_DETAIL d
ON d.ID_CARD = t.ID_CARD;

-- ---------- MATERIALIZED_VIEW: V_SML_NEWS_AUTH_RULE_AND_GROUP ----------
CREATE MATERIALIZED VIEW "FCS_FRN"."V_SML_NEWS_AUTH_RULE_AND_GROUP" ("AUTH_ID", "TRANSACTION_PK", "USER_ID", "GROUP_ID")
  SEGMENT CREATION IMMEDIATE
  ORGANIZATION HEAP PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255 
 NOCOMPRESS LOGGING  NO INMEMORY 
  BUILD IMMEDIATE
  USING INDEX 
  REFRESH COMPLETE ON DEMAND
  USING DEFAULT LOCAL ROLLBACK SEGMENT
  USING ENFORCED CONSTRAINTS DISABLE ON QUERY COMPUTATION DISABLE QUERY REWRITE
  AS SELECT auth."AUTH_ID",
    AUTH.TRANSACTION_PK,
    U.user_id,
    U.GROUP_ID
  FROM
    (SELECT au.auth_id,
      agt.GROUP_ID AS auth_group_id,
      au.system_code,
      au.transaction_pk,
      au.table_transaction_pk,
      au.start_date,
      au.end_date,
      au1.auth_value AS auth_branch_type,
      au2.auth_value AS auth_region,
      au3.auth_value AS auth_branch_id,
      au4.auth_value AS auth_fc_emp_id,
      au5.auth_value AS auth_mn_emp_id,
      au6.auth_value AS auth_dv_emp_id
    FROM fcs_authorize au
    INNER JOIN fcs_authorize_group ag
    ON ag.auth_group_id = au.auth_group_id
    AND ag.system_code  = 'FML'
    INNER JOIN fcs_authorize_group_trans agt
    ON agt.auth_group_id = ag.auth_group_id
    LEFT JOIN
      (SELECT aut1.* FROM fcs_authorize_trans aut1 WHERE aut1.auth_type = 1
      ) au1
    ON au1.auth_id = au.auth_id
    LEFT JOIN
      (SELECT aut1.* FROM fcs_authorize_trans aut1 WHERE aut1.auth_type = 2
      ) au2
    ON au2.auth_id = au.auth_id
    LEFT JOIN
      (SELECT aut1.* FROM fcs_authorize_trans aut1 WHERE aut1.auth_type = 3
      ) au3
    ON au3.auth_id = au.auth_id
    LEFT JOIN
      (SELECT aut1.* FROM fcs_authorize_trans aut1 WHERE aut1.auth_type = 4 
        and AUTH_VALUE like '2000%'
      ) au4
    ON au4.auth_id = au.auth_id
    LEFT JOIN
      (SELECT aut1.* FROM fcs_authorize_trans aut1 WHERE aut1.auth_type = 4
         and AUTH_VALUE like '70%'
     ) au5
    ON au5.auth_id = au.auth_id
    LEFT JOIN
      (SELECT aut1.* FROM fcs_authorize_trans aut1 WHERE aut1.auth_type = 4
        and AUTH_VALUE like '15%'
      ) au6
    ON au6.auth_id       = au.auth_id
    WHERE au.system_code = 'FML'
    AND TRUNC (SYSDATE) BETWEEN NVL (au.start_date, TRUNC (SYSDATE)) AND NVL (au.end_date, TRUNC (SYSDATE))
     ) auth
  INNER JOIN
    (SELECT s.branch_id,
      s.branch_name,
      s.branch_type,
      cc.code_value status_type,
      s.region,
      s.data_type,
      fc.emp_id   AS fc_emp_id,
      fc.fullname AS fc_full_name,
      mn.emp_id   AS mn_emp_id,
      mn.fullname AS mn_fullname,
      dv.emp_id   AS dv_emp_id,
      dv.fullname AS dv_fullname,
      S.ACTIVE_FLAG
    FROM mas_store s
    left join common_code cc 
    on cc.code_mapping = s.status_type
    and cc.code_type = '00019'
    LEFT JOIN mas_store_organize fc
    ON fc.branch_id    = s.branch_id
    AND s.active_flag  = 'Y'
    AND fc.active_flag = 'Y'
    AND fc.GROUP_ID    = 2000
    LEFT JOIN mas_store_organize mn
    ON mn.branch_id    = s.branch_id
    AND s.active_flag  = 'Y'
    AND mn.active_flag = 'Y'
    AND mn.GROUP_ID    = 70
    LEFT JOIN mas_store_organize dv
    ON dv.branch_id                      = s.branch_id
    AND s.active_flag                    = 'Y'
    AND dv.active_flag                   = 'Y'
    AND dv.GROUP_ID                      = 15
    ) ms ON NOT ( auth.auth_branch_type IS NULL
  AND auth.auth_region                  IS NULL
  AND auth.auth_branch_id               IS NULL
  AND auth.auth_fc_emp_id               IS NULL
  AND auth.auth_mn_emp_id               IS NULL
  AND auth.auth_dv_emp_id               IS NULL)
  AND ( 
        ( 
          (( 
              ( ms.status_type                   = auth.auth_branch_type AND auth.auth_region IS NULL )
                OR 
              ( ms.region                           = auth.auth_region  AND auth.auth_branch_type IS NULL )
               OR
               ( ms.region                           = auth.auth_region 
                  AND ms.status_type                   = auth.auth_branch_type  
                  AND auth.auth_branch_type IS NOT NULL 
                  AND auth.auth_region IS NOT NULL
                )
            ) 
            and auth.auth_branch_id IS NULL 
           )
          OR (  ms.branch_id = auth.auth_branch_id
                and auth.auth_branch_id IS NOT NULL 
              ) 
          OR (auth.auth_region IS NULL AND auth.auth_branch_type IS NULL and auth.auth_branch_id IS NULL AND (auth.auth_fc_emp_id IS NOT NULL
              or auth.auth_mn_emp_id IS NOT NULL
              or auth.auth_dv_emp_id IS NOT NULL))
      ) 
      AND (
        ( auth.auth_fc_emp_id IS NULL
          and auth.auth_mn_emp_id IS NULL
          and auth.auth_dv_emp_id IS NULL
        )
        OR (
            (
               '2000'||REPLACE(ms.fc_full_name , ' ', '')  like   nvl(auth.auth_fc_emp_id,'-')||'%'               
              OR '70'||REPLACE(ms.mn_fullname, ' ', '') like  nvl(auth.auth_mn_emp_id,'-')||'%'                       
              OR '15'||REPLACE(ms.dv_fullname , ' ', '') like nvl(auth.auth_dv_emp_id,'-')||'%'      
            )
            and ( auth.auth_fc_emp_id IS NOT NULL
              or auth.auth_mn_emp_id IS NOT NULL
              or auth.auth_dv_emp_id IS NOT NULL
            )
          )
      
      )
  )
  INNER JOIN V_SML_NEWS_AUTH_STORE_USER U
  ON U.BRANCH_ID     = MS.BRANCH_ID 
  and u.group_id = auth.auth_group_id
  WHERE ms.data_type = '1'
  AND MS.ACTIVE_FLAG = 'Y';

-- ---------- MATERIALIZED_VIEW: V_SML_NEWS_AUTH_RULE_ONLY ----------
CREATE MATERIALIZED VIEW "FCS_FRN"."V_SML_NEWS_AUTH_RULE_ONLY" ("AUTH_ID", "TRANSACTION_PK", "USER_ID")
  SEGMENT CREATION IMMEDIATE
  ORGANIZATION HEAP PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255 
 NOCOMPRESS LOGGING  NO INMEMORY 
  BUILD IMMEDIATE
  USING INDEX 
  REFRESH COMPLETE ON DEMAND
  USING DEFAULT LOCAL ROLLBACK SEGMENT
  USING ENFORCED CONSTRAINTS DISABLE ON QUERY COMPUTATION DISABLE QUERY REWRITE
  AS SELECT auth."AUTH_ID",
    AUTH.TRANSACTION_PK,
    U.user_id
  FROM
    (SELECT au.auth_id,
      au.system_code,
      AU.AUTH_GROUP_ID,
      au.transaction_pk,
      au.table_transaction_pk,
      au.start_date,
      au.end_date,
      au1.auth_value AS auth_branch_type,
      au2.auth_value AS auth_region,
      au3.auth_value AS auth_branch_id,
      au4.auth_value AS auth_fc_emp_id,
      au5.auth_value AS auth_mn_emp_id,
      au6.auth_value AS auth_dv_emp_id
    FROM fcs_authorize au
    LEFT JOIN
      (SELECT aut1.* FROM fcs_authorize_trans aut1 WHERE aut1.auth_type = 1
      ) au1
    ON au1.auth_id = au.auth_id
    LEFT JOIN
      (SELECT aut1.* FROM fcs_authorize_trans aut1 WHERE aut1.auth_type = 2
      ) au2
    ON au2.auth_id = au.auth_id
    LEFT JOIN
      (SELECT aut1.* FROM fcs_authorize_trans aut1 WHERE aut1.auth_type = 3
      ) au3
    ON au3.auth_id = au.auth_id
    LEFT JOIN
      (SELECT aut1.*
      FROM fcs_authorize_trans aut1
      WHERE aut1.auth_type = 4
      AND AUTH_VALUE LIKE '2000%'
      ) au4
    ON au4.auth_id = au.auth_id
    LEFT JOIN
      (SELECT aut1.*
      FROM fcs_authorize_trans aut1
      WHERE aut1.auth_type = 4
      AND AUTH_VALUE LIKE '70%'
      ) au5
    ON au5.auth_id = au.auth_id
    LEFT JOIN
      (SELECT aut1.*
      FROM fcs_authorize_trans aut1
      WHERE aut1.auth_type = 4
      AND AUTH_VALUE LIKE '15%'
      ) au6
    ON au6.auth_id       = au.auth_id
    WHERE au.system_code = 'FML'
    AND TRUNC (SYSDATE) BETWEEN NVL (au.start_date, TRUNC (SYSDATE)) AND NVL (au.end_date, TRUNC (SYSDATE))
    ) auth
  INNER JOIN
    (SELECT s.branch_id,
      s.branch_name,
      s.branch_type,
      cc.code_value status_type,
      s.region,
      s.data_type,
      fc.emp_id   AS fc_emp_id,
      fc.fullname AS fc_full_name,
      mn.emp_id   AS mn_emp_id,
      mn.fullname AS mn_fullname,
      dv.emp_id   AS dv_emp_id,
      dv.fullname AS dv_fullname,
      S.ACTIVE_FLAG
    FROM mas_store s
    LEFT JOIN common_code cc
    ON cc.code_mapping = s.status_type
    AND cc.code_type   = '00019'
    LEFT JOIN mas_store_organize fc
    ON fc.branch_id    = s.branch_id
    AND s.active_flag  = 'Y'
    AND fc.active_flag = 'Y'
    AND fc.GROUP_ID    = 2000
    LEFT JOIN mas_store_organize mn
    ON mn.branch_id    = s.branch_id
    AND s.active_flag  = 'Y'
    AND mn.active_flag = 'Y'
    AND mn.GROUP_ID    = 70
    LEFT JOIN mas_store_organize dv
    ON dv.branch_id                      = s.branch_id
    AND s.active_flag                    = 'Y'
    AND dv.active_flag                   = 'Y'
    AND dv.GROUP_ID                      = 15
    ) ms ON NOT ( auth.auth_branch_type IS NULL
  AND auth.auth_region                  IS NULL
  AND auth.auth_branch_id               IS NULL
  AND auth.auth_fc_emp_id               IS NULL
  AND auth.auth_mn_emp_id               IS NULL
  AND auth.auth_dv_emp_id               IS NULL)
  AND ( ( ( ( ( ms.status_type           = auth.auth_branch_type
  AND auth.auth_region                  IS NULL)
  OR ( ms.region                         = auth.auth_region
  AND auth.auth_branch_type             IS NULL)
  OR ( ms.region                         = auth.auth_region
  AND ms.status_type                     = auth.auth_branch_type
  AND auth.auth_branch_type             IS NOT NULL
  AND auth.auth_region                  IS NOT NULL))
  AND auth.auth_branch_id               IS NULL)
  OR ( ms.branch_id                      = auth.auth_branch_id
  AND auth.auth_branch_id               IS NOT NULL)
  OR ( auth.auth_region                 IS NULL
  AND auth.auth_branch_type             IS NULL
  AND auth.auth_branch_id               IS NULL
  AND ( auth.auth_fc_emp_id             IS NOT NULL
  OR auth.auth_mn_emp_id                IS NOT NULL
  OR auth.auth_dv_emp_id                IS NOT NULL)))
  AND ( ( auth.auth_fc_emp_id           IS NULL
  AND auth.auth_mn_emp_id               IS NULL
  AND auth.auth_dv_emp_id               IS NULL)
  OR ( ( '2000'
    || REPLACE (ms.fc_full_name, ' ', '') LIKE NVL (auth.auth_fc_emp_id, '-')
    || '%'
  OR '70'
    || REPLACE (ms.mn_fullname, ' ', '') LIKE NVL (auth.auth_mn_emp_id, '-')
    || '%'
  OR '15'
    || REPLACE (ms.dv_fullname, ' ', '') LIKE NVL (auth.auth_dv_emp_id, '-')
    || '%')
  AND ( auth.auth_fc_emp_id IS NOT NULL
  OR auth.auth_mn_emp_id    IS NOT NULL
  OR auth.auth_dv_emp_id    IS NOT NULL))))
  LEFT JOIN
    (SELECT AUTH_GROUP_ID,
      COUNT (1) AS GROUP_AUTH
    FROM FCS_AUTHORIZE_GROUP_TRANS
    GROUP BY AUTH_GROUP_ID
    ) AT
  ON AT.AUTH_GROUP_ID = AUTH.AUTH_GROUP_ID
  INNER JOIN V_SML_NEWS_AUTH_STORE_USER U
  ON U.BRANCH_ID     = MS.BRANCH_ID
  WHERE GROUP_AUTH  IS NULL
  AND ms.data_type   = '1'
  AND MS.ACTIVE_FLAG = 'Y';

-- ---------- MATERIALIZED_VIEW: V_SML_NEWS_AUTH_STORE_USER ----------
CREATE MATERIALIZED VIEW "FCS_FRN"."V_SML_NEWS_AUTH_STORE_USER" ("BRANCH_ID", "USER_ID", "GROUP_ID")
  SEGMENT CREATION IMMEDIATE
  ORGANIZATION HEAP PCTFREE 10 PCTUSED 40 INITRANS 1 MAXTRANS 255 
 NOCOMPRESS LOGGING  NO INMEMORY 
  BUILD IMMEDIATE
  USING INDEX 
  REFRESH COMPLETE ON DEMAND
  USING DEFAULT LOCAL ROLLBACK SEGMENT
  USING ENFORCED CONSTRAINTS DISABLE ON QUERY COMPUTATION DISABLE QUERY REWRITE
  AS SELECT MSO.BRANCH_ID,
    U.USER_ID,
    U.GROUP_ID
  FROM mas_store_organize mso
  INNER JOIN
    (SELECT bu.user_id,
      bu.emp_id,
      bu.first_name,
      bu.last_name,
      NVL (bug.GROUP_ID, bu.GROUP_ID) AS GROUP_ID
    FROM business_user bu
    LEFT JOIN
      (SELECT DISTINCT user_id,
        GROUP_ID
      FROM business_user_group
      WHERE GROUP_ID IN (2000, 70, 15, 38, 28) --2000=FC, 70=MN, 15=DV, 38=GM, 28=VP
      ) bug
    ON bug.user_id                       = bu.user_id
    WHERE bu.active_flag                 = 'Y'
    AND (bu.GROUP_ID                    IN (2000, 70, 15, 38, 28)
    OR bug.GROUP_ID                     IN (2000, 70, 15, 38, 28))
    ) u ON u.GROUP_ID                    = mso.GROUP_ID
  AND (u.emp_id                          = mso.emp_id
  OR (INSTR (mso.fullname, u.first_name) > 0
  AND INSTR (mso.fullname, u.last_name)  > 0))
  WHERE mso.data_type                    = '1'
  AND mso.active_flag                    = 'Y'
  UNION ALL
  SELECT DISTINCT F.STORE_ID AS BRANCH_ID,
    u.user_id                AS USER_ID,
    U.GROUP_ID
  FROM FR_STORE F
  INNER JOIN
    (SELECT bu.user_id,
      bu.franchisee_id,
      bu.emp_id,
      bu.first_name,
      bu.last_name,
      NVL (bug.GROUP_ID, bu.GROUP_ID) AS GROUP_ID
    FROM business_user bu
    LEFT JOIN
      (SELECT DISTINCT user_id, GROUP_ID FROM business_user_group
      ) bug
    ON bug.user_id         = bu.user_id 
    WHERE bu.active_flag   = 'Y' 
    ) u ON U.franchisee_id = F.OWNER_ID1
  WHERE NVL(F.STATUS,'-') != 'D'
      and f.cancel_type = '00';


