-- ---------- FUNCTION: BLOB_TO_BASE64ENCODE_CLOB ----------
CREATE OR REPLACE EDITIONABLE FUNCTION "FCS_FRN"."BLOB_TO_BASE64ENCODE_CLOB" (p_blob IN BLOB)
  RETURN CLOB

IS
  l_clob CLOB;
  l_step PLS_INTEGER := 12000; -- make sure you set a multiple of 3 not higher than 24573
BEGIN
  FOR i IN 0 .. TRUNC((DBMS_LOB.getlength(p_blob) - 1 )/l_step) LOOP
    l_clob := l_clob || UTL_RAW.cast_to_varchar2(UTL_ENCODE.base64_encode(DBMS_LOB.substr(p_blob, l_step, i * l_step + 1)));
  END LOOP;
  RETURN l_clob;
END;
/

-- ---------- FUNCTION: DECODEBASE64 ----------
CREATE OR REPLACE EDITIONABLE FUNCTION "FCS_FRN"."DECODEBASE64" (InBase64Char IN CLOB) RETURN CLOB IS

    blob_loc BLOB;
    clob_trim CLOB;
    res CLOB;

    lang_context INTEGER := DBMS_LOB.DEFAULT_LANG_CTX;
    dest_offset INTEGER := 1;
    src_offset INTEGER := 1;
    read_offset INTEGER := 1;
    warning INTEGER;
    ClobLen INTEGER;

    amount INTEGER := 1440; -- must be a whole multiple of 4
    buffer RAW(1440);
    stringBuffer VARCHAR2(1440);
    -- BASE64 characters are always simple ASCII. Thus you get never any Mulit-Byte character and having the same size as 'amount' is sufficient

BEGIN
    IF DBMS_LOB.GETLENGTH(InBase64Char) IS NULL THEN 
        RETURN NULL;
    END IF;

    -- Remove all NEW_LINE from base64 string
    ClobLen := DBMS_LOB.GETLENGTH(InBase64Char);
    DBMS_LOB.CREATETEMPORARY(clob_trim, TRUE);
    LOOP
        EXIT WHEN read_offset > ClobLen;
        stringBuffer := REPLACE(REPLACE(DBMS_LOB.SUBSTR(InBase64Char, amount, read_offset), CHR(13), NULL), CHR(10), NULL);
        DBMS_LOB.WRITEAPPEND(clob_trim, LENGTH(stringBuffer), stringBuffer);
        read_offset := read_offset + amount;
    END LOOP;

    read_offset := 1;
    ClobLen := DBMS_LOB.GETLENGTH(clob_trim);
    DBMS_LOB.CREATETEMPORARY(blob_loc, TRUE);
    LOOP
        EXIT WHEN read_offset > ClobLen;
        buffer := UTL_ENCODE.BASE64_DECODE(UTL_RAW.CAST_TO_RAW(DBMS_LOB.SUBSTR(clob_trim, amount, read_offset)));
        DBMS_LOB.WRITEAPPEND(blob_loc, DBMS_LOB.GETLENGTH(buffer), buffer);
        read_offset := read_offset + amount;
    END LOOP;

    DBMS_LOB.CREATETEMPORARY(res, TRUE);
    DBMS_LOB.CONVERTTOCLOB(res, blob_loc, DBMS_LOB.LOBMAXSIZE, dest_offset, src_offset,  DBMS_LOB.DEFAULT_CSID, lang_context, warning);

    DBMS_LOB.FREETEMPORARY(blob_loc);
    DBMS_LOB.FREETEMPORARY(clob_trim);
    RETURN res;    

END DecodeBASE64; 
/

-- ---------- FUNCTION: ENCODEBASE64 ----------
CREATE OR REPLACE EDITIONABLE FUNCTION "FCS_FRN"."ENCODEBASE64" (InBase64Char IN CLOB) RETURN CLOB IS

    blob_loc BLOB;
    clob_trim CLOB;
    res CLOB;

    lang_context INTEGER := DBMS_LOB.DEFAULT_LANG_CTX;
    dest_offset INTEGER := 1;
    src_offset INTEGER := 1;
    read_offset INTEGER := 1;
    warning INTEGER;
    ClobLen INTEGER;

    amount INTEGER := 1440; -- must be a whole multiple of 4
    buffer RAW(1440);
    stringBuffer VARCHAR2(1440);
    -- BASE64 characters are always simple ASCII. Thus you get never any Mulit-Byte character and having the same size as 'amount' is sufficient

BEGIN
    IF DBMS_LOB.GETLENGTH(InBase64Char) IS NULL THEN 
        RETURN NULL;
    END IF;

    -- Remove all NEW_LINE from base64 string
    ClobLen := DBMS_LOB.GETLENGTH(InBase64Char);
    DBMS_LOB.CREATETEMPORARY(clob_trim, TRUE);
    LOOP
        EXIT WHEN read_offset > ClobLen;
        stringBuffer := REPLACE(REPLACE(DBMS_LOB.SUBSTR(InBase64Char, amount, read_offset), CHR(13), NULL), CHR(10), NULL);
        DBMS_LOB.WRITEAPPEND(clob_trim, LENGTH(stringBuffer), stringBuffer);
        read_offset := read_offset + amount;
    END LOOP;

    read_offset := 1;
    ClobLen := DBMS_LOB.GETLENGTH(clob_trim);
    DBMS_LOB.CREATETEMPORARY(blob_loc, TRUE);
    LOOP
        EXIT WHEN read_offset > ClobLen;
        buffer := UTL_ENCODE.BASE64_ENCODE(UTL_RAW.CAST_TO_RAW(DBMS_LOB.SUBSTR(clob_trim, amount, read_offset)));
        DBMS_LOB.WRITEAPPEND(blob_loc, DBMS_LOB.GETLENGTH(buffer), buffer);
        read_offset := read_offset + amount;
    END LOOP;

    DBMS_LOB.CREATETEMPORARY(res, TRUE);
    DBMS_LOB.CONVERTTOCLOB(res, blob_loc, DBMS_LOB.LOBMAXSIZE, dest_offset, src_offset,  DBMS_LOB.DEFAULT_CSID, lang_context, warning);

    DBMS_LOB.FREETEMPORARY(blob_loc);
    DBMS_LOB.FREETEMPORARY(clob_trim);
    RETURN res;    

END encodeBASE64;
/

-- ---------- FUNCTION: FUNC_FES_EVALUATE_PERIOD ----------
CREATE OR REPLACE EDITIONABLE FUNCTION "FCS_FRN"."FUNC_FES_EVALUATE_PERIOD" (
    v_fr_start_date  date,
    v_open_date date, 
    v_importdata_mm varchar2,
    v_importdata_yy varchar2, 
    v_return_type varchar2    
) 
RETURN varchar2 IS
    v_month_diff integer;    
    v_eva_midyear_period integer;
    v_period varchar2(6 char);
    v_eva_period varchar2(25 char);
    v_return_value varchar2(25 char);         
/******************************************************************************
   NAME:       FCS_FRN.FUNC_FES_EVALUATE_PERIOD
   PURPOSE:    for gathering evaluate period (only case "MIDYEAR")

   REVISIONS:
   Ver        Date        Author           Description
   ---------  ----------  ---------------  ------------------------------------
   1.0        19/1/2014  Kiet        1. Created this function.

   NOTES:

   Automatically available Auto Replace Keywords:
      Object Name:     FCS_FRN.FUNC_FES_EVALUATE_PERIOD
      Sysdate:         19/1/2014
      Date and Time:   19/1/2014, 17:29:21, and 19/1/2014 17:29:21
      Username:         (set in TOAD Options, Procedure Editor)
      Table Name:       (set in the "New PL/SQL Object" dialog)

******************************************************************************/
BEGIN
--    v_fr_start_date := sysdate;
--    v_open_date := add_months(sysdate,5);
    v_month_diff := ceil(trunc(months_between(trunc(v_open_date,'MM'), trunc(v_fr_start_date,'MM'))+1) / 6);

     dbms_output.put_line('v_fr_start_date = ' || to_char(v_fr_start_date,'DD/MM/YYYY'));
     dbms_output.put_line('v_open_date = ' || to_char(v_open_date,'DD/MM/YYYY'));
     dbms_output.put_line('v_month_diff = ' || v_month_diff);          
     
    if (v_month_diff > 0) and (v_importdata_mm is not null) and (v_importdata_yy is not null)  then
             
        for i in 1..v_month_diff loop
--            dbms_output.put_line(i); -- statements here execute 10 times
            dbms_output.put_line(to_char(add_months(v_fr_start_date, 6*i),'DD/MM/YYYY'));
--            dbms_output.put_line(to_char(add_months(v_fr_start_date, 6*i),'YYMM'));
            v_period := to_char(add_months(v_fr_start_date, 6*i),'YYYYMM');
        end loop;      
           
        v_eva_midyear_period := -6; 
        if (v_month_diff = 1) then
            if (to_char(v_fr_start_date,'DD') != '01') then
                v_eva_midyear_period := -5;
            end if;
        end if;
      
        if (to_date(v_importdata_mm || '/' || v_importdata_yy,'MM/YY') between add_months (to_date (v_period,'YYYYMM'), v_eva_midyear_period) and add_months (to_date (v_period,'YYYYMM'), -1)) then      
            v_eva_period := to_char (
                 add_months (to_date (v_period,'YYYYMM'), v_eva_midyear_period),
                 'FMMON YY',
                 'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI')
              || ' - '
              || to_char (
                    add_months (
                       to_date (v_period,'YYYYMM'), -1),
                    'FMMON YY',
                    'NLS_CALENDAR=''THAI BUDDHA'' NLS_DATE_LANGUAGE=THAI');        
        end if;   

    end if;     
    
    if (v_return_type = '1') then
        v_return_value := v_period;
    else
        v_return_value := v_eva_period;        
    end if;
    
    dbms_output.put_line('v_period = ' || v_period || ' ' || v_eva_period || ' ' || to_date(v_importdata_mm || '/' || v_importdata_yy,'MM/YY'));
    dbms_output.put_line(add_months (to_date (v_period,'YYYYMM'), v_eva_midyear_period) || ' ' || add_months (to_date (v_period,'YYYYMM'), -1) );
   RETURN v_return_value;
   
END FUNC_FES_EVALUATE_PERIOD;
/

-- ---------- FUNCTION: FUNC_FMP_DISPLAY_STATUS_EMP ----------
CREATE OR REPLACE EDITIONABLE FUNCTION "FCS_FRN"."FUNC_FMP_DISPLAY_STATUS_EMP" (
    V_OPT_STRUCTURE_FORMAT  VARCHAR2,
    V_END_DATE  DATE ,
    V_START_ROUND_DATE  DATE , 
    V_END_ROUND_DATE  DATE ,
    V_RESIGN_REASON_CODE VARCHAR2
    
) RETURN varchar2 IS
    v_status VARCHAR2(50 char ) := null;
    v_man_power float := to_number(V_OPT_STRUCTURE_FORMAT); 
    v_REASON_ID VARCHAR2(50 CHAR ):=to_char(V_RESIGN_REASON_CODE);
    V_EX_REASON_ID mas_param.param_value%type;
BEGIN
    
         BEGIN
              SELECT param_value  INTO V_EX_REASON_ID  FROM mas_param where param_name = 'RESIGN_RESON_CODE_EXCLUDE' and  param_value like '%'''||v_REASON_ID||'''%' ;
        EXCEPTION
          WHEN NO_DATA_FOUND THEN
            V_EX_REASON_ID := NULL;     
        END; 
    
         if( v_man_power != 0 ) then 
         
                 if( V_END_DATE is null ) then
                   v_status := 'ปฏิบัติงาน';
                else                                  
                     if( ( V_START_ROUND_DATE - V_END_DATE ) > 0  ) then 
                         v_status := 'ปฏิบัติงาน - ลาออกย้อนหลัง';
                     else 
                            if( ( V_END_DATE -  V_END_ROUND_DATE  ) > 0  ) then
                                      v_status := 'ปฏิบัติงาน - ลาออกล่วงหน้า';
                            else 
                                                        
                            if( V_RESIGN_REASON_CODE is null ) then
                                     v_status := 'โอนออก';
                            else 
                                       
                                    if( V_EX_REASON_ID is not null ) then
                                     v_status := 'ลาออก - ไม่นับ (ไม่นับอัตราการลาออก)' ;      
                                    else 
                                    v_status := 'ลาออก - นับ (นับอัตราการลาออก)' ;
                                   end if;
                            end if;
                        
                        end if;
                 end if;
             
             end if;                
           else 
            v_status := 'ไม่ปฏิบัติงาน';
         end if;
        
         
   RETURN v_status;
      
END FUNC_FMP_DISPLAY_STATUS_EMP;
/

