-- ---------- FUNCTION: FUNC_MANPOWER_ADJUST_TIME ----------
CREATE OR REPLACE EDITIONABLE FUNCTION "FCS_FRN"."FUNC_MANPOWER_ADJUST_TIME" (
    v_time                varchar2     
) RETURN float IS

    v_adjust_time float := 0;
    
BEGIN

          if(v_time >= 5 and v_time < 8) then
          
          v_adjust_time := v_time - 0.50;     
          
          else if( v_time >= 8) then
          
          v_adjust_time :=v_time - 1.00;       
          else 
          v_adjust_time :=v_time; 
          end if;          
          end if;
                  
   

   RETURN v_adjust_time;


   
END FUNC_MANPOWER_ADJUST_TIME;
/

-- ---------- FUNCTION: FUNC_MANPOWER_ROUND ----------
CREATE OR REPLACE EDITIONABLE FUNCTION "FCS_FRN"."FUNC_MANPOWER_ROUND" (
    v_manpower_total                varchar2     
) RETURN float IS

    v_manpower_round float := 0;
    v_decimal float:=0;
    v_manpower_positive float :=  trunc(v_manpower_total);

BEGIN
         v_decimal := v_manpower_total - v_manpower_positive;
         
          if(v_decimal > 0.00 and v_decimal < 0.50) then
          v_decimal := 0.50;
          else if(v_decimal > 0.50 and v_decimal < 1) then
          v_decimal := 1.00;      
          end if;          
          end if;          
          v_manpower_round := v_manpower_positive + v_decimal ;   
   RETURN v_manpower_round;

END FUNC_MANPOWER_ROUND;
/

-- ---------- FUNCTION: FUNC_RENEWAL_ROUND ----------
CREATE OR REPLACE EDITIONABLE FUNCTION "FCS_FRN"."FUNC_RENEWAL_ROUND" (
    v_fr_start_date                 date,
    v_contract_end_date     date,
    v_period_all                        varchar2     
) RETURN integer IS

    v_renewal_round integer := 0;

    v_period integer;
    v_year_diff integer;
    v_period_arr dbms_utility.lname_array;
    v_period_count integer;    

BEGIN

    /* split param "v_period" into array with comma separator  
    
        The list must be a non-empty comma-delimited list: Anything other than a comma-delimited list is rejected. Commas inside double quotes do not count.

        Entries in the comma-delimited list cannot include multibyte characters such as hyphens (-).

        The values in tab are cut from the original list, with no transformations.    
    */
    dbms_utility.comma_to_table ( 
        list           => regexp_replace(v_period_all,'(^|,)','\1x'),   --replace all numeric with prefix x for conversion numberic to string ex. "x1,x2,x3"
        tablen    => v_period_count, 
        tab          => v_period_arr
    );

    /* years between v_contract_end_date   */
     v_year_diff := trunc(trunc(months_between(v_contract_end_date, v_fr_start_date)) / 12);

     dbms_output.put_line('v_year_diff = ' || v_year_diff);
     dbms_output.put_line('v_renewal_round = ' || v_renewal_round);
     
    /* calculate round of renewal contract */     
    if (v_year_diff > 0) and (v_period_count > 0)  then             
    
        while v_year_diff > 0

            loop
         
                if (v_renewal_round < v_period_count) then
                    v_period := substr(v_period_arr(v_renewal_round + 1), 2);
                else
                    v_period := substr(v_period_arr(v_period_count), 2);                                                         
                end if; 
                
                v_year_diff := v_year_diff - v_period;
                v_renewal_round := v_renewal_round + 1;    
                           
                dbms_output.put_line('debug===> ' || v_renewal_round || ' | ' || v_year_diff || ' | ' || v_period);

                if (v_year_diff <= 0) then
                    exit;
                end if;
                
            end loop;              
    end if;     

   RETURN v_renewal_round;
   
END FUNC_RENEWAL_ROUND;
/

-- ---------- FUNCTION: FUNC_SML_GEN_DOC_NUM_COOP ----------
CREATE OR REPLACE EDITIONABLE FUNCTION "FCS_FRN"."FUNC_SML_GEN_DOC_NUM_COOP" 
(
  V_REGION IN VARCHAR2 
, V_STORE_ID IN VARCHAR2
) RETURN VARCHAR2 AS 
V_DOC_NUM VARCHAR2(25 CHAR);
BEGIN

    select NVL(V_REGION,'XX') 
        || ' ' || LPAD(V_STORE_ID, 5, '0')
        || '.'
        || lpad(nvl((
                select count(store_id)+1 count
                from fml_cooperation_trn
                where year =  to_char(sysdate, 'yyyy')
                and store_id = V_STORE_ID
                and doc_number is not null
                group by store_id)
                ,1),2,'0')
        ||'/' || to_char(sysdate, 'yyyy') into V_DOC_NUM
    FROM DUAL;

RETURN V_DOC_NUM;

END FUNC_SML_GEN_DOC_NUM_COOP;
/

