-- ---------- FUNCTION: FX_FMS_GEN_PROCESS_ID ----------
CREATE OR REPLACE EDITIONABLE FUNCTION "FCS_FRN"."FX_FMS_GEN_PROCESS_ID" (
 v_name_process_id_running_no varchar2,
 v_process_type varchar2
) RETURN VARCHAR2 IS
PRAGMA AUTONOMOUS_TRANSACTION;
/******************************************************************************
   NAME:       FX_FMS_GEN_PROCESS_ID
   PURPOSE:    Generate process id for FMS process [ NEW STORE , EXPAND STORE , EXTEND CONTRACT]

   REVISIONS:
   Ver        Date        Author           Description
   ---------  ----------  ---------------  ------------------------------------
   1.0        3/3/2016   supakitmad       1. Created this function. 

******************************************************************************/

    v_year integer;
    v_month integer;
    v_running_no integer;    
    v_yyyymm integer;
    v_sys_yyyymm integer;    
    v_process_id VARCHAR2(15 BYTE);
BEGIN
     
    select param_value into v_year from mas_param where ref_name = 'FMS_PROCESS_ID' and param_name = 'FMS_PROCESS_ID_YEAR';
    select param_value into v_month from mas_param where ref_name = 'FMS_PROCESS_ID' and param_name = 'FMS_PROCESS_ID_MONTH';
    select param_value into v_running_no from mas_param where ref_name = 'FMS_PROCESS_ID' and param_name = v_name_process_id_running_no;
    
    v_yyyymm := to_number(v_year || lpad(v_month,2,'0'));
    v_sys_yyyymm := to_number(to_char(sysdate,'YYYYMM'));
    
    if (v_yyyymm != v_sys_yyyymm) then
        v_running_no := 1;         
   
    update mas_param 
    set param_value = decode( param_name , v_name_process_id_running_no ,  v_running_no+1 ,  v_running_no )
    where ref_name = 'FMS_PROCESS_ID'
    and param_name in ('FMS_PROCESS_ID1_RUNNING_NO','FMS_PROCESS_ID2_RUNNING_NO','FMS_PROCESS_ID3_RUNNING_NO');  
    else
    
    update mas_param 
    set param_value = v_running_no+1
    where ref_name = 'FMS_PROCESS_ID'
        and param_name = v_name_process_id_running_no;
        
    end if;
    
    if ( v_process_type = '1' ) then
        v_process_id := to_char(v_sys_yyyymm) || lpad(to_char(v_running_no),5,'0');
    else
        v_process_id := lpad(v_process_type,2,'0')||to_char(v_sys_yyyymm) || lpad(to_char(v_running_no),5,'0');
    end if;
        
    update mas_param 
    set param_value = substr(v_sys_yyyymm, 1, 4)
    where ref_name = 'FMS_PROCESS_ID'
        and param_name = 'FMS_PROCESS_ID_YEAR';  

    update mas_param 
    set param_value = substr(v_sys_yyyymm, 5, 2)
    where ref_name = 'FMS_PROCESS_ID'
        and param_name = 'FMS_PROCESS_ID_MONTH';
    
    commit;

    dbms_output.put_line('v_process_id=' || v_process_id);
        
    return (v_process_id);        

END FX_FMS_GEN_PROCESS_ID; 
/

