-- ---------- FUNCTION: F_POJO ----------
CREATE OR REPLACE EDITIONABLE FUNCTION "FCS_FRN"."F_POJO" (TABLE_NAME IN varchar2(255))
   RETURN varchar2(4000)
   IS result varchar2(4000);
   BEGIN 
     SELECT 'private String ' ||
        SUBSTR(REPLACE(INITCAP('a' || LOWER(T1.COLUMN_NAME)), '_', ''), 2) || ';' ||
                 SUBSTR(T2.COMMENTS,1,20) pojo into result
  FROM USER_TAB_COLUMNS T1
  LEFT JOIN USER_COL_COMMENTS T2
    ON T1.TABLE_NAME = T2.TABLE_NAME
   AND T1.COLUMN_NAME = T2.COLUMN_NAME
   WHERE T1.TABLE_NAME = UPPER('WF_STEP_HISTORY');
     return (result);
 END;
/

