-- ---------- FUNCTION: GET_BLOB_FILE_FOR_K2 ----------
CREATE OR REPLACE EDITIONABLE FUNCTION "FCS_FRN"."GET_BLOB_FILE_FOR_K2" (v_table_name VARCHAR2, v_file_name_column_name VARCHAR2, v_blob_column_name VARCHAR2, v_where_clause VARCHAR2)
RETURN INTEGER
--RETURN CLOB
IS

    v_file_name                     VARCHAR2(500);
    v_content_type              VARCHAR2 (100);
    v_file_content                  BLOB;
    v_file_content_clob      CLOB;
    v_file_data_type_k2     CLOB;
    v_clob_k2_id                   INTEGER  :=  0;      --{0 : FAIL, >0 : ID}
    v_k2_data_type_tag     VARCHAR2 (20);   --{image | file} 
    stmt_str                              CLOB;
    
BEGIN

    begin
    
        /*===select blob (file) from target table===*/
        stmt_str := ' SELECT ' || v_file_name_column_name || ', ' || v_blob_column_name ||
                            ' FROM ' || v_table_name || 
                            ' WHERE 1=1 ' ||  v_where_clause;
        
        dbms_output.put_line('Query: ' || stmt_str);
        execute immediate stmt_str into v_file_name, v_file_content;

        /*===get file's content_type===*/
        select lower(code_name) into v_content_type
        from common_code
        where code_type = 'FILE_CONTENT_TYPE'
            and code_value = lower(
                substr(
                    v_file_name, 
                    instr(v_file_name, '.') + 1
                )        
            );  

        execute immediate(stmt_str);

        if (instr(v_content_type, 'image') > 0) then
            v_k2_data_type_tag := 'image';
        else
            v_k2_data_type_tag := 'file';            
        end if;        

        /*===convert blob to clob (K2 data format)===*/        
        v_file_content_clob := blob_to_base64encode_clob(v_file_content);
        
        v_file_data_type_k2 := '<' || v_k2_data_type_tag || '>' ||
                                                    '<name>' || v_file_name || '</name>' ||
                                                    '<content>' || v_file_content_clob || '</content>' ||
                                                    '</' || v_k2_data_type_tag || '>'; 
        
        /*===insert clob (K2 data format) into tmp table for K2 usage===*/
        select FCS_TMP_BLOB_TO_CLOB_K2_SEQ.nextval into v_clob_k2_id from dual;        

        insert into FCS_TMP_BLOB_TO_CLOB_K2 
        (ID, CONTENT_CLOB)
        values
        (v_clob_k2_id, v_file_data_type_k2);

        delete from FCS_TMP_BLOB_TO_CLOB_K2 where create_date < sysdate;

        commit;
        
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            dbms_output.put_line('GET_BLOB_FILE_FOR_K2 - NO_DATA_FOUND');
            v_file_data_type_k2 := NULL;
        WHEN OTHERS THEN                     
            dbms_output.put_line('GET_BLOB_FILE_FOR_K2 error - '||SQLCODE||' -ERROR- ' || SQLERRM);
            v_file_data_type_k2 := NULL;
            rollback;
    end;

RETURN v_clob_k2_id;
--RETURN v_file_data_type_k2;

END GET_BLOB_FILE_FOR_K2;
/

-- ---------- FUNCTION: GET_BLOB_FROM_BASE64_STRING ----------
CREATE OR REPLACE EDITIONABLE FUNCTION "FCS_FRN"."GET_BLOB_FROM_BASE64_STRING" (p_clob CLOB)
RETURN BLOB
IS
l_chunk BLOB; --Chunks of decoded blob that'll be appended
l_result BLOB; --Final blob result to be returned
l_rawout RAW (32767); --Decoded raw data from first pass decode
l_rawin RAW (32767); --Encoded raw data chunk
l_amt NUMBER DEFAULT 7700;
--Default length of data to decode
l_offset NUMBER DEFAULT 1;
--Default Offset of data to decode
l_tempvarchar VARCHAR2 (32767);
BEGIN
    BEGIN
        DBMS_LOB.createtemporary (l_result, FALSE, DBMS_LOB.CALL);
        DBMS_LOB.createtemporary (l_chunk, FALSE, DBMS_LOB.CALL);
        LOOP
        --dbms_output.put_line('get_blob_from_base64_string : loop');
        DBMS_LOB.READ (p_clob, l_amt, l_offset, l_tempvarchar);
        l_offset := l_amt + l_offset;
        l_rawin := UTL_RAW.cast_to_raw (l_tempvarchar);
        l_rawout := UTL_ENCODE.base64_decode (l_rawin);
        l_chunk := to_blob (l_rawout);
        DBMS_LOB.append (l_result, l_chunk);
        END LOOP;

        dbms_output.put_line(utl_raw.cast_to_varchar2( dbms_lob.substr( l_result, 32000, 1 ) ));

        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                dbms_output.put_line('get_blob_from_base64_string : NO_DATA_FOUND');
    end;

return l_result;

END get_blob_from_base64_string;
/

-- ---------- FUNCTION: INSERT_FILE_FOR_K2 ----------
CREATE OR REPLACE EDITIONABLE FUNCTION "FCS_FRN"."INSERT_FILE_FOR_K2" (v_k2_data_type_file CLOB, v_table_name VARCHAR2, v_where_clause VARCHAR2)
RETURN INTEGER
IS

    v_result                        INTEGER := 0;                 --{0=FAIL, 1=PASS}
    v_file_name               VARCHAR2 (300);
    v_content_type         VARCHAR2 (100);
    v_file_content            CLOB;
    v_blob                          BLOB;
    
    EXP_FILE_NAME   EXCEPTION;
    EXP_CONTENT     EXCEPTION;
    
    stmt_str                        CLOB;
    
BEGIN

    /*
    example "v_k2_data_type_file" from K2
    <file><name>MyFile.pdf</name><content>//5VAFMARQAgAFsAQgBUAF0ADQAKAEcATwANAAoASQBOAFMARQBSAFQ</content></file>  
    */

    BEGIN
        v_file_name := substr(v_k2_data_type_file, instr(v_k2_data_type_file, '<name>')+length('<name>'), instr(v_k2_data_type_file, '</name>') - (instr(v_k2_data_type_file, '<name>')+length('<name>')));
        v_file_content := substr(v_k2_data_type_file, instr(v_k2_data_type_file, '<content>')+length('<content>'), instr(v_k2_data_type_file, '</content>') - (instr(v_k2_data_type_file, '<content>')+length('<content>')));    

--        v_file_name := NULL;
--        v_file_content := NULL;

        if (v_file_name is null) then
            RAISE  EXP_FILE_NAME;
        end if;

        if (v_file_content is null) then
            RAISE  EXP_CONTENT;
        end if;

        /*===get file's content_type===*/
        select code_name into v_content_type
        from common_code
        where code_type = 'FILE_CONTENT_TYPE'
            and code_value = lower(
                substr(
                    v_file_name, 
                    instr(v_file_name, '.') + 1
                )        
            );  

        IF SQL%NOTFOUND THEN
          DBMS_OUTPUT.PUT_LINE('No such record : ' || v_where_clause);
          RAISE NO_DATA_FOUND;
        END IF;

        /*===update file's data into target table===*/
        stmt_str := ' update ' || v_table_name || ' set ' ||
                            '   file_name = :file_name ' || ', ' ||
                            '   content_type = :content_type ' || ', ' ||
                            '   content = :file_content ' ||
                            ' where 1=1 ' || v_where_clause;

        dbms_output.put_line('stmt_str=' || stmt_str);
        dbms_output.put_line('v_file_name=' || v_file_name);
--        dbms_output.put_line('v_file_content=' || v_file_content);        //may be error some content

        v_blob := GET_BLOB_FROM_BASE64_STRING(v_file_content);

        execute immediate(stmt_str) using v_file_name, v_content_type, v_blob;

        IF SQL%NOTFOUND THEN
          DBMS_OUTPUT.PUT_LINE('No such record : ' || v_where_clause);
          RAISE NO_DATA_FOUND;
        END IF;

        commit;
        
        v_result := 1;
        
    EXCEPTION 
        WHEN EXP_FILE_NAME THEN
                    dbms_output.put_line('INSERT_FILE_FOR_K2 - file_name is null');
        WHEN EXP_CONTENT THEN
                    dbms_output.put_line('INSERT_FILE_FOR_K2 - content is null');                
        WHEN NO_DATA_FOUND THEN
                    dbms_output.put_line('INSERT_FILE_FOR_K2 - NO_DATA_FOUND');           
    END;       
                         
RETURN v_result;

END INSERT_FILE_FOR_K2;
/

