-- ---------- PROCEDURE: BL_MOVE_DATA ----------
CREATE OR REPLACE EDITIONABLE PROCEDURE "FCS_FRN"."BL_MOVE_DATA" 
IS
BEGIN
    -- Create Save point
    SAVEPOINT save_point;
    
    -- Move Statement_file
    INSERT INTO fml_bellinee_statement_file
        SELECT fr.*
        FROM fml_franchise_statement_file fr
            INNER JOIN bellinee_store_organize bl
        ON fr.store_id=bl.branch_id;
    
    DELETE FROM fml_franchise_statement_file 
    WHERE store_id in
        (
            SELECT store_id FROM fml_bellinee_statement_file
        );
    
    -- Move Statement
    INSERT INTO fml_bellinee_statement
        SELECT fr.* 
        FROM fml_franchise_statement fr
            INNER JOIN bellinee_store_organize bl
        ON fr.store_id=bl.branch_id;
        
    DELETE FROM fml_franchise_statement
    WHERE store_id in
        (
            SELECT store_id FROM fml_bellinee_statement
        );
            
    -- Move STMT
    INSERT INTO fml_stacc_bl_stmt
        SELECT fr.*
        FROM fml_stacc_fr_stmt fr
            INNER JOIN bellinee_store_organize bl
        ON fr.branch=bl.branch_id;
        
    DELETE FROM fml_stacc_fr_stmt
    WHERE branch in
        (
            SELECT branch FROM fml_stacc_bl_stmt
        );
    
    -- Move STMT_END
    INSERT INTO fml_stacc_bl_stmt_end
        SELECT fr.*
        FROM fml_stacc_fr_stmt_end fr
            INNER JOIN fml_stacc_bl_stmt bl
        ON fr.process_id=bl.process_id;
        
    DELETE FROM fml_stacc_fr_stmt_end
    WHERE process_id in
        (
            SELECT process_id FROM fml_stacc_bl_stmt_end
        );
            
    COMMIT;
    
    -- Exception
    EXCEPTION
        WHEN OTHERS THEN
            BEGIN
                ROLLBACK TO save_point;
            END;
END;
/

-- ---------- PROCEDURE: COPYFESVALUE ----------
CREATE OR REPLACE EDITIONABLE PROCEDURE "FCS_FRN"."COPYFESVALUE" (
