END COPYFESVALUE;
/

-- ---------- PROCEDURE: COPYFESVALUE_20170203 ----------
CREATE OR REPLACE EDITIONABLE PROCEDURE "FCS_FRN"."COPYFESVALUE_20170203" (
    v_store_id_old integer, 
    v_store_id_new integer, 
    v_eval_start_yyyym integer, 
    v_eval_end_yyyym integer, 
    v_imp_start_yymm integer, 
    v_imp_end_yymm integer,
    v_fr_store_order_id integer
) IS

/******************************************************************************
   NAME:       FCS_FRN.copyFESValue
   PURPOSE:    

   REVISIONS:
   Ver        Date        Author           Description
   ---------  ----------  ---------------  ------------------------------------
   2.0        08/11/2013    Kiettichai C.          1. Created this procedure.

   NOTES:
    for copying evaluated data from old store id to new store id

******************************************************************************/
--DECLARE

--    v_eval_start_yyyym varchar(6) := v_eval_end_yyyym; 

BEGIN
    
--    if (v_eval_round = 1) then
--        v_eval_start_yyyym := to_char(add_months(to_date(v_eval_end_yyyym || '01', 'YYYYMMDD'), -4),'YYYY') || to_number(to_char(add_months(to_date(v_eval_end_yyyym || '01', 'YYYYMMDD'), -4),'MM'));
--    end if;

insert into fr_store_insure
(order_id, store_id, seq_no, year, month, money_support, split, create_date, create_user, update_date, update_user)
(
    select v_fr_store_order_id, v_store_id_new, si.seq_no, si.year, si.month, si.money_support, si.split, si.create_date, si.create_user, si.update_date, si.update_user
    from fr_store_insure si
    where si.order_id in (
        select s.parent_order_id
        from fr_store s
        where s.order_id = v_fr_store_order_id
            and s.parent_order_id is not null
    )
); 


insert into fr_store_assessment
(order_id, store_id, year_no, seq_no, score, grade, update_date, update_user, create_date, create_user )
(
    select v_fr_store_order_id, v_store_id_new, sa.year_no, sa.seq_no, sa.score, sa.grade, sa.update_date, sa.update_user, sa.create_date, sa.create_user 
    from fr_store_assessment sa
    where sa.order_id in (
        select s.parent_order_id
        from fr_store s
        where s.order_id = v_fr_store_order_id
            and s.parent_order_id is not null
    )    
);

    
insert into fes_evaluate (
    evaluate_id, eval_type, send_date, order_id, note, 
    eval_month, eval_year, evaluatedform_id, create_id, create_date, 
    modify_id, modify_date, total_point, grade, status, 
    description,fr_store_order_id
)
(
    select 
        SEQ_FESEVALUATE.NextVal, eval_type, send_date, v_store_id_new, note,
        eval_month, eval_year, evaluatedform_id, create_id, create_date, 
        modify_id, modify_date, total_point, grade, status, 
        description,v_fr_store_order_id
    from fes_evaluate a
    where a.order_id = v_store_id_old 
        and (
            a.del_status is null
            or (
                a.status_temp is null
                and a.fr_store_order_id in (
                    select s.parent_order_id
                    from fr_store s
                    where s.order_id = v_fr_store_order_id
                        and s.parent_order_id is not null
                )
            )
        )             
--        and a.eval_year || a.eval_month >= v_eval_start_yyyym        
--        and a.eval_year || a.eval_month <= v_eval_end_yyyym
);


insert into fes_evaluatedperson ( 
    evaluatedperson_id, user_id, status, eval_date, eval_user, 
    submit_date, submit_user, approve_date, approve_user, verify_date, 
    verify_user, evaluate_id, create_id, create_date, modify_id, 
    modify_date
)
(
    select
        SEQ_FESEVALUATEDPERSON.NextVal, b.user_id, b.status, b.eval_date, b.eval_user,  
        b.submit_date, b.submit_user, b.approve_date, b.approve_user, b.verify_date, 
        b.verify_user, eva.evaluate_id, b.create_id, b.create_date, b.modify_id, 
        b.modify_date    
    from fes_evaluate a
        inner join fes_evaluate eva on eva.eval_type = a.eval_type 
            and eva.eval_month = a.eval_month
            and eva.eval_year = a.eval_year
            and eva.evaluatedform_id = a.evaluatedform_id
            and eva.fr_store_order_id = v_fr_store_order_id
        inner join fes_evaluatedperson b on b.evaluate_id = a.evaluate_id 
    where a.order_id = v_store_id_old    
        and (
            a.del_status is null
            or (
                a.status_temp is null
                and a.fr_store_order_id in (
                    select s.parent_order_id
                    from fr_store s
                    where s.order_id = v_fr_store_order_id
                        and s.parent_order_id is not null
                )
            )        
        )        
--        and a.eval_year || a.eval_month >= v_eval_start_yyyym        
--        and a.eval_year || a.eval_month <= v_eval_end_yyyym
);


insert into fes_copylvtwo (
    copylvtwo_id, point, evalleveltwo_id, evaluate_id
) 
(
    select
        SEQ_FESCOPYLVTWO.NextVal, b.point, b.evalleveltwo_id, eva.evaluate_id
    from fes_evaluate a
        inner join fes_evaluate eva on eva.eval_type = a.eval_type 
            and eva.eval_month = a.eval_month
            and eva.eval_year = a.eval_year
            and eva.evaluatedform_id = a.evaluatedform_id
            and eva.fr_store_order_id = v_fr_store_order_id    
        inner join fes_copylvtwo b on b.evaluate_id = a.evaluate_id
    where a.order_id = v_store_id_old
        and (
            a.del_status is null
            or (
                a.status_temp is null
                and a.fr_store_order_id in (
                    select s.parent_order_id
                    from fr_store s
                    where s.order_id = v_fr_store_order_id
                        and s.parent_order_id is not null
                )
            )            
        )                  
--        and a.eval_year || a.eval_month >= v_eval_start_yyyym        
--        and a.eval_year || a.eval_month <= v_eval_end_yyyym
);


insert into fes_copylvthree (
    copylvthree_id, point, evallevelthree_id, evaluate_id
)
(
        select SEQ_FESCOPYLVTHREE.NextVal, b.point, b.evallevelthree_id, eva.evaluate_id
        from fes_evaluate a
            inner join fes_evaluate eva on eva.eval_type = a.eval_type 
                and eva.eval_month = a.eval_month
                and eva.eval_year = a.eval_year
                and eva.evaluatedform_id = a.evaluatedform_id
                and eva.fr_store_order_id = v_fr_store_order_id            
            inner join fes_copylvthree b on b.evaluate_id = a.evaluate_id 
        where a.order_id = v_store_id_old
            and (
                a.del_status is null
                or (
                    a.status_temp is null
                    and a.fr_store_order_id in (
                        select s.parent_order_id
                        from fr_store s
                        where s.order_id = v_fr_store_order_id
                            and s.parent_order_id is not null
                    )
                )            
            )                      
--            and a.eval_year || a.eval_month >= v_eval_start_yyyym        
--            and a.eval_year || a.eval_month <= v_eval_end_yyyym                         
);  


delete from fes_importdata b
