-- ---------- PROCEDURE: FML_PURGE_SBP_PROFILE ----------
CREATE OR REPLACE EDITIONABLE PROCEDURE "FCS_FRN"."FML_PURGE_SBP_PROFILE" AS
v_franchisee_id  NUMBER;
v_start_date     DATE ; 
v_row_del        NUMBER;        
v_row_ins        NUMBER;
v_row_clear      NUMBER; 
v_acction        varchar2(25);
v_owner          varchar2(50) := 'FCS_FRN';
v_franchisee_list   VARCHAR2(4000);
v_sql_ins           VARCHAR2(4000);
v_sql_del           VARCHAR2(4000);
v_sql_clear         VARCHAR2(4000);
v_err_code       NUMBER; 	
v_err_msg        VARCHAR2(255);
v_tbname         VARCHAR2(255);

CURSOR getTable IS
    SELECT PARAM_VALUE FROM MAS_PARAM 
    WHERE PARAM_NAME = 'FML_PURGE_TABLE'
    AND ACTIVE_FLAG = 'Y';

PROCEDURE procress(v_tablename IN VARCHAR2,v_in_franchisee_list IN VARCHAR2) IS
BEGIN

     if length(v_in_franchisee_list) > 0  then

			 v_start_date := SYSDATE;
			 v_acction := 'BACKUP' ;

			 v_sql_ins := 'INSERT INTO ' || v_owner ||'.'||v_tablename||'_BACKUP' 
              ||' SELECT FC.* , SYSDATE FROM ' ||v_owner ||'.'||v_tablename ||' FC WHERE FC.FRANCHISEE_ID in ( '||v_in_franchisee_list || ')' ;
			EXECUTE IMMEDIATE v_sql_ins ; 
			v_row_ins := sql%rowcount ;	  	 	 

			insert into fml_purge_log( start_date,end_date,table_owner,table_name,action_type,job_status,records_row,sql_code,sql_errm,ref_1)
			values(v_start_date,SYSDATE,v_owner,v_tablename,v_acction,'SUCCESS',v_row_ins,null,null,v_in_franchisee_list);

            v_start_date := SYSDATE ;
			v_acction := 'PURGE' ;
            v_sql_del := 'DELETE FROM ' || v_owner ||'.'||v_tablename || ' WHERE FRANCHISEE_ID in ( '||v_in_franchisee_list || ')' ;			
			EXECUTE IMMEDIATE v_sql_del ;
			v_row_del := sql%rowcount ;	  	 	 

            insert into fml_purge_log( start_date,end_date,table_owner,table_name,action_type,job_status,records_row,sql_code,sql_errm,ref_1)
			values(v_start_date,SYSDATE,v_owner,v_tablename,v_acction,'SUCCESS',v_row_del,null,null,v_in_franchisee_list);  

            v_start_date := SYSDATE ;
			v_acction := 'CLEAR_BACKUP' ;
            v_sql_clear := 'DELETE FROM ' || v_owner ||'.'||v_tablename||'_BACKUP ' || ' WHERE sysdate - backup_date >= 30 ' ;			
			EXECUTE IMMEDIATE v_sql_clear ;
            v_row_clear := sql%rowcount ;	  	 	

			insert into fml_purge_log( start_date,end_date,table_owner,table_name,action_type,job_status,records_row,sql_code,sql_errm)
			values(v_start_date,SYSDATE,v_owner,v_tablename||'_BACKUP',v_acction,'SUCCESS',v_row_clear,null,null);
		    commit;  
    end if;
EXCEPTION
    WHEN OTHERS THEN
         rollback;
           v_err_code := SQLCODE ;
           v_err_msg := SUBSTR(SQLERRM, 1, 255);
        INSERT INTO FCS_FRN.FML_PURGE_LOG(START_DATE,END_DATE,TABLE_OWNER,TABLE_NAME,ACTION_TYPE,JOB_STATUS,RECORDS_ROW,SQL_CODE,SQL_ERRM)
        VALUES(v_start_date,SYSDATE,v_owner,v_tablename,v_acction,'ERROR',NULL,v_err_code,v_err_msg);
        COMMIT;
END procress;

BEGIN

    SELECT DISTINCT LISTAGG(S.OWNER_ID1, ', ') WITHIN GROUP (ORDER BY S.OWNER_ID1) 
     into v_franchisee_list 
      FROM (
            select s.owner_id1
            from fr_store  s
            left join sevenshop fssv on ( s.store_id = fssv.branch_id  and fssv.branch_id is null )
            inner join franchisee fs on  s.owner_id1 = fs.franchisee_id
            having  trunc(sysdate -  max(contract_end_date)) >= 3620
            group by owner_id1 ) S;
            
   for i in getTable
      LOOP
        procress(i.PARAM_VALUE,v_franchisee_list);
      END LOOP;

END;
/

-- ---------- PROCEDURE: FMP_PREPAREINCENTIVEROUND1 ----------
CREATE OR REPLACE EDITIONABLE PROCEDURE "FCS_FRN"."FMP_PREPAREINCENTIVEROUND1" AS
v_seq_fmp       NUMBER; 

CURSOR getData IS
SELECT *
  FROM (WITH employee_detail AS (SELECT fr.store_id,
                                        de.employee_id,
                                        de.position_name,
                                        de.position_id,
                                        emp.first_name || ' ' || emp.last_name AS emp_name,
                                        fr.store_name,
                                        fr.start_date,
                                        fr.start_date_display,
                                        Decode(fr.region, NULL, ms.region, fr.region) region,
                                        Decode(fr.fr_type, NULL, cct.code_value, fr.fr_type) fr_type,
                                        bu.user_id dv_user_id,
                                        mso.fullname dv_name,
                                        de.start_date emp_start_date,
                                        de.end_date emp_end_date,
                                        Min(ad.business_date) AS start_clock_date,
                                        cca.code_name incentive_amount,
                                        Nvl(inc.inc_status, 2) incentive_received,
                                        mp.param_value remark,
                                        fr.order_id,
                                        To_date('20/05/2020', 'DD/MM/YYYY') end_period_clock_date,
                                        mso.group_id
                                   FROM (SELECT CASE
                                                  WHEN start_date BETWEEN To_date('22/03/2020', 'DD/MM/YYYY') AND
                                                       To_date('20/04/2020', 'DD/MM/YYYY') THEN
                                                   '202004'
                                                  ELSE
                                                   '202005'
                                                END period,
                                                s.*
                                           FROM (SELECT (CASE
                                                          WHEN (level = 1 AND to_open_date IS NULL) THEN
                                                           1
                                                          WHEN level = 2 THEN
                                                           1
                                                          ELSE
                                                           3
                                                        END) flag,
                                                        level AS lvl,
                                                        row_number() OVER(partition BY connect_by_root store_id ORDER BY level ASC, order_id DESC) r,
                                                        connect_by_root store_id AS store_id,
                                                        connect_by_root order_id AS order_id,
                                                        connect_by_root store_name AS store_name,
                                                        connect_by_root region AS region,
                                                        connect_by_root fr_type AS fr_type,
                                                        decode(to_open_date, NULL, connect_by_root start_date, to_open_date) AS start_date,
                                                        connect_by_root start_date AS start_date_display,
                                                        connect_by_root cancel_type AS cancel_type,
                                                        connect_by_root cancel_date AS,
                                                        connect_by_root status AS status,
                                                        add_months(decode(to_open_date,
                                                                          NULL,
                                                                          connect_by_root start_date,
                                                                          to_open_date),
                                                                   -4),
                                                        add_months(decode(to_open_date,
                                                                          NULL,
                                                                          connect_by_root start_date,
                                                                          to_open_date),
                                                                   -1)
                                                   FROM fr_store
                                                  WHERE (to_open_date BETWEEN to_date('22/03/2020', 'DD/MM/YYYY') AND
                                                        to_date('21/04/2020', 'DD/MM/YYYY') OR connect_by_root
                                                         start_date BETWEEN to_date('22/03/2020', 'DD/MM/YYYY') AND
                                                         to_date('21/04/2020', 'DD/MM/YYYY'))
                                                        AND connect_by_root
                                                  nvl(cancel_type, '-') NOT IN ('01', '02', '03', '04', '08')
                                                        AND level <= 2
                                                 connect BY prior parent_order_id = order_id) s
                                          WHERE r = 1
                                                AND flag = 1) fr
                                   LEFT JOIN fmp_employee_detail de
                                     ON de.store_id = fr.store_id
                                        AND de.year || de.month BETWEEN '202004' AND '202005'
                                        AND de.position_id IN ('1', '2', '3', '4')
                                        AND de.department_id = 'E'
                                        AND de.year || de.month = fr.period
                                   LEFT JOIN fmp_employee emp
                                     ON emp.id = de.fmp_employee_id
                                   LEFT JOIN fmp_employee_attendance ad
                                     ON de.store_id = ad.store_id
                                        AND de.employee_id = ad.employee_id
                                        AND ad.business_date >= fr.start_date
                                   LEFT JOIN (SELECT de.employee_id,
                                                    CASE
                                                      WHEN nvl(sum(decode(inc.incentive_company,
                                                                          NULL,
                                                                          inc.incentive_sbp,
                                                                          inc.incentive_company)),
                                                               0) > 0 THEN
                                                       1
                                                      ELSE
                                                       2
                                                    END inc_status,
                                                    CASE
                                                      WHEN nvl(sum(decode(inc.incentive_company,
                                                                          NULL,
                                                                          inc.incentive_sbp,
                                                                          inc.incentive_company)),
                                                               0) > 0 AND de.position_id IN ('1', '2') THEN
                                                       1
                                                      WHEN nvl(sum(decode(inc.incentive_company,
                                                                          NULL,
                                                                          inc.incentive_sbp,
                                                                          inc.incentive_company)),
                                                               0) > 0 AND de.position_id IN ('3', '4') THEN
                                                       2
                                                      ELSE
                                                       0
                                                    END amount_id
                                               FROM (SELECT *
                                                       FROM (SELECT '1' AS idx,
                                                                    (CASE
                                                                      WHEN (level = 1 AND to_open_date IS NULL) THEN
                                                                       1
                                                                      WHEN level = 2 THEN
                                                                       1
                                                                      ELSE
                                                                       3
                                                                    END) flag,
                                                                    level AS lvl,
                                                                    row_number() OVER(partition BY connect_by_root store_id ORDER BY level ASC, order_id DESC) r,
                                                                    connect_by_root store_id AS store_id,
                                                                    connect_by_root order_id AS order_id,
                                                                    connect_by_root store_name AS store_name,
                                                                    connect_by_root region AS region,
                                                                    connect_by_root fr_type AS fr_type,
                                                                    decode(to_open_date,
                                                                           NULL,
                                                                           connect_by_root start_date,
                                                                           to_open_date) AS start_date,
                                                                    connect_by_root cancel_type AS cancel_type,
                                                                    connect_by_root cancel_date AS,
                                                                    connect_by_root status AS status,
                                                                    add_months(decode(to_open_date,
                                                                                      NULL,
                                                                                      connect_by_root start_date,
                                                                                      to_open_date),
                                                                               -4),
                                                                    add_months(decode(to_open_date,
                                                                                      NULL,
                                                                                      connect_by_root start_date,
                                                                                      to_open_date),
                                                                               -1)
                                                               FROM fr_store
                                                              WHERE (to_open_date BETWEEN
                                                                    to_date('22/03/2020', 'DD/MM/YYYY') AND
                                                                    to_date('21/04/2020', 'DD/MM/YYYY') OR connect_by_root
                                                                     start_date BETWEEN to_date('22/03/2020', 'DD/MM/YYYY') AND
                                                                     to_date('21/04/2020', 'DD/MM/YYYY'))
                                                                    AND level <= 2
                                                             connect BY prior parent_order_id = order_id)
                                                      WHERE r = 1
                                                            AND flag = 1) fr
                                              INNER JOIN (SELECT 1 AS idx,
                                                                level id,
                                                                add_months(to_date('04/2020', 'MM/YYYY'), -level) AS period
                                                           FROM dual a
                                                         connect BY level <= 4) pd
                                                 ON fr.idx = pd.idx
                                              INNER JOIN fmp_employee_detail de
                                                 ON de.store_id = fr.store_id
                                                    AND de.year || de.month BETWEEN '202004' AND '202005'
                                               LEFT JOIN fmp_employee emp
                                                 ON emp.id = de.fmp_employee_id
                                              INNER JOIN fcs_incentive inc
                                                 ON inc.year || inc.month = to_char(pd.period, 'YYYYMM')
                                                    AND inc.emp_id = de.employee_id
                                              WHERE trunc(period, 'MM') BETWEEN
                                                    trunc(add_months(fr.start_date, -3), 'MM') AND
                                                    trunc(add_months(fr.start_date, -1), 'MM')
                                                    AND de.year || de.month = CASE
                                                      WHEN fr.start_date BETWEEN to_date('22/03/2020', 'DD/MM/YYYY') AND
                                                           to_date('21/04/2020', 'DD/MM/YYYY') THEN
                                                       '202004'
                                                      ELSE
                                                       '202005'
                                                    END
                                                    AND de.position_id IN ('1', '2', '3', '4')
                                                    AND de.department_id = 'E'
                                                    AND de.employee_type_id = 'F'
                                              GROUP BY de.employee_id,
                                                       de.position_id) inc
                                     ON de.employee_id = inc.employee_id
                                   LEFT JOIN common_code ccs
                                     ON ccs.code_type = 'INC_STATUS'
                                        AND ccs.code_value = nvl(inc.inc_status, 2)
                                   LEFT JOIN common_code cca
                                     ON cca.code_type = 'INC_AMOUNT'
                                        AND cca.code_value LIKE ('%' || nvl(de.position_id, '9999') || '%')
                                        AND cca.code_mapping = ccs.code_value
                                   LEFT JOIN mas_store_organize mso
                                     ON mso.branch_id = fr.store_id
                                        AND mso.group_id in (15, 70, 2000, 91)
                                   LEFT JOIN mas_store ms
                                     ON ms.branch_id = fr.store_id
                                   LEFT JOIN business_user bu
                                     ON lower(mso.email) = lower(bu.email)
                                        AND bu.group_id = mso.group_id
                                   LEFT JOIN common_code cct
                                     ON cct.code_type = '00019'
                                        AND cct.code_mapping = ms.status_type
                                   LEFT JOIN mas_param mp
                                     ON mp.param_name = 'FMP_SUPPORT_STORE_WORDING_INIT'
                                  GROUP BY de.employee_id,
                                           de.position_name,
                                           emp.first_name || ' ' || emp.last_name,
                                           fr.start_date,
                                           fr.store_id,
                                           fr.store_name,
                                           fr.region,
                                           fr.fr_type,
                                           de.start_date,
                                           de.end_date,
                                           cca.code_name,
                                           start_date_display,
                                           ccs.code_name,
                                           inc.inc_status,
                                           bu.user_id,
                                           mso.fullname,
                                           de.position_id,
                                           ms.region,
                                           ms.status_type,
                                           cct.code_value,
                                           mp.param_value,
                                           fr.order_id,
                                           mso.group_id)
         SELECT '1' AS support_round,
                '2020' AS support_year,
                '04' AS support_month,
                order_id,
                store_id,
                store_name,
                region,
                fr_type AS sbp_type,
                start_date AS sbp_start_date,
                start_date_display AS sbp_start_date_display,
                employee_id AS emp_id,
                emp_name,
                employee_id,
                position_id,
                emp_start_date,
                emp_end_date,
                dv_name,
                dv_user_id,
                ck AS clock_time,
                C_2A,
                C_2B,
                C_2C,
                C_2E,
                C_2J,
                C_3A,
                C_4A,
                C_5A,
                C_5B,
                To_char(C_2A + C_2B + C_2C + C_2E + C_2J + C_3A) AS absence,
                CASE
                  WHEN start_clock_date IS NOT NULL THEN
                   Nvl(To_char(Last_day(start_clock_date), 'DD') -
                       (C_2A + C_2B + C_2C + C_2E + C_2J + C_3A + C_4A + C_5A + C_5B + ck),
                       '0')
                  ELSE
                   To_number(To_char(Last_day(start_date), 'DD'))
                END AS unclock,
                ck + C_4A + C_5A + C_5B AS total_clock,
                CASE
                  WHEN start_clock_date IS NOT NULL THEN
                   To_char(Last_day(start_clock_date), 'DD')
                  ELSE
                   To_char(Last_day(start_date), 'DD')
                END total_day,
                CASE
                  WHEN start_clock_date + To_char(Last_day(start_clock_date), 'DD') - 1 > end_period_clock_date THEN
                   '3'
                  WHEN To_char(Last_day(start_clock_date), 'DD') = 31 AND
                       To_char(Last_day(start_clock_date), 'DD') - 6 <= ck + C_4A + C_5A + C_5B AND
                       C_2A + C_2B + C_2C + C_2E + C_2J + C_3A < 2 THEN
                   '1'
                  WHEN To_char(Last_day(start_clock_date), 'DD') != 31 AND
                       To_char(Last_day(start_clock_date), 'DD') - 5 <= ck + C_4A + C_5A + C_5B AND
                       C_2A + C_2B + C_2C + C_2E + C_2J + C_3A < 2 THEN
                   '1'
                  WHEN employee_id IS NULL THEN
                   '4'
                  ELSE
                   '2'
                END AS incentive_status,
                incentive_amount,
                start_clock_date,
                CASE
                  WHEN (start_clock_date + To_char(Last_day(start_clock_date), 'DD') - 1) > end_period_clock_date THEN
                   start_clock_date
                  WHEN (start_clock_date + To_char(Last_day(start_clock_date), 'DD') - 1) <= end_period_clock_date THEN
                   (start_clock_date + To_char(Last_day(start_clock_date), 'DD') - 1)
                  WHEN start_clock_date IS NULL THEN
                   NULL
                END end_clock_date,
                incentive_received,
                wf_to_step_id,
                wf_step_id,
                wf_to_status_id trn_status,
                remark,
                '202004' period,
                trn.wf_version_id,
                group_id
           FROM (SELECT DISTINCT de.employee_id,
                                 de.start_clock_date,
                                 de.emp_start_date,
                                 de.emp_end_date,
                                 de.store_id,
                                 de.store_name,
                                 de.region,
                                 de.fr_type,
                                 de.emp_name,
                                 de.start_date,
                                 de.start_date_display,
                                 incentive_received,
                                 incentive_amount,
                                 dv_user_id,
                                 dv_name,
                                 de.position_id,
                                 remark,
                                 end_period_clock_date,
                                 de.order_id,
                                 '5' wf_version_id,
                                 group_id,
                                 Sum(CASE
                                       WHEN adjust_reason_code IS NULL AND
                                            (ck_in_date IS NOT NULL OR ck_out_date IS NOT NULL OR
                                            adjust_ck_in_date IS NOT NULL OR adjust_ck_out_date IS NOT NULL) THEN
                                        1
                                       ELSE
                                        0
                                     END) OVER(partition BY de.employee_id, de.store_id) AS "CK",
                                 Sum(Decode(Nvl(ad.adjust_reason_code, '0'), '2A', 1, 0)) OVER(partition BY de.employee_id, de.store_id) AS C_2A,
                                 Sum(Decode(Nvl(ad.adjust_reason_code, '0'), '2B', 1, 0)) OVER(partition BY de.employee_id, de.store_id) AS C_2B,
                                 Sum(Decode(Nvl(ad.adjust_reason_code, '0'), '2C', 1, 0)) OVER(partition BY de.employee_id, de.store_id) AS C_2C,
                                 Sum(Decode(Nvl(ad.adjust_reason_code, '0'), '2E', 1, 0)) OVER(partition BY de.employee_id, de.store_id) AS C_2E,
                                 Sum(Decode(Nvl(ad.adjust_reason_code, '0'), '2J', 1, 0)) OVER(partition BY de.employee_id, de.store_id) AS C_2J,
                                 Sum(Decode(Nvl(ad.adjust_reason_code, '0'), '3A', 1, 0)) OVER(partition BY de.employee_id, de.store_id) AS C_3A,
                                 Sum(Decode(Nvl(ad.adjust_reason_code, '0'), '4A', 1, 0)) OVER(partition BY de.employee_id, de.store_id) AS C_4A,
                                 Sum(Decode(Nvl(ad.adjust_reason_code, '0'), '5A', 1, 0)) OVER(partition BY de.employee_id, de.store_id) AS C_5A,
                                 Sum(Decode(Nvl(ad.adjust_reason_code, '0'), '5B', 1, 0)) OVER(partition BY de.employee_id, de.store_id) AS C_5B,
                                 Sum(1) OVER(partition BY de.employee_id, de.store_id)
                   FROM employee_detail DE
                   LEFT JOIN fmp_employee_attendance AD
                     ON de.store_id = ad.store_id
                        AND ad.employee_id = de.employee_id
                        AND ad.business_date BETWEEN de.start_clock_date AND
                        (de.start_clock_date + To_char(Last_day(de.start_clock_date), 'DD') - 1)
                        AND ad.business_date <= de.end_period_clock_date) TRN
          INNER JOIN (SELECT wf_step_id,
                             wf_to_step_id,
                             s.wf_version_id,
                             r.wf_to_status_id
                        FROM wf_step S
                       INNER JOIN wf_route R
                          ON s.wf_version_id = r.wf_version_id
                             AND s.wf_step_id = r.wf_from_step_id
                       WHERE s.wf_version_id = '5'
                             AND s.step_seq = '0') WF
             ON trn.wf_version_id = wf.wf_version_id) trn
          WHERE NOT EXISTS (SELECT *
                   FROM fmp_incentive_trn tb
                  WHERE tb.period = trn.period
                        AND tb.trn_status != '501001'
                        AND tb.store_id = trn.store_id
                        AND tb.emp_id = trn.emp_id);
BEGIN
      select fmp_incentive_trn_seq.nextval into v_seq_fmp from dual;
      for data in getData
      loop
       INSERT INTO fmp_incentive_trn ( 
              trn_id, 
              support_round, 
              support_year, 
              support_month , 
              order_id, 
              store_id, 
              store_name, 
              region, 
              sbp_type, 
              sbp_start_date , 
              sbp_start_date_display, 
              emp_id, 
              position_id, 
              emp_start_date, 
              emp_end_date, 
              dv_name, 
              dv_user_id, 
              clock_time, 
              leave_reason_2a, 
              leave_reason_2b, 
              leave_reason_2c, 
              leave_reason_2e, 
              leave_reason_2j, 
              leave_reason_3a, 
              leave_reason_4a, 
              leave_reason_5a, 
              leave_reason_5b, 
              absence, 
              incentive_status_sbp, 
              incentive_amount_sbp, 
              incentive_status_opt, 
              incentive_amount_opt, 
              incentive_received, 
              step_id, 
              trn_status, 
              end_clock_date, 
              start_clock_date, 
              incentive_status , 
              incentive_amount , 
              emp_name , 
              period , 
              unclock , 
              total_day , 
              total_clock 
       ) 
       VALUES 
       ( 
              v_seq_fmp, 
              data.support_round, 
              data.support_year, 
              data.support_month , 
              data.order_id, 
              data.store_id , 
              data.store_name , 
              data.region , 
              data.sbp_type , 
              data.sbp_start_date , 
              data.sbp_start_date_display, 
              data.emp_id , 
              data.position_id , 
              data.emp_start_date , 
              data.emp_end_date , 
              data.dv_name , 
              data.dv_user_id , 
              data.clock_time , 
              '2A', 
              '2B', 
              '2C', 
              '2E', 
              '2J', 
              '3A', 
              '4A', 
              '5A', 
              '5B', 
              data.absence , 
              data.incentive_status, 
              data.incentive_amount, 
              data.incentive_status, 
              data.incentive_amount, 
              data.incentive_received, 
              data.wf_to_step_id , 
              data.trn_status , 
              data.end_clock_date , 
              data.start_clock_date , 
              data.incentive_status , 
              data.incentive_amount , 
              data.emp_name , 
              data.period, 
              data.unclock , 
              data.total_day , 
              data.total_clock 
       ); 
      END loop;
END;
/

