-- ---------- PROCEDURE: SPM_PURGE_REGISTER_CARD ----------
CREATE OR REPLACE EDITIONABLE PROCEDURE "FCS_FRN"."SPM_PURGE_REGISTER_CARD" AS
v_franchisee_id  NUMBER;
v_start_date     DATE ; 
v_row_del        NUMBER;        
v_row_ins        NUMBER;
v_row_clear      NUMBER; 
v_acction        varchar2(25);
v_owner          varchar2(255) := 'FCS_FRN';
v_per_cust_id   VARCHAR2(4000);
v_cust_id   VARCHAR2(4000);
v_sql_ins           VARCHAR2(4000);
v_sql_del           VARCHAR2(4000);
v_sql_clear         VARCHAR2(4000);
v_err_code       NUMBER;  
v_err_msg        VARCHAR2(255);
v_tbname         VARCHAR2(255);

CURSOR getTable IS
    SELECT PARAM_VALUE FROM MAS_PARAM 
    WHERE PARAM_NAME = 'SPM_PURGE_TABLE'
    AND ACTIVE_FLAG = 'Y';

--CURSOR getCustId IS
--        select c.cust_id
--        from customer c
--        left join franchisee f on (c.cust_id = f.cust_id and f.cust_id is null)
--        where TRUNC(sysdate - c.create_date) >= 3620; 
    
CURSOR   v_per_cust_id_cursor IS
	 select DISTINCT LISTAGG(cust_id, ', ') WITHIN GROUP (ORDER BY cust_id) 
     from cust_pre_process cpp
     where TRUNC(MONTHS_BETWEEN(sysdate, cpp.create_date) / 12) >= 5
     AND cpp.ID_CARD  NOT IN (
        	SELECT DISTINCT  c.ID_CARD 
        	FROM CUSTOMER c
        	inner JOIN FR_PROCESS_TRN fpt ON c.CUST_ID = fpt.CUST_ID 
        	WHERE c.ID_CARD IS NOT null)
;
   
 

       
PROCEDURE procress(v_tablename IN VARCHAR2) IS

BEGIN


     if length(v_per_cust_id) > 0  then

            v_start_date := SYSDATE;
            v_acction := 'BACKUP' ;
            v_sql_ins := 'INSERT INTO ' || v_owner ||'.'||v_tablename||'_BACKUP' 
              ||' SELECT FC.* , SYSDATE FROM ' ||v_owner ||'.'||v_tablename ||' FC WHERE FC.cust_id in ( '||v_per_cust_id || ')' ;
   EXECUTE IMMEDIATE v_sql_ins ; 
   v_row_ins := sql%rowcount ;     

   insert into fml_purge_log( start_date,end_date,table_owner,table_name,action_type,job_status,records_row,sql_code,sql_errm,ref_1)
   values(v_start_date,SYSDATE,v_owner,v_tablename,v_acction,'SUCCESS',v_row_ins,null,null,v_per_cust_id);
     
            v_start_date := SYSDATE ;
   v_acction := 'PURGE' ;
            v_sql_del := 'DELETE FROM ' || v_owner ||'.'||v_tablename || ' WHERE cust_id in ( '||v_per_cust_id || ')' ;   
   EXECUTE IMMEDIATE v_sql_del ;
   v_row_del := sql%rowcount ;       

            insert into fml_purge_log( start_date,end_date,table_owner,table_name,action_type,job_status,records_row,sql_code,sql_errm,ref_1)
   values(v_start_date,SYSDATE,v_owner,v_tablename,v_acction,'SUCCESS',v_row_del,null,null,v_per_cust_id);

            v_start_date := SYSDATE ;
   v_acction := 'CLEAR_BACKUP' ;
            v_sql_clear := 'DELETE FROM ' || v_owner ||'.'||v_tablename||'_BACKUP ' || ' WHERE sysdate - backup_date >= 30 ' ;   
   EXECUTE IMMEDIATE v_sql_clear ;
            v_row_clear := sql%rowcount ;     

   insert into fml_purge_log( start_date,end_date,table_owner,table_name,action_type,job_status,records_row,sql_code,sql_errm)
   values(v_start_date,SYSDATE,v_owner,v_tablename||'_BACKUP',v_acction,'SUCCESS',v_row_clear,null,null);
      commit;  
    end if;
EXCEPTION
    WHEN OTHERS THEN
        rollback;
           v_err_code := SQLCODE ;
           v_err_msg := SUBSTR(SQLERRM, 1, 255);
        INSERT INTO FCS_FRN.FML_PURGE_LOG(START_DATE,END_DATE,TABLE_OWNER,TABLE_NAME,ACTION_TYPE,JOB_STATUS,RECORDS_ROW,SQL_CODE,SQL_ERRM)
        VALUES(v_start_date,SYSDATE,v_owner,v_tablename,v_acction,'ERROR',NULL,v_err_code,v_err_msg);
        COMMIT;
END procress;

BEGIN
	  OPEN v_per_cust_id_cursor;
      FETCH v_per_cust_id_cursor INTO v_per_cust_id;
      CLOSE v_per_cust_id_cursor;
     
      for i in getTable
      loop
        procress(i.PARAM_VALUE);
      END loop;
END;
/

-- ---------- PROCEDURE: SP_DELETE_STORE_TOUR ----------
CREATE OR REPLACE EDITIONABLE PROCEDURE "FCS_FRN"."SP_DELETE_STORE_TOUR" (
	pEMPLOYEEID IN NUMBER , pCOURSECODE IN VARCHAR2
	
)
IS
BEGIN
DELETE FTS_REGISTER R
			WHERE  R.CUST_ID = pEMPLOYEEID AND R.COURSE_CODE = pCOURSECODE;
			COMMIT;
END; 
/

-- ---------- PROCEDURE: SP_FMS_GET_FRANCHISECODE ----------
CREATE OR REPLACE EDITIONABLE PROCEDURE "FCS_FRN"."SP_FMS_GET_FRANCHISECODE" (		
		FranchiseID OUT VARCHAR2	
	)		
	IS		
	BEGIN		
			SELECT CONCAT(CONCAT(
			TO_CHAR( EXTRACT(YEAR FROM SYSDATE) ),
			LPAD(TO_CHAR( EXTRACT(MONTH FROM SYSDATE) ),2,'00')),
			LPAD(TO_CHAR(COUNT(PROCESS_ID)+1),5,'00000'))
			INTO  FranchiseID
			 FROM FR_PROCESS
			WHERE  EXTRACT(YEAR FROM CREATE_DATE)  = EXTRACT(YEAR FROM SYSDATE) AND 
			EXTRACT(MONTH FROM CREATE_DATE)  = EXTRACT(MONTH FROM SYSDATE) ;
	END; 
/

-- ---------- PROCEDURE: SP_FMS_GET_LASTINSTITUE ----------
CREATE OR REPLACE EDITIONABLE PROCEDURE "FCS_FRN"."SP_FMS_GET_LASTINSTITUE" (p_ProcessID   IN CUSTOMER_EDUCATION.PROCESS_ID%TYPE,
                      p_recordset OUT SYS_REFCURSOR) AS 
BEGIN 
  OPEN p_recordset FOR
 SELECT CustEdu.INSTITUTE,CustEdu.MAJOR,CustEdu.GRADUATE_YEAR FROM (SELECT * FROM FCS_FRN.CUSTOMER_EDUCATION
WHERE  CUSTOMER_EDUCATION.PROCESS_ID = p_ProcessID
ORDER BY GRADUATE_YEAR DESC) CustEdu WHERE ROWNUM = 1;
END SP_FMS_GET_LASTINSTITUE;
/

-- ---------- PROCEDURE: SP_FMS_GET_SEMINAR_USER ----------
CREATE OR REPLACE EDITIONABLE PROCEDURE "FCS_FRN"."SP_FMS_GET_SEMINAR_USER" (
    pCustID IN NUMBER,
	cursorParam OUT SYS_REFCURSOR 
)
IS
BEGIN
	OPEN  cursorParam For 
	SELECT cast( CR.RELATED_CUST_ID as varchar(10)) ,CCR.FIRST_NAME
	FROM  CUSTOMER C  
	 JOIN  CUSTOMER_RELATED CR ON CR.CUST_ID = C.CUST_ID
	 LEFT JOIN CUSTOMER CCR ON CR.RELATED_CUST_ID  = CCR.CUST_ID
	WHERE CR.RELATED_TYPE = 1 AND CR.CUST_ID = pCustID
	UNION
	SELECT cast( Cus.CUST_ID as varchar(10)),Cus.FIRST_NAME
	FROM  CUSTOMER Cus
	WHERE Cus.CUST_ID = pCustID;

END;
/

