-- ---------- PROCEDURE: SP_UPDATE_CAPITAL_ATTACH ----------
CREATE OR REPLACE EDITIONABLE PROCEDURE "FCS_FRN"."SP_UPDATE_CAPITAL_ATTACH" (
	pCustID IN NUMBER
)
IS
BEGIN
UPDATE FMS_CM_ATTACH  CM
			SET DELETE_FLAG = 'Y'
			WHERE  CM.CUST_ID = pCustID AND CM.DOC_TYPE_ID = 'doc02' AND CM.DOC_SUB_TYPE_ID = 1 ; 
			COMMIT;
END; 
/

-- ---------- PROCEDURE: SP_UPDATE_CMATTACH ----------
CREATE OR REPLACE EDITIONABLE PROCEDURE "FCS_FRN"."SP_UPDATE_CMATTACH" (
	pDOCATTACHID IN NUMBER
)
IS
BEGIN
UPDATE FMS_CM_ATTACH
			SET DELETE_FLAG = 'Y'
			WHERE  DOCATTACH_ID = pDOCATTACHID;
			COMMIT;
END;
/

