-- ---------- PACKAGE: FES_TMP_IMPORTDATA_PCK ----------
CREATE OR REPLACE EDITIONABLE PACKAGE "FCS_FRN"."FES_TMP_IMPORTDATA_PCK" AS
    
    TYPE fes_tmp_importdata_record IS RECORD (
        ORDER_ID NUMBER, 
        STORE_ID VARCHAR2(15), 
        STORE_NAME VARCHAR2(255), 
        STORE_TYPE VARCHAR2(12), 
        REGION VARCHAR2(5),
        START_DATE VARCHAR2(20), 
        FR_START_DATE DATE, 
        OPEN_DATE DATE, 
        IMPORT_ID INTEGER, 
        FIRST_IMPORT_ID NUMBER, 
        TITLE_ID INTEGER, 
        GOAL_GET VARCHAR2(1), 
        MM VARCHAR2(2), 
        YY VARCHAR2(2), 
        TOP_VALUE NUMBER, 
        BOTTOM_VALUE NUMBER, 
        TITLE VARCHAR2(500), 
        POINT NUMBER,
        FIXED NUMBER  ,
        SEQ NUMBER
    );

    TYPE fes_tmp_importdata_table IS TABLE OF fes_tmp_importdata_record;

    FUNCTION queryFesTmpImportData(
        v_store_id varchar2,
        v_store_name varchar2,
        v_store_region varchar2,
        v_fr_type varchar2,
        v_eval_start_yymm varchar2,
        v_eval_end_yymm varchar2,
        v_eval_type varchar2     
    )
        RETURN fes_tmp_importdata_table
        PIPELINED;
END;
/

CREATE OR REPLACE EDITIONABLE PACKAGE BODY "FCS_FRN"."FES_TMP_IMPORTDATA_PCK" AS

    FUNCTION queryFesTmpImportData (
        v_store_id varchar2,                        --optional
        v_store_name varchar2,              --optional
        v_store_region varchar2,            --optional
        v_fr_type varchar2,                         --optional
        v_eval_start_yymm varchar2,     --required
        v_eval_end_yymm varchar2,      --required
        v_eval_type varchar2                    --required  {'THREE','MIDYEAR'}  
    )
        RETURN fes_tmp_importdata_table
        PIPELINED IS

        rec            fes_tmp_importdata_record;

        TYPE importdata_ref IS REF CURSOR;
        importdata_cur  importdata_ref;
        
--        v_stmt_fr_store_query varchar2(4000 char);
        v_stmt_fr_store_hierarchy varchar2(4000 char);
        v_stmt_str clob; --varchar2(4000 char);

    BEGIN

        /*====================v_stmt_fr_store_hierarchy=====================*/
        v_stmt_fr_store_hierarchy := 'with fr_store_hierarchy as ( ' || 
                                                    ' select * ' ||
                                                    ' from ( ' ||
                                                    '    select  order_id, store_id, start_date, to_open_date ' ||
                                                    '         ,  regexp_substr( substr(root_path,2), '',?([^,]*)'', 1, level, ''i'', 1 )  as ref_order_id ' ||
                                                    '      from  ( ' ||
                                                    '             select s.order_id, s.store_id, s.start_date, s2.to_open_date, s.parent_order_id, ' ||
                                                    '                SYS_CONNECT_BY_PATH(s.order_id,'','') as root_path ' ||
                                                    '             from fr_store s ' ||
                                                    '                 left join fr_store s2 on s2.order_id = s.parent_order_id ' ||
                                                    '             where s.store_id != ''00000'' ' ||
                                                    '                 and ( ' ||
                                                    '                         s.status is null  ' ||
                                                    '                         or s.status != ''D'' ' ||
                                                    '                     ) ' ||
                                                    '                     and s.cancel_date is null    ' ||
                                                    '             start with s.parent_order_id is null ' ||
                                                    '             connect by prior s.order_id = s.parent_order_id ' ||
                                                    '      ) ' ||
                                                    '            CONNECT BY ' ||
                                                    '              ( regexp_count(root_path,'','')+1 >= level ' ||
                                                    '                and prior order_id = order_id ' ||
                                                    '                and prior dbms_random.value is not null ' ||
                                                    '              ) ' ||
                                                    ' ) ' ||
                                                    ' where ref_order_id is not null ' ||
                                                    '     and 1 = ( ' ||
                                                    '     case when ''' || v_eval_type || ''' = ''MIDYEAR'' then ' ||
                                                    '         case when to_char (start_date, ''YYYY'') <= to_char(add_months(to_date(''' || v_eval_end_yymm || ''',''RRMM''), -5),''YYYY'') then ' ||
                                                    '             1 ' ||
                                                    '         else ' ||
                                                    '             0 ' ||
                                                    '         end ' ||
                                                    '     else ' || --THREE
                                                    '         case when to_char (start_date, ''YYYY'') = to_char(add_months(to_date(''' || v_eval_end_yymm || ''',''RRMM''), -3),''YYYY'') then ' ||
                                                    '             1 ' ||
                                                    '         else ' ||
                                                    '             0 ' ||
                                                    '         end ' ||
                                                    '     end ' ||
                                                    '     ) ' ||
                                                    '     and 1 = ( ' ||
                                                    '       case when ''' || v_eval_type || ''' = ''MIDYEAR'' then ' ||
                                                    '           case when to_char (start_date, ''MM'') in ( ' ||
                                                    '                   to_char(add_months(to_date(''' || v_eval_end_yymm || ''',''RRMM''), -5),''MM''), to_char(add_months(to_date(''' || v_eval_end_yymm || ''',''RRMM''), 1),''MM'') ' ||
                                                    '               ) then ' ||
                                                    '               1 ' ||
                                                    '           else ' ||
                                                    '               0 ' ||
                                                    '           end ' ||
                                                    '         else ' || --THREE
                                                    '           case when to_char (start_date, ''MM'') = to_char(add_months(to_date(''' || v_eval_end_yymm || ''',''RRMM''), -3),''MM'') then ' ||
                                                    '               1 ' ||
                                                    '           else ' ||
                                                    '               0 ' ||
                                                    '           end ' ||
                                                    '         end ' ||
                                                    '     ) ';
                                                                                                        
        if (v_store_id is not null) then                                                        
            v_stmt_fr_store_hierarchy := v_stmt_fr_store_hierarchy || 
                                '     and store_id = ''' || v_store_id || ''' ';
        end if;      
             
         v_stmt_fr_store_hierarchy := v_stmt_fr_store_hierarchy || ' ) ';             
                
        /*====================v_stmt_str=====================*/        
        v_stmt_str := v_stmt_fr_store_hierarchy ||
                            ' select imp.order_id, imp.store_id, ' ||
                            '     ms.branch_name as store_name,    ' ||
                            '     decode (ms.status_type,         ' ||
                            '         ''FPT1'',''Type ???.'',        ' ||
                            '         ''FAM'',''Type A'',        ' ||
                            '         ''FB1'',''Type B'',        ' ||
                            '         ''FB2'',''Type ???????'',        ' ||
                            '         ''FC1'',''Type C'',        ' ||
                            '         null    ' ||
                            '     ) as store_type,    ' ||
                            '     ms.region,    ' ||
                            '     to_char( imp.start_date, ''DD/MM/YYYY'', ''NLS_CALENDAR=''''THAI BUDDHA'''' NLS_DATE_LANGUAGE=THAI'' ) as  start_date,    ' ||
                            '     imp.start_date as fr_start_date, imp.to_open_date as open_date, ' ||
                            '     imp.import_id, imp.first_import_id, imp.title_id, imp.goal_get, imp.mm, imp.yy, imp.top_value, imp.bottom_value,    ' ||
                            '     lv3.levelthree_name as title, lv3.point, lv3.fixed, fet.seq  ' ||
                            ' from ( ' ||           
                            '     select * ' ||
                            '     from (    ' ||
                            '         select s2.*, imp.import_id, imp.title_id, imp.goal_get, imp.mm, imp.yy, imp.branch_id as importdata_store_id, imp.top_value, imp.bottom_value, imp.status,  ' ||
                            '             first_value(imp.import_id) over(partition by s2.order_id, imp.title_id, imp.goal_get, imp.yy, imp.mm order by imp.status, imp.import_id desc) first_import_id ' ||
                            '         from fes_importdata imp ' ||
                            '             inner join fr_store_hierarchy s2 on s2.ref_order_id = imp.fr_store_order_id ' ||
                            '                         and to_char(imp.status) = ''Y'' ' ||
                            '                         and to_char(imp.yy || imp.mm) between ''' || v_eval_start_yymm || ''' and ''' || v_eval_end_yymm || ''' ' ||
                            '                         and to_char(imp.yy || imp.mm) != ( ' ||    /*cut non full month (MIDYEAR first times)*/    
                            '                             case when s2.to_open_date != trunc(s2.to_open_date,''MM'') then ' ||
                            '                                 to_char(s2.to_open_date,''RRMM'') ' ||
                            '                             when s2.start_date != trunc(s2.start_date,''MM'') then ' ||
                            '                                 to_char(s2.start_date,''RRMM'') ' ||
                            '                             else ' ||
                            '                                 ''9999'' ' ||
                            '                             end ' ||
                            '                         ) ' ||
                            '     ) imp ' ||
                            '     where imp.import_id = imp.first_import_id ' ||
                            ' ) imp ' ||
                            '    inner join mas_store ms on ms.branch_id = imp.store_id ' ||
                            '     inner join fes_evaluatedform_title fet on fet.title_id = imp.title_id ' ||
                            '         and fet.eval_level = 3 ' ||
                            '         and fet.evaluatedform_id = ( ' ||
                            '             select evaluatedform_id  ' ||
                            '             from fes_evaluatedform ' ||
                            '             where  ( to_char(add_months(to_date(''' || v_eval_end_yymm || ''', ''RRMM''), 1),''yyyymm'') between (start_year)||lpad(start_month,2,0) and (end_year)||lpad(end_month,2,0) )  ' ||
                            '                 or (  ' ||
                            '                     to_char(add_months(to_date(''' || v_eval_end_yymm || ''',''RRMM''), 1),''yyyymm'')  >= (start_year)||lpad(start_month,2,0) and end_month is null and end_year is null ' ||
                            '                 )  ' ||
                            '         ) ' ||
                            '     inner join fes_evallevelthree lv3 on  lv3.evallevelthree_id = fet.eval_level_id ' ||
                            ' where 1=1 ';

        if (v_store_name is not null) then                                                        
            v_stmt_str := v_stmt_str || 
                                    '     and ms.branch_name like ''%' || v_store_name || '%''';
        end if;                                                          

        if (v_store_region is not null) then                                                        
            v_stmt_str := v_stmt_str || 
                                    '     and ms.region = ''' || v_store_region || '''';
        end if;
        
        if (v_fr_type is not null) then                                                        
            v_stmt_str := v_stmt_str || 
                                    '     and ms.status_type = decode(''' || v_fr_type || ''',' ||
                                    '           ''PTT'',''FPT1'',' ||
                                    '           ''A'',''FAM'',' ||
                                    '           ''B'',''FB1'',' ||
                                    '           ''EMP'',''FB2'',' ||
                                    '           ''C'',''FC1'',' ||
                                    '           null' ||        
                                    '    )';                                    
        end if;    

        v_stmt_str := v_stmt_str ||
                            ' order by store_id, fet.seq , imp.yy || imp.mm ';

     dbms_output.put_line('v_stmt_str = ' || v_stmt_str);                

        IF NOT importdata_cur%ISOPEN THEN
            OPEN importdata_cur for v_stmt_str;
        END IF;
        
        LOOP
            FETCH importdata_cur INTO rec;        
            EXIT WHEN importdata_cur%NOTFOUND;
             PIPE ROW (rec);
        END LOOP;
        
        IF importdata_cur%ISOPEN THEN
            CLOSE importdata_cur;
        END IF;            
        
        RETURN;
                
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
            RETURN;
                
    END queryFesTmpImportData;
END; 
/

-- ---------- PACKAGE: PCK_FCS_CALL_CM_WS ----------
CREATE OR REPLACE EDITIONABLE PACKAGE "FCS_FRN"."PCK_FCS_CALL_CM_WS" AS
/******************************************************************************
   NAME:       PCK_FCS_CALL_CM_WS
   PURPOSE:

   REVISIONS:
   Ver        Date        Author           Description
   ---------  ----------  ---------------  ------------------------------------
   1.0        1/2/2016      kiettichaicha       1. Created this package.
******************************************************************************/

    TYPE tbl_param_name IS TABLE OF VARCHAR2(50) INDEX BY BINARY_INTEGER;
    TYPE tbl_param_type IS TABLE OF VARCHAR2(50) INDEX BY BINARY_INTEGER;
    TYPE tbl_param_value IS TABLE OF VARCHAR2(50) INDEX BY BINARY_INTEGER;    

  FUNCTION CallCMWebService(
        param_name tbl_param_name,
        param_type tbl_param_type,
        param_value tbl_param_value
    ) RETURN VARCHAR2;

END;
/

CREATE OR REPLACE EDITIONABLE PACKAGE BODY "FCS_FRN"."PCK_FCS_CALL_CM_WS" IS

    FUNCTION CallCMWebService(
        param_name tbl_param_name,
        param_type tbl_param_type,
        param_value tbl_param_value
    ) RETURN VARCHAR2
    
    IS
    
        l_return    VARCHAR2(32767);    

        l_request   soap_api.t_request;
        l_response  soap_api.t_response;
                  
        l_url          VARCHAR2(32767);
        l_namespace    VARCHAR2(32767);
        l_method       VARCHAR2(32767);
        l_soap_action  VARCHAR2(32767);
        l_result_name  VARCHAR2(32767);
    
    BEGIN

        l_url         := 'http://sectmdv02.cpall.co.th/ECMWS/services/MaintainCMContent';
        l_namespace   := 'targetNamespace="http://main.ws.ecm.gosoft.co.th" xmlns:apachesoap="http://xml.apache.org/xml-soap" xmlns:impl="http://main.ws.ecm.gosoft.co.th" xmlns:intf="http://main.ws.ecm.gosoft.co.th" xmlns:tns1="http://constant.ws.ecm.gosoft.co.th" xmlns:wsdl="http://schemas.xmlsoap.org/wsdl/" xmlns:wsdlsoap="http://schemas.xmlsoap.org/wsdl/soap/" xmlns:xsd="http://www.w3.org/2001/XMLSchema"';  --http://www.w3.org/2001/XMLSchema      http://main.ws.ecm.gosoft.co.th     http://constant.ws.ecm.gosoft.co.th
        l_method      := 'sendToCM';
        l_soap_action := '""';
        l_result_name := 'ns1:sendToCMReturn';
                  
        IF ((param_name.count != param_type.count) and (param_name.count != param_value.count)) THEN
            dbms_output.put_line('parameter''s size is not eqivalent');
            l_return := 'fail';  
            RETURN l_return;        
        END IF;
                  
        l_request := soap_api.new_request(p_method       => l_method,
                                        p_namespace    => l_namespace);

        for i in 1 .. param_name.count
        loop
        soap_api.add_parameter(p_request => l_request,
                         p_name    => param_name(i),
                         p_type    => param_type(i),
                         p_value   => param_value(i));        
        end loop;           

        --          soap_api.add_parameter(p_request => l_request,
        --                                 p_name    => 'fileName',
        --                                 p_type    => 'xsd:string',
        --                                 p_value   => null);
        --
        --          soap_api.add_parameter(p_request => l_request,
        --                                 p_name    => 'actionType',
        --                                 p_type    => 'xsd:string',
        --                                 p_value   => 'delete');
        --
        --          soap_api.add_parameter(p_request => l_request,
        --                                 p_name    => 'fileContent',
        --                                 p_type    => 'xsd:string',
        --                                 p_value   => null);
        --
        --          soap_api.add_parameter(p_request => l_request,
        --                                 p_name    => 'templateName',
        --                                 p_type    => 'xsd:string',
        --                                 p_value   => 'FR_CONT_TEST');
        --
        --          soap_api.add_parameter(p_request => l_request,
        --                                 p_name    => 'paramName',
        --                                 p_type    => 'xsd:string',
        --                                 p_value   => 'TLDocID');
        --
        --          soap_api.add_parameter(p_request => l_request,
        --                                 p_name    => 'paramValue',
        --                                 p_type    => 'xsd:string',
        --                                 p_value   => v_doc_id);
        --
        --          soap_api.add_parameter(p_request => l_request,
        --                                 p_name    => 'paramType',
        --                                 p_type    => 'xsd:string',
        --                                 p_value   => 'STRING');

        l_response := soap_api.invoke(p_request => l_request,
                                    p_url     => l_url,
                                    p_action  => l_soap_action);

        l_return := soap_api.get_return_value(p_response  => l_response,
                                            p_name      => l_result_name,
                                            p_namespace => 'xmlns:ns1="http://main.ws.ecm.gosoft.co.th">');                                        

        dbms_output.put_line('l_return=' || l_return);    

        RETURN l_return;    
        
    END CallCMWebService;

END PCK_FCS_CALL_CM_WS;
/

-- ---------- PACKAGE: SOAP_API ----------
CREATE OR REPLACE EDITIONABLE PACKAGE "FCS_FRN"."SOAP_API" AS
-- --------------------------------------------------------------------------
-- Name         : https://oracle-base.com/dba/miscellaneous/soap_api.sql
-- Author       : Tim Hall
-- Description  : SOAP related functions for consuming web services.
-- License      : Free for personal and commercial use.
--                You can amend the code, but leave existing the headers, current
--                amendments history and links intact.
--                Copyright and disclaimer available here:
--                https://oracle-base.com/misc/site-info.php#copyright
-- Ammedments   :
--   When         Who       What
--   ===========  ========  =================================================
--   04-OCT-2003  Tim Hall  Initial Creation
--   23-FEB-2006  Tim Hall  Parameterized the "soap" envelope tags.
--   25-MAY-2012  Tim Hall  Added debug switch.
--   29-MAY-2012  Tim Hall  Allow parameters to have no type definition.
--                          Change the default envelope tag to "soap".
--                          add_complex_parameter: Include parameter XML manually.
--   24-MAY-2014  Tim Hall  Added license information.
-- --------------------------------------------------------------------------

TYPE t_request IS RECORD (
  method        VARCHAR2(256),
--  namespace     VARCHAR2(256),
  namespace     VARCHAR2(500),  
  body          VARCHAR2(32767),
  envelope_tag  VARCHAR2(30)
);

TYPE t_response IS RECORD
(
  doc           XMLTYPE,
  envelope_tag  VARCHAR2(30)
);

FUNCTION new_request(p_method        IN  VARCHAR2,
                     p_namespace     IN  VARCHAR2,
                     p_envelope_tag  IN  VARCHAR2 DEFAULT 'soap')
  RETURN t_request;


PROCEDURE add_parameter(p_request  IN OUT NOCOPY  t_request,
                        p_name     IN             VARCHAR2,
                        p_value    IN             VARCHAR2,
                        p_type     IN             VARCHAR2 := NULL);

PROCEDURE add_complex_parameter(p_request  IN OUT NOCOPY  t_request,
                                p_xml      IN             VARCHAR2);

FUNCTION invoke(p_request  IN OUT NOCOPY  t_request,
                p_url      IN             VARCHAR2,
                p_action   IN             VARCHAR2)
  RETURN t_response;

FUNCTION get_return_value(p_response   IN OUT NOCOPY  t_response,
                          p_name       IN             VARCHAR2,
                          p_namespace  IN             VARCHAR2)
  RETURN VARCHAR2;

PROCEDURE debug_on;
PROCEDURE debug_off;

END soap_api;
/

CREATE OR REPLACE EDITIONABLE PACKAGE BODY "FCS_FRN"."SOAP_API" AS
-- --------------------------------------------------------------------------
-- Name         : https://oracle-base.com/dba/miscellaneous/soap_api.sql
-- Author       : Tim Hall
-- Description  : SOAP related functions for consuming web services.
-- License      : Free for personal and commercial use.
--                You can amend the code, but leave existing the headers, current
--                amendments history and links intact.
--                Copyright and disclaimer available here:
--                https://oracle-base.com/misc/site-info.php#copyright
-- Ammedments   :
--   When         Who       What
--   ===========  ========  =================================================
--   04-OCT-2003  Tim Hall  Initial Creation
--   23-FEB-2006  Tim Hall  Parameterized the "soap" envelope tags.
--   25-MAY-2012  Tim Hall  Added debug switch.
--   29-MAY-2012  Tim Hall  Allow parameters to have no type definition.
--                          Change the default envelope tag to "soap".
--                          add_complex_parameter: Include parameter XML manually.
--   24-MAY-2014  Tim Hall  Added license information.
-- --------------------------------------------------------------------------

g_debug  BOOLEAN := FALSE;

PROCEDURE show_envelope(p_env     IN  VARCHAR2,
                        p_heading IN  VARCHAR2 DEFAULT NULL);



-- ---------------------------------------------------------------------
FUNCTION new_request(p_method        IN  VARCHAR2,
                     p_namespace     IN  VARCHAR2,
                     p_envelope_tag  IN  VARCHAR2 DEFAULT 'soap')
  RETURN t_request AS
-- ---------------------------------------------------------------------
  l_request  t_request;
BEGIN
  l_request.method       := p_method;
  l_request.namespace    := p_namespace;
  l_request.envelope_tag := p_envelope_tag;
  RETURN l_request;
END;
-- ---------------------------------------------------------------------



-- ---------------------------------------------------------------------
PROCEDURE add_parameter(p_request  IN OUT NOCOPY  t_request,
                        p_name     IN             VARCHAR2,
                        p_value    IN             VARCHAR2,
                        p_type     IN             VARCHAR2 := NULL) AS
-- ---------------------------------------------------------------------
BEGIN
  IF p_type IS NULL THEN
    p_request.body := p_request.body||'<'||p_name||'>'||p_value||'</'||p_name||'>';
  ELSE
    p_request.body := p_request.body||'<'||p_name||' xsi:type="'||p_type||'">'||p_value||'</'||p_name||'>';
  END IF;
END;
-- ---------------------------------------------------------------------



-- ---------------------------------------------------------------------
PROCEDURE add_complex_parameter(p_request  IN OUT NOCOPY  t_request,
                                p_xml      IN             VARCHAR2) AS
-- ---------------------------------------------------------------------
BEGIN
  p_request.body := p_request.body||p_xml;
END;
-- ---------------------------------------------------------------------



-- ---------------------------------------------------------------------
PROCEDURE generate_envelope(p_request  IN OUT NOCOPY  t_request,
                                p_env      IN OUT NOCOPY  VARCHAR2) AS
-- ---------------------------------------------------------------------
BEGIN
  p_env := '<'||p_request.envelope_tag||':Envelope xmlns:'||p_request.envelope_tag||'="http://schemas.xmlsoap.org/soap/envelope/" ' ||
               'xmlns:xsi="http://www.w3.org/1999/XMLSchema-instance" xmlns:xsd="http://www.w3.org/1999/XMLSchema">' ||
             '<'||p_request.envelope_tag||':Body>' ||
               '<'||p_request.method||' '||p_request.namespace||' '||p_request.envelope_tag||':encodingStyle="http://schemas.xmlsoap.org/soap/encoding/">' ||
                   p_request.body ||
               '</'||p_request.method||'>' ||
             '</'||p_request.envelope_tag||':Body>' ||
           '</'||p_request.envelope_tag||':Envelope>';
END;
-- ---------------------------------------------------------------------



-- ---------------------------------------------------------------------
PROCEDURE show_envelope(p_env     IN  VARCHAR2,
                        p_heading IN  VARCHAR2 DEFAULT NULL) AS
-- ---------------------------------------------------------------------
  i      PLS_INTEGER;
  l_len  PLS_INTEGER;
BEGIN

--    dbms_output.put_line('p_env=' || p_env);

  IF g_debug THEN
    IF p_heading IS NOT NULL THEN
      DBMS_OUTPUT.put_line('*****' || p_heading || '*****');
    END IF;

    i := 1; l_len := LENGTH(p_env);
    WHILE (i <= l_len) LOOP
      DBMS_OUTPUT.put_line(SUBSTR(p_env, i, 60));
      i := i + 60;
    END LOOP;
  END IF;
END;
-- ---------------------------------------------------------------------



-- ---------------------------------------------------------------------
PROCEDURE check_fault(p_response IN OUT NOCOPY  t_response) AS
-- ---------------------------------------------------------------------
  l_fault_node    XMLTYPE;
  l_fault_code    VARCHAR2(256);
  l_fault_string  VARCHAR2(32767);
  var_test char;
BEGIN
   var_test := 'N';
  l_fault_node := p_response.doc.extract('/'||p_response.envelope_tag||':Fault',
                                         'xmlns:'||p_response.envelope_tag||'="http://schemas.xmlsoap.org/soap/envelope/');
  IF (l_fault_node IS NOT NULL) THEN

    l_fault_code   := l_fault_node.extract('/'||p_response.envelope_tag||':Fault/faultcode/child::text()',
                                           'xmlns:'||p_response.envelope_tag||'="http://schemas.xmlsoap.org/soap/envelope/').getstringval();
    l_fault_string := l_fault_node.extract('/'||p_response.envelope_tag||':Fault/faultstring/child::text()',
                                           'xmlns:'||p_response.envelope_tag||'="http://schemas.xmlsoap.org/soap/envelope/').getstringval();
                                           
    RAISE_APPLICATION_ERROR(-20000, l_fault_code || ' - ' || l_fault_string);
  END IF;
END;
-- ---------------------------------------------------------------------



-- ---------------------------------------------------------------------
FUNCTION invoke(p_request IN OUT NOCOPY  t_request,
                p_url     IN             VARCHAR2,
                p_action  IN             VARCHAR2)
  RETURN t_response AS
-- ---------------------------------------------------------------------
  l_envelope       VARCHAR2(32767);
  l_http_request   UTL_HTTP.req;
  l_http_response  UTL_HTTP.resp;
  l_response       t_response;
BEGIN

  generate_envelope(p_request, l_envelope);
  show_envelope(l_envelope, 'Request');
  l_http_request := UTL_HTTP.begin_request(p_url, 'POST','HTTP/1.1');
  UTL_HTTP.set_header(l_http_request, 'Content-Type', 'text/xml');
  UTL_HTTP.set_header(l_http_request, 'Content-Length', LENGTH(l_envelope));
  UTL_HTTP.set_header(l_http_request, 'SOAPAction', p_action);
  UTL_HTTP.write_text(l_http_request, l_envelope);
  l_http_response := UTL_HTTP.get_response(l_http_request);
  UTL_HTTP.read_text(l_http_response, l_envelope);
  UTL_HTTP.end_response(l_http_response);
  show_envelope(l_envelope, 'Response');
  l_response.doc := XMLTYPE.createxml(l_envelope);
  l_response.envelope_tag := p_request.envelope_tag;
  l_response.doc := l_response.doc.extract('/'||l_response.envelope_tag||':Envelope/'||l_response.envelope_tag||':Body/child::node()',
                                           'xmlns:'||l_response.envelope_tag||'="http://schemas.xmlsoap.org/soap/envelope/"');
                                           
  check_fault(l_response);
  RETURN l_response;
END;
-- ---------------------------------------------------------------------



-- ---------------------------------------------------------------------
FUNCTION get_return_value(p_response   IN OUT NOCOPY  t_response,
                          p_name       IN             VARCHAR2,
                          p_namespace  IN             VARCHAR2)
  RETURN VARCHAR2 AS
-- ---------------------------------------------------------------------
BEGIN

    dbms_output.put_line('p_response.doc.getstringval()=' || p_response.doc.getstringval());    

  RETURN p_response.doc.extract('//'|| p_name || '/ns1:cmResult/text()','xmlns:ns1="http://main.ws.ecm.gosoft.co.th"').getstringval();

--  RETURN p_response.doc.extract('//'||p_name||'/child::text()',p_namespace).getstringval();
END;
-- ---------------------------------------------------------------------



-- ---------------------------------------------------------------------
PROCEDURE debug_on AS
-- ---------------------------------------------------------------------
BEGIN
  g_debug := TRUE;
END;
-- ---------------------------------------------------------------------



-- ---------------------------------------------------------------------
PROCEDURE debug_off AS
-- ---------------------------------------------------------------------
BEGIN
  g_debug := FALSE;
END;
-- ---------------------------------------------------------------------

END soap_api;
/


