    v_action_err varchar2(4000 char);

BEGIN

    IF UPDATING THEN
        v_action_type := 'AU';
    ELSIF INSERTING THEN
        v_action_type := 'AI';
    ELSE
        v_action_type := 'AD';               
    END IF;
    
    DBMS_OUTPUT.PUT_LINE('FRANCHISEE_BACKGROUND.OLD_FRANCHISEE_ID : ' || :old.franchisee_id || ' | FRANCHISEE_BACKGROUND.NEW_FRANCHISEE_ID : ' || :new.franchisee_id);
    
        insert into fz_background_log (
			franchisee_id, father_title_code, father_first_name, father_last_name, father_age, 
			father_occp_code, father_occp, father_tower, father_floor, father_address_no, 
