			closer_province, closer_zip, closer_mobile, closer_tel, closer_off, 
			closer_tel_off, closer_relation, married_title_code, married_first_name, married_last_name, 
			married_occp_code, married_occp, married_mobile, married_off, married_tel_off, 
			create_date, create_user, update_date, update_user, father_occp_code2, 
			father_occp_code3, mother_occp_code2, mother_occp_code3, closer_occp_code2, closer_occp_code3, 
			married_occp_code2, married_occp_code3, cust_id,
            action_type, action_error
        )
        values(
			:new.franchisee_id, :new.father_title_code, :new.father_first_name, :new.father_last_name, :new.father_age, 
			:new.father_occp_code, :new.father_occp, :new.father_tower, :new.father_floor, :new.father_address_no, 
			:new.father_moo, :new.father_soi, :new.father_street, :new.father_district, :new.father_city, 
			:new.father_province, :new.father_zip, :new.father_mobile, :new.father_tel, :new.father_off, 
			:new.father_tel_off, :new.mather_title_code, :new.mather_first_name, :new.mather_last_name, :new.mather_age, 
			:new.mather_occp_code, :new.mather_occp, :new.mather_mobile, :new.mather_tel, :new.mather_off, 
			:new.mather_tel_off, :new.closer_title_code, :new.closer_first_name, :new.closer_last_name, :new.closer_age, 
			:new.closer_occp_code, :new.closer_occp, :new.closer_tower, :new.closer_floor, :new.closer_address_no, 
			:new.closer_moo, :new.closer_soi, :new.closer_street, :new.closer_district, :new.closer_city, 
			:new.closer_province, :new.closer_zip, :new.closer_mobile, :new.closer_tel, :new.closer_off, 
			:new.closer_tel_off, :new.closer_relation, :new.married_title_code, :new.married_first_name, :new.married_last_name, 
			:new.married_occp_code, :new.married_occp, :new.married_mobile, :new.married_off, :new.married_tel_off, 
			:new.create_date, :new.create_user, :new.update_date, :new.update_user, :new.father_occp_code2, 
