			:new.married_occp_code2, :new.married_occp_code3, :new.cust_id,
            v_action_type, v_action_err
        );

    DBMS_OUTPUT.PUT_LINE('before commit (AF)'); 
    COMMIT;
    DBMS_OUTPUT.PUT_LINE('after commit (AF)'); 

EXCEPTION
    WHEN OTHERS THEN

        ROLLBACK;
    
        DBMS_OUTPUT.PUT_LINE('FRANCHISEE_BACKGROUND.FRANCHISEE_ID : ' || :new.franchisee_id || ' : Error code ' || SQLCODE || ' : ' || SQLERRM);
    
