-- ---------- TRIGGER: BF_ACTION_FZ_LOG_TRG ----------
CREATE OR REPLACE EDITIONABLE TRIGGER "FCS_FRN"."BF_ACTION_FZ_LOG_TRG" 

BEFORE INSERT OR UPDATE OR DELETE ON FCS_FRN.FRANCHISEE FOR EACH ROW
DECLARE

    PRAGMA AUTONOMOUS_TRANSACTION;   
    v_chk_rec integer;
    v_action_type varchar2(2 char);
    v_action_err varchar2(4000 char);

BEGIN

    IF UPDATING THEN
        v_action_type := 'BU';
    ELSIF INSERTING THEN
        v_action_type := 'BI';
    ELSE
        v_action_type := 'BD';               
    END IF;

    select count(1) into v_chk_rec
    from franchisee
    where franchisee_id = :new.franchisee_id;
        
    IF (v_chk_rec > 0) THEN
        IF INSERTING or (UPDATING AND :new.franchisee_id != :old.franchisee_id) THEN
            v_action_err := :new.cust_id || ' is duplicated';          
        END IF;
    END IF;

    IF v_action_err IS NOT NULL THEN
        DBMS_OUTPUT.PUT_LINE(v_action_err);   
    END IF;

    insert into franchisee_log (
        cust_id, franchisee_id, title_code, first_name, last_name, 
        relation, nick_name, birthday, sex, status_code, 
        edu_code, edu_other, school, major, occp_code, 
        occp_other, id_card, religion, salary, tower, 
        floor, address_no, moo, soi, street, 
        district, city, province, zip, mobile, 
        tel, fax, email, office, department, 
        position, cust_img, franchisee_source, media_source, married_title_code, 
        married_first_name, married_last_name, married_occp_code, married_occp, married_mobile, 
        married_off, married_tel_off, number_child, expect_salary, experience, 
        society, sport, future_trend, status, age, 
        create_date, create_user, update_date, update_user, spouse_img_id, 
        p_pac_pri, p_pac_sec, train_result, franchisee_img_id, franchisee_group_id, 
        first_name_en, last_name_en, religion_other, occp_code2, occp_code3, 
        married_occp_code2, married_occp_code3, media_source_category, media_source_other, nationality, 
        married_id_card, position_type, action_type, action_err 
    )
    values(
        :new.cust_id, nvl(:old.franchisee_id, :new.franchisee_id), :new.title_code, :new.first_name, :new.last_name,
        :new.relation, :new.nick_name, :new.birthday, :new.sex, :new.status_code,
        :new.edu_code, :new.edu_other, :new.school, :new.major, :new.occp_code,
        :new.occp_other, :new.id_card, :new.religion, :new.salary, :new.tower,
        :new.floor, :new.address_no, :new.moo, :new.soi, :new.street,
        :new.district, :new.city, :new.province, :new.zip, :new.mobile,
        :new.tel, :new.fax, :new.email, :new.office, :new.department,
        :new.position, :new.cust_img, :new.franchisee_source, :new.media_source, :new.married_title_code,
        :new.married_first_name, :new.married_last_name, :new.married_occp_code, :new.married_occp, :new.married_mobile,
        :new.married_off, :new.married_tel_off, :new.number_child, :new.expect_salary, :new.experience,
        :new.society, :new.sport, :new.future_trend, :new.status, :new.age,
        :new.create_date, :new.create_user, :new.update_date, :new.update_user, :new.spouse_img_id,
        :new.p_pac_pri, :new.p_pac_sec, :new.train_result, :new.franchisee_img_id, :new.franchisee_group_id,
        :new.first_name_en, :new.last_name_en, :new.religion_other, :new.occp_code2, :new.occp_code3,
        :new.married_occp_code2, :new.married_occp_code3, :new.media_source_category, :new.media_source_other, :new.nationality, 
        :new.married_id_card, :new.position_type, v_action_type, v_action_err   
    );
   
    DBMS_OUTPUT.PUT_LINE('before commit'); 
    COMMIT;
    DBMS_OUTPUT.PUT_LINE('after commit'); 

EXCEPTION
    WHEN OTHERS THEN

        ROLLBACK;
    
        DBMS_OUTPUT.PUT_LINE('Error code ' || SQLCODE || ' : ' || SQLERRM);   
        v_action_err := SQLCODE || ' : ' || SUBSTR(SQLERRM, 1, 3500);

        DBMS_OUTPUT.PUT_LINE(:new.franchisee_id);
    
        insert into franchisee_log (
            cust_id, franchisee_id, title_code, first_name, last_name, 
            relation, nick_name, birthday, sex, status_code, 
            edu_code, edu_other, school, major, occp_code, 
