-- ---------- TRIGGER: FR_STORE_CONTRACT_HISTORY_TRG_LOG ----------
CREATE OR REPLACE EDITIONABLE TRIGGER "FCS_FRN"."FR_STORE_CONTRACT_HISTORY_TRG_LOG" 		
AFTER INSERT OR UPDATE ON FR_STORE_CONTRACT_HISTORY		
FOR EACH ROW		
BEGIN		
    IF INSERTING THEN		
        INSERT INTO FR_STORE_CONTRACT_HISTORY_LOG (STORE_ID,SEQ_NO,START_DATE,END_DATE,SIGNED_DATE,EDIT_END_DATE,REMARK,UPDATE_DATE,UPDATE_USER,CREATE_DATE,CREATE_USER,ACTION_TYPE,ACTION_DATE)		
        VALUES (:NEW.STORE_ID,:NEW.SEQ_NO,:NEW.START_DATE,:NEW.END_DATE,:NEW.SIGNED_DATE,:NEW.EDIT_END_DATE,:NEW.REMARK,:NEW.UPDATE_DATE,:NEW.UPDATE_USER,:NEW.CREATE_DATE,:NEW.CREATE_USER, 'AI',sysdate);		
    ELSIF UPDATING THEN		
        INSERT INTO FR_STORE_CONTRACT_HISTORY_LOG (STORE_ID,SEQ_NO,START_DATE,END_DATE,SIGNED_DATE,EDIT_END_DATE,REMARK,UPDATE_DATE,UPDATE_USER,CREATE_DATE,CREATE_USER,ACTION_TYPE,ACTION_DATE)		
        VALUES (:NEW.STORE_ID,:NEW.SEQ_NO,:NEW.START_DATE,:NEW.END_DATE,:NEW.SIGNED_DATE,:NEW.EDIT_END_DATE,:NEW.REMARK,:NEW.UPDATE_DATE,:NEW.UPDATE_USER,:NEW.CREATE_DATE,:NEW.CREATE_USER, 'AU',sysdate);		
    END IF;		
END;	
/
ALTER TRIGGER "FCS_FRN"."FR_STORE_CONTRACT_HISTORY_TRG_LOG" ENABLE;

